// A chat transcript: the user's question sits right-aligned, the assistant
// streams its reply on the left with a tool chip, then a follow-up arrives.
import { ATTR, glyphs, uni, phase, fit, tint, reveal, wrapLines, stringWidth, thinkGlyph } from './_ai.js';

const MSGS = [
  ['user', 0, 'Why is checkout slow since lunch?'],
  ['tool', 1.0, 'searched traces, metrics, deploys'],
  ['bot', 1.8, 'p99 went from 180ms to 2.4s at 12:02, right when v2.14.1 shipped. That release runs 32 workers against a 20-connection pool, so requests queue for a connection.'],
  ['user', 5.4, 'Can you fix it?'],
  ['bot', 6.1, 'Yes: raise DB_POOL_SIZE to 40. I have queued it as fix #142 for your approval.'],
];

export default {
  id: 'ai-chat-transcript',
  title: 'Chat Transcript',
  category: 'Agents & Pipelines',
  description: 'A chat transcript: user questions sit right-aligned in tinted bubbles, the assistant streams replies on the left with a tool-use chip, and the view scrolls.',
  tags: ['chat', 'transcript', 'assistant', 'conversation', 'streaming'],
  kind: 'tui',
  size: { w: 64, h: 16 },
  minSize: { w: 40, h: 10 },
  loop: 9.5,
  color: '256',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 9.5);
      const rows = [];
      const bw = Math.max(16, Math.floor(W * 0.62));
      for (const [who, at, text] of MSGS) {
        if (p < at) break;
        if (who === 'user') {
          const lines = wrapLines(text, bw - 4);
          const w = Math.max(...lines.map((l) => stringWidth(l))) + 4;
          rows.push({ kind: 'label', who: 'you', x: W - 3 });
          for (const l of lines) rows.push({ kind: 'user', text: l, x: W - w, w });
        } else if (who === 'tool') {
          rows.push({ kind: 'tool', text });
        } else {
          const r = reveal(text, p, at, 24);
          if (!r.n) { rows.push({ kind: 'think' }); continue; }
          rows.push({ kind: 'label', who: 'mainbrain', x: 0 });
          const lines = wrapLines(r.text, bw);
          lines.forEach((l, i) => rows.push({ kind: 'bot', text: l, caret: !r.done && i === lines.length - 1 }));
        }
        rows.push({ kind: 'gap' });
      }
      const first = Math.max(0, rows.length - H);
      rows.slice(first).forEach((row, y) => {
        if (row.kind === 'label') {
          const lab = row.who;
          b.text(row.who === 'you' ? W - stringWidth(lab) : 0, y, lab, row.who === 'you' ? th.muted : th.accent, undefined, ATTR.BOLD);
        } else if (row.kind === 'user') {
          const bg = tint(ctx, th.accent, 0.22);
          b.fill(row.x, y, row.w, 1, ' ', undefined, bg);
          b.text(row.x + 2, y, row.text, th.ink, bg);
        } else if (row.kind === 'bot') {
          const x = b.text(0, y, row.text, th.ink);
          if (row.caret) b.set(Math.min(W - 1, x), y, u ? '▍' : '_', th.accent);
        } else if (row.kind === 'tool') {
          const chip = ` ${g.spark} ${row.text} `;
          b.text(0, y, fit(chip, W, undefined, ctx).trimEnd(), th.muted, tint(ctx, th.panel2, 0.9), ATTR.ITALIC);
        } else if (row.kind === 'think') {
          b.text(0, y, `${thinkGlyph(ctx, t)} thinking${g.ellipsis}`, th.dim, undefined, ATTR.ITALIC);
        }
      });
    };
  },
};

// A context window filling up: a stacked bar of system, tools, files,
// history and output grows turn by turn until auto-compact squeezes the
// history into a summary and frees room.
import { ATTR, glyphs, uni, phase, ease, fit, mix } from './_ai.js';

const MAX = 200; // k tokens
const SEGS = [['system', 'muted'], ['tools', 'info'], ['files', 'warn'], ['history', 'accent'], ['output', 'pos']];
const COMPACT = [5.8, 6.6];

export default {
  id: 'ai-context-window',
  title: 'Context Window',
  category: 'Model Internals',
  description: 'A 200k context window filling turn by turn as a stacked bar of system, tools, files, history and output, until auto-compact squeezes history into a summary.',
  tags: ['context window', 'tokens', 'compaction', 'memory', 'budget'],
  kind: 'chart',
  size: { w: 64, h: 9 },
  minSize: { w: 40, h: 7 },
  loop: 9,
  color: '256',
  order: 10,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 9);
      // Usage in k tokens: history and files grow with each turn, then compaction.
      const grow = Math.min(1, p / COMPACT[0]);
      const squeeze = ease(p, COMPACT[0], COMPACT[1]);
      const history = (6 + grow * 118) * (1 - squeeze) + 9 * squeeze;
      const files = 4 + grow * 38 - squeeze * 14;
      const output = 1 + grow * 9 + Math.max(0, p - COMPACT[1]) * 2.5;
      const used = { system: 3.2, tools: 11.8, files, history, output };
      const total = Object.values(used).reduce((a, c) => a + c, 0);
      const pct = total / MAX;
      b.text(0, 0, 'context', th.ink, undefined, ATTR.BOLD);
      const head = `${total.toFixed(1)}k / ${MAX}k  ${Math.round(pct * 100)}%`;
      b.text(W - head.length, 0, head, pct > 0.8 ? th.warn : th.muted, undefined, pct > 0.8 ? ATTR.BOLD : 0);
      // Stacked bar, two rows tall.
      const bw = W;
      let x = 0;
      SEGS.forEach(([key, tone], i) => {
        const w = Math.round((used[key] / MAX) * bw);
        const glyph = u ? '█▓▒░█'[i] : '#=+:%'[i];
        for (let k = 0; k < w && x < bw; k++, x++) { b.set(x, 1, glyph, th[tone]); b.set(x, 2, glyph, mix(th[tone], th.bg, 0.25)); }
      });
      for (; x < bw; x++) { b.set(x, 1, u ? '·' : '.', th.line); b.set(x, 2, u ? '·' : '.', th.line); }
      // Auto-compact threshold marker at 80%.
      const tx = Math.round(0.8 * bw);
      b.set(Math.min(W - 1, tx), 3, u ? '▲' : '^', th.warn);
      if (tx + 14 <= W) b.text(tx + 2, 3, 'auto-compact', th.dim);
      // Legend.
      let lx = 0, ly = 4;
      SEGS.forEach(([key, tone], i) => {
        const item = `${key} ${used[key].toFixed(1)}k`;
        if (lx + item.length + 2 > W) { lx = 0; ly++; }
        if (ly >= H - 1) return;
        b.set(lx, ly, u ? '█▓▒░█'[i] : '#=+:%'[i], th[tone]);
        lx = b.text(lx + 2, ly, item, th.muted) + 3;
      });
      const msg = squeeze > 0 && squeeze < 1 ? `${g.spark} compacting history: ${Math.round(6 + 118)}k ${g.right} 9k summary`
        : squeeze >= 1 ? `${g.check} compacted ${g.mid} freed 129k ${g.mid} summary keeps the incident timeline`
          : `turn ${1 + Math.floor(grow * 23)} ${g.mid} history grows with every tool result`;
      b.text(0, H - 1, fit(msg, W, undefined, ctx), squeeze > 0 ? th.pos : th.dim);
    };
  },
};

