// A collapsible reasoning block: "Thinking…" expands with summary lines
// streaming in dim italics, collapses to "Thought for 14s", then the answer streams.
import { ATTR, glyphs, uni, phase, fit, mix, reveal, wrapLines, thinkGlyph, shimmer } from './_ai.js';

const THOUGHTS = [
  'p99 jumped at 12:02, same minute as the v2.14.1 deploy.',
  'The diff raises worker concurrency 8 -> 32 but the pool stays at 20.',
  'Pool wait time tracks p99 almost exactly, so requests queue for connections.',
  'Smallest safe fix: size the pool to the workers, alert on pool wait.',
];
const ANSWER = 'The p99 spike is connection-pool starvation: v2.14.1 raised workers to 32 while the DB pool stayed at 20. Raise DB_POOL_SIZE to 40 (Postgres max_connections is 200, so there is headroom) and add an alert on pool wait > 200ms.';
const T = { think: 0.2, collapse: 4.6, answer: 5.0 };

export default {
  id: 'ai-reasoning-summary',
  title: 'Reasoning Summary',
  category: 'Thinking States',
  description: 'A collapsible reasoning block: thought summaries stream in dim italics while the model works, fold to "Thought for 14s", then the final answer streams below.',
  tags: ['reasoning', 'thinking', 'collapsible', 'summary', 'chain of thought'],
  kind: 'text',
  size: { w: 64, h: 11 },
  minSize: { w: 40, h: 7 },
  loop: 11,
  color: '256',
  order: 30,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx);
      const p = phase(t, 11);
      const open = p < T.collapse;
      let y = 0;
      if (open) {
        const label = `Thinking${g.ellipsis}`;
        b.text(0, y, g.triDown, th.muted);
        b.text(2, y, thinkGlyph(ctx, t), th.accent, undefined, ATTR.BOLD);
        [...label].forEach((ch, i) => b.set(4 + i, y, ch, shimmer(th.muted, th.ink, i, label.length, t), undefined, ATTR.BOLD));
        y++;
        // Thought lines reveal one after another.
        let at = T.think;
        for (const line of THOUGHTS) {
          const r = reveal(line, p, at, 22);
          if (!r.n) break;
          for (const l of wrapLines(r.text, W - 4)) {
            if (y >= H) break;
            b.text(0, y, g.v, mix(th.bg, th.line, 0.9));
            b.text(2, y++, fit(l, W - 2, undefined, ctx).trimEnd(), th.dim, undefined, ATTR.ITALIC);
          }
          at += r.total / 22 + 0.25;
        }
        return;
      }
      b.text(0, y, g.tri, th.muted);
      b.text(2, y, 'Thought for 14s', th.muted, undefined, ATTR.BOLD);
      b.text(18, y, `${g.mid} 4 steps`, th.dim);
      y += 2;
      const r = reveal(ANSWER, p, T.answer, 26);
      const lines = wrapLines(r.text, W);
      lines.slice(0, H - y).forEach((l, i) => b.text(0, y + i, l, th.ink));
      if (!r.done && lines.length) {
        const last = lines[Math.min(lines.length, H - y) - 1];
        const ly = y + Math.min(lines.length, H - y) - 1;
        if (ly < H) b.set(Math.min(W - 1, last.length), ly, uni(ctx) ? '▍' : '_', th.accent);
      }
    };
  },
};

// Next-token sampling: top-k candidates as probability bars that sharpen or
// flatten as the temperature slides, the sampled token flashing and joining
// the text above.
import { ATTR, glyphs, uni, phase, fit, mix, hbar, ease } from './_ai.js';

const PROMPT = 'The p99 spike is caused by DB';
// Steps: [candidates with logits, chosen index]
const STEPS = [
  [[[' pool', 3.1], [' connection', 1.9], [' lock', 0.9], [' query', 0.6], [' index', 0.1], [' CPU', -0.4]], 0],
  [[[' exhaustion', 2.6], [' starvation', 2.2], [' limits', 0.9], [' size', 0.7], [' wait', 0.4], [' churn', -0.6]], 1],
  [[['.', 3.4], [' after', 1.3], [' since', 1.1], [',', 0.8], [' under', 0.2], [' when', -0.2]], 0],
];
const STEP = 2.6;

const softmax = (ls, T) => { const e = ls.map((l) => Math.exp(l / T)); const s = e.reduce((a, c) => a + c, 0); return e.map((v) => v / s); };

export default {
  id: 'ai-sampling-probs',
  title: 'Next-Token Sampling',
  category: 'Model Internals',
  description: 'Next-token sampling: top-k candidates as probability bars that sharpen or flatten as temperature slides, then the sampled token flashes and joins the text.',
  tags: ['sampling', 'temperature', 'probabilities', 'top-k', 'logits'],
  kind: 'chart',
  size: { w: 60, h: 10 },
  minSize: { w: 40, h: 9 },
  loop: STEP * 3,
  color: '256',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, STEP * 3);
      const k = Math.floor(p / STEP), local = p - k * STEP;
      const [cands, pick] = STEPS[k];
      // Temperature sweeps 0.4 -> 1.4 -> 0.8 within each step.
      const T = 0.4 + ease(local, 0.1, 1.0) * 1.0 - ease(local, 1.1, 1.6) * 0.6;
      const probs = softmax(cands.map((c) => c[1]), T);
      const sampled = local >= 1.8;
      // Text so far.
      const text = PROMPT + STEPS.slice(0, k).map(([c, i]) => c[i][0]).join('');
      let x = b.text(0, 0, fit(text, W - 12, undefined, ctx).trimEnd(), th.ink);
      if (sampled) x = b.text(x, 0, cands[pick][0], th.bg, th.accent, ATTR.BOLD);
      else b.set(x, 0, u ? '▍' : '_', th.accent);
      // Temperature slider.
      const sw = Math.min(20, W - 20);
      b.text(0, 2, 'temperature', th.muted);
      for (let i = 0; i < sw; i++) b.set(12 + i, 2, u ? '─' : '-', th.line);
      b.set(12 + Math.round(((T - 0.2) / 1.4) * (sw - 1)), 2, u ? '●' : 'O', th.warn, undefined, ATTR.BOLD);
      b.text(13 + sw, 2, T.toFixed(2), th.warn, undefined, ATTR.BOLD);
      // Candidate bars.
      const bw = Math.max(8, W - 26);
      cands.forEach(([tok, ], i) => {
        const y = 4 + i;
        if (y >= H) return;
        const on = sampled && i === pick;
        const label = JSON.stringify(tok).slice(1, -1).replace(/^ /, u ? '·' : '_');
        b.text(0, y, fit(label, 12, undefined, ctx), on ? th.accent : th.ink, undefined, on ? ATTR.BOLD : 0);
        hbar(ctx, b, 13, y, bw, probs[i], on ? th.accent : mix(th.info, th.accent, probs[i]));
        b.text(14 + bw, y, `${(probs[i] * 100).toFixed(1)}%`.padStart(6), on ? th.accent : th.muted, undefined, on ? ATTR.BOLD : 0);
        if (on && 21 + bw < W) b.text(21 + bw, y, g.left, th.accent, undefined, ATTR.BOLD);
      });
    };
  },
};

