// A working indicator: a breathing glyph, a status verb with a shimmer band
// sweeping across it, elapsed time and token count, finished steps above.
import { ATTR, glyphs, phase, fit, mix, thinkGlyph, shimmer, stringWidth } from './_ai.js';

// [start, verb, finished-step summary shown once the next verb starts]
const STEPS = [
  [0, 'Reading the trace', 'Read trace 4bf92f35 (31 spans)'],
  [2.2, 'Correlating spans with pool metrics', 'Correlated p99 with pool wait (r=0.94)'],
  [4.6, 'Checking the deploy diff', 'v2.14.1 raised workers to 32, pool left at 20'],
  [7.0, 'Drafting a fix', ''],
];

export default {
  id: 'ai-thinking-shimmer',
  title: 'Thinking Shimmer',
  category: 'Thinking States',
  description: 'An agent working indicator: a breathing glyph and a status verb with a shimmer sweeping across it, elapsed time and tokens, finished steps ticking off above.',
  tags: ['thinking', 'shimmer', 'working', 'spinner', 'agent'],
  kind: 'spinner',
  size: { w: 64, h: 6 },
  minSize: { w: 36, h: 3 },
  loop: 9.5,
  color: '256',
  order: 10,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx);
      const p = phase(t, 9.5);
      let k = 0;
      STEPS.forEach(([at], i) => { if (p >= at) k = i; });
      // Finished steps above the live line (as many as fit).
      const done = STEPS.slice(0, k).map((s) => s[2]);
      const rows = done.slice(-(H - 1));
      rows.forEach((text, r) => {
        b.text(0, r, g.check, th.pos, undefined, ATTR.BOLD);
        b.text(2, r, fit(text, W - 2, undefined, ctx), th.muted);
      });
      const y = rows.length;
      const verb = `${STEPS[k][1]}${g.ellipsis}`;
      b.text(0, y, thinkGlyph(ctx, t), th.accent, undefined, ATTR.BOLD);
      const vw = Math.min(stringWidth(verb), W - 2);
      [...verb].slice(0, vw).forEach((ch, i) => b.set(2 + i, y, ch, shimmer(mix(th.bg, th.accent, 0.75), th.ink, i, vw, t), undefined, ATTR.BOLD));
      const secs = Math.floor(p * 1.6) + 3;
      const toks = (0.4 + p * 0.31).toFixed(1);
      const meta = `(${secs}s ${g.mid} ${g.down} ${toks}k tokens ${g.mid} esc to interrupt)`;
      if (2 + vw + 1 + stringWidth(meta) <= W) b.text(3 + vw, y, meta, th.dim);
      else if (y + 1 < H) b.text(2, y + 1, fit(meta, W - 2, undefined, ctx), th.dim);
    };
  },
};

sources.prism-term/src/facets/ai/throughput-mete:
// An inference throughput panel: concurrent streams with progress and
// per-stream rates, an aggregate tok/s sparkline, TTFT, cache hits and cost.
import { ATTR, glyphs, uni, phase, fit, hbar, panel, mix } from './_ai.js';

// [id, output tokens, start, tok/s, ttft ms]
const REQS = [['7f3a', 900, 0.0, 54, 280], ['2c91', 700, 0.8, 61, 340], ['9be0', 480, -4.0, 48, 310], ['d41e', 620, 3.2, 66, 260]];
const LOOP = 10;

export default {
  id: 'ai-throughput-meter',
  title: 'Throughput Meter',
  category: 'Token Streams',
  description: 'An inference panel with concurrent streams, per-stream progress and tok/s, an aggregate throughput sparkline, TTFT, cache hit rate and a running cost.',
  tags: ['throughput', 'tok/s', 'inference', 'dashboard', 'latency'],
  kind: 'widget',
  size: { w: 70, h: 8 },
  minSize: { w: 50, h: 8 },
  loop: LOOP,
  color: '256',
  order: 30,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, LOOP);
      const state = (r, at) => {
        const [, total, start, rate, ttft] = r;
        const el = at - start - ttft / 1000;
        if (at < start) return { s: 'queued', n: 0 };
        if (el < 0) return { s: 'ttft', n: 0 };
        const n = Math.min(total, Math.floor(el * rate * (1 + 0.15 * Math.sin(el * 3))));
        return { s: n >= total ? 'done' : 'stream', n };
      };
      const aggregate = (at) => REQS.reduce((sum, r) => sum + (state(r, at).s === 'stream' ? r[3] : 0), 0);
      const inner = panel(ctx, b, 0, 0, W, H, { title: `reasoning-large ${g.mid} ${REQS.filter((r) => state(r, p).s === 'stream').length} streaming`, footer: `$${(0.0112 + p * 0.0031).toFixed(4)}`, color: th.line });
      const iw = inner.width;
      REQS.forEach((r, i) => {
        const [id, total, , rate, ttft] = r;
        const st = state(r, p);
        const y = i;
        if (y >= inner.height - 2) return;
        inner.text(0, y, `req ${id}`, st.s === 'done' ? th.dim : th.ink, undefined, st.s === 'stream' ? ATTR.BOLD : 0);
        const bw = Math.max(6, iw - 40);
        hbar(ctx, inner, 9, y, bw, st.n / total, st.s === 'done' ? th.pos : th.accent);
        let x = 10 + bw;
        x = inner.text(x, y, `${String(st.n).padStart(3)}/${total}`, th.muted) + 2;
        const tail = st.s === 'done' ? `${g.check} done` : st.s === 'ttft' ? `waiting ${ttft}ms` : st.s === 'queued' ? 'queued' : `${rate} t/s  ttft ${ttft}ms`;
        inner.text(x, y, fit(tail, Math.max(0, iw - x), undefined, ctx).trimEnd(), st.s === 'done' ? th.pos : st.s === 'stream' ? th.ink : th.dim);
      });
      // Aggregate throughput sparkline (last ~5 s).
      const sy = inner.height - 2;
      const LV = u ? ' ▁▂▃▄▅▆▇█' : ' .:-=+*#%';
      inner.text(0, sy, 'throughput', th.muted);
      const sw = Math.max(8, iw - 26);
      for (let i = 0; i < sw; i++) {
        const v = aggregate(p - (sw - 1 - i) * 0.2) / 200;
        inner.set(11 + i, sy, LV[Math.max(1, Math.min(8, Math.round(v * 8)))], mix(th.info, th.accent, v));
      }
      inner.text(12 + sw, sy, `${String(aggregate(p)).padStart(3)} tok/s`, th.ink, undefined, ATTR.BOLD);
      inner.text(0, sy + 1, fit(`cache hits 62% ${g.mid} input 18.2k ${g.mid} output ${(1.1 + p * 0.09).toFixed(1)}k ${g.mid} p95 ttft 340ms`, iw, undefined, ctx), th.dim);
    };
  },
};

sources.prism-term/src/facets/ai/token-stream.js:
// A response streaming token by token: each new token flashes, the rate
// wobbles like a real stream, then a tokenizer view tints token boundaries.
import { ATTR, glyphs, uni, phase, mix, fit, tint, tokenize } from './_ai.js';

const TEXT = 'Checkout latency is up because the DB pool is exhausted. Since v2.14.1 the service runs 32 workers but still opens only 20 connections, so about a third of requests wait in the pool queue. Raising the pool to 40 should bring p99 back under 300ms.';
const TOKS = tokenize(TEXT);
const START = 0.4, TOKVIEW = 6.2, RATE = 14;

export default {
  id: 'ai-token-stream',
  title: 'Token Stream',
  category: 'Token Streams',
  description: 'A response streaming token by token with each new token flashing, a live tok/s sparkline and TTFT, then a tokenizer view that tints every token boundary.',
  tags: ['tokens', 'streaming', 'llm', 'tokenizer', 'tok/s'],
  kind: 'text',
  size: { w: 64, h: 9 },
  minSize: { w: 36, h: 6 },
  loop: 9,
  color: '256',
  order: 10,
  setup(ctx) {
    const th = ctx.theme;
    const PAL = ['accent', 'pos', 'warn', 'info', 'crit'];
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 9);
      // Warped clock so the rate wobbles: bursts and short stalls.
      const tp = Math.max(0, p - START);
      const warped = tp + 0.12 * Math.sin(tp * 4.1) + 0.06 * Math.sin(tp * 9.3);
      const n = Math.min(TOKS.length, Math.max(0, Math.floor(warped * RATE)));
      const tokView = p >= TOKVIEW;
      // Lay tokens out with word wrap, keeping each token whole.
      const bodyH = H - 2;
      let x = 0, y = 0;
      const cells = [];
      for (let i = 0; i < n; i++) {
        let tok = TOKS[i];
        // Wrap whole words: a word runs until the next token with a leading space.
        if (/^\s/.test(tok) || i === 0) {
          let wl = tok.length;
          for (let j = i + 1; j < TOKS.length && !/^\s/.test(TOKS[j]); j++) wl += TOKS[j].length;
          if (x + wl > W && x > 0) { y++; x = 0; tok = tok.replace(/^\s+/, ''); }
        }
        cells.push([x, y, tok, i]);
        x += tok.length;
      }
      const first = Math.max(0, y - bodyH + 1);
      for (const [cx, cy, tok, i] of cells) {
        if (cy < first) continue;
        const age = n - 1 - i;
        let fg = th.ink, bg;
        if (tokView) { bg = tint(ctx, th[PAL[i % PAL.length]], 0.3); }
        else if (age < 3) { bg = tint(ctx, th.accent, 0.35 - age * 0.1); fg = mix(th.ink, th.accent, 0.3); }
        b.text(cx, cy - first, tok, fg, bg, tokView ? 0 : age === 0 ? ATTR.BOLD : 0);
        // Mono-safe boundary marks in tokenizer view.
        if (tokView && !u) b.set(cx, cy - first, tok[0] === ' ' ? '|' : tok[0], fg, bg);
      }
      if (n < TOKS.length && n > 0) {
        const [lx, ly, lt] = cells[cells.length - 1];
        if (ly - first < bodyH) b.set(Math.min(W - 1, lx + lt.length), ly - first, u ? '▍' : '_', th.accent);
      }
      // Stats.
      const sy = H - 1;
      b.fill(0, sy - 1, W, 1, u ? '─' : '-', th.line);
      const rate = n >= TOKS.length ? 0 : Math.round(RATE * (1 + 0.48 * Math.cos(tp * 4.1) + 0.56 * Math.cos(tp * 9.3)));
      const stats = tokView
        ? `view: tokens ${g.mid} ${TOKS.length} tokens ${g.mid} ${TEXT.length} chars ${g.mid} ${(TEXT.length / TOKS.length).toFixed(1)} chars/token`
        : `TTFT 380ms ${g.mid} ${String(Math.max(0, rate)).padStart(2)} tok/s ${g.mid} ${n}/${TOKS.length} tokens`;
      let sx = b.text(0, sy, fit(stats, W, undefined, ctx).trimEnd(), tokView ? th.info : th.muted);
      // Rate sparkline on the right while streaming.
      if (!tokView && sx + 14 <= W) {
        const LV = u ? '▁▂▃▄▅▆▇█' : '.:-=+*#%';
        for (let i = 0; i < 12; i++) {
          const tt = tp - (11 - i) * 0.25;
          const r = tt < 0 || n >= TOKS.length && tt > TOKS.length / RATE ? 0 : 1 + 0.48 * Math.cos(tt * 4.1) + 0.56 * Math.cos(tt * 9.3);
          b.set(W - 12 + i, sy, LV[Math.max(0, Math.min(7, Math.round(r * 3)))], r ? th.accent : th.dim);
        }
      }
    };
  },
};

sources.prism-term/src/facets/ai/tool-calls.js:
// An agent's tool calls stacking up, coding-agent style: each call shows a
// spinner while it runs, then collapses to a one-line result under a ⎿ elbow.
import { ATTR, glyphs, uni, phase, fit, spin, stringWidth } from './_ai.js';

// [start, duration, tool, args, result, extra lines]
const CALLS = [
  [0, 0.9, 'Read', 'src/db/pool.js', 'Read 24 lines', 0],
  [1.5, 1.2, 'Bash', 'kubectl top pods -n checkout', '3 pods, cpu 41-58%', 12],
  [3.0, 0.8, 'Grep', 'pattern: "POOL_SIZE"', 'Found 3 files', 0],
  [4.1, 1.4, 'Query', 'pool_wait_ms p99 [30m]', '840ms (was 12ms before 12:02)', 0],
];

export default {
  id: 'ai-tool-call-card',
  title: 'Tool Calls',
  category: 'Tool Calls',
  description: 'An agent\'s tool calls stacking up: each shows a spinner and its arguments while running, then collapses to a one-line result, with long output folded away.',
  tags: ['tool calls', 'agent', 'function calling', 'coding agent', 'spinner'],
  kind: 'tui',
  size: { w: 64, h: 12 },
  minSize: { w: 40, h: 8 },
  loop: 8,
  color: '16',
  order: 10,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 8);
      const rows = [];
      for (const [at, dur, tool, args, result, extra] of CALLS) {
        if (p < at) break;
        const running = p < at + dur;
        rows.push({ kind: 'call', tool, args, running });
        if (running) rows.push({ kind: 'wait', text: tool === 'Bash' ? 'Running' : tool === 'Query' ? 'Querying metrics' : 'Working' });
        else {
          rows.push({ kind: 'result', text: result });
          if (extra) rows.push({ kind: 'more', text: `${g.ellipsis} +${extra} lines (ctrl+o to expand)` });
        }
        rows.push({ kind: 'gap' });
      }
      const first = Math.max(0, rows.length - H);
      rows.slice(first).forEach((row, y) => {
        if (row.kind === 'call') {
          b.text(0, y, row.running ? spin(ctx, t) : (u ? '●' : '*'), row.running ? th.warn : th.pos, undefined, ATTR.BOLD);
          const x = b.text(2, y, row.tool, th.ink, undefined, ATTR.BOLD);
          const a = `(${row.args})`;
          b.text(x, y, stringWidth(a) <= W - x ? a : fit(a, W - x, undefined, ctx), th.muted);
        } else if (row.kind === 'result' || row.kind === 'wait' || row.kind === 'more') {
          b.text(2, y, u ? '⎿' : '\\_', th.dim);
          const c = row.kind === 'wait' ? th.warn : row.kind === 'more' ? th.dim : th.ink;
          b.text(5, y, fit(row.kind === 'wait' ? `${row.text}${g.ellipsis}` : row.text, W - 5, undefined, ctx).trimEnd(), c, undefined, row.kind === 'more' ? ATTR.ITALIC : 0);
        }
      });
    };
  },
};

sources.prism-term/src/facets/ai/typing-indicato:
// A sampler of "the model is working" indicators, each labeled:
// bouncing dots, a braille wave, a pulse, an orbit, a scanner and a meter.
import { ATTR, uni, phase, mix, fit } from './_ai.js';

const BRAILLE_LV = ['⡀', '⡄', '⡆', '⡇', '⡏', '⡟', '⡿', '⣿'];

export default {
  id: 'ai-typing-indicators',
  title: 'Typing Indicators',
  category: 'Thinking States',
  description: 'Six labeled "model is working" indicators side by side: a chat bubble of bouncing dots, a braille wave, a pulse, an orbit, a scanner and an equalizer.',
  tags: ['typing indicator', 'dots', 'wave', 'loading', 'chat'],
  kind: 'spinner',
  size: { w: 66, h: 4 },
  minSize: { w: 33, h: 4 },
  loop: 2.4,
  color: '256',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx);
      const p = phase(t, 2.4);
      // Whole cycles per loop, so every indicator repeats seamlessly.
      const w = (k) => (2 * Math.PI * k) / 2.4;
      const cells = [
        ['bounce', (s, x, y) => {
          // Chat bubble with three dots rising in turn.
          s.text(x, y, u ? '╭───────╮' : '+-------+', th.line);
          s.text(x, y + 1, u ? '│       │' : '|       |', th.line);
          s.text(x, y + 2, u ? '╰─┬─────╯' : '+-+-----+', th.line);
          for (let i = 0; i < 3; i++) {
            const k = Math.max(0, Math.sin((p / 2.4) * Math.PI * 4 - i * 0.9));
            s.set(x + 2 + i * 2, y + 1, u ? (k > 0.6 ? '●' : k > 0.2 ? '•' : '∙') : (k > 0.6 ? 'O' : k > 0.2 ? 'o' : '.'), mix(th.muted, th.accent, k), undefined, ATTR.BOLD);
          }
        }],
        ['wave', (s, x, y) => {
          for (let i = 0; i < 9; i++) {
            const v = (Math.sin(w(2) * p - i * 0.7) + 1) / 2;
            s.set(x + i, y + 1, u ? BRAILLE_LV[Math.round(v * 7)] : ' .:-=+*#'[Math.round(v * 7)], mix(th.info, th.accent, v));
          }
        }],
        ['pulse', (s, x, y) => {
          const k = (Math.sin(w(2) * p) + 1) / 2;
          const ring = u ? ['∙', '•', '●', '◉', '◎'][Math.round(k * 4)] : ['.', 'o', 'O', '@', '0'][Math.round(k * 4)];
          s.set(x + 4, y + 1, ring, mix(th.dim, th.accent, k), undefined, ATTR.BOLD);
          s.text(x, y + 1, u ? '·  ' : '.  ', mix(th.bg, th.accent, k * 0.6));
          s.text(x + 6, y + 1, u ? '  ·' : '  .', mix(th.bg, th.accent, k * 0.6));
        }],
        ['orbit', (s, x, y) => {
          const pts = [[4, 0], [6, 1], [4, 2], [2, 1]];
          pts.forEach(([dx, dy], i) => {
            const lead = Math.floor(p * 5) % 4;
            const age = (lead - i + 4) % 4;
            s.set(x + dx, y + dy, u ? (age === 0 ? '●' : '∙') : (age === 0 ? 'O' : '.'), age === 0 ? th.accent : mix(th.bg, th.accent, 0.6 - age * 0.15), undefined, ATTR.BOLD);
          });
          s.set(x + 4, y + 1, u ? '✳' : '*', th.muted);
        }],
        ['scan', (s, x, y) => {
          const n = 9, pos = Math.round((Math.sin(w(1) * p) + 1) / 2 * (n - 1));
          for (let i = 0; i < n; i++) {
            const d = Math.abs(i - pos);
            s.set(x + i, y + 1, u ? (d === 0 ? '█' : d === 1 ? '▓' : d === 2 ? '▒' : '░') : (d === 0 ? '#' : d === 1 ? '=' : '-'), d < 3 ? mix(th.accent, th.bg, d * 0.3) : th.line);
          }
        }],
        ['meter', (s, x, y) => {
          const LV = u ? ' ▁▂▃▄▅▆▇█' : ' ..::==##';
          for (let i = 0; i < 7; i++) {
            const v = (Math.sin(w(2 + (i % 3)) * p + i) + 1) / 2;
            s.set(x + 1 + i, y + 1, LV[1 + Math.round(v * 7)], mix(th.pos, th.warn, v));
          }
        }],
      ];
      // Lay the cells out in as many columns as fit (11 columns each).
      const cw = 11, cols = Math.max(1, Math.floor(W / cw)), rowH = 4;
      const rows = Math.max(1, Math.floor(H / rowH));
      const n = Math.min(cells.length, cols * rows);
      const x0 = Math.max(0, Math.floor((W - Math.min(cols, n) * cw) / 2));
      for (let i = 0; i < n; i++) {
        const [name, draw] = cells[i];
        const cx = x0 + (i % cols) * cw, cy = Math.floor(i / cols) * rowH;
        draw(b, cx, cy);
        b.text(cx, cy + 3, fit(name, cw - 1, undefined, ctx).trimEnd(), th.dim);
      }
    };
  },
};

