// A code panel stepping like a debugger: gutter line numbers, syntax color,
// a breakpoint, diff markers and the current-line highlight walking down.
import { ATTR, uni, panel, codeLine, phase, mix, fit } from './_kit.js';

const CODE = [
  "import { connect } from './db.js';",
  '',
  'export async function reserve(order) {',
  '  const pool = await connect({ size: 40 });',
  "  const rows = await pool.query('SELECT * FROM stock');",
  '  if (rows.length === 0) throw new Error("out of stock");',
  '  // hold the items for ten minutes',
  "  await pool.query('UPDATE stock SET held = true');",
  '  return { ok: true, held: rows.length };',
  '}',
];
const DIFF = { 3: '+', 7: '~' };
const BREAK = 5;

export default {
  id: 'callouts-code-block',
  title: 'Code Block',
  category: 'Panels & Borders',
  description: 'A titled code panel with line numbers, syntax coloring, a breakpoint, diff markers and a debugger-style current line stepping through.',
  tags: ['code', 'syntax', 'line numbers', 'debugger', 'snippet'],
  kind: 'widget',
  size: { w: 66, h: 14 },
  minSize: { w: 36, h: 7 },
  loop: 9,
  color: '256',
  order: 50,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx);
      const p = phase(t, 9);
      const lines = CODE.length;
      const cur = [2, 3, 4, 5, 7, 8][Math.floor(p / 1.5) % 6];
      const inner = panel(ctx, b, 0, 0, W, H, { title: 'inventory/reserve.js', footer: `Ln ${cur + 1}, Col 3 ${u ? '·' : '-'} JavaScript`, color: th.line });
      const iw = inner.width, ih = inner.height;
      const first = Math.max(0, Math.min(lines - ih, cur - Math.floor(ih / 2)));
      for (let r = 0; r < ih; r++) {
        const i = first + r;
        if (i >= lines) break;
        const isCur = i === cur;
        const bg = isCur ? mix(th.bg, th.accent, 0.16) : undefined;
        if (bg !== undefined) inner.fill(0, r, iw, 1, ' ', undefined, bg);
        const gut = i === BREAK ? (u ? '●' : '*') : isCur ? (u ? '▶' : '>') : ' ';
        inner.set(0, r, gut, i === BREAK ? th.neg : th.accent, bg);
        inner.text(1, r, fit(String(i + 1), 3, 'right', ctx), isCur ? th.ink : th.dim, bg);
        const mark = DIFF[i];
        inner.set(5, r, mark || ' ', mark === '+' ? th.pos : th.warn, bg);
        codeLine(ctx, inner, 7, r, iw - 7, CODE[i], bg);
      }
    };
  },
};

// Labeled rules in every weight, with a light sweeping along them.
import { ATTR, uni, phase, mix } from './_kit.js';

const RULES = [
  { ch: ['─', '-'], label: 'Section', align: 'left' },
  { ch: ['━', '='], label: 'Heavy', align: 'center' },
  { ch: ['═', '='], label: 'Double', align: 'right' },
  { ch: ['┄', '.'], label: 'Dotted', align: 'left' },
  { ch: ['╌', '-'], label: 'Dashed', align: 'center' },
  { ch: ['·', '.'], label: 'Middle dots', align: 'center' },
  { ch: ['•', '*'], spaced: true, label: '', align: 'center' },
  { ch: ['▔', '-'], label: 'Overline', align: 'left' },
];

export default {
  id: 'callouts-dividers',
  title: 'Dividers & Rules',
  category: 'Dividers & Headers',
  description: 'Horizontal rules in light, heavy, double, dotted, dashed and dotted-bullet weights with left, centered and right labels and a sweep of light.',
  tags: ['divider', 'rule', 'separator', 'hr', 'section'],
  kind: 'widget',
  size: { w: 64, h: 15 },
  minSize: { w: 24, h: 6 },
  loop: 4,
  color: '256',
  order: 10,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx);
      const step = H >= RULES.length * 2 - 1 ? 2 : 1;
      const sweep = (phase(t, 4) / 4) * (W + 20) - 10;
      RULES.forEach((r, i) => {
        const y = i * step;
        if (y >= H) return;
        const ch = r.ch[u ? 0 : 1];
        for (let x = 0; x < W; x++) {
          if (r.spaced && x % 2) continue;
          const k = Math.max(0, 1 - Math.abs(x - sweep - i * 2) / 6);
          b.set(x, y, ch, mix(th.line, th.accent, k));
        }
        if (r.label) {
          const text = ` ${r.label} `;
          const lx = r.align === 'left' ? 3 : r.align === 'right' ? W - text.length - 3 : Math.floor((W - text.length) / 2);
          b.text(Math.max(0, lx), y, text, i === 0 ? th.ink : th.muted, undefined, ATTR.BOLD);
        }
      });
    };
  },
};

sources.prism-term/src/facets/callouts/focus-pan:
// A four-pane layout where focus moves like Tab in a real TUI: the focused
// pane gets a heavy accent border, the rest recede.
import { panel, glyphs, ATTR, fit, phase, uni } from './_kit.js';

const LOGS = ['GET /cart 200 41ms', 'POST /checkout 201 212ms', 'GET /search?q=tent 200 22ms', 'healthcheck ok', 'GET /account 200 34ms', 'POST /login 200 88ms'];

export default {
  id: 'callouts-focus-panels',
  title: 'Focus Ring Layout',
  category: 'Panels & Borders',
  description: 'A four-pane dashboard where keyboard focus cycles with Tab — heavy accent border on the active pane, dimmed borders on the rest.',
  tags: ['focus', 'layout', 'panes', 'tab', 'dashboard'],
  kind: 'tui',
  size: { w: 76, h: 20 },
  minSize: { w: 40, h: 10 },
  loop: 8,
  color: '16',
  order: 30,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx);
      const focus = Math.floor(phase(t, 8) / 2) % 4;
      const lw = Math.floor(W * 0.42), rw = W - lw - 1;
      const PH = H - 1; // last row is the key hint
      const th1 = Math.floor((PH - 1) / 2), th2 = PH - 1 - th1 - 1;
      const panes = [
        { x: 0, y: 0, w: lw, h: th1, title: 'Services' },
        { x: lw + 1, y: 0, w: rw, h: th1, title: 'Logs' },
        { x: 0, y: th1 + 1, w: lw, h: th2 + 1, title: 'Alerts' },
        { x: lw + 1, y: th1 + 1, w: rw, h: th2 + 1, title: 'Metrics' },
      ];
      panes.forEach((p, i) => {
        const on = i === focus;
        const inner = panel(ctx, b, p.x, p.y, p.w, p.h, { style: on ? 'heavy' : 'round', title: on ? `${g.tri} ${p.title}` : p.title, titleColor: on ? th.accent : th.muted, color: on ? th.accent : th.line });
        const ink = on ? th.ink : th.muted;
        for (let r = 0; r < inner.height; r++) {
          if (i === 0) {
            const svc = ['edge-lb', 'api-gateway', 'checkout', 'payments', 'catalog', 'search'][r];
            if (!svc) break;
            const bad = svc === 'payments' && Math.sin(t * 0.8) > 0.2;
            inner.text(1, r, g.dot, bad ? th.warn : th.pos);
            inner.text(3, r, fit(svc, Math.max(0, inner.width - 12), undefined, ctx), ink);
            inner.text(inner.width - 8, r, bad ? 'degraded' : 'running', bad ? th.warn : th.dim);
          } else if (i === 1) {
            const k = (Math.floor(t * 1.5) + r) % LOGS.length;
            inner.text(1, r, fit(LOGS[k], inner.width - 2, undefined, ctx), r === inner.height - 1 ? th.ink : ink);
          } else if (i === 2) {
            const al = [['warn', 'payments p95 above SLO for 3m'], ['info', 'deploy search v2.3.1 finished'], ['ok', 'cert renewed for edge-lb']][r];
            if (!al) break;
            const c = al[0] === 'warn' ? th.warn : al[0] === 'ok' ? th.pos : th.info;
            inner.text(1, r, al[0].toUpperCase().padEnd(5), c, undefined, ATTR.BOLD);
            inner.text(7, r, fit(al[1], Math.max(0, inner.width - 8), undefined, ctx), ink);
          } else {
            const bars = ['cpu', 'mem', 'disk', 'net'][r];
            if (!bars) break;
            const v = 0.3 + 0.25 * Math.sin(t * (0.6 + r * 0.3) + r) + r * 0.08;
            inner.text(1, r, bars.padEnd(5), th.muted);
            const bw = Math.max(1, inner.width - 13);
            for (let k = 0; k < bw; k++) inner.set(7 + k, r, k < v * bw ? (uni(ctx) ? '▮' : '#') : (uni(ctx) ? '▯' : '.'), k < v * bw ? (on ? th.info : th.dim) : th.line);
            inner.text(8 + bw, r, `${Math.round(v * 100)}%`.padStart(4), ink);
          }
        }
      });
      const hint = `Tab next pane ${g.mid} Shift-Tab previous`;
      b.text(Math.max(0, W - hint.length - 1), H - 1, hint, th.dim);
    };
  },
};

