// A delivery flowchart with decisions and a loop: a run token walks the graph,
// fails tests once, goes round the fix loop, then ships through a canary.
import { ATTR, glyphs, uni, phase, fit } from '../callouts/_kit.js';
import { LineGrid, nodeBox, box, polyline, along } from './_lines.js';

// Node layout on a 64-column grid; decisions are drawn double-bordered.
const NODES = {
  commit: [0, 2, 11, 'commit'], build: [17, 2, 9, 'build'], tests: [32, 2, 12, 'tests?', 1], notify: [52, 2, 10, 'notify'],
  canary: [32, 8, 13, 'canary 5%'], healthy: [14, 8, 13, 'healthy?', 1], promote: [0, 8, 9, 'ship'],
  rollback: [14, 13, 13, 'roll back'],
};
// Steps the run token takes: [kind, id, seconds, result].
const STEPS = [
  ['node', 'commit', 0.5], ['edge', 'commit-build', 0.3], ['node', 'build', 0.6], ['edge', 'build-tests', 0.3],
  ['node', 'tests', 0.5, 'fail'], ['edge', 'tests-notify', 0.3], ['node', 'notify', 0.5], ['edge', 'notify-build', 0.6],
  ['node', 'build', 0.5], ['edge', 'build-tests', 0.3], ['node', 'tests', 0.5, 'pass'], ['edge', 'tests-canary', 0.4],
  ['node', 'canary', 0.7], ['edge', 'canary-healthy', 0.3], ['node', 'healthy', 0.5, 'pass'], ['edge', 'healthy-promote', 0.3],
  ['node', 'promote', 1.9, 'done'],
];

export default {
  id: 'diagrams-flowchart',
  title: 'Flowchart',
  category: 'Boxes & Flows',
  description: 'A delivery flowchart with decisions, labeled yes/no branches and a fix loop; a run token walks it, fails tests once, loops back, then ships via a canary.',
  tags: ['flowchart', 'decision', 'process', 'ci', 'graph'],
  kind: 'diagram',
  size: { w: 64, h: 17 },
  minSize: { w: 62, h: 17 },
  loop: 9,
  color: '16',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    const N = Object.fromEntries(Object.entries(NODES).map(([k, [x, y, w]]) => [k, box(x, y, w, 3)]));
    const EDGES = {
      'commit-build': [[N.commit.right, N.build.left]],
      'build-tests': [[N.build.right, N.tests.left]],
      'tests-notify': [[N.tests.right, N.notify.left], 'no'],
      'notify-build': [[N.notify.top, [N.notify.cx, 0], [N.build.cx, 0], N.build.top], 'fix'],
      'tests-canary': [[N.tests.bottom, N.canary.top], 'yes'],
      'canary-healthy': [[N.canary.left, N.healthy.right]],
      'healthy-promote': [[N.healthy.left, N.promote.right], 'yes'],
      'healthy-rollback': [[N.healthy.bottom, N.rollback.top], 'no'],
    };
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 9);
      // Where is the token?
      let acc = 0, cur = STEPS.length - 1, local = 1;
      for (let i = 0; i < STEPS.length; i++) {
        if (p < acc + STEPS[i][2]) { cur = i; local = (p - acc) / STEPS[i][2]; break; }
        acc += STEPS[i][2];
      }
      const visited = new Set(), results = {};
      for (let i = 0; i <= cur; i++) {
        const [kind, id, , res] = STEPS[i];
        if (kind === 'node') { visited.add(id); if (res && (i < cur || local > 0.6)) results[id] = res; }
      }
      const [kind, id] = STEPS[cur];

      const grid = new LineGrid(W, H - 1);
      for (const [eid, [corners]] of Object.entries(EDGES)) {
        const hot = kind === 'edge' && eid === id;
        grid.path(corners, { c: hot ? th.accent : undefined, arrow: true });
      }
      grid.paint(ctx, b, 0, 0, { style: 'round' });
      for (const [eid, [corners, label]] of Object.entries(EDGES)) {
        if (!label) continue;
        const [[ax, ay], [bx, by]] = corners;
        const lx = ay === by ? Math.floor((ax + bx) / 2) - Math.floor(label.length / 2) : ax + 1;
        const ly = ay === by ? ay - (eid === 'notify-build' ? 0 : 1) : Math.floor((ay + by) / 2);
        if (eid === 'notify-build') b.text(Math.floor((N.notify.cx + N.build.cx) / 2) - 2, 0, ` ${label} `, th.muted);
        else b.text(lx, ly, label, label === 'no' ? th.neg : th.pos);
      }
      for (const [nid, [x, y, w, label, decision]] of Object.entries(NODES)) {
        const here = kind === 'node' && id === nid;
        const res = results[nid];
        const color = res === 'fail' && (here || !visited.has('canary')) ? th.neg : here ? th.accent : visited.has(nid) ? th.pos : th.line;
        const mark = res === 'fail' ? `${g.cross} ` : res === 'pass' || res === 'done' ? `${g.check} ` : '';
        nodeBox(ctx, b, x, y, here || res ? `${mark}${label}` : label, {
          w, color, style: decision ? 'double' : 'round',
          fg: nid === 'rollback' ? th.muted : here ? th.ink : visited.has(nid) ? th.ink : th.muted, attr: here ? ATTR.BOLD : 0,
        });
      }
      // The token, traveling the current edge.
      if (kind === 'edge') {
        const at = along(polyline(EDGES[id][0]), local);
        if (at) b.set(at[0], at[1], u ? '●' : '@', th.accent, undefined, ATTR.BOLD);
      }
      const msg = results.promote === 'done' ? `${g.check} shipped a1f9c3e ${g.mid} 2 runs, 1 fix`
        : results.tests === 'fail' && !visited.has('canary') ? `${g.cross} unit tests failed ${g.mid} author notified` : `run #418 ${g.mid} ${kind === 'node' ? NODES[id][3].replace('?', '') : `${g.ellipsis}`}`;
      b.text(0, H - 1, fit(msg, W, undefined, ctx), results.promote === 'done' ? th.pos : msg.startsWith(g.cross) ? th.neg : th.muted);
    };
  },
};

sources.prism-term/src/facets/diagrams/gantt.js:
// A rollout Gantt chart: the "now" line sweeps the maintenance window, bars
// fill as tasks complete, and when the schema migration overruns the
// dependent tasks slide 15 minutes later.
import { ATTR, glyphs, uni, phase, ease, fit, tint } from '../callouts/_kit.js';

// [label, start, end] in minutes after midnight; index 1 overruns by SLIP.
const TASKS = [
  ['snapshot db', 60, 90], ['migrate schema', 90, 150], ['canary 5%', 150, 210], ['canary 25%', 210, 255],
  ['full rollout', 255, 330], ['verify & soak', 330, 390],
];
const MILESTONE = ['all-clear', 390];
const T0 = 60, T1 = 420, SLIP = 15;
const hhmm = (m) => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(Math.round(m % 60)).padStart(2, '0')}`;

export default {
  id: 'diagrams-gantt',
  title: 'Gantt Chart',
  category: 'Sequence & Timelines',
  description: 'A rollout Gantt chart for a maintenance window: the now-line sweeps, bars fill as tasks finish, and an overrunning migration slides every dependent task later.',
  tags: ['gantt', 'schedule', 'timeline', 'plan', 'rollout'],
  kind: 'diagram',
  size: { w: 72, h: 12 },
  minSize: { w: 54, h: 11 },
  loop: 9,
  color: '256',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 9);
      const now = T0 + Math.min(1, p / 7.5) * (T1 - T0);
      // The migration overruns once "now" reaches its planned end.
      const slipAt = (TASKS[1][2] - T0) / (T1 - T0) * 7.5;
      const slip = SLIP * ease(p, slipAt, slipAt + 0.6);
      const tasks = TASKS.map(([l, a, z], i) => (i === 1 ? [l, a, z + slip] : i > 1 ? [l, a + slip, z + slip] : [l, a, z]));
      const mile = MILESTONE[1] + slip;
      const lw = Math.min(16, Math.floor(W * 0.25)), x0 = lw + 1, cw = W - x0 - 1;
      const col = (m) => x0 + Math.round(((m - T0) / (T1 - T0)) * (cw - 1));
      // Axis.
      for (let m = T0; m <= T1; m += 60) {
        const x = col(m);
        const lab = hhmm(m);
        if (x + lab.length <= W && (m < T1 || W - x >= lab.length)) b.text(Math.min(x, W - lab.length), 0, lab, th.muted);
        b.set(x, 1, u ? '┬' : '+', th.line);
      }
      for (let x = x0; x < x0 + cw; x++) if (b.get(x, 1)?.ch === ' ') b.set(x, 1, u ? '─' : '-', th.line);
      // Bars.
      tasks.forEach(([label, a, z], i) => {
        const y = 2 + i;
        if (y >= H - 2) return;
        const state = now >= z ? 'done' : now >= a ? 'run' : 'todo';
        const late = i === 1 && slip > 0.5;
        b.text(0, y, fit(label, lw, undefined, ctx), state === 'todo' ? th.muted : th.ink, undefined, state === 'run' ? ATTR.BOLD : 0);
        const xa = col(a), xz = Math.max(xa + 1, col(z));
        for (let x = xa; x < xz; x++) {
          const m = T0 + ((x - x0) / (cw - 1)) * (T1 - T0);
          const filled = m < now;
          const over = late && m >= TASKS[1][2];
          const c = over ? th.neg : filled ? (state === 'done' ? th.pos : th.accent) : tint(ctx, th.accent, 0.55);
          b.set(x, y, u ? (filled ? '█' : '▒') : (filled ? '#' : '='), c);
        }
        if (late && xz + 5 <= W) b.text(xz + 1, y, `+${Math.round(slip)}m`, th.neg, undefined, ATTR.BOLD);
      });
      // Milestone.
      const my = 2 + tasks.length;
      if (my < H - 2) {
        b.text(0, my, fit(MILESTONE[0], lw, undefined, ctx), now >= mile ? th.pos : th.muted, undefined, ATTR.BOLD);
        b.text(col(mile), my, u ? '◆' : '<>', now >= mile ? th.pos : th.warn, undefined, ATTR.BOLD);
        if (col(mile) + 9 <= W) b.text(col(mile) + 2, my, hhmm(mile), th.dim);
      }
      // Now line.
      const nx = col(now);
      // Through the gaps only: on a bar, the fill edge already marks "now".
      for (let y = 1; y < Math.min(H - 2, my + 1); y++) {
        const cell = b.get(nx, y);
        if (y === 1 || !cell || cell.ch === ' ') b.set(nx, y, u ? (y === 1 ? '╋' : '┃') : '|', th.warn, undefined, ATTR.BOLD);
      }
      b.text(Math.max(0, Math.min(W - 5, nx - 2)), H - 2, hhmm(now), th.warn, undefined, ATTR.BOLD);
      const msg = now >= mile ? `${g.check} all-clear at ${hhmm(mile)} ${g.mid} 15m late, inside the window`
        : slip > 0.5 ? `${g.warn} migrate schema +${Math.round(slip)}m ${g.mid} all-clear now ${hhmm(mile)}`
        : `maintenance window 01:00-07:00 ${g.mid} ${tasks.filter(([, , z]) => now >= z).length}/${tasks.length} done`;
      b.text(0, H - 1, fit(msg, W, undefined, ctx), now >= mile ? th.pos : slip > 0.5 ? th.warn : th.muted);
    };
  },
};

sources.prism-term/src/facets/diagrams/git-branc:
// A branch diagram drawn left to right: main, a hotfix and a feature branch
// fork and merge as a playhead reveals history, tags riding above main.
import { ATTR, uni, phase, fit } from '../callouts/_kit.js';
import { LineGrid } from './_lines.js';

// Lanes: [name, row, color key]
const LANES = { main: ['main', 2, 'accent'], hotfix: ['hotfix/cart', 5, 'warn'], feat: ['feat/pool-size', 8, 'pos'] };
// Branches: [lane, fork at, merge at]
const BRANCHES = [['feat', 0.2, 0.76], ['hotfix', 0.4, 0.55]];
// Commits: [lane, at, hash, message, tag, merge?]
const COMMITS = [
  ['main', 0.04, '6c4f2d9', 'Split checkout worker'], ['main', 0.13, '9d02c55', 'Release v2.14.0', 'v2.14.0'],
  ['feat', 0.28, '3b8d0aa', 'Add pool wait alert'], ['main', 0.34, 'e41d7f2', 'Bump checkout deps'],
  ['feat', 0.43, '7c2e9b1', 'Size DB pool to workers'], ['hotfix', 0.47, 'c0a1b3f', 'Fix cart rounding'],
  ['main', 0.55, '5e2a9d0', 'Merge hotfix/cart', 'v2.14.1', true], ['feat', 0.63, '8f3c1e7', 'Alert on pool wait p99'],
  ['main', 0.76, 'a1f9c3e', 'Merge pull request #418', '', true], ['main', 0.88, 'b72ffed', 'Release v2.15.0', 'v2.15.0'],
];
const SWEEP = 7;

export default {
  id: 'diagrams-git-branches',
  title: 'Branch Diagram',
  category: 'Git Graphs',
  description: 'A left-to-right branch diagram: a feature branch and a hotfix fork from main, gain commits and merge back as a playhead reveals history, with release tags.',
  tags: ['git', 'branches', 'gitflow', 'merge', 'release'],
  kind: 'diagram',
  size: { w: 76, h: 11 },
  minSize: { w: 56, h: 11 },
  loop: 9,
  color: '16',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx);
      const p = phase(t, 9);
      const head = Math.min(1, p / SWEEP);
      const lw = W >= 70 ? 15 : 12;
      const x0 = lw + 1, cw = W - x0 - 2;
      const X = (f) => x0 + Math.round(f * cw);
      const grid = new LineGrid(W, H - 1);
      const mainY = LANES.main[1];
      grid.hline(x0, X(head), mainY, th[LANES.main[2]]);
      for (const [lane, fork, merge] of BRANCHES) {
        if (head < fork) continue;
        const [, y, ck] = LANES[lane], c = th[ck];
        grid.vline(X(fork), mainY, y, c);
        grid.hline(X(fork), X(Math.min(head, merge)), y, c);
        if (head >= merge) grid.vline(X(merge), mainY, y, c);
      }
      grid.paint(ctx, b, 0, 0, { style: 'round' });
      // Lane labels.
      for (const [key, [name, y, ck]] of Object.entries(LANES)) {
        const active = key === 'main' || BRANCHES.some(([l, f]) => l === key && head >= f);
        b.text(0, y, fit(name, lw, undefined, ctx), active ? th[ck] : th.dim, undefined, active ? ATTR.BOLD : 0);
      }
      // Commits and tags.
      let latest = null;
      for (const c of COMMITS) {
        const [lane, at, , , tag, merge] = c;
        if (head < at) continue;
        latest = c;
        const [, y, ck] = LANES[lane];
        const fresh = head - at < 0.06;
        b.set(X(at), y, merge ? (u ? '◉' : '@') : (u ? '●' : 'o'), fresh ? th.ink : th[ck], undefined, ATTR.BOLD);
        if (tag) b.text(Math.min(W - tag.length, X(at) - Math.floor(tag.length / 2)), y - 2, tag, th.warn, undefined, ATTR.BOLD);
        if (tag) b.set(X(at), y - 1, u ? '╷' : '|', th.warn);
      }
      // Playhead.
      if (p < SWEEP) for (let y = 0; y < H - 1; y++) if (b.get(X(head), y)?.ch === ' ') b.set(X(head), y, u ? '┊' : ':', th.dim);
      if (latest) {
        const [lane, , hash, msg] = latest;
        let x = b.text(0, H - 1, hash, th.warn);
        x = b.text(x + 1, H - 1, LANES[lane][0], th[LANES[lane][2]], undefined, ATTR.BOLD);
        b.text(x + 2, H - 1, fit(msg, Math.max(0, W - x - 2), undefined, ctx), th.ink);
      }
    };
  },
};

