// A network map learned passively from telemetry: hosts, switches and the
// gateway appear as they are first seen in incoming data (no scanning),
// links draw in once both ends are known.
import { ATTR, glyphs, uni, phase, tint, fit, stringWidth } from '../callouts/_kit.js';
import { LineGrid, nodeBox, box, tap, DIR } from './_lines.js';

// id: [label, ip, tier, column(0..5), seen at, source]
const NODES = {
  edge: ['edge-lb', '203.0.113.10', 0, 2.5, 3.3, 'access log X-Forwarded-For'],
  core: ['core-gw', '10.20.0.1', 1, 2.5, 2.0, 'default gateway in netflow'],
  swWeb: ['sw-web', '10.20.1.0/24', 2, 1, 1.2, 'subnet of web-01, web-02'],
  swData: ['sw-data', '10.20.2.0/24', 2, 4, 2.4, 'subnet of db-01'],
  web1: ['web-01', '10.20.1.11', 3, 0, 0.2, 'OTLP resource host.name'],
  web2: ['web-02', '10.20.1.12', 3, 1, 0.8, 'OTLP resource host.name'],
  web3: ['web-03', '10.20.1.13', 3, 2, 3.8, 'syslog hostname'],
  db1: ['db-01', '10.20.2.41', 3, 3, 1.6, 'postgres log peer address'],
  cache1: ['cache-01', '10.20.2.51', 3, 4, 2.8, 'redis client span peer'],
  queue1: ['queue-01', '10.20.2.61', 3, 5, 4.3, 'consumer group metadata'],
};
const LINKS = [['edge', 'core'], ['core', 'swWeb'], ['core', 'swData'], ['swWeb', 'web1'], ['swWeb', 'web2'], ['swWeb', 'web3'], ['swData', 'db1'], ['swData', 'cache1'], ['swData', 'queue1']];
const TIER_Y = [0, 4, 8, 12];

export default {
  id: 'diagrams-network-topology',
  title: 'Learned Network Map',
  category: 'Networks & Topologies',
  description: 'A network map that builds itself passively from telemetry: hosts, subnets and the gateway appear as they show up in incoming data, and links draw in.',
  tags: ['network', 'topology', 'discovery', 'subnet', 'passive'],
  kind: 'diagram',
  size: { w: 76, h: 18 },
  minSize: { w: 66, h: 18 },
  loop: 9,
  color: '256',
  order: 10,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 9);
      const colW = Math.floor(W / 6);
      const B = {};
      for (const [id, [label, , tier, col]] of Object.entries(NODES)) {
        const w = Math.min(colW - 1, stringWidth(label) + 4);
        const cx = Math.round(col * colW + colW / 2);
        B[id] = box(cx - Math.floor(w / 2), TIER_Y[tier], w, 3);
      }
      const known = (id) => p >= NODES[id][4];
      const fresh = (id) => known(id) && p < NODES[id][4] + 0.7;

      const grid = new LineGrid(W, H - 1), taps = [];
      for (const [a, z] of LINKS) {
        if (!known(a) || !known(z)) continue;
        const A = B[a], Z = B[z], c = fresh(a) || fresh(z) ? th.accent : undefined;
        // Bus on the row between tiers, tapped into both box borders.
        const my = A.y + 3;
        if (A.cx === Z.cx) grid.bits(A.cx, my, DIR.N | DIR.S, c);
        else { grid.hline(A.cx, Z.cx, my, c); grid.bits(A.cx, my, DIR.N, c); grid.bits(Z.cx, my, DIR.S, c); }
        taps.push([A.cx, A.y + 2, 'bottom', c], [Z.cx, Z.y, 'top', c]);
      }
      grid.paint(ctx, b, 0, 0, { style: 'round' });
      for (const [id, [label, ip, tier]] of Object.entries(NODES)) {
        if (!known(id)) continue;
        const bx = B[id];
        const c = fresh(id) ? th.accent : tier === 0 ? th.warn : tier < 3 ? th.info : th.line;
        nodeBox(ctx, b, bx.x, bx.y, label, { w: bx.w, color: c, bg: fresh(id) ? tint(ctx, th.accent, 0.2) : undefined, attr: fresh(id) ? ATTR.BOLD : 0 });
        // Address under hosts; beside the box for the upper tiers.
        if (tier === 3) b.text(bx.cx - Math.floor(ip.length / 2), bx.y + 3, ip, th.dim);
        else if (bx.x + bx.w + 1 + ip.length <= W) b.text(bx.x + bx.w + 1, bx.cy, ip, th.dim);
      }
      for (const [x, y, side, c] of taps) tap(ctx, b, x, y, side, c ?? th.line);
      // Learning log.
      const seen = Object.entries(NODES).filter(([id]) => known(id)).sort((a, z) => a[1][4] - z[1][4]);
      const hosts = seen.filter(([, n]) => n[2] === 3).length;
      const last = seen[seen.length - 1];
      const line = last && p < 5
        ? `${g.spark} learned ${last[1][0]} (${last[1][1]}) from ${last[1][5]}`
        : `${hosts} hosts ${g.mid} 2 subnets ${g.mid} learned passively from 2.1k events`;
      b.text(0, H - 1, fit(line, W, undefined, ctx), p < 5 ? th.accent : th.muted, undefined, p < 5 ? ATTR.BOLD : 0);
      if (!seen.length) b.text(0, H - 1, fit(`${g.ellipsis} waiting for telemetry`, W, undefined, ctx), th.dim);
    };
  },
};

sources.prism-term/src/facets/diagrams/org-chart:
// A top-down hierarchy (org chart / agent tree): mainbrain dispatches
// instructions down to its agents and findings travel back up the elbows.
import { ATTR, glyphs, uni, phase, tint, fit, stringWidth } from '../callouts/_kit.js';
import { LineGrid, nodeBox, box, polyline, along, tap } from './_lines.js';

const ROOT = 'mainbrain';
const TEAM = [
  ['collector', ['ingest', 'logs']],
  ['analyst', ['detect', 'correlate']],
  ['fixer', ['planner', 'approve']],
];
// Message script: [start, leaf index 0-5, direction 'down' | 'up', text]
const MSGS = [
  [0.2, 0, 'down', 'sample checkout spans'], [1.0, 0, 'up', '1.2k spans/s, p99 2.4s'],
  [1.8, 2, 'down', 'scan for anomalies'], [2.6, 3, 'up', 'pool wait ~ p99 (r=0.94)'],
  [3.4, 4, 'down', 'plan: pool 20 -> 40'], [4.2, 5, 'up', 'fix #142 awaiting approval'],
  [5.0, 1, 'down', 'tail checkout errors'], [5.8, 1, 'up', 'timeouts down 92%'],
];
const HOP = 0.8;

export default {
  id: 'diagrams-org-chart',
  title: 'Agent Hierarchy',
  category: 'Trees & Hierarchies',
  description: 'An org-chart style tree with elbow connectors: mainbrain sends instructions down to its agents and their findings travel back up, each hop lighting the path.',
  tags: ['org chart', 'hierarchy', 'tree', 'agents', 'elbow connectors'],
  kind: 'diagram',
  size: { w: 76, h: 16 },
  minSize: { w: 70, h: 16 },
  loop: 7,
  color: '256',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 7);
      // Leaves spread across the width; parents center over their children.
      const leaves = TEAM.flatMap(([, kids]) => kids);
      const lw = leaves.map((l) => stringWidth(l) + 4);
      const gap = Math.max(1, Math.floor((W - lw.reduce((a, c) => a + c, 0)) / (leaves.length - 1)));
      let x = Math.max(0, Math.floor((W - lw.reduce((a, c) => a + c, 0) - gap * (leaves.length - 1)) / 2));
      const L = leaves.map((name, i) => { const bx = box(x, 12, lw[i], 3); x += lw[i] + gap; return bx; });
      const P = TEAM.map(([name], i) => {
        const a = L[i * 2], z = L[i * 2 + 1];
        const w = stringWidth(name) + 4;
        return box(Math.round((a.cx + z.cx) / 2 - w / 2), 6, w, 3);
      });
      const rw = stringWidth(ROOT) + 6;
      // Root sits over the middle agent so its stem drops straight through.
      const R = box(P[1].cx - Math.floor(rw / 2), 0, rw, 3);

      // Which path is active?
      const live = MSGS.filter(([at]) => p >= at && p < at + HOP).pop();
      const grid = new LineGrid(W, H - 1);
      const edge = (from, to, my) => [from.bottom, [from.cx, my], [to.cx, my], to.top];
      P.forEach((pp, i) => {
        const hot = live && Math.floor(live[1] / 2) === i;
        grid.path(edge(R, pp, 4), { c: hot ? (live[2] === 'down' ? th.accent : th.pos) : undefined });
        [0, 1].forEach((k) => {
          const leafHot = live && live[1] === i * 2 + k;
          grid.path(edge(pp, L[i * 2 + k], 10), { c: leafHot ? (live[2] === 'down' ? th.accent : th.pos) : undefined });
        });
      });
      grid.paint(ctx, b, 0, 0, { style: 'round' });

      nodeBox(ctx, b, R.x, R.y, ROOT, { w: R.w, color: th.accent, bg: tint(ctx, th.accent, 0.15), attr: ATTR.BOLD });
      TEAM.forEach(([name], i) => {
        const hot = live && Math.floor(live[1] / 2) === i;
        nodeBox(ctx, b, P[i].x, P[i].y, name, { w: P[i].w, color: hot ? th.info : th.line, attr: hot ? ATTR.BOLD : 0 });
      });
      leaves.forEach((name, i) => {
        const hot = live && live[1] === i;
        nodeBox(ctx, b, L[i].x, L[i].y, name, { w: L[i].w, color: hot ? (live[2] === 'down' ? th.accent : th.pos) : th.line, fg: hot ? th.ink : th.muted });
      });

      // Join the connectors into the box borders.
      tap(ctx, b, R.cx, R.y + 2, 'bottom', th.accent);
      P.forEach((pp, i) => { tap(ctx, b, pp.cx, pp.y, 'top'); tap(ctx, b, pp.cx, pp.y + 2, 'bottom'); tap(ctx, b, L[i * 2].cx, L[i * 2].y, 'top'); tap(ctx, b, L[i * 2 + 1].cx, L[i * 2 + 1].y, 'top'); });
      // The message dot, root → leaf or leaf → root.
      if (live) {
        const [at, leaf, dir] = live;
        const pi = Math.floor(leaf / 2);
        const pts = [...polyline(edge(R, P[pi], 4)), ...polyline(edge(P[pi], L[leaf], 10))];
        const f = (p - at) / HOP;
        const pt = along(pts, dir === 'down' ? f : 1 - f);
        if (pt) b.set(pt[0], pt[1], u ? '●' : 'o', dir === 'down' ? th.accent : th.pos, undefined, ATTR.BOLD);
      }
      // Message log line.
      const last = MSGS.filter(([at]) => p >= at).pop();
      if (last) {
        const [, leaf, dir, text] = last;
        const who = leaves[leaf];
        const arrow = dir === 'down' ? `${ROOT} ${g.right} ${who}` : `${who} ${g.right} ${ROOT}`;
        let lx = b.text(0, H - 1, arrow, dir === 'down' ? th.accent : th.pos, undefined, ATTR.BOLD);
        b.text(lx + 2, H - 1, fit(u ? text.replace('->', '→') : text, Math.max(0, W - lx - 2), undefined, ctx), th.ink);
      }
    };
  },
};

// A CI/CD pipeline graph: build fans out to parallel test jobs, fans back in
// to staging, waits at a human approval gate, then deploys to production.
import { ATTR, glyphs, uni, phase, fit, spin } from '../callouts/_kit.js';
import { LineGrid, nodeBox, box } from './_lines.js';

// [id, label, start, end] in seconds; the approval gate waits for a human.
const JOBS = [
  ['build', 'build', 0.2, 1.5],
  ['unit', 'unit', 1.6, 2.9], ['integ', 'integ', 1.6, 3.6], ['lint', 'lint', 1.6, 2.3],
  ['staging', 'staging', 3.7, 4.9],
  ['approve', 'approve', 5.0, 6.6],
  ['prod', 'prod', 6.7, 8.0],
];
const MIN_PER_S = 55; // fake minutes:seconds shown per real second

const clock = (s) => `${Math.floor(s / 60)}m${String(Math.floor(s % 60)).padStart(2, '0')}s`;

export default {
  id: 'diagrams-pipeline',
  title: 'CI/CD Pipeline',
  category: 'Boxes & Flows',
  description: 'A pipeline graph: build fans out to parallel test jobs with spinners and timings, fans in to staging, waits at a human approval gate, then deploys to prod.',
  tags: ['pipeline', 'ci', 'cd', 'dag', 'approval'],
  kind: 'diagram',
  size: { w: 76, h: 13 },
  minSize: { w: 70, h: 13 },
  loop: 10,
  color: '256',
  order: 30,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 10);
      const state = (id) => {
        const [, , a, z] = JOBS.find((j) => j[0] === id);
        return p >= z ? 'done' : p >= a ? (id === 'approve' ? 'wait' : 'run') : 'todo';
      };
      // Layout: five columns, the test column holds three stacked jobs.
      const cw = [11, 11, 13, 13, 10];
      const gap = Math.max(3, Math.floor((W - cw.reduce((a, c) => a + c, 0)) / 4));
      const xs = [0];
      for (let i = 1; i < 5; i++) xs.push(xs[i - 1] + cw[i - 1] + gap);
      const mid = 4;
      const B = {
        build: box(xs[0], mid, cw[0], 3),
        unit: box(xs[1], 0, cw[1], 3), integ: box(xs[1], 4, cw[1], 3), lint: box(xs[1], 8, cw[1], 3),
        staging: box(xs[2], mid, cw[2], 3), approve: box(xs[3], mid, cw[3], 3), prod: box(xs[4], mid, cw[4], 3),
      };
      const fanOut = B.build.x + B.build.w + Math.floor(gap / 2), fanIn = xs[1] + cw[1] + Math.floor(gap / 2);
      const grid = new LineGrid(W, H - 1);
      const ec = (from) => (state(from) === 'done' ? th.pos : th.line);
      grid.hline(B.build.right[0], fanOut, B.build.cy, ec('build'));
      grid.vline(fanOut, B.unit.cy, B.lint.cy, ec('build'));
      for (const id of ['unit', 'integ', 'lint']) {
        grid.path([[fanOut, B[id].cy], B[id].left], { c: ec('build'), arrow: true });
        grid.path([B[id].right, [fanIn, B[id].cy]], { c: ec(id) });
      }
      const allTests = ['unit', 'integ', 'lint'].every((id) => state(id) === 'done');
      grid.vline(fanIn, B.unit.cy, B.lint.cy, allTests ? th.pos : th.line);
      grid.path([[fanIn, B.staging.cy], B.staging.left], { c: allTests ? th.pos : th.line, arrow: true });
      grid.path([B.staging.right, B.approve.left], { c: ec('staging'), arrow: true });
      grid.path([B.approve.right, B.prod.left], { c: ec('approve'), arrow: true });
      grid.paint(ctx, b, 0, 0, { style: 'round' });

      for (const [id, label, a, z] of JOBS) {
        const s = state(id), bx = B[id];
        const mark = s === 'done' ? g.check : s === 'run' ? spin(ctx, t) : s === 'wait' ? (u ? '‖' : '=') : g.ring;
        const color = s === 'done' ? th.pos : s === 'run' ? th.accent : s === 'wait' ? (Math.floor(p * 2) % 2 ? th.warn : th.line) : th.line;
        nodeBox(ctx, b, bx.x, bx.y, `${mark} ${label}`, { w: bx.w, color, fg: s === 'todo' ? th.muted : th.ink, attr: s === 'run' || s === 'wait' ? ATTR.BOLD : 0 });
        // Timing / gate note under (or beside) each box.
        const note = s === 'done' ? (id === 'approve' ? 'by you' : clock((z - a) * MIN_PER_S)) : s === 'run' ? clock((p - a) * MIN_PER_S) : s === 'wait' ? 'needs you' : '';
        const ny = bx.y + 3;
        if (note && ny < H - 1) b.text(bx.x + Math.floor((bx.w - note.length) / 2), ny, note, s === 'wait' ? th.warn : th.dim, undefined, s === 'wait' ? ATTR.BOLD : 0);
      }
      const total = clock(Math.min(p, 8) * MIN_PER_S);
      const msg = p >= 8 ? `${g.check} pipeline #2291 passed in ${total}`
        : state('approve') === 'wait' ? `${u ? '‖' : '='} waiting for approval ${g.mid} deploy v2.14.1 to prod?`
          : `${spin(ctx, t)} pipeline #2291 ${g.mid} ${total}`;
      b.text(0, H - 1, fit(msg, W, undefined, ctx), p >= 8 ? th.pos : state('approve') === 'wait' ? th.warn : th.muted, undefined, p >= 8 ? ATTR.BOLD : 0);
    };
  },
};

// A sequence diagram: lifelines for four participants, call arrows that grow
// from caller to callee, dashed returns, activation bars and a note.
import { ATTR, glyphs, uni, phase, ease, fit, clip, stringWidth } from '../callouts/_kit.js';
import { nodeBox } from './_lines.js';

const WHO = ['client', 'gateway', 'checkout', 'postgres'];
// [from, to, label, kind, start]
const MSGS = [
  [0, 1, 'POST /checkout', 'call', 0.4],
  [1, 2, 'createOrder()', 'call', 1.0],
  [2, 3, 'BEGIN; INSERT order', 'call', 1.6],
  [2, 2, 'pool 20/20 busy, waited 840ms', 'note', 2.3],
  [3, 2, 'ok 12ms', 'ret', 3.3],
  [2, 1, '201 Created', 'ret', 3.9],
  [1, 0, '201  1.12s', 'ret', 4.5],
];
const GROW = 0.35;

export default {
  id: 'diagrams-sequence',
  title: 'Sequence Diagram',
  category: 'Sequence & Timelines',
  description: 'A sequence diagram of one checkout request: call arrows grow between lifelines, activation bars mark who is busy, a note flags pool wait, returns come back dashed.',
  tags: ['sequence diagram', 'uml', 'lifeline', 'request', 'trace'],
  kind: 'diagram',
  size: { w: 72, h: 19 },
  minSize: { w: 60, h: 13 },
  loop: 9,
  color: '16',
  order: 10,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 9);
      const xs = WHO.map((_, i) => Math.floor((W / WHO.length) * (i + 0.5)));
      WHO.forEach((name, i) => {
        const w = stringWidth(name) + 4;
        nodeBox(ctx, b, xs[i] - Math.floor(w / 2), 0, name, { w, color: th.accent, attr: ATTR.BOLD });
      });
      const top = 3, rowsAvail = H - top - 1;
      const step = rowsAvail >= MSGS.length * 2 ? 2 : 1;
      const rowOf = (k) => top + 1 + k * step;
      // Lifelines.
      for (let y = top; y < H - 1; y++) xs.forEach((x) => b.set(x, y, u ? '┊' : ':', th.dim));
      // Activation bars: from a call's arrival until the matching return leaves.
      const bar = (who, y0, y1) => { for (let y = y0; y <= y1; y++) b.set(xs[who], y, u ? '┃' : '#', th.accent, undefined, ATTR.BOLD); };
      const shown = MSGS.filter((m) => p >= m[4]).length;
      const lastRow = rowOf(Math.max(0, shown - 1));
      MSGS.forEach(([from, to, , kind, at], k) => {
        if (kind !== 'call' || p < at + GROW) return;
        const ret = MSGS.findIndex((m, j) => j > k && m[3] === 'ret' && m[0] === to && m[1] === from);
        const end = ret >= 0 && p >= MSGS[ret][4] ? rowOf(ret) : lastRow;
        bar(to, rowOf(k) + (step === 2 ? 1 : 0), end + (step === 2 ? 1 : 0));
      });
      // Messages.
      MSGS.forEach(([from, to, label, kind, at], k) => {
        if (p < at) return;
        // With room, labels ride on their own row above the arrow.
        const y = rowOf(k) + (step === 2 && kind !== 'note' ? 1 : 0);
        if (y >= H - 1) return;
        if (kind === 'note') {
          const text = ` ${label} `;
          const nx = Math.max(0, Math.min(W - stringWidth(text), xs[from] - Math.floor(stringWidth(text) / 2)));
          b.text(nx, y, fit(text, W - nx, undefined, ctx), th.bg, th.warn, ATTR.BOLD);
          return;
        }
        const grow = ease(p, at, at + GROW);
        const dir = to > from ? 1 : -1;
        const x0 = xs[from] + dir, x1 = xs[to] - dir;
        const len = Math.abs(x1 - x0);
        const reach = Math.round(len * grow);
        const ch = kind === 'ret' ? (u ? '╌' : '.') : (u ? '─' : '-');
        const c = kind === 'ret' ? th.muted : th.ink;
        for (let s = 0; s <= reach; s++) b.set(x0 + dir * s, y, ch, c);
        if (grow >= 1) {
          b.set(x1, y, dir > 0 ? (u ? '▶' : '>') : (u ? '◀' : '<'), c, undefined, ATTR.BOLD);
          const lab = step === 2 ? label : ` ${label} `;
          const room = step === 2 ? len + 6 : len - 1;
          const shownLab = clip(ctx, lab, Math.max(0, room));
          const lx = Math.min(x0, x1) + Math.floor((len - stringWidth(shownLab)) / 2) + 1;
          b.text(lx, step === 2 ? y - 1 : y, shownLab, kind === 'ret' ? th.muted : th.ink, undefined, kind === 'call' ? ATTR.BOLD : 0);
        }
      });
      const done = p >= MSGS[MSGS.length - 1][4] + GROW;
      b.text(0, H - 1, fit(done ? `${g.check} 201 in 1.12s ${g.mid} 840ms of it waiting for a db connection` : `trace 4bf92f35 ${g.mid} ${shown}/${MSGS.length} spans`, W, undefined, ctx), done ? th.warn : th.muted);
    };
  },
};

