// Aurora borealis: three curtains of light whose folds and rays come from
// per-column fbm noise (cheap: noise is sampled per column, not per pixel),
// hung over a twinkling night sky and a mountain ridge with a lake reflection.
export default {
  title: 'Aurora',
  gallery: 'fx',
  category: 'Light & Sky',
  kind: 'scene',
  tags: ['aurora', 'northern lights', 'sky', 'noise'],
  order: 60,
  description: 'Northern-lights curtains with drifting rays over a twinkling sky, mountains and a mirrored lake.',
  canvas: 'field',
  palette: 'aurora',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const rand = ctx.rng;
    const { noise2, fbm } = ctx.noise;
    const { width: W, height: H, px } = cv;
    const horizon = Math.floor(H * 0.78);
    const sky = new Int32Array(W * H);
    const top = 0x02030c, low = 0x0b1630;
    for (let y = 0; y < H; y++) {
      const k = Math.min(1, y / horizon);
      const r = ((top >> 16) & 255) * (1 - k) + ((low >> 16) & 255) * k;
      const g = ((top >> 8) & 255) * (1 - k) + ((low >> 8) & 255) * k;
      const b = (top & 255) * (1 - k) + (low & 255) * k;
      sky.fill((r << 16) | (g << 8) | (b | 0), y * W, (y + 1) * W);
    }
    const stars = Array.from({ length: Math.floor(W * horizon * 0.012) }, () => ({
      x: Math.floor(rand() * W), y: Math.floor(rand() * horizon * 0.92), p: rand() * 6.28, s: 0.4 + rand() * 0.6, f: 0.5 + rand() * 2,
    }));
    // Ridged noise (1 − |n|) gives sharp peaks rather than rolling hills.
    const ridge = new Float32Array(W);
    for (let x = 0; x < W; x++) {
      const u = x / W;
      const p = 1 - Math.abs(fbm(u * 3.2, 3.1, 0, 2)) * 1.6, q = 1 - Math.abs(fbm(u * 9, 7.7, 0, 2)) * 1.8;
      ridge[x] = horizon - H * (0.03 + 0.13 * Math.max(0, p) ** 2 + 0.035 * Math.max(0, q) ** 2);
    }
    const layers = [
      { base: 0.50, amp: 0.07, len: 0.42, f: 2.2, sp: 0.05, lo: 0.62, hi: 0.9, gain: 1.5 },
      { base: 0.42, amp: 0.06, len: 0.30, f: 3.4, sp: 0.08, lo: 0.55, hi: 0.75, gain: 1.0 },
      { base: 0.32, amp: 0.05, len: 0.26, f: 1.6, sp: 0.035, lo: 0.78, hi: 1.0, gain: 0.7 },
    ];
    const lb = new Float32Array(W), li = new Float32Array(W);
    const acc = new Float32Array(W * horizon * 3);

    return (t) => {
      acc.fill(0);
      for (let L = 0; L < layers.length; L++) {
        const ly = layers[L];
        for (let x = 0; x < W; x++) {
          const u = x / W;
          const fold = fbm(u * ly.f + L * 7.3, t * ly.sp, L, 3);
          lb[x] = H * (ly.base + ly.amp * Math.sin(u * 5 + t * 0.2 + L) + fold * 0.14);
          const rays = 0.5 + 0.5 * noise2(u * 38 + t * 0.6 * (L + 1) * 0.4, t * 0.35 + L * 3);
          li[x] = Math.max(0, fold * 0.9 + 0.55) * (0.35 + rays * rays * 1.3) * ly.gain;
        }
        const c0 = pal(ly.lo), c1 = pal(ly.hi); // bright lower hem → violet crown
        const len = H * ly.len;
        for (let x = 0; x < W; x++) {
          const b = lb[x], inten = li[x];
          if (inten <= 0.01) continue;
          const y0 = Math.max(0, Math.floor(b - len)), y1 = Math.min(horizon - 1, Math.ceil(b + 3));
          for (let y = y0; y <= y1; y++) {
            const d = b - y; // >0 above the curtain's lower edge
            const a = d >= 0 ? Math.exp(-d / (len * 0.35)) * Math.min(1, d / 2 + 0.6) : Math.exp(d * 1.2);
            const k = inten * a;
            if (k < 0.004) continue;
            const m = Math.min(1, Math.max(0, d / len));
            const j = (y * W + x) * 3;
            acc[j] += (((c0 >> 16) & 255) * (1 - m) + ((c1 >> 16) & 255) * m) * k;
            acc[j + 1] += (((c0 >> 8) & 255) * (1 - m) + ((c1 >> 8) & 255) * m) * k;
            acc[j + 2] += ((c0 & 255) * (1 - m) + (c1 & 255) * m) * k;
          }
        }
      }
      for (let y = 0, i = 0; y < H; y++) {
        for (let x = 0; x < W; x++, i++) {
          if (y < horizon) {
            const s = sky[i], j = i * 3;
            const r = ((s >> 16) & 255) + acc[j], g = ((s >> 8) & 255) + acc[j + 1], b = (s & 255) + acc[j + 2];
            px[i] = y >= ridge[x] ? mountain(x, y, acc, j) : ((r > 255 ? 255 : r) << 16) | ((g > 255 ? 255 : g) << 8) | (b > 255 ? 255 : b | 0);
          } else {
            // Lake: mirror the sky above the horizon with ripple wobble and darkening.
            const d = y - horizon;
            const sx = Math.min(W - 1, Math.max(0, Math.round(x + Math.sin(d * 0.9 + t * 2.1) * (1 + d * 0.08))));
            const my = horizon - 1 - d;
            const src = my >= 0 ? px[my * W + sx] : 0;
            const k = 0.55 - (d / (H - horizon)) * 0.3;
            px[i] = ((((src >> 16) & 255) * k) << 16) | ((((src >> 8) & 255) * k) << 8) | (((src & 255) * k) | 0);
          }
        }
      }
      for (const s of stars) {
        if (s.y >= ridge[s.x]) continue;
        const tw = s.s * (0.55 + 0.45 * Math.sin(t * s.f + s.p));
        cv.add(s.x, s.y, ((tw * 200) << 16) | ((tw * 210) << 8) | (tw * 255 | 0));
      }
      cv.paint(ctx.buffer);
    };

    function mountain(x, y, acc, j) {
      // Ridge silhouette, rim-lit by whatever aurora light falls just above it.
      const edge = y - ridge[x];
      const rim = edge < 1.5 ? 0.5 : 0.06;
      const r = 6 + acc[j] * rim, g = 8 + acc[j + 1] * rim, b = 16 + acc[j + 2] * rim;
      return ((r > 255 ? 255 : r) << 16) | ((g > 255 ? 255 : g) << 8) | (b > 255 ? 255 : b | 0);
    }
  },
};

sources.prism-term/src/facets/fx/burning-ship.js:
// The Burning Ship fractal (z → (|Re z| + i|Im z|)² + c), flipped upright and
// colored like its name. The camera breathes from the whole hull down into
// the little ship riding the antenna off its bow and back, on a log-scale zoom.
export default {
  title: 'Burning Ship',
  gallery: 'fx',
  category: 'Fractals',
  kind: 'scene',
  tags: ['burning ship', 'fractal', 'escape time', 'zoom', 'fire'],
  order: 50,
  description: 'The Burning Ship fractal in flame colors, breathing from the whole hull down to the little ship on its antenna.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: 30,
  canvas: 'field',
  palette: 'fire',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 1024 });
    const { width: W, height: H, px, aspect } = cv;
    const C0 = [-0.5, -0.5], W0 = 3.4;                // the whole hull
    const C1 = [-1.755, -0.03], W1 = 0.12;            // the little ship on the bow's antenna
    const inside = ctx.theme.bg;
    return (t) => {
      const s = 0.5 - 0.5 * Math.cos(((t % 30) / 30) * Math.PI * 2);
      const w = W0 * Math.pow(W1 / W0, s);
      const k = (w - W1) / (W0 - W1);                  // zooms toward the target point
      const cx = C1[0] + (C0[0] - C1[0]) * k, cy = C1[1] + (C0[1] - C1[1]) * k;
      const unit = w / Math.min(W, (H * aspect) * 1.6);
      const maxIt = Math.round(70 + 110 * s);
      for (let y = 0, i = 0; y < H; y++) {
        const ci = cy + (y - H / 2 + 0.5) * aspect * unit;
        for (let x = 0; x < W; x++, i++) {
          const cr = cx + (x - W / 2 + 0.5) * unit;
          let zr = 0, zi = 0, n = 0, r2 = 0, i2 = 0;
          while (n < maxIt) {
            r2 = zr * zr; i2 = zi * zi;
            if (r2 + i2 > 64) break;
            zi = Math.abs(2 * zr * zi) + ci;
            zr = r2 - i2 + cr;
            n++;
          }
          if (n >= maxIt) { px[i] = inside; continue; }
          const mu = n + 1 - Math.log(Math.log(r2 + i2) * 0.5) / Math.LN2;
          const v = Math.min(1, Math.pow(mu / maxIt, 0.42) * 1.15);
          px[i] = pal(v);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/caustics.js:
// The bottom of a swimming pool on a sunny day: tiles and grout bent by the
// moving surface, overlaid with the bright network of caustics — light focused
// where the surface's wave crests act as lenses. Two noise layers drift
// against each other; caustic lines live where their sum crosses zero.
import { lerpc, clamp01 } from '../retro/_kit.js';

export default {
  title: 'Pool Caustics',
  gallery: 'fx',
  category: 'Fire & Water',
  kind: 'scene',
  tags: ['caustics', 'pool', 'water', 'light', 'refraction', 'summer', 'tiles'],
  order: 100,
  description: 'A sunlit pool floor: tiles bent by the moving surface under a dancing network of bright caustic light.',
  size: { w: 72, h: 24 },
  minSize: { w: 16, h: 6 },
  loop: 16,
  canvas: 'field',
  palette: 'ocean',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { noise3 } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const S = Math.min(W, H * aspect);
    const tile = Math.max(4, S / 5);
    const water = pal(0.42), deep = pal(0.28), light = pal(0.95), grout = lerpc(pal(0.22), 0x000000, 0.2);
    // The three noise fields are smooth, so on big canvases they're evaluated on a
    // coarse lattice and interpolated; tile edges and ridges stay per-pixel.
    const g = W * H > 9000 ? 2 : 1;
    const GW = Math.ceil(W / g) + 2, GH = Math.ceil(H / g) + 2;
    const OX = new Float32Array(GW * GH), OY = new Float32Array(GW * GH), NN = new Float32Array(GW * GH);
    const lerp2 = (A, x, y) => {
      const gx = x / g, gy = y / g, ix = gx | 0, iy = gy | 0, fx = gx - ix, fy = gy - iy, j = iy * GW + ix;
      return (A[j] * (1 - fx) + A[j + 1] * fx) * (1 - fy) + (A[j + GW] * (1 - fx) + A[j + GW + 1] * fx) * fy;
    };
    return (t) => {
      const u = (t / 16) * Math.PI * 2;
      const ca = Math.cos(u), sa = Math.sin(u);
      for (let gy = 0; gy < GH; gy++) for (let gx = 0; gx < GW; gx++) {
        const vx = (gx * g + 0.5) / S, vy = ((gy * g + 0.5) * aspect) / S, j = gy * GW + gx;
        OX[j] = noise3(vx * 2.2 + ca * 0.4, vy * 2.2, sa * 0.4 + 1) * 0.06;
        OY[j] = noise3(vx * 2.2, vy * 2.2 + sa * 0.4, ca * 0.4 + 5) * 0.06;
        NN[j] = noise3(vx * 3.1 + ca * 0.7, vy * 3.1 + sa * 0.7, 0.5) + noise3(vx * 3.7 - sa * 0.6, vy * 3.7 + ca * 0.6, 7.5) * 0.8 + noise3(vx * 5.3 + sa, vy * 5.3 - ca, 3.1) * 0.35;
      }
      for (let y = 0, i = 0; y < H; y++) {
        const vy = ((y + 0.5) * aspect) / S;
        for (let x = 0; x < W; x++, i++) {
          const vx = (x + 0.5) / S;
          // Refraction wobble for the tiles.
          const gx = ((vx + lerp2(OX, x, y)) * S) / tile, gy = ((vy + lerp2(OY, x, y)) * S) / tile;
          const fx = gx - Math.floor(gx), fy = gy - Math.floor(gy);
          const line = Math.min(fx, 1 - fx, fy, 1 - fy) * tile;
          let c = lerpc(deep, water, 0.5 + 0.5 * Math.sin(Math.floor(gx) * 1.7 + Math.floor(gy) * 2.3) * 0.3);
          if (line < Math.max(0.6, tile * 0.07)) c = grout;
          // Caustic network: sharp ridges where drifting noise layers cancel.
          const ridge = Math.pow(clamp01(1 - Math.abs(lerp2(NN, x, y)) * 3.2), 3);
          c = lerpc(c, light, Math.min(0.85, ridge * 0.95));
          px[i] = c;
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/crt-static.js:
// Between channels on an old CRT: snow, a darker hum bar crawling up the
// tube, scanlines and a vignette — then the set catches a station for a beat,
// a test card rolls into lock with the channel number, and it's gone again.
import { lerpc, clamp01, hash2 } from '../retro/_kit.js';

const LOOP = 12;

export default {
  title: 'CRT Static',
  gallery: 'fx',
  category: 'Glitch & Noise',
  kind: 'scene',
  tags: ['static', 'snow', 'crt', 'tv', 'noise', 'analog', 'channel'],
  order: 40,
  description: 'Between channels on an old CRT: snow, a crawling hum bar and scanlines, until a test card rolls into lock.',
  size: { w: 64, h: 20 },
  minSize: { w: 16, h: 6 },
  loop: LOOP,
  canvas: 'field',
  setup(ctx) {
    const cv = ctx.canvas();
    const b = ctx.buffer;
    const { theme } = ctx;
    const { width: W, height: H, px, aspect } = cv;
    const tint = lerpc(0xffffff, theme.info, 0.12);
    // A simple test card: bars, a gray ramp, a circle with a cross.
    const card = (x, y) => {
      const u = x / W, v = y / H;
      const dx = (u - 0.5) * W, dy = (v - 0.5) * H * aspect, r = Math.hypot(dx, dy), R = Math.min(W, H * aspect) * 0.36;
      if (Math.abs(r - R) < 0.9 || (r < R && (Math.abs(dx) < 0.6 || Math.abs(dy) < 0.6))) return 0xffffff;
      if (v > 0.38 && v < 0.62 && r < R) return lerpc(0x101010, 0xf0f0f0, Math.floor(u * 8) / 7);
      if (v < 0.5) return [0xb0b0b0, 0xb0b000, 0x00b0b0, 0x00b000, 0xb000b0, 0xb00000, 0x0000b0][Math.min(6, Math.floor(u * 7))];
      return [0x0000b0, 0x101010, 0xb000b0, 0x101010, 0x00b0b0, 0x101010, 0xb0b0b0][Math.min(6, Math.floor(u * 7))];
    };
    return (t) => {
      const lt = t % LOOP, frame = Math.floor(t * 30);
      // Station lock: fades in from 6.0 s, rolls into place, holds, drops at 8.4 s.
      const lock = lt > 6 && lt < 8.4 ? clamp01((lt - 6) * 3) * clamp01((8.4 - lt) * 5) : 0;
      const roll = lt > 6 ? Math.floor(Math.max(0, 1 - (lt - 6) * 1.4) * H * 1.5) : 0;
      const hum = ((-lt / 3) % 1 + 1) % 1 * H * 1.4 - H * 0.2;
      for (let y = 0, i = 0; y < H; y++) {
        const bar = Math.exp(-Math.pow((y - hum) / (H * 0.12), 2));
        const scan = y % 2 ? 0.86 : 1;
        for (let x = 0; x < W; x++, i++) {
          let v = hash2(x, y, frame);
          v = v * v * 0.9 + (hash2(x >> 1, y, frame + 99) > 0.97 ? 0.4 : 0);
          let c = lerpc(0x000000, tint, clamp01(v) * (1 - bar * 0.45) * scan);
          if (lock > 0) c = lerpc(c, card(x, (y + roll) % H), lock * (0.9 - bar * 0.2) * scan);
          // Vignette toward the tube's corners.
          const vx = (x / W - 0.5) * 2, vy = (y / H - 0.5) * 2;
          px[i] = lerpc(c, 0x000000, clamp01((vx * vx + vy * vy - 0.55) * 0.55));
        }
      }
      cv.paint(b);
      if (lock > 0.5) b.text(Math.max(1, ctx.width - 7), 1, 'CH 03', theme.pos);
      else if (ctx.width >= 24) b.text(Math.max(1, ctx.width - 7), 1, `CH ${String(2 + (Math.floor(lt / 1.5) % 11)).padStart(2, '0')}`, lerpc(theme.pos, 0x000000, 0.3));
    };
  },
};

sources.prism-term/src/facets/fx/fire.js:
// Old-school fire: each pixel averages the heat beneath it (drifting with a
// gusting wind) minus a scrolling cooling map, which tears the rising heat into
// tongues of flame; a flickering fuel bed feeds it and embers spiral off the top.
export default {
  title: 'Fire',
  gallery: 'fx',
  category: 'Fire & Water',
  kind: 'scene',
  tags: ['fire', 'doom', 'embers', 'heat'],
  order: 20,
  description: 'Classic demoscene fire — heat rises, averages and cools through a scrolling noise map, throwing embers on the wind.',
  canvas: 'field',
  palette: 'fire',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const rand = ctx.rng;
    const { noise3 } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const heat = new Float32Array(W * (H + 2)); // two extra rows = fuel bed
    const rate = 32 * Math.max(1, H / 70);   // simulation steps (rows of rise) per second
    // Cooling texture, seamlessly tiled vertically so it can scroll forever.
    const CH = H * 2;
    const cool = new Float32Array(W * CH);
    const strength = ctx.param('height', 1);
    const base = 255 / Math.max(10, H * 0.62 * strength);
    for (let y = 0; y < CH; y++)
      for (let x = 0; x < W; x++) {
        const f = (yy) => {
          const n = noise3(x * 0.19, yy * 0.075 * aspect, 0.5) * 0.5 + 0.5;
          return n * n;
        };
        const k = y / CH;
        cool[y * W + x] = base * (0.35 + 2.3 * (f(y) * (1 - k) + f(y + CH) * k));
      }
    const embers = [];
    let acc = 0, scroll = 0, steps = 0;

    const step = (t) => {
      const fuel = H * W;
      for (let x = 0; x < W; x++) {
        const n = noise3(x * 0.05, t * 1.3, 2.7);
        const v = 205 + n * 150 + (rand() - 0.5) * 70;
        heat[fuel + x] = v < 0 ? 0 : v > 255 ? 255 : v;
        heat[fuel + W + x] = heat[fuel + x];
      }
      scroll = (scroll + 1) % CH;
      for (let y = 0; y < H; y++) {
        const wind = noise3(y * 0.04, t * 0.35, 9.1) * 1.8 + Math.sin(t * 0.5) * 0.6;
        const shift = wind > 0.5 ? 1 : wind < -0.5 ? -1 : 0;
        const r1 = (y + 1) * W, r2 = (y + 2) * W;
        const cr = ((y + scroll) % CH) * W;
        for (let x = 0; x < W; x++) {
          const xs = x - shift;
          const a = xs > 0 ? xs - 1 : 0, b = xs < 0 ? 0 : xs >= W ? W - 1 : xs, c = xs + 1 < W ? xs + 1 : W - 1;
          const v = (heat[r1 + a] + heat[r1 + b] + heat[r1 + c] + heat[r2 + b]) * 0.25 - cool[cr + x];
          heat[y * W + x] = v > 0 ? v : 0;
        }
      }
      if (rand() < 0.3 * Math.max(1, W / 80)) {
        embers.push({ x: rand() * W, y: H * (0.55 + rand() * 0.3), vx: (rand() - 0.5) * 8, vy: -(12 + rand() * 20) * Math.max(1, H / 60), life: 1, p: rand() * 6 });
      }
      steps++;
    };

    return (t, dt) => {
      acc += dt * rate;
      let n = 0;
      while (acc >= 1 && n < 4) { step(t); acc -= 1; n++; }
      if (acc > 4) acc = 0;
      if (steps === 0) for (let k = 0; k < H; k++) step(t); // start with flames already up

      for (let i = 0; i < W * H; i++) {
        const h = heat[i];
        px[i] = h < 10 ? -1 : pal(h / 255);
      }
      for (let i = embers.length - 1; i >= 0; i--) {
        const e = embers[i];
        e.x += (e.vx + Math.sin(t * 2.5 + e.p) * 6) * dt;
        e.y += e.vy * dt;
        e.life -= dt * 0.6;
        if (e.life <= 0 || e.y < 0) { embers.splice(i, 1); continue; }
        cv.set(e.x, e.y, pal(0.45 + e.life * 0.5));
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/fractal-tree.js:
// A recursive blossom tree: ten generations of branches, each a little shorter
// and thinner, swaying more the further they are from the trunk. Blossoms at
// the tips, petals drifting down on the wind.
import { lerpc, hash2 } from '../retro/_kit.js';

const LOOP = 16;

export default {
  title: 'Blossom Tree',
  gallery: 'fx',
  category: 'Fractals',
  kind: 'scene',
  tags: ['tree', 'fractal', 'recursive', 'l-system', 'blossom', 'sakura', 'wind'],
  order: 70,
  description: 'A recursive blossom tree swaying in the wind — ten generations of branches, blooming tips and drifting petals.',
  size: { w: 64, h: 24 },
  minSize: { w: 20, h: 8 },
  loop: LOOP,
  canvas: 'line',
  palette: 'candy',
  params: { depth: { default: 10, min: 5, max: 12, label: 'Generations' } },
  setup(ctx) {
    const cv = ctx.canvas('line');
    const pal = ctx.palette();
    const { theme } = ctx;
    const { width: PW, height: PH, aspect } = cv;
    const depth = Math.max(5, Math.min(12, Math.round(ctx.param('depth', 10))));
    const bark = lerpc(0x6b4a2e, theme.ink, 0.15), twig = lerpc(0x9a7a5a, theme.ink, 0.2);
    const blossom = [pal(0), pal(0.15), lerpc(pal(0), 0xffffff, 0.5)];
    const ground = lerpc(theme.bg, theme.pos, 0.35);
    const len0 = Math.min(PH * 0.3 * aspect, PW * 0.2);
    const petals = Array.from({ length: Math.round(PW * 0.25) }, (_, i) => ({ x: hash2(i, 1), ph: hash2(i, 2), sp: 1 + Math.floor(hash2(i, 3) * 2), c: blossom[i % 3] }));
    return (t) => {
      cv.clear();
      const u = (t / LOOP) * Math.PI * 2;
      const wind = Math.sin(u) * 0.6 + Math.sin(u * 3 + 1) * 0.25;
      // Ground line with a little grass.
      const gy = PH - 1;
      for (let x = 0; x < PW; x++) { cv.set(x, gy, ground); if (hash2(x, 5) < 0.3) cv.set(x, gy - 1, ground); }
      const tips = [];
      const grow = (x, y, ang, len, d, seed) => {
        const sway = wind * 0.035 * (depth - d + 1) * (1 + 0.3 * Math.sin(u * 2 + seed));
        const a = ang + sway;
        const x2 = x + Math.sin(a) * len, y2 = y - (Math.cos(a) * len) / aspect;
        const thick = Math.max(1, Math.round((d / depth) ** 2 * 3.2));
        const c = d > depth * 0.5 ? bark : twig;
        for (let o = 0; o < thick; o++) cv.line(x + o - (thick >> 1), y, x2 + o - (thick >> 1), y2, c);
        if (d <= 1) { tips.push([x2, y2, seed]); return; }
        const spread = 0.42 + 0.08 * Math.sin(seed * 3.1);
        const shrink = 0.72 + 0.06 * hash2(seed, d);
        grow(x2, y2, a - spread, len * shrink, d - 1, seed * 2 + 1);
        grow(x2, y2, a + spread * 0.9, len * (shrink - 0.03), d - 1, seed * 2 + 2);
      };
      grow(PW / 2, gy - 1, 0, len0, depth, 1);
      for (const [x, y, s] of tips) {
        const c = blossom[s % 3];
        cv.set(x, y, c); cv.set(x + 1, y, c); cv.set(x, y - 1, c);
        if (hash2(s, 7) < 0.5) cv.set(x - 1, y + 1, c);
      }
      // Petals: each falls on its own loop, sliding with the wind.
      for (const p of petals) {
        const f = ((t / LOOP) * p.sp + p.ph) % 1;
        const y = PH * 0.15 + f * PH * 0.85;
        const x = (p.x * PW + f * PW * 0.25 + Math.sin(f * 12 + p.ph * 9) * PW * 0.02 + wind * PW * 0.03 * f) % PW;
        cv.set(x, y, p.c);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/god-rays.js:
// Crepuscular rays through a forest: the low sun behind swaying canopy and
// trunks, its light marched pixel by pixel back toward the sun through the
// gaps, so shafts of light fan out through the haze. Dust motes drift in them.
import { lerpc, clamp01, hash2 } from '../retro/_kit.js';

const LOOP = 20, STEPS = 14;

export default {
  title: 'God Rays',
  gallery: 'fx',
  category: 'Light & Sky',
  kind: 'scene',
  tags: ['god rays', 'crepuscular', 'volumetric', 'light shafts', 'forest', 'sun', 'haze'],
  order: 90,
  description: 'Volumetric light: the low sun behind a swaying forest canopy, shafts fanning through the gaps and dust drifting in them.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 8 },
  loop: LOOP,
  canvas: 'field',
  palette: 'gold',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const occ = new Float32Array(W * H);                      // 1 = blocked, 0 = open sky
    const trunks = Array.from({ length: Math.max(3, Math.round(W / 9)) }, (_, i) => ({ x: (i + 0.3 + hash2(i, 1) * 0.4) * (W / Math.max(3, Math.round(W / 9))), w: 1 + hash2(i, 2) * Math.max(1, W / 40), lean: (hash2(i, 3) - 0.5) * 0.15 }));
    const motes = Array.from({ length: Math.round(W * H * 0.008) }, (_, i) => [hash2(i, 4), hash2(i, 5), hash2(i, 6)]);
    const haze = pal(0.45), dark = lerpc(pal(0.04), 0x000000, 0.4), sunC = pal(0.98);
    const emit = new Float32Array(W * H);
    // The canopy noise is smooth: on big canvases it's computed every other pixel.
    const g = W * H > 9000 ? 2 : 1, GW = Math.ceil(W / g) + 1, GH = Math.ceil(H / g) + 1;
    const leafG = new Float32Array(GW * GH), lightG = new Float32Array(GW * GH);
    return (t) => {
      const u = (t / LOOP) * Math.PI * 2;
      const sunX = W * (0.5 + 0.08 * Math.sin(u)), sunY = H * 0.2;
      for (let gy = 0; gy < GH; gy++) for (let gx = 0; gx < GW; gx++) {
        const x = gx * g, y = gy * g, sway = Math.sin(u + y * 0.1) * 1.5;
        leafG[gy * GW + gx] = fbm((x + sway) * 0.06, y * aspect * 0.06, Math.cos(u) * 0.3 + Math.sin(u) * 0.3, 3);
      }
      // Occluders: a canopy thickest at the top with gaps, trunks, the forest floor.
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
        const v = y / H, gx = x / g, gy = y / g, ix = gx | 0, iy = gy | 0, fx = gx - ix, fy = gy - iy, j = iy * GW + ix;
        const leaf = (leafG[j] * (1 - fx) + leafG[j + 1] * fx) * (1 - fy) + (leafG[j + GW] * (1 - fx) + leafG[j + GW + 1] * fx) * fy;
        let o = clamp01((leaf + 0.2 - v * 0.6) * 5);
        if (v > 0.86) o = 1;
        occ[y * W + x] = o;
      }
      for (const tr of trunks) for (let y = Math.floor(H * 0.2); y < H; y++) {
        const cx = tr.x + (y - H) * tr.lean;
        for (let dx = 0; dx < tr.w; dx++) { const x = Math.round(cx + dx); if (x >= 0 && x < W) occ[y * W + x] = 1; }
      }
      // Only open sky near the sun emits; marching toward the sun smears it into shafts.
      for (let y = 0, i = 0; y < H; y++) for (let x = 0; x < W; x++, i++) {
        const d = Math.hypot((x - sunX) / W, ((y - sunY) * aspect) / W);
        emit[i] = (1 - occ[i]) * Math.pow(clamp01(1 - d / 0.55), 2.2);
      }
      // The light march runs on the same lattice — shafts are smooth along their length.
      for (let gy = 0; gy < GH; gy++) for (let gx = 0; gx < GW; gx++) {
        const x = Math.min(W - 1, gx * g), y = Math.min(H - 1, gy * g);
        const dx = (sunX - x) / STEPS, dy = (sunY - y) / STEPS;
        let light = 0, sx = x, sy = y, w = 1;
        for (let s = 0; s < STEPS; s++) {
          const ix = sx | 0, iy = sy | 0;
          if (ix >= 0 && iy >= 0 && ix < W && iy < H) light += emit[iy * W + ix] * w;
          sx += dx; sy += dy; w *= 0.95;
        }
        lightG[gy * GW + gx] = light / 4.7;
      }
      for (let y = 0, i = 0; y < H; y++) for (let x = 0; x < W; x++, i++) {
        const gx = x / g, gy = y / g, ix = gx | 0, iy = gy | 0, fx = gx - ix, fy = gy - iy, j = iy * GW + ix;
        const light = (lightG[j] * (1 - fx) + lightG[j + 1] * fx) * (1 - fy) + (lightG[j + GW] * (1 - fx) + lightG[j + GW + 1] * fx) * fy;
        const d = Math.hypot((x - sunX) / W, ((y - sunY) * aspect) / W);
        const open = 1 - occ[i];
        let c = lerpc(dark, haze, open * 0.4 * (1 - y / H));            // dim far forest air
        c = lerpc(c, haze, clamp01(light * 1.1));                         // the shafts
        c = lerpc(c, sunC, clamp01(light * 1.6 - 0.6));
        c = lerpc(c, sunC, clamp01(1 - d * 11) * open);                   // the sun's disc
        px[i] = c;
      }
      // Dust motes catching the light inside the shafts.
      for (const [mx, my, k] of motes) {
        const x = (mx * W + Math.sin(u + k * 9) * 3 + W) % W, y = ((((my + (t / LOOP) * (k > 0.5 ? 1 : -1)) % 1) + 1) % 1) * H * 0.85;
        const i = Math.floor(y) * W + Math.floor(x);
        cv.blend(x, y, sunC, clamp01((((px[i] >> 8) & 255) - 90) / 120) * 0.7);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/interference.js:
// Ripple-tank interference: three point sources on slow Lissajous orbits, each
// sending out concentric waves. Where crests meet they reinforce, where crest
// meets trough they cancel — the moiré of nodal lines sweeps as sources move.
import { lerpc } from '../retro/_kit.js';

export default {
  title: 'Interference',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['interference', 'waves', 'moire', 'ripple tank', 'physics', 'rings'],
  order: 60,
  description: 'A ripple tank: three orbiting sources whose concentric waves reinforce and cancel into sweeping moiré nodal lines.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: 20,
  canvas: 'field',
  palette: 'ocean',
  params: {
    sources: { default: 3, min: 2, max: 5, label: 'Sources' },
    wavelength: { default: 1, min: 0.4, max: 3, label: 'Wavelength' },
  },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 512 });
    const { width: W, height: H, px, aspect } = cv;
    const n = Math.max(2, Math.min(5, Math.round(ctx.param('sources', 3))));
    const S = Math.min(W, H * aspect);
    const k = (Math.PI * 2) / (Math.max(5, S * 0.17) * ctx.param('wavelength', 1));
    const src = Array.from({ length: n }, (_, i) => ({ a: 1 + (i % 3), b: 2 + ((i + 1) % 2), ph: i * 2.1, r: 0.22 + 0.06 * i }));
    const pos = new Float32Array(n * 2);
    const omega = (Math.PI * 2) / 1.25;   // a crest every 1.25 s
    const node = lerpc(ctx.theme.bg, pal(0), 0.5);
    return (t) => {
      const u = (t / 20) * Math.PI * 2;
      src.forEach((s, i) => {
        pos[i * 2] = W / 2 + Math.sin(u * s.a + s.ph) * W * s.r * 1.2;
        pos[i * 2 + 1] = (H * aspect) / 2 + Math.cos(u * s.b + s.ph * 0.7) * H * aspect * s.r;
      });
      const wt = omega * t;
      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y + 0.5) * aspect;
        for (let x = 0; x < W; x++, i++) {
          let v = 0;
          for (let j = 0; j < n; j++) {
            const dx = x + 0.5 - pos[j * 2], dy = vy - pos[j * 2 + 1];
            const d = Math.sqrt(dx * dx + dy * dy);
            v += Math.sin(d * k - wt) / (1 + d * 0.012);
          }
          v /= n;
          // Amplitude picks the color; near-zero (the nodal lines) falls into shadow.
          const a = Math.abs(v);
          px[i] = lerpc(node, pal(0.5 + v * 0.55), Math.min(1, a * 2.4));
        }
      }
      // Bright dots at the sources themselves.
      for (let j = 0; j < n; j++) cv.set(pos[j * 2], pos[j * 2 + 1] / aspect, 0xffffff);
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/kaleidoscope.js:
// A kaleidoscope: a slowly flowing field of interleaved waves and noise, folded
// through mirrored wedges around the center and turning — the classic tube,
// with a soft vignette like the eyepiece.
import { lerpc } from '../retro/_kit.js';

export default {
  title: 'Kaleidoscope',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['kaleidoscope', 'mirror', 'symmetry', 'mandala', 'psychedelic', 'polar'],
  order: 90,
  description: 'A turning kaleidoscope: a flowing field folded through mirrored wedges into a mandala, with an eyepiece vignette.',
  size: { w: 72, h: 24 },
  minSize: { w: 16, h: 6 },
  loop: 24,
  canvas: 'field',
  palette: 'prism',
  params: { segments: { default: 6, min: 3, max: 12, label: 'Mirrors' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 512 });
    const { noise3 } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const seg = Math.max(3, Math.min(12, Math.round(ctx.param('segments', 6))));
    const wedge = Math.PI / seg;
    const R = Math.min(W, H * aspect) / 2;
    const bg = ctx.theme.bg;
    return (t) => {
      const u = (t / 24) * Math.PI * 2;
      const rot = u, flow = Math.sin(u) * 0.8;
      for (let y = 0, i = 0; y < H; y++) {
        const dy = ((y + 0.5) * aspect - (H * aspect) / 2) / R;
        for (let x = 0; x < W; x++, i++) {
          const dx = (x + 0.5 - W / 2) / R;
          const r = Math.sqrt(dx * dx + dy * dy);
          if (r > 1.11) { px[i] = bg; continue; }
          // Fold the angle into one mirrored wedge.
          let a = Math.atan2(dy, dx) + rot;
          a = ((a % (2 * wedge)) + 2 * wedge) % (2 * wedge);
          if (a > wedge) a = 2 * wedge - a;
          const fx = Math.cos(a) * r * 2.2, fy = Math.sin(a) * r * 2.2;
          const n = noise3(fx * 1.3 + flow, fy * 1.3, Math.cos(u) * 0.6 + 2) * 1.4;
          const v = Math.sin(fx * 3.1 + Math.sin(fy * 4.2 + u) + n * 2) + Math.sin(fy * 5.3 - u * 2 + n);
          const band = (v * 0.25 + r * 0.4 - t / 24 + 10) % 1;
          const light = 0.55 + 0.45 * Math.cos(v * 2.4);
          let c = lerpc(bg, pal(band), light);
          if (r > 0.86) c = lerpc(c, bg, Math.min(1, (r - 0.86) * 4));
          px[i] = c;
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/lava-lamp.js:
// Lava lamps on a shelf: wax blobs warm at the bulb, rise, cool, stretch and
// sink again — metaballs inside a tapered glass, lit from below, with the
// metal cap and base. One lamp when narrow, a row of three when there's room.
import { lerpc, clamp01 } from '../retro/_kit.js';

const LOOP = 30;

export default {
  title: 'Lava Lamp',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['lava lamp', 'metaballs', 'wax', 'blobs', 'retro', '1970s', 'groovy'],
  order: 80,
  description: 'Lava lamps on a shelf: metaball wax warms at the bulb, rises, stretches and sinks inside tapered glass lit from below.',
  size: { w: 64, h: 24 },
  minSize: { w: 16, h: 8 },
  loop: LOOP,
  canvas: 'field',
  palette: 'magma',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 512 });
    const rand = ctx.rng;
    const { theme } = ctx;
    const { width: W, height: H, px, aspect } = cv;
    const count = W / (H * aspect) > 1.05 ? 3 : 1;
    const lamps = Array.from({ length: count }, (_, i) => {
      const cx = W * ((i + 0.5) / count);
      const half = Math.min((W / count) * 0.34, H * aspect * 0.15);
      const hue = count === 1 ? 0 : [0.08, 0, 0.16][i];
      return {
        cx, half, hue,
        top: H * 0.05, cap: H * 0.17, bot: H * 0.8, base: H * 0.97,
        blobs: Array.from({ length: 5 }, (_, j) => ({ ph: rand(), sp: 1 + (j % 3), sw: rand() * 6.28, r: 0.26 + rand() * 0.2 })),
      };
    });
    const wall = lerpc(theme.bg, theme.panel, 0.6);
    const metal = [0x3a3a46, 0x8a8a9e, 0xd8d8e8];
    // Glass radius at height v (0 = top of glass, 1 = bottom): a tall tapered rocket shape.
    const radius = (v) => (0.5 + 0.5 * v) * Math.sqrt(Math.min(1, v * 12, (1 - v) * 14 + 0.3));
    return (t) => {
      // Back wall with a warm pool of light behind each lamp.
      for (let y = 0, i = 0; y < H; y++) for (let x = 0; x < W; x++, i++) px[i] = wall;
      for (const L of lamps) {
        const liquid = pal(0.18 + L.hue), waxLo = pal(0.62 + L.hue), waxHi = pal(0.9 + L.hue * 0.5);
        for (let y = 0; y < H; y++) for (let x = Math.max(0, Math.floor(L.cx - L.half * 3.2)); x < Math.min(W, L.cx + L.half * 3.2); x++) {
          const dx = (x + 0.5 - L.cx) / (L.half * 3.2), dy = (y - L.bot) / H;
          px[y * W + x] = lerpc(px[y * W + x], waxLo, clamp01(0.22 - (dx * dx + dy * dy) * 0.3));
        }
        // Blob centers: each rides a slow heat cycle, rising from the bulb and sinking back.
        const bl = L.blobs.map((b) => {
          const ph = ((t / LOOP) * b.sp + b.ph) % 1;
          const rise = 0.5 - 0.5 * Math.cos(ph * Math.PI * 2);
          return { x: Math.sin(((t * Math.PI * 2) / LOOP) * b.sp + b.sw) * 0.35, y: 0.93 - rise * 0.86, r: b.r * (0.75 + 0.35 * Math.sin(ph * Math.PI * 4 + b.sw)) };
        });
        const gh = L.bot - L.cap;
        for (let y = Math.floor(L.cap); y < Math.ceil(L.bot); y++) {
          const v = (y + 0.5 - L.cap) / gh, rw = L.half * radius(v);
          for (let x = Math.max(0, Math.floor(L.cx - rw)); x < Math.min(W, Math.ceil(L.cx + rw)); x++) {
            const lx = (x + 0.5 - L.cx) / L.half, ux = (x + 0.5 - L.cx) / rw;
            let f = 0;
            for (const b of bl) {
              const dx = lx - b.x, dy = ((v - b.y) * gh * aspect) / L.half;
              f += (b.r * b.r) / (dx * dx + dy * dy + 0.02);
            }
            f += Math.max(0, (v - 0.93) * 14) * 1.2;           // the molten pool on the bottom
            const glow = clamp01(v * 0.6 + 0.1);               // lit from the bulb below
            let c = lerpc(liquid, waxLo, glow * 0.25);
            if (f > 1) {
              const core = clamp01((f - 1) * 0.6);
              c = lerpc(waxLo, waxHi, core * (0.55 + 0.45 * glow));
            } else if (f > 0.8) c = lerpc(c, waxLo, (f - 0.8) / 0.2 * 0.6);
            // Glass: a highlight down the left, darkening at the rim.
            const rim = Math.abs(ux);
            if (rim > 0.82) c = lerpc(c, 0x000000, (rim - 0.82) * 2.2);
            if (ux > -0.62 && ux < -0.48) c = lerpc(c, 0xffffff, 0.22);
            px[y * W + x] = c;
          }
        }
        // Cap and base: brushed metal cones.
        const metalAt = (u) => (u < -0.3 ? lerpc(metal[0], metal[1], (u + 1) / 0.7) : u < 0.25 ? lerpc(metal[1], metal[2], (u + 0.3) / 0.55) : lerpc(metal[2], metal[0], (u - 0.25) / 0.75));
        for (let y = Math.floor(L.top); y < Math.ceil(L.cap); y++) {
          const k = (y - L.top) / (L.cap - L.top), rw = L.half * (0.3 + 0.13 * k);
          for (let x = Math.floor(L.cx - rw); x < L.cx + rw; x++) if (x >= 0 && x < W) px[y * W + x] = metalAt((x + 0.5 - L.cx) / rw);
        }
        for (let y = Math.floor(L.bot); y < Math.min(H, Math.ceil(L.base)); y++) {
          const k = (y - L.bot) / (L.base - L.bot), rw = L.half * (0.5 + 0.55 * Math.sin(k * Math.PI * 0.6 + 0.35));
          for (let x = Math.floor(L.cx - rw); x < L.cx + rw; x++) if (x >= 0 && x < W) px[y * W + x] = metalAt((x + 0.5 - L.cx) / rw);
        }
      }
      // The shelf.
      for (let y = Math.floor(H * 0.97); y < H; y++) px.fill(lerpc(theme.panel, 0x000000, 0.3), y * W, (y + 1) * W);
      cv.paint(ctx.buffer);
    };
  },
};

