// A thunderstorm over the hills: rolling cloud decks, slanting rain, and every
// few seconds a forked bolt built by midpoint displacement — it flickers two or
// three times, lighting the clouds from inside and the land beneath.
import { lerpc, clamp01, hash2 } from '../retro/_kit.js';

const LOOP = 24, EVERY = 3;

function bolt(k, W, top, bottom) {
  // Midpoint displacement from cloud base to ground, plus a few forks.
  let seed = 0;
  const r = () => hash2(k, seed++, 77);
  const x0 = W * (0.15 + r() * 0.7);
  let pts = [[x0, top], [x0 + (r() - 0.5) * W * 0.25, bottom]];
  for (let pass = 0; pass < 6; pass++) {
    const out = [pts[0]];
    for (let i = 1; i < pts.length; i++) {
      const [ax, ay] = pts[i - 1], [bx, by] = pts[i];
      const len = Math.hypot(bx - ax, by - ay);
      out.push([(ax + bx) / 2 + (r() - 0.5) * len * 0.55, (ay + by) / 2 + (r() - 0.5) * len * 0.1], pts[i]);
    }
    pts = out;
  }
  const forks = [];
  for (let f = 0; f < 3; f++) {
    const start = pts[Math.floor((0.15 + r() * 0.5) * pts.length)];
    let [x, y] = start;
    const dir = r() < 0.5 ? -1 : 1, seg = [];
    seg.push([x, y]);
    for (let i = 0; i < 10; i++) { x += dir * (0.6 + r() * 2.2); y += 0.8 + r() * 2.4; seg.push([x, y]); }
    forks.push(seg);
  }
  return { main: pts, forks, x: x0 };
}

export default {
  title: 'Thunderstorm',
  gallery: 'fx',
  category: 'Light & Sky',
  kind: 'scene',
  tags: ['lightning', 'storm', 'thunder', 'rain', 'clouds', 'weather', 'bolt'],
  order: 70,
  description: 'A thunderstorm: rolling clouds, slanting rain and forked bolts that flicker, lighting the clouds from inside.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 8 },
  loop: LOOP,
  canvas: 'field',
  palette: 'ice',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const base = Math.floor(H * 0.42), ground = H * 0.82;
    // Cloud deck, tiled horizontally so it can roll forever.
    const cloud = new Float32Array(W * H);
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      const k = x / W, f = (xx) => fbm(xx * 0.035, y * aspect * 0.06, 1.7, 5);
      cloud[y * W + x] = (f(x) * (1 - k) + f(x - W) * k) * 0.5 + 0.5;
    }
    const hills = new Float32Array(W);
    for (let x = 0; x < W; x++) hills[x] = ground + (Math.sin(x * 0.07 + 1) * 0.5 + Math.sin(x * 0.19) * 0.25) * H * 0.05;
    const drops = Array.from({ length: Math.round(W * H * 0.012) }, (_, i) => [hash2(i, 1), hash2(i, 2), 1 + Math.floor(hash2(i, 3) * 2)]);
    const skyDark = lerpc(pal(0.1), 0x000000, 0.2), cloudLit = pal(0.85), cloudDim = pal(0.34), boltC = 0xf4f8ff, glowC = pal(0.7);
    const land = lerpc(0x0a0f0a, pal(0.1), 0.3);
    let cacheK = -1, cache = null;
    return (t) => {
      const lt = t % LOOP;
      const k = Math.floor(lt / EVERY), at = k * EVERY + hash2(k, 5) * 0.8, age = lt - at;
      // Flash envelope: two or three quick pulses.
      let flash = 0;
      if (age >= 0 && age < 0.6) {
        const pulses = 2 + Math.floor(hash2(k, 6) * 2);
        for (let p = 0; p < pulses; p++) { const pt = p * 0.13, d = age - pt; if (d >= 0 && d < 0.09) flash = Math.max(flash, 1 - d / 0.09); }
        flash = Math.max(flash, Math.max(0, 0.25 - age * 0.4));
      }
      if (k !== cacheK) { cacheK = k; cache = bolt(k, W, base * 0.9, ground); }
      const roll = (lt / LOOP) * W;
      for (let y = 0, i = 0; y < H; y++) for (let x = 0; x < W; x++, i++) {
        const cv0 = cloud[y * W + (Math.floor(x + roll) % W)];
        const depth = clamp01(1 - y / (base * 1.4));
        let c = lerpc(skyDark, cloudDim, clamp01((cv0 - 0.3) * 2.4) * (0.55 + depth * 0.45));
        if (flash > 0) {
          const near = Math.exp(-Math.pow((x - cache.x) / (W * 0.25), 2));
          c = lerpc(c, cloudLit, flash * clamp01(cv0 * 1.3 - 0.2) * (0.25 + 0.75 * near) * (0.4 + 0.6 * clamp01(1.6 - y / base)));
        }
        if (y >= hills[x]) c = lerpc(land, pal(0.5), flash * 0.25);
        px[i] = c;
      }
      // Rain: short slanting streaks, brighter during a flash.
      const rainC = lerpc(cloudDim, cloudLit, 0.25 + flash * 0.5);
      for (const [rx, ry, sp] of drops) {
        const y = ((ry + (lt / LOOP) * 12 * sp) % 1) * H, x = (rx * W + y * 0.35) % W;
        for (let j = 0; j < 2; j++) cv.blend(x - j * 0.35, y - j, rainC, 0.6);
      }
      // The bolt.
      if (age >= 0 && age < 0.55 && flash > 0.05) {
        const draw = (pts, c, w) => { for (let i = 1; i < pts.length; i++) { cv.line(pts[i - 1][0], pts[i - 1][1], pts[i][0], pts[i][1], c); if (w) cv.line(pts[i - 1][0] + 1, pts[i - 1][1], pts[i][0] + 1, pts[i][1], lerpc(glowC, c, 0.4)); } };
        for (const f of cache.forks) draw(f, lerpc(glowC, boltC, flash * 0.7), false);
        draw(cache.main, lerpc(glowC, boltC, 0.5 + flash * 0.5), true);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/mandelbrot.js:
// Endless Mandelbrot dive into Seahorse Valley with smooth (normalized
// iteration count) coloring. The zoom breathes in and out on a log scale, and
// the iteration cap adapts to the work done last frame so cost stays bounded.
// `--set set=julia` swaps in an animated Julia set.
export default {
  title: 'Mandelbrot Dive',
  gallery: 'fx',
  category: 'Fractals',
  kind: 'scene',
  tags: ['mandelbrot', 'julia', 'fractal', 'zoom'],
  order: 40,
  description: 'Continuous zoom into Seahorse Valley with smooth iteration coloring; --set set=julia for a morphing Julia set.',
  canvas: 'field',
  palette: 'magma',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 1024 });
    const julia = ctx.param('set', 'mandelbrot') === 'julia';
    const period = ctx.param('period', 36);
    const { width: W, height: H, px, aspect } = cv;
    const FX = -0.743643887037151, FY = 0.13182590420533;
    const maxLog = Math.log(julia ? 6 : 3e4);
    const budget = 3.6e6; // iterations per frame (~6 ms)
    const inside = ctx.theme.bg;
    let cap = 220;

    return (t) => {
      const phase = (t % period) / period;
      const zoom = Math.exp(maxLog * (1 - Math.cos(phase * Math.PI * 2)) / 2);
      const want = Math.min(900, Math.floor(90 + 110 * Math.log10(zoom)));
      const maxIt = Math.max(24, Math.min(want, cap));
      const unit = (julia ? 3.1 : 3.0) / (Math.min(W, H * aspect) * zoom);
      const rot = julia ? 0 : phase * Math.PI * 2;
      const cr = Math.cos(rot), sr = Math.sin(rot);
      // Julia c walks the main cardioid's boundary (c = e^iθ/2 − e^2iθ/4), where the
      // sets are connected and most intricate.
      const jt = t * 0.12 + 1.2;
      const jr = 0.5 * Math.cos(jt) - 0.25 * Math.cos(2 * jt), ji = 0.5 * Math.sin(jt) - 0.25 * Math.sin(2 * jt);
      const cx0 = julia ? 0 : FX, cy0 = julia ? 0 : FY;
      const shift = t * 0.015;
      let work = 0;

      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y - H / 2 + 0.5) * aspect * unit;
        for (let x = 0; x < W; x++, i++) {
          const vx = (x - W / 2 + 0.5) * unit;
          const ox = cx0 + vx * cr - vy * sr, oy = cy0 + vx * sr + vy * cr;
          let zr, zi, ar, ai;
          if (julia) { zr = ox; zi = oy; ar = jr; ai = ji; }
          else {
            zr = 0; zi = 0; ar = ox; ai = oy;
            // Skip the main cardioid and period-2 bulb outright.
            const q = (ox - 0.25) * (ox - 0.25) + oy * oy;
            if (q * (q + (ox - 0.25)) <= 0.25 * oy * oy || (ox + 1) * (ox + 1) + oy * oy <= 0.0625) { px[i] = inside; continue; }
          }
          let n = 0, r2 = 0, i2 = 0;
          while (n < maxIt) {
            r2 = zr * zr; i2 = zi * zi;
            if (r2 + i2 > 256) break;
            zi = 2 * zr * zi + ai;
            zr = r2 - i2 + ar;
            n++;
          }
          work += n;
          if (n >= maxIt) { px[i] = inside; continue; }
          const mu = n + 1 - Math.log(Math.log(r2 + i2) * 0.5) / Math.LN2;
          const s = Math.log2(Math.max(1, mu) + 1) * 0.3 + shift;
          px[i] = pal(1 - Math.abs(((s % 2) + 2) % 2 - 1));
        }
      }
      // Steer next frame's cap toward the budget (deterministic: depends only on content).
      if (work > budget) cap = Math.max(24, Math.floor(cap * 0.85));
      else if (work < budget * 0.6) cap = Math.min(900, Math.ceil(cap * 1.08) + 1);
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/matrix.js:
// Digital rain with real glyphs: halfwidth katakana, digits and symbols fall
// in per-column streams. Every lit cell decays at its stream's own rate, so
// trail lengths vary; heads burn white, glyphs mutate as they fade, and dimmer
// slow columns read as a second, more distant layer.
const KATAKANA = Array.from({ length: 0xff9d - 0xff66 + 1 }, (_, i) => String.fromCodePoint(0xff66 + i));
const UNICODE_GLYPHS = [...KATAKANA, ...'0123456789', ...'=+-*<>:."|¦_'];
const ASCII_GLYPHS = [...'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$%&*+=-<>?'];

export default {
  title: 'Digital Rain',
  gallery: 'fx',
  category: 'Glitch & Noise',
  kind: 'scene',
  tags: ['matrix', 'digital rain', 'katakana', 'hacker'],
  order: 20,
  description: 'Matrix digital rain in real halfwidth katakana — white-hot heads, per-column speeds and trail lengths, mutating glyphs.',
  canvas: 'ascii',
  palette: 'matrix',
  setup(ctx) {
    const W = ctx.width, H = ctx.height;
    const rand = ctx.rng;
    const pal = ctx.palette();
    const speedK = ctx.param('speed', 1);
    const glyphs = ctx.caps.unicode === false || ctx.mode === 'ascii' ? ASCII_GLYPHS : UNICODE_GLYPHS;
    const pick = () => glyphs[Math.floor(rand() * glyphs.length)];
    const N = W * H;
    const I = new Float32Array(N); // intensity 0..1
    const R = new Float32Array(N); // decay rate (1/s) of the stream that last lit the cell
    const G = new Array(N);
    for (let i = 0; i < N; i++) G[i] = pick();
    const head = new Uint8Array(N);
    // Column depth: a dim, slow back layer and a bright, fast front layer.
    const depth = new Float32Array(W);
    for (let x = 0; x < W; x++) depth[x] = rand() < 0.35 ? 0.35 + rand() * 0.25 : 0.75 + rand() * 0.25;

    const D = W + Math.ceil(W * 0.4 * Math.min(1, H / 30));
    const dc = new Int32Array(D), dy = new Float32Array(D), dv = new Float32Array(D), dl = new Float32Array(D);
    const respawn = (d, initial) => {
      dc[d] = d < W ? d : Math.floor(rand() * W);
      const z = depth[dc[d]];
      dv[d] = (5 + rand() * 18) * (0.45 + z * 0.75);
      dl[d] = 5 + rand() * Math.max(6, H * 0.9);
      dy[d] = initial ? rand() * H * 1.4 - H * 0.4 : -rand() * H * 0.6;
    };
    for (let d = 0; d < D; d++) respawn(d, true);

    let mutateAcc = 0;
    return (t, dt) => {
      // Decay every lit cell at its stream's rate.
      for (let i = 0; i < N; i++) {
        head[i] = 0;
        if (I[i] > 0) { I[i] *= Math.exp(-R[i] * dt); if (I[i] < 0.02) I[i] = 0; }
      }
      // Advance drops, lighting every cell the head passed this frame.
      for (let d = 0; d < D; d++) {
        const x = dc[d], v = dv[d] * speedK;
        const y0 = Math.floor(dy[d]);
        dy[d] += v * dt;
        const y1 = Math.floor(dy[d]);
        const rate = (Math.log(40) * v) / dl[d];
        for (let y = Math.max(0, y0); y <= Math.min(H - 1, y1); y++) {
          const i = y * W + x;
          I[i] = 1; R[i] = rate;
          if (y !== y0) G[i] = pick();
        }
        if (y1 >= 0 && y1 < H) head[y1 * W + x] = 1;
        if (dy[d] - dl[d] > H) respawn(d, false);
      }
      // Glyph mutation: a few percent of lit cells flicker to new symbols per second.
      mutateAcc += N * 0.05 * dt;
      while (mutateAcc >= 1) { mutateAcc--; const i = Math.floor(rand() * N); if (I[i] > 0) G[i] = pick(); }

      const buf = ctx.buffer;
      for (let y = 0, i = 0; y < H; y++) {
        for (let x = 0; x < W; x++, i++) {
          const v = I[i];
          if (v <= 0) continue;
          if (head[i]) buf.set(x, y, G[i], pal(1), undefined, depth[x] > 0.7 ? 1 : 0);
          else buf.set(x, y, G[i], pal(0.12 + 0.82 * Math.pow(v, 0.65) * depth[x]));
        }
      }
    };
  },
};

sources.prism-term/src/facets/fx/metaballs.js:
// Metaballs: an inverse-square field from orbiting blobs. Color is the
// field-weighted blend of each ball's palette hue, so merging blobs mix
// smoothly; the iso-surface gets a hot rim and the outside a soft halo.
export default {
  title: 'Metaballs',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['metaballs', 'blobs', 'isosurface', 'glow'],
  order: 50,
  description: 'Orbiting metaballs that merge with blended hues, a glowing iso-contour rim and soft halo.',
  canvas: 'field',
  palette: 'candy',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const rand = ctx.rng;
    const count = Math.max(2, Math.min(12, ctx.param('count', 6)));
    const { width: W, height: H, px, aspect } = cv;
    const S = Math.min(W, H * aspect);
    const balls = Array.from({ length: count }, (_, i) => {
      const c = pal(i / count);
      return {
        r: S * (0.1 + rand() * 0.06),
        ax: 0.25 + rand() * 0.2, ay: 0.22 + rand() * 0.18,
        fx: 0.3 + rand() * 0.5, fy: 0.25 + rand() * 0.5, p: rand() * 6.28,
        cr: (c >> 16) & 255, cg: (c >> 8) & 255, cb: c & 255,
        x: 0, y: 0, r2: 0,
      };
    });
    const bg = ctx.theme.bg;
    const bR = (bg >> 16) & 255, bG = (bg >> 8) & 255, bB = bg & 255;

    return (t) => {
      for (const b of balls) {
        b.x = W / 2 + Math.sin(t * b.fx + b.p) * W * b.ax * 0.95;
        b.y = (H * aspect) / 2 + Math.cos(t * b.fy + b.p * 1.3) * H * aspect * b.ay * 0.95;
        const pulse = 1 + 0.12 * Math.sin(t * 1.7 + b.p);
        b.r2 = b.r * b.r * pulse * pulse;
      }
      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y + 0.5) * aspect;
        for (let x = 0; x < W; x++, i++) {
          let f = 0, r = 0, g = 0, bl = 0;
          for (let k = 0; k < count; k++) {
            const b = balls[k];
            const dx = x + 0.5 - b.x, dy = vy - b.y;
            const w = b.r2 / (dx * dx + dy * dy + 1);
            f += w; r += b.cr * w; g += b.cg * w; bl += b.cb * w;
          }
          r /= f; g /= f; bl /= f;
          let k, wh;
          if (f >= 1) {
            const e = Math.min(1, (f - 1) * 3);       // 0 at the rim → 1 deep inside
            const rim = Math.exp(-(f - 1) * (f - 1) * 90);
            k = 0.55 + 0.45 * e;
            wh = rim * 0.7;
          } else {
            const halo = f * f * f;
            k = halo * 0.55;
            wh = Math.exp(-(f - 1) * (f - 1) * 260) * 0.35;
          }
          const rr = bR * (1 - Math.min(1, k)) + r * k + (255 - r) * wh;
          const gg = bG * (1 - Math.min(1, k)) + g * k + (255 - g) * wh;
          const bb = bB * (1 - Math.min(1, k)) + bl * k + (255 - bl) * wh;
          px[i] = ((rr > 255 ? 255 : rr) << 16) | ((gg > 255 ? 255 : gg) << 8) | (bb > 255 ? 255 : bb | 0);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/nebula.js:
// Deep field: a domain-warped emission nebula with dark dust lanes, painted
// once into a texture larger than the screen, then slowly turned and breathed
// through. Twinkling stars in front, a few bright ones with diffraction spikes.
import { lerpc, clamp01, hash2 } from '../retro/_kit.js';

const LOOP = 40;

export default {
  title: 'Nebula',
  gallery: 'fx',
  category: 'Light & Sky',
  kind: 'scene',
  tags: ['nebula', 'space', 'stars', 'cosmos', 'galaxy', 'deep field', 'ambient'],
  order: 80,
  description: 'A domain-warped emission nebula with dust lanes, slowly turning, with twinkling stars and diffraction spikes.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: LOOP,
  canvas: 'field',
  palette: 'magma',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 512 });
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const VH = H * aspect;
    // Texture in visual units: a square that covers the screen at any rotation.
    // It's smooth, so it's painted at most 200 texels across and sampled bilinearly.
    const T = Math.ceil(Math.hypot(W, VH) * 1.15), S = Math.min(W, VH);
    const N = Math.min(T, 200), q = T / N;
    const R = new Float32Array(N * N), G = new Float32Array(N * N), B = new Float32Array(N * N);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
      const u = ((x * q) / S) * 1.6, v = ((y * q) / S) * 1.6;
      const wx = fbm(u + 3.1, v + 1.7, 0.5, 4), wy = fbm(u - 2.3, v + 4.4, 1.5, 4);
      const gas = fbm(u + wx * 1.4, v + wy * 1.4, 2.5, 5) * 0.5 + 0.5;
      const dust = clamp01(fbm(u * 2.2 + wy, v * 2.2 - wx, 7.5, 4) * 1.8 + 0.1);
      const glow = Math.pow(clamp01(gas * 1.25 - 0.18), 1.6);
      const c = pal(clamp01(glow * 0.95 + 0.04));
      const o = lerpc(c, 0x000000, clamp01(dust * 0.85) * clamp01(glow * 2)), j = y * N + x;
      R[j] = (o >> 16) & 255; G[j] = (o >> 8) & 255; B[j] = o & 255;
    }
    const sample = (tx, ty) => {
      const fx = Math.min(N - 1.001, Math.max(0, tx / q)), fy = Math.min(N - 1.001, Math.max(0, ty / q));
      const ix = fx | 0, iy = fy | 0, ax = fx - ix, ay = fy - iy, j = iy * N + ix;
      const w00 = (1 - ax) * (1 - ay), w10 = ax * (1 - ay), w01 = (1 - ax) * ay, w11 = ax * ay;
      const r = R[j] * w00 + R[j + 1] * w10 + R[j + N] * w01 + R[j + N + 1] * w11;
      const g = G[j] * w00 + G[j + 1] * w10 + G[j + N] * w01 + G[j + N + 1] * w11;
      const b = B[j] * w00 + B[j + 1] * w10 + B[j + N] * w01 + B[j + N + 1] * w11;
      return (r << 16) | (g << 8) | b;
    };
    const stars = Array.from({ length: Math.round(W * H * 0.02) }, (_, i) => [hash2(i, 1), hash2(i, 2), hash2(i, 3)]);
    const bright = Array.from({ length: Math.max(2, Math.round((W * H) / 900)) }, (_, i) => [hash2(i, 11) * W, hash2(i, 12) * H, hash2(i, 13)]);
    return (t) => {
      const u = (t / LOOP) * Math.PI * 2;
      const rot = Math.sin(u) * 0.12, zoom = 1 + 0.06 * Math.sin(u * 2 + 1);
      const cr = Math.cos(rot) / zoom, sr = Math.sin(rot) / zoom;
      const ox = T / 2 + Math.cos(u) * S * 0.04, oy = T / 2 + Math.sin(u) * S * 0.03;
      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y + 0.5) * aspect - VH / 2;
        for (let x = 0; x < W; x++, i++) {
          const vx = x + 0.5 - W / 2;
          px[i] = sample(ox + vx * cr - vy * sr, oy + vx * sr + vy * cr);
        }
      }
      for (const [sx, sy, k] of stars) {
        const tw = 0.55 + 0.45 * Math.sin((t * Math.PI * 2 * (1 + Math.floor(k * 4))) / 8 + k * 50);
        cv.add(sx * W, sy * H, lerpc(0x000000, k > 0.7 ? 0xbfd8ff : 0xfff0d8, tw * (0.35 + k * 0.6)));
      }
      for (const [bx, by, k] of bright) {
        const tw = 0.75 + 0.25 * Math.sin((t * Math.PI * 2) / 4 + k * 20);
        const c = lerpc(0x000000, 0xffffff, tw), arm = Math.max(2, Math.round(Math.min(W, H) * 0.05));
        cv.set(bx, by, 0xffffff);
        for (let d = 1; d <= arm; d++) {
          const a = tw * (1 - d / (arm + 1));
          cv.blend(bx + d, by, c, a); cv.blend(bx - d, by, c, a);
          cv.blend(bx, by + d / aspect, c, a); cv.blend(bx, by - d / aspect, c, a);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

// Newton's method as art: every point is a guess that slides toward one of a
// polynomial's roots. Color says which root it reaches, shade says how fast.
// The roots orbit and breathe, so the fractal basin boundaries writhe.
import { lerpc } from '../retro/_kit.js';

export default {
  title: 'Newton Basins',
  gallery: 'fx',
  category: 'Fractals',
  kind: 'scene',
  tags: ['newton', 'fractal', 'basins', 'roots', 'complex', 'polynomial'],
  order: 60,
  description: "Newton's method basins for a polynomial whose roots orbit and breathe — color by root, shade by speed.",
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: 24,
  canvas: 'field',
  palette: 'prism',
  params: { roots: { default: 3, min: 3, max: 6, label: 'Roots' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { width: W, height: H, px, aspect } = cv;
    const n = Math.max(3, Math.min(6, Math.round(ctx.param('roots', 3))));
    const colors = Array.from({ length: n }, (_, k) => pal(k / n));
    const dark = lerpc(ctx.theme.bg, 0x000000, 0.4);
    const rr = new Float64Array(n), ri = new Float64Array(n);
    const MAX = 28;
    return (t) => {
      const u = (t / 24) * Math.PI * 2;
      for (let k = 0; k < n; k++) {
        const a = (k / n) * Math.PI * 2 + u * 0.5, m = 1 + 0.28 * Math.sin(u * (k % 2 ? 1 : 2) + k);
        rr[k] = Math.cos(a) * m; ri[k] = Math.sin(a) * m;
      }
      const unit = 3.4 / Math.min(W, H * aspect * 1.4);
      for (let y = 0, i = 0; y < H; y++) {
        const y0 = (y - H / 2 + 0.5) * aspect * unit;
        for (let x = 0; x < W; x++, i++) {
          let zr = (x - W / 2 + 0.5) * unit, zi = y0, it = 0, hit = -1, near = 1;
          for (; it < MAX; it++) {
            // z ← z − 1 / Σ 1/(z − r_k)
            let sr = 0, si = 0;
            for (let k = 0; k < n; k++) {
              const dr = zr - rr[k], di = zi - ri[k], d = dr * dr + di * di;
              if (d < 1e-6) { hit = k; near = d; break; }
              sr += dr / d; si -= di / d;
            }
            if (hit >= 0) break;
            const s2 = sr * sr + si * si;
            if (s2 < 1e-12) break;
            zr -= sr / s2; zi += si / s2;
          }
          if (hit < 0) { px[i] = dark; continue; }
          // Smooth the iteration count with the last step's distance.
          const f = (it + Math.log(-Math.log(near + 1e-12) + 1) * 0.1) / MAX;
          px[i] = lerpc(colors[hit], dark, Math.min(0.92, Math.pow(f, 0.55) * 1.05));
        }
      }
      // Root markers.
      for (let k = 0; k < n; k++) cv.set(W / 2 + rr[k] / unit, H / 2 + ri[k] / unit / aspect, 0xffffff);
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/ocean-waves.js:
// Open sea at sunset, looking toward the horizon. Every water pixel is a
// point on a sum-of-waves height field seen in perspective: its normal
// reflects the sky (more of it at grazing angles), and where it tilts toward
// the low sun the glitter path flickers. Distant waves fade so nothing aliases.
import { lerpc, clamp01 } from '../retro/_kit.js';

const WAVES = [
  [0.9, 0.42, 0.55, 1.0], [-0.6, 0.8, 0.9, 0.55], [0.2, 1, 1.7, 0.3], [-0.95, 0.3, 2.9, 0.16], [0.7, -0.7, 4.3, 0.09],
].map(([dx, dz, k, a]) => {
  // Deep-water dispersion (ω = √gk), rounded so every wave repeats over the 20 s loop.
  const l = Math.hypot(dx, dz), w = Math.max(1, Math.round((Math.sqrt(9.8 * k) * 1.2 * 20) / (2 * Math.PI))) * ((2 * Math.PI) / 20);
  return { dx: dx / l, dz: dz / l, k, a, w };
});

export default {
  title: 'Ocean at Sunset',
  gallery: 'fx',
  category: 'Fire & Water',
  kind: 'scene',
  tags: ['ocean', 'sea', 'waves', 'sunset', 'reflection', 'glitter', 'water'],
  order: 80,
  description: 'Open sea at sunset in perspective: a height field of waves reflecting the sky, with a flickering sun-glitter path.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: 20,
  canvas: 'field',
  palette: 'sunset',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 512 });
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const hz = Math.floor(H * 0.42);
    const sunX = W * 0.5, sunR = Math.min(W * 0.09, hz * aspect * 0.5);
    const sky = (e) => pal(clamp01(0.86 - e * 1.9));                 // elevation 0 = horizon
    const deep = lerpc(pal(0.04), 0x000814, 0.4);
    const clouds = new Float32Array(W * hz);
    // Cloud bands, tiled horizontally (two fbm copies cross-faded) so they can drift forever.
    for (let y = 0; y < hz; y++) for (let x = 0; x < W; x++) {
      const k = x / W, f = (xx) => fbm(xx * 0.03, y * aspect * 0.22, 3.3, 4);
      clouds[y * W + x] = clamp01((f(x) * (1 - k) + f(x - W) * k) * 1.6 - 0.05) * clamp01((y / hz) * 1.6 - 0.15);
    }
    const focal = W * 0.6, camH = 2.2;
    return (t) => {
      const drift = (t / 20) * W;
      // Sky: gradient, banks of cloud lit from below, and a sun sitting on the horizon.
      for (let y = 0; y < hz; y++) {
        const e = (hz - y) / (H * 0.9);
        for (let x = 0; x < W; x++) {
          let c = sky(e);
          const dx = x + 0.5 - sunX, dy = (y + 0.5 - hz + sunR * 0.35 / aspect) * aspect, d = Math.hypot(dx, dy);
          if (d < sunR) c = lerpc(pal(0.97), pal(0.85), clamp01(dy / sunR + 0.5));
          else c = lerpc(c, pal(0.9), clamp01(1 - (d - sunR) / (sunR * 2.5)) * 0.35);
          const cl = clouds[y * W + (Math.floor(x + drift) % W)];
          if (cl > 0) c = lerpc(c, lerpc(pal(0.25), pal(0.75), clamp01(1 - e * 2.5)), Math.min(0.5, cl * 0.7));
          px[y * W + x] = c;
        }
      }
      // Sea.
      for (let y = hz; y < H; y++) {
        const r = y - hz + 0.5, z = (camH * focal) / (r * aspect);
        const fade = clamp01(1 - z / 140);                            // far waves average out to flat
        for (let x = 0; x < W; x++) {
          const wx = ((x + 0.5 - W / 2) * z) / focal;
          let sx = 0, sz = 0, h = 0;
          for (const wv of WAVES) {
            const lod = clamp01(1.4 - (z * wv.k) / 60);
            if (lod <= 0) continue;
            const ph = (wx * wv.dx + z * wv.dz) * wv.k - wv.w * t;
            const a = wv.a * lod * fade;
            h += Math.sin(ph) * a;
            const g = Math.cos(ph) * a * wv.k;
            sx += g * wv.dx; sz += g * wv.dz;
          }
          // Normal, view ray, reflection.
          let nx = -sx * 0.22, ny = 1, nz = -sz * 0.22;
          const nl = Math.hypot(nx, ny, nz); nx /= nl; ny /= nl; nz /= nl;
          let vx = wx, vy = -camH, vz = z;
          const vl = Math.hypot(vx, vy, vz); vx /= vl; vy /= vl; vz /= vl;
          const dn = vx * nx + vy * ny + vz * nz;
          const ry = vy - 2 * dn * ny, rx = vx - 2 * dn * nx;
          const fres = 0.25 + 0.75 * Math.pow(1 - Math.max(0, -dn), 4);
          let c = lerpc(deep, sky(Math.min(0.42, Math.max(0, ry) * 0.7)), fres);
          // Sun glitter: reflections that point back at the low sun.
          const toSun = Math.max(0, 1 - Math.hypot((rx - (sunX - W / 2) / focal) * 1.6, ry - 0.04) * 6);
          if (toSun > 0) c = lerpc(c, pal(0.98), Math.min(1, Math.pow(toSun, 2.5) * 2.6));
                    px[y * W + x] = c;
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/pixel-sort.js:
// Pixel sorting, the glitch-art staple: a sunset scene whose rows are sorted
// by brightness wherever they fall inside a moving threshold window — but only
// within drifting bands, so the clean image and the smeared streaks alternate.
import { lerpc, clamp01 } from '../retro/_kit.js';

const LOOP = 16;
const lum = (c) => ((c >> 16) & 255) * 0.3 + ((c >> 8) & 255) * 0.59 + (c & 255) * 0.11;

export default {
  title: 'Pixel Sort',
  gallery: 'fx',
  category: 'Glitch & Noise',
  kind: 'scene',
  tags: ['pixel sort', 'glitch', 'databend', 'melt', 'sort', 'glitch art'],
  order: 50,
  description: 'Glitch-art pixel sorting: a sunset whose rows sort by brightness inside a moving threshold, in drifting smeared bands.',
  size: { w: 80, h: 24 },
  minSize: { w: 16, h: 6 },
  loop: LOOP,
  canvas: 'field',
  palette: 'sunset',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    // The source: sky, sun, ridge and a lake — painted once.
    const src = new Int32Array(W * H), L = new Float32Array(W * H);
    const hz = Math.floor(H * 0.62), sunR = Math.min(W * 0.14, hz * aspect * 0.55);
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      const ridge = hz - H * (0.06 + 0.12 * Math.abs(fbm(x * 0.03, 0.5, 0, 3)) * 2.2);
      let c;
      if (y < hz) {
        c = pal(0.1 + (y / hz) * 0.75);
        const cl = clamp01(fbm(x * 0.045, y * aspect * 0.16, 4.2, 4) * 2.2 + 0.1);   // banks of cloud
        c = lerpc(c, cl > 0.5 ? pal(0.92) : pal(0.12), Math.abs(cl - 0.5) * 0.9);
        const d = Math.hypot(x + 0.5 - W * 0.62, (y + 0.5 - hz * 0.62) * aspect);
        if (d < sunR) c = lerpc(pal(0.98), pal(0.85), d / sunR);
        if (y > ridge) c = lerpc(pal(0.06), 0x000000, 0.3);
      } else {
        const my = 2 * hz - y, ripple = Math.sin(y * 1.7) * 0.5 + 0.5;
        c = lerpc(pal(0.1 + (my / hz) * 0.75), pal(0.04), 0.25 + ((y - hz) / (H - hz)) * 0.3 + ripple * 0.2);
        if (Math.abs(x + 0.5 - W * 0.62) < sunR * (0.9 - (y - hz) / (H - hz) * 0.4) * (0.6 + 0.4 * ripple)) c = lerpc(c, pal(0.95), 0.6);
      }
      src[y * W + x] = c; L[y * W + x] = lum(c);
    }
    const idx = new Int32Array(W), keys = new Float32Array(W);
    return (t) => {
      px.set(src);
      const u = (t / LOOP) * Math.PI * 2;
      const lo = 55 + 40 * Math.sin(u), hi = 235 + 20 * Math.sin(u * 2 + 1);
      for (let y = 0; y < H; y++) {
        // Only rows inside the drifting glitch bands get sorted; the rest stay clean for contrast.
        const band = Math.sin(y * 0.19 + u * 2) * Math.cos(y * 0.061 - u);
        if (band < 0.12) continue;
        const reach = clamp01(0.3 + band);
        let x = 0;
        while (x < W) {
          while (x < W && !(L[y * W + x] >= lo && L[y * W + x] <= hi)) x++;
          const x0 = x;
          while (x < W && L[y * W + x] >= lo && L[y * W + x] <= hi) x++;
          const span = x - x0, n = Math.max(1, Math.floor(span * reach));
          if (span < 3) continue;
          for (let k = 0; k < n; k++) { idx[k] = src[y * W + x0 + k]; keys[k] = L[y * W + x0 + k]; }
          // Insertion sort, darkest first: light streams off to the right.
          for (let a = 1; a < n; a++) {
            const kv = keys[a], iv = idx[a];
            let j = a - 1;
            while (j >= 0 && keys[j] > kv) { keys[j + 1] = keys[j]; idx[j + 1] = idx[j]; j--; }
            keys[j + 1] = kv; idx[j + 1] = iv;
          }
          // Stretch the sorted run across the whole span: the smear.
          for (let k = 0; k < span; k++) px[y * W + x0 + k] = idx[Math.min(n - 1, Math.floor((k / span) * n))];
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

