// Demoscene tunnel: an angle/depth lookup table over a 2× oversized window, so
// the camera can wobble by sliding the viewport. Checkered walls stream toward
// the viewer through a cycling palette; neon ribs are anti-aliased to a constant
// pixel width (their world-space width is derived per pixel from the LUT).
export default {
  title: 'Tunnel',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['tunnel', 'demoscene', 'texture', 'lut'],
  order: 30,
  description: 'Textured demoscene tunnel — precomputed angle/depth LUT, neon ribs, palette cycling and camera wobble.',
  canvas: 'field',
  palette: 'prism',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const segs = 8;
    const { width: W, height: H, px, aspect } = cv;
    const LW = W * 2, LH = H * 2;
    const ang = new Float32Array(LW * LH), dep = new Float32Array(LW * LH);
    const fog = new Float32Array(LW * LH), wu = new Float32Array(LW * LH), wv = new Float32Array(LW * LH);
    const R = Math.min(W, H * aspect) * 0.5;
    const lineW = Math.max(0.7, R / 40); // rib half-width in pixels
    for (let y = 0, i = 0; y < LH; y++) {
      const dy = (y - LH / 2 + 0.5) * aspect;
      for (let x = 0; x < LW; x++, i++) {
        const dx = x - LW / 2 + 0.5;
        const r = Math.sqrt(dx * dx + dy * dy) + 0.0001;
        ang[i] = Math.atan2(dy, dx) / (Math.PI * 2) + 0.5;
        dep[i] = (R * 0.8) / r;
        // Pixels per texture unit: depth changes as R·0.8/r², angle as 2πr/segs.
        wv[i] = lineW / Math.max(1e-4, (r * r) / (R * 0.8));
        wu[i] = lineW / ((2 * Math.PI * r) / segs);
        const f = Math.min(1, r / (R * 1.1));
        fog[i] = f * f * (3 - 2 * f);
      }
    }
    const bg = ctx.theme.bg;
    const br = (bg >> 16) & 255, bgc = (bg >> 8) & 255, bb = bg & 255;

    return (t) => {
      const tt = t * speed;
      const ox = Math.floor(W / 2 + Math.sin(tt * 0.61) * W * 0.16);
      const oy = Math.floor(H / 2 + Math.sin(tt * 0.47 + 1) * H * 0.14);
      const twist = tt * 0.06, move = tt * 1.6;
      for (let y = 0, i = 0; y < H; y++) {
        let j = (y + oy) * LW + ox;
        for (let x = 0; x < W; x++, i++, j++) {
          const d = dep[j];
          const u = ang[j] * segs + twist + d * 0.12;
          const v = d + move;
          const fu = u - Math.floor(u), fv = v - Math.floor(v);
          const check = ((Math.floor(u * 2) + Math.floor(v * 2)) & 1) ? 0.16 : 0.34;
          const eu = Math.min(fu, 1 - fu) / wu[j], ev = Math.min(fv, 1 - fv) / wv[j];
          const rib = Math.max(0, 1 - Math.min(eu, ev));
          const c = pal(v * 0.11 - tt * 0.04);
          const f = fog[j];
          const k = f * (check + rib * 0.95);
          const hot = rib * rib * f * 120; // white-hot core on the ribs
          const r = ((c >> 16) & 255) * k + br * (1 - f) + hot;
          const g = ((c >> 8) & 255) * k + bgc * (1 - f) + hot;
          const b = (c & 255) * k + bb * (1 - f) + hot;
          px[i] = ((r > 255 ? 255 : r) << 16) | ((g > 255 ? 255 : g) << 8) | (b > 255 ? 255 : b | 0);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/vhs-glitch.js:
// A worn VHS tape of color bars: per-line jitter, chroma bleeding off the
// luma, a tracking band rolling down the frame, head-switching noise along the
// bottom, dropout specks, and the deck's on-screen display over it all.
import { lerpc, clamp01, hash2 } from '../retro/_kit.js';

const LOOP = 12;
const BARS = [0xc0c0c0, 0xc0c000, 0x00c0c0, 0x00c000, 0xc000c0, 0xc00000, 0x0000c0];
const REV = [0x0000c0, 0x131313, 0xc000c0, 0x131313, 0x00c0c0, 0x131313, 0xc0c0c0];
const PLUGE = [[0.25, 0x00214c], [0.25, 0xffffff], [0.25, 0x32006a], [0.25, 0x131313]];

export default {
  title: 'VHS Tracking',
  gallery: 'fx',
  category: 'Glitch & Noise',
  kind: 'scene',
  tags: ['vhs', 'glitch', 'tracking', 'analog', 'color bars', 'vcr', 'retro'],
  order: 30,
  description: 'Worn VHS color bars: line jitter, chroma bleed, a rolling tracking band, head-switch noise and the deck OSD.',
  size: { w: 80, h: 24 },
  minSize: { w: 24, h: 8 },
  loop: LOOP,
  canvas: 'field',
  setup(ctx) {
    const cv = ctx.canvas();
    const b = ctx.buffer;
    const { width: W, height: H, px } = cv;
    const bars = (x, y) => {
      const u = x / W, v = y / H;
      if (v < 0.67) return BARS[Math.min(6, Math.floor(u * 7))];
      if (v < 0.75) return REV[Math.min(6, Math.floor(u * 7))];
      if (u < 5 / 7) { let a = 0; for (const [w, c] of PLUGE) { a += w * (5 / 7); if (u < a) return c; } }
      return 0x131313;
    };
    const R = new Float32Array(W), G = new Float32Array(W), B = new Float32Array(W);
    return (t) => {
      const lt = t % LOOP, frame = Math.floor(t * 30);
      const band = ((lt / LOOP) * 1.6 - 0.3) * H, bandH = Math.max(2, H * 0.08);
      const burst = lt > 7.2 && lt < 7.6;                 // a hard tracking slip once a loop
      const roll = burst ? Math.floor((lt - 7.2) * H * 2.5) : 0;
      for (let y = 0; y < H; y++) {
        const sy = (y + roll) % H;
        const inBand = Math.abs(y - band) < bandH;
        const head = y >= H - Math.max(2, Math.round(H * 0.05));
        let off = (hash2(y, frame, 1) - 0.5) * 1.2 + Math.sin(y * 0.3 + t * 2) * 0.6;
        if (inBand) off += (hash2(y, frame, 2) - 0.2) * W * 0.06;
        if (head) off += (y - (H - H * 0.05)) * W * 0.03;
        for (let x = 0; x < W; x++) {
          const c = bars(Math.min(W - 1, Math.max(0, Math.round(x - off))), sy);
          R[x] = (c >> 16) & 255; G[x] = (c >> 8) & 255; B[x] = c & 255;
        }
        for (let x = 0; x < W; x++) {
          // Chroma bleeds right, smeared; luma stays sharper.
          const xr = Math.max(0, x - 2), xb = Math.min(W - 1, x + 1);
          let r = (R[xr] * 0.6 + R[Math.max(0, xr - 1)] * 0.4), g = G[x], bl = (B[xb] * 0.6 + B[Math.max(0, x)] * 0.4);
          let n = (hash2(x, y, frame) - 0.5) * 26;
          if (inBand) n += hash2(x >> 1, y, frame + 7) > 0.82 ? 150 : 0;
          if (head) n += (hash2(x, y, frame + 3) - 0.5) * 160;
          if (hash2(x, y * 7, frame) > 0.9985) n += 220;      // dropouts
          const k = inBand ? 0.82 : 1;
          px[y * W + x] = (clamp01((r * k + n) / 255) * 255) << 16 | (clamp01((g * k + n) / 255) * 255) << 8 | (clamp01((bl * k + n) / 255) * 255);
        }
      }
      cv.paint(b);
      // Deck OSD, drawn straight over the picture the way VCRs did.
      const CW = ctx.width, CH = ctx.height;
      const osd = (x, y, s) => b.text(x, y, s, 0xf4f4f4);
      if (Math.floor(t * 2) % 2 === 0 || lt > 2) osd(2, 1, 'PLAY ▶');
      const secs = 754 + Math.floor(lt);
      const tc = `SP  ${Math.floor(secs / 3600)}:${String(Math.floor(secs / 60) % 60).padStart(2, '0')}:${String(secs % 60).padStart(2, '0')}`;
      if (CW >= 30) osd(CW - tc.length - 3, CH - 2, tc);
      if (burst && CW >= 30) osd(Math.floor(CW / 2) - 4, Math.floor(CH / 2), 'TRACKING');
    };
  },
};

sources.prism-term/src/facets/fx/voronoi.js:
// Living Voronoi: drifting seeds carve the plane into cells. Each cell is shaded
// like a bevelled tile (bright at its seed, darker toward its edge) and the
// borders — where the nearest and second-nearest seeds tie — glow.
import { lerpc } from '../retro/_kit.js';

export default {
  title: 'Voronoi Cells',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['voronoi', 'worley', 'cells', 'tiles', 'stained glass', 'procedural'],
  order: 70,
  description: 'Drifting seeds carve living Voronoi cells — bevelled stained-glass tiles with glowing borders where neighbors meet.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: 24,
  canvas: 'field',
  palette: 'prism',
  params: { cells: { default: 1, min: 0.3, max: 3, label: 'Cell density' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 512 });
    const rand = ctx.rng;
    const { width: W, height: H, px, aspect } = cv;
    const VH = H * aspect;
    const n = Math.max(6, Math.min(48, Math.round(((W * VH) / 260) * ctx.param('cells', 1) * (80 / Math.max(80, W)) ** 0.5)));
    const seeds = Array.from({ length: n }, () => ({ x: rand(), y: rand(), ax: 0.05 + rand() * 0.07, ay: 0.05 + rand() * 0.07, fa: 1 + Math.floor(rand() * 2), fb: 1 + Math.floor(rand() * 2), ph: rand() * 6.28, hue: rand() }));
    const sx = new Float32Array(n), sy = new Float32Array(n);
    const S = Math.sqrt((W * VH) / n);               // typical cell size
    const edge = lerpc(0xffffff, ctx.theme.ink, 0.3), lead = lerpc(ctx.theme.bg, 0x000000, 0.4);
    return (t) => {
      const u = (t / 24) * Math.PI * 2;
      for (let j = 0; j < n; j++) {
        const s = seeds[j];
        sx[j] = (s.x + Math.sin(u * s.fa + s.ph) * s.ax) * W;
        sy[j] = (s.y + Math.cos(u * s.fb + s.ph * 1.3) * s.ay) * VH;
      }
      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y + 0.5) * aspect;
        for (let x = 0; x < W; x++, i++) {
          let d1 = 1e9, d2 = 1e9, best = 0;
          for (let j = 0; j < n; j++) {
            const dx = x + 0.5 - sx[j], dy = vy - sy[j], d = dx * dx + dy * dy;
            if (d < d1) { d2 = d1; d1 = d; best = j; } else if (d < d2) d2 = d;
          }
          const f1 = Math.sqrt(d1), f2 = Math.sqrt(d2), gap = (f2 - f1) / S;
          const base = pal((seeds[best].hue + t / 48) % 1);
          let c = lerpc(base, lead, Math.min(0.75, (f1 / S) * 0.9));       // bevel: darker away from the seed
          if (gap < 0.08) c = lead;                                               // the leading between panes
          else if (gap < 0.2) c = lerpc(c, edge, (1 - (gap - 0.08) / 0.12) * 0.35); // light catching the pane's edge
          px[i] = c;
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/input/_input.js:
// Shared bits for the input gallery: a scripted "user", a dimmed backdrop for
// dialogs, and a prompt-line renderer.
export * from '../callouts/_kit.js';
import { mix, uni, ATTR, panel, clip, stringWidth } from '../callouts/_kit.js';

const BACK = [
  ['INFO', 'checkout-api', 'GET /cart 200 41ms'],
  ['INFO', 'payments-worker', 'charge ok order=88412 312ms'],
  ['WARN', 'checkout-api', 'db pool wait 840ms (20/20 in use)'],
  ['INFO', 'search-api', 'GET /search?q=tent 200 22ms'],
  ['INFO', 'gateway', 'POST /checkout 201 212ms'],
  ['ERROR', 'checkout-api', 'timeout acquiring connection after 5000ms'],
  ['INFO', 'inventory', 'reserve sku=TNT-2P qty=1 ok'],
  ['INFO', 'gateway', 'GET /account 200 34ms'],
  ['WARN', 'payments-worker', 'retrying charge order=88415 attempt=2'],
  ['INFO', 'search-api', 'reindex shard 3/8 done'],
];

/** Dimmed app content (a log view) behind modals so they read as overlays. */
export function backdrop(ctx, s, t = 0) {
  const th = ctx.theme;
  const ink = mix(th.bg, th.muted, 0.3);
  const lvl = { INFO: mix(th.bg, th.info, 0.3), WARN: mix(th.bg, th.warn, 0.35), ERROR: mix(th.bg, th.neg, 0.4) };
  const base = Math.floor(t / 1.5);
  for (let y = 0; y < (s.height ?? ctx.height); y++) {
    const [level, svc, msg] = BACK[(y + base) % BACK.length];
    const sec = 31 + y + base;
    const ts = `12:04:${String(sec % 60).padStart(2, '0')}`;
    let x = s.text(0, y, ts, ink);
    x = s.text(x + 1, y, level.padEnd(5), lvl[level]);
    x = s.text(x + 1, y, svc.padEnd(15), ink);
    s.text(x + 1, y, msg, ink);
  }
}

/** Fill a dialog rectangle with the panel color (clears what's behind). */
export function clearRect(ctx, s, x, y, w, h, bg) {
  s.fill(x, y, w, h, ' ', undefined, bg ?? ctx.theme.panel);
}

/** "? Question  answer" prompt line, in the style of inquirer/gum/clack. */
export function promptLine(ctx, s, x, y, question, { state = 'active', answer = '' } = {}) {
  const th = ctx.theme, u = uni(ctx);
  const mark = state === 'done' ? (u ? '✔' : '+') : state === 'error' ? (u ? '✖' : 'x') : '?';
  const c = state === 'done' ? th.pos : state === 'error' ? th.neg : th.accent;
  let cx = s.text(x, y, mark, c, undefined, ATTR.BOLD);
  cx = s.text(cx + 1, y, question, th.ink, undefined, ATTR.BOLD);
  if (answer) s.text(cx + 1, y, clip(ctx, answer, Math.max(0, (s.width ?? ctx.width) - cx - 1)), state === 'done' ? th.accent : th.muted);
  return cx;
}

/** Case-insensitive subsequence match: returns matched indices or null, plus a score (contiguous + early is better). */
export function fuzzyMatch(q, s) {
  q = q.toLowerCase();
  if (!q) return { idx: [], score: 0 };
  const idx = [];
  let j = 0;
  for (let i = 0; i < s.length && j < q.length; i++) if (s[i].toLowerCase() === q[j]) { idx.push(i); j++; }
  if (j < q.length) return null;
  let score = 0;
  for (let k = 1; k < idx.length; k++) score += idx[k] === idx[k - 1] + 1 ? 3 : 0;
  score -= idx[0] * 0.05 + s.length * 0.01;
  return { idx, score };
}

/**
 * A modal dialog: a soft drop shadow over whatever is behind it, then a filled
 * panel. `enter` (0→1) slides it down into place. Returns the interior View.
 */
export function modal(ctx, s, x, y, w, h, opts = {}) {
  const th = ctx.theme;
  const { enter = 1, ...rest } = opts;
  const yy = y - Math.round((1 - enter) * 2);
  const shade = mix(th.bg, 0x000000, 0.45);
  for (let r = 1; r <= h; r++) {
    for (let c = 2; c <= w + 1; c++) {
      if (r < h && c < w) continue;
      const cell = s.get(x + c, yy + r);
      if (cell) s.set(x + c, yy + r, undefined, mix(shade, cell.fg < 0 ? th.muted : cell.fg, 0.35), shade);
    }
  }
  return panel(ctx, s, x, yy, w, h, { bg: th.panel, ...rest });
}

/** Join picked items for a collapsed answer, ending "+N" when they don't all fit in `w`. */
export function listAnswer(items, w) {
  for (let n = items.length; n > 0; n--) {
    const s = items.slice(0, n).join(', ') + (n < items.length ? ` +${items.length - n}` : '');
    if (stringWidth(s) <= w) return s;
  }
  return `${items.length} selected`;
}

sources.prism-term/src/facets/input/autocomplete:
// Shell completion: a fish-style ghost suggestion from history, then a
// zsh-style completion menu that Tab cycles through, then the command runs.
import { ATTR, glyphs, uni, phase, typed, blink, tint, mix, fit } from './_input.js';

const PS1 = '~/infra $ ';
const HISTORY = [
  ['kubectl get deploy -n checkout', 0],
  ['NAME           READY   UP-TO-DATE   AVAILABLE', 1],
  ['checkout-api   2/3     3            2', 1],
];
const SUGGEST = 'kubectl rollout status deploy/checkout-api';
const SUBS = [
  ['history', 'view rollout history'],
  ['pause', 'mark as paused'],
  ['restart', 'restart a resource'],
  ['resume', 'resume a paused resource'],
  ['status', 'show rollout status'],
  ['undo', 'undo a previous rollout'],
];
// Script (seconds into the loop).
const T = { type1: 0.3, tab1: 1.8, cycle: [2.4, 2.9, 3.4], type2: 3.8, accept: 5.2, enter: 5.8 };

export default {
  id: 'input-autocomplete',
  title: 'Shell Autocomplete',
  category: 'Command Palettes',
  description: 'A shell prompt with a fish-style ghost suggestion from history, a zsh-style completion menu that Tab cycles, then → accepts and the command runs.',
  tags: ['autocomplete', 'completion', 'shell', 'zsh', 'fish'],
  kind: 'tui',
  size: { w: 64, h: 12 },
  minSize: { w: 40, h: 8 },
  loop: 8,
  color: '16',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 8);
      // Line, ghost text and menu state for this moment (menu: -2 hidden, -1 open, n highlighted).
      let line = typed('kubectl ro', p, T.type1, 7), ghost = '', menu = -2, hint = '';
      if (line && SUGGEST.startsWith(line) && p < T.tab1) {
        ghost = SUGGEST.slice(line.length);
        hint = `${g.right} accept suggestion ${g.mid} tab complete`;
      }
      if (p >= T.tab1) {
        line = 'kubectl rollout ';
        menu = -1;
        T.cycle.forEach((at, i) => { if (p >= at) menu = i; });
        if (menu >= 0) line += SUBS[menu][0];
        hint = menu < 0 ? `tab cycle ${g.mid} ${SUBS.length} completions` : `tab next ${g.mid} enter accept ${g.mid} esc cancel`;
      }
      if (p >= T.type2) {
        menu = -2;
        const arg = typed('deploy/ch', p, T.type2, 9);
        line = 'kubectl rollout restart ' + arg;
        hint = '';
        if (arg.length >= 7) { ghost = 'deploy/checkout-api'.slice(arg.length); hint = `${g.right} accept completion`; }
      }
      if (p >= T.accept) { line = 'kubectl rollout restart deploy/checkout-api'; ghost = ''; hint = `enter run`; }
      const ran = p >= T.enter;

      // History above the prompt, as much as fits with the menu open.
      const room = H - (menu > -2 ? Math.min(SUBS.length, H - 3) + 2 : 3);
      const keep = Math.max(0, Math.min(HISTORY.length, room - 1));
      const hist = keep ? HISTORY.slice(-keep) : [];
      if (keep === HISTORY.length) hist[0] = [PS1 + HISTORY[0][0], 0];
      let y = 0;
      for (const [txt, out] of hist) b.text(0, y++, fit(txt, W, undefined, ctx), out ? th.muted : th.dim);
      if (keep) y++;
      const py = y;

      // The command line scrolls left when it no longer fits.
      const room2 = W - PS1.length - 1;
      const off = Math.max(0, line.length - room2);
      const lx = PS1.length - off;
      const [cmd, ...rest] = line.split(' ');
      let x = b.text(lx, py, cmd, th.pos, undefined, ATTR.BOLD);
      if (rest.length) x = b.text(x, py, ' ' + rest.join(' '), th.ink);
      if (ghost) b.text(x, py, fit(ghost, Math.max(0, W - x), undefined, ctx).trimEnd(), mix(th.bg, th.muted, 0.6));
      // Block cursor over the ghost text (inverse, so it survives NO_COLOR); a bar otherwise.
      if (!ran && blink(t, 0.9)) {
        if (ghost) b.set(x, py, undefined, undefined, undefined, ATTR.INVERSE);
        else b.set(x, py, u ? '▏' : '_', th.ink);
      }
      b.fill(0, py, PS1.length, 1, ' ');
      let px = b.text(0, py, '~/infra', th.info, undefined, ATTR.BOLD);
      b.text(px + 1, py, '$', th.pos, undefined, ATTR.BOLD);
      if (off) b.text(PS1.length - 1, py, u ? '…' : '<', th.dim);

      if (menu > -2) {
        // Menu aligned under the word being completed, as far as the width allows.
        const mw = Math.min(W, 40);
        const mx = Math.max(0, Math.min(W - mw, PS1.length + 'kubectl rollout '.length - 1));
        const rows = Math.min(SUBS.length, H - py - 2);
        const first = Math.max(0, Math.min(SUBS.length - rows, menu - rows + 1));
        for (let r = 0; r < rows; r++) {
          const i = first + r, [name, desc] = SUBS[i];
          const on = i === menu;
          const bg = on ? th.accent : tint(ctx, th.panel2, 0.9);
          b.fill(mx, py + 1 + r, mw, 1, ' ', undefined, bg);
          b.text(mx + 1, py + 1 + r, name.padEnd(9), on ? th.bg : th.ink, bg, ATTR.BOLD);
          b.text(mx + 10, py + 1 + r, fit(`-- ${desc}`, mw - 11, undefined, ctx), on ? th.bg : th.dim, bg);
        }
      } else if (ran) {
        b.text(0, py + 1, fit('deployment.apps/checkout-api restarted', W, undefined, ctx), th.ink);
        if (py + 2 < H) {
          px = b.text(0, py + 2, '~/infra', th.info, undefined, ATTR.BOLD);
          px = b.text(px + 1, py + 2, '$', th.pos, undefined, ATTR.BOLD) + 1;
          if (blink(t, 0.9)) b.set(px, py + 2, u ? '▏' : '_', th.ink);
        }
      }
      if (hint && !ran) b.text(0, H - 1, fit(hint, W, undefined, ctx), th.dim);
    };
  },
};

