// A ctrl+shift+p style command palette over the app: the query filters
// commands live, the cursor moves, Enter runs one and a status line reports it.
import { ATTR, glyphs, uni, phase, typed, blink, tint, mix, fit, spin, stringWidth, backdrop, panel, fuzzyMatch } from './_input.js';

const COMMANDS = [
  ['Service', 'Restart checkout-api', 'ctrl+r'],
  ['Logs', 'Tail logs: checkout-api', 'ctrl+l'],
  ['Service', 'Restart payments-worker', ''],
  ['Deploy', 'Rollback checkout-api to v2.14.0', ''],
  ['Incident', 'Open runbook: DB pool exhaustion', ''],
  ['Deploy', 'Promote canary to 100%', ''],
  ['Service', 'Scale search-api', ''],
  ['View', 'Toggle compact log view', 'ctrl+k c'],
  ['Incident', 'Page on-call (sev2)', ''],
  ['Traces', 'Search traces by request id', 'ctrl+t'],
  ['Settings', 'Change theme', 'ctrl+k t'],
  ['Service', 'Restart search-api', ''],
];
const QUERY = 'restart';
// Pointer moves [seconds into the loop, rows] once the query has filtered the list.
const MOVES = [[2.3, 1], [2.8, 1], [3.3, -1]];
const ENTER = 3.9, CLOSE = 4.6, DONE = 5.6;

export default {
  id: 'input-command-palette',
  title: 'Command Palette',
  category: 'Command Palettes',
  description: 'A ctrl+shift+p palette over a dimmed app: the query fuzzy-filters commands with highlighted matches and key hints, Enter runs one and the status line confirms.',
  tags: ['command palette', 'fuzzy', 'launcher', 'overlay', 'keyboard'],
  kind: 'tui',
  size: { w: 66, h: 16 },
  minSize: { w: 40, h: 10 },
  loop: 8,
  color: '256',
  order: 10,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 8);
      backdrop(ctx, b, t);
      // Status line along the bottom of the "app".
      b.fill(0, H - 1, W, 1, ' ', undefined, th.panel2);
      if (p >= ENTER && p < DONE) {
        b.text(1, H - 1, fit(`${spin(ctx, t)} Restarting checkout-api ${g.mid} ${Math.min(2, Math.floor((p - ENTER) / 0.5))}/3 pods ready`, W - 2, undefined, ctx), th.warn, th.panel2);
      } else if (p >= DONE) {
        b.text(1, H - 1, fit(`${g.check} Restarted checkout-api ${g.mid} 3/3 pods ready in 9.4s`, W - 2, undefined, ctx), th.pos, th.panel2, ATTR.BOLD);
      } else b.text(1, H - 1, fit(`ctrl+shift+p commands ${g.mid} prod-us-east-2`, W - 2, undefined, ctx), th.muted, th.panel2);
      if (p >= CLOSE) return;

      const query = typed(QUERY, p, 0.7, 9);
      const hits = COMMANDS.map((c, i) => ({ c, i, m: fuzzyMatch(query, c[1]) }))
        .filter((h) => h.m)
        .sort((a, z) => (query ? z.m.score - a.m.score : 0) || a.i - z.i);
      let cur = 0;
      for (const [at, d] of MOVES) if (p >= at) cur = Math.max(0, Math.min(hits.length - 1, cur + d));

      const pw = Math.min(W - 4, 58), px = Math.floor((W - pw) / 2);
      // The palette shrinks to its results, like the real thing.
      const ph = Math.min(H - 2, 4 + Math.max(1, Math.min(hits.length, 9)));
      const inner = panel(ctx, b, px, 0, pw, ph, { color: th.accent, bg: th.panel });
      const iw = inner.width, ih = inner.height;
      // Query row.
      let x = inner.text(1, 0, '>', th.accent, th.panel, ATTR.BOLD) + 1;
      if (!query) inner.text(x + 1, 0, fit('Type a command', iw - x - 2, undefined, ctx), mix(th.panel, th.muted, 0.7), th.panel, ATTR.ITALIC);
      x = inner.text(x, 0, query, th.ink, th.panel, ATTR.BOLD);
      if (blink(t, 0.8)) inner.set(x, 0, u ? '▏' : '_', th.ink, th.panel);
      const count = `${hits.length} of ${COMMANDS.length}`;
      if (iw > 24) inner.text(iw - count.length - 1, 0, count, th.dim, th.panel);
      inner.fill(0, 1, iw, 1, u ? '─' : '-', th.line, th.panel);

      const rows = Math.min(hits.length, ih - 2);
      const first = Math.max(0, Math.min(hits.length - rows, cur - rows + 1));
      for (let r = 0; r < rows; r++) {
        const { c: [cat, label, key], m } = hits[first + r];
        const y = 2 + r, on = first + r === cur;
        const pressed = on && p >= ENTER;
        const bg = on ? (pressed ? th.accent : tint(ctx, th.accent, 0.22)) : th.panel;
        inner.fill(0, y, iw, 1, ' ', undefined, bg);
        if (on) inner.set(0, y, u ? '▌' : '>', pressed ? th.bg : th.accent, bg, ATTR.BOLD);
        let cx = inner.text(2, y, `${cat}: `, pressed ? th.bg : th.dim, bg);
        const keyW = key && iw > 34 ? stringWidth(key) + 2 : 0;
        const shown = fit(label, Math.max(0, iw - cx - keyW - 1), undefined, ctx).trimEnd();
        [...shown].forEach((ch, i) => {
          const hit = m.idx.includes(i);
          inner.text(cx + i, y, ch, pressed ? th.bg : hit ? th.accent : on ? th.ink : th.muted, bg, hit || on ? ATTR.BOLD : 0);
        });
        if (keyW) inner.text(iw - keyW, y, ` ${key} `, pressed ? th.bg : th.muted, pressed ? th.accent : th.panel2);
      }
      if (!hits.length) inner.text(2, 2, 'No matching commands', th.dim, th.panel, ATTR.ITALIC);
    };
  },
};

sources.prism-term/src/facets/input/confirm-dial:
// A destructive-action confirm dialog: Cancel is the default, Delete stays
// disabled until the resource name is typed, then it runs and closes.
import { ATTR, glyphs, uni, phase, typed, blink, ease, mix, fit, spin, button, backdrop, modal } from './_input.js';

const NAME = 'checkout';
const T = { open: 0.1, type: 0.9, tab: 2.6, enter: 3.2, close: 4.6 };

export default {
  id: 'input-confirm-dialog',
  title: 'Confirm Dialog',
  category: 'Dialogs & Prompts',
  description: 'A destructive-action modal with a shadow: Cancel is focused by default and Delete unlocks only after the namespace is typed, then it runs and closes.',
  tags: ['dialog', 'modal', 'confirm', 'destructive', 'buttons'],
  kind: 'tui',
  size: { w: 64, h: 15 },
  minSize: { w: 42, h: 10 },
  loop: 7,
  color: '256',
  order: 10,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 7);
      backdrop(ctx, b, t);
      b.fill(0, H - 1, W, 1, ' ', undefined, th.panel2);
      if (p >= T.close) {
        b.text(1, H - 1, fit(`${g.check} Deleted 3 pods in ${NAME} ${g.mid} rescheduling`, W - 2, undefined, ctx), th.pos, th.panel2, ATTR.BOLD);
        return;
      }
      b.text(1, H - 1, fit(`k9s ${g.mid} ${NAME} ${g.mid} pods`, W - 2, undefined, ctx), th.muted, th.panel2);

      const mw = Math.min(W - 4, 50), mh = Math.min(H - 2, 9);
      const mx = Math.floor((W - mw) / 2), my = Math.max(0, Math.floor((H - 1 - mh) / 2));
      const inner = modal(ctx, b, mx, my, mw, mh, {
        enter: ease(p, T.open, T.open + 0.35), color: th.neg,
        title: `${u ? '▲' : '!'} Delete pods`, titleColor: th.neg,
      });
      const iw = inner.width, ih = inner.height;
      const typedName = typed(NAME, p, T.type, 7);
      const ok = typedName === NAME;
      const running = p >= T.enter;
      let y = 0;
      inner.text(1, y++, fit('Terminate 3 pods in checkout?', iw - 2, undefined, ctx), th.ink, th.panel, ATTR.BOLD);
      if (ih >= 7) inner.text(1, y++, fit("They'll be rescheduled; local logs are lost.", iw - 2, undefined, ctx), th.muted, th.panel);
      if (ih >= 7) y++;
      const tag = `Type ${NAME} to confirm`;
      inner.text(1, y, fit(tag, iw - 2, undefined, ctx), th.muted, th.panel);
      inner.text(6, y, NAME, th.ink, th.panel, ATTR.BOLD);
      y++;
      // Confirmation field.
      const fw = Math.min(iw - 2, 30);
      const fbg = mix(th.panel, th.bg, 0.6);
      inner.fill(1, y, fw, 1, ' ', undefined, fbg);
      let fx = inner.text(2, y, typedName, ok ? th.pos : th.ink, fbg);
      if (!typedName && p > T.open + 0.3) inner.text(2, y, NAME, mix(fbg, th.muted, 0.45), fbg, ATTR.ITALIC);
      if (p < T.tab && blink(t, 0.9)) inner.set(fx, y, undefined, undefined, undefined, ATTR.INVERSE);
      if (ok) inner.text(fw - 1, y, g.check, th.pos, fbg, ATTR.BOLD);
      y += 2;

      // Buttons, right-aligned. Cancel holds focus until Tab.
      const by = Math.min(ih - 1, y);
      if (running) {
        const n = Math.min(3, 1 + Math.floor((p - T.enter) / 0.45));
        inner.text(1, by, fit(`${spin(ctx, t)} Deleting ${n}/3 ${g.ellipsis}`, iw - 2, undefined, ctx), th.warn, th.panel, ATTR.BOLD);
        return;
      }
      const focusDelete = p >= T.tab;
      const del = 'Delete 3 pods', cancel = 'Cancel';
      const dw = u ? del.length + 2 : del.length + 4, cw = u ? cancel.length + 2 : cancel.length + 4;
      const dx = iw - dw - 1, cx = dx - cw - 2;
      button(ctx, inner, cx, by, cancel, { focused: !focusDelete, color: th.muted });
      if (ok) button(ctx, inner, dx, by, del, { focused: focusDelete, color: th.neg, pressed: p > T.enter - 0.15 });
      else inner.text(dx, by, u ? ` ${del} ` : `[ ${del} ]`, mix(th.panel, th.muted, 0.5), u ? mix(th.panel, th.panel2, 0.5) : undefined, ATTR.DIM);
    };
  },
};

// A calendar date-range picker: arrow keys walk the grid, Enter sets the start,
// the range previews as the cursor moves, Enter again sets the end.
import { ATTR, glyphs, uni, phase, tint, fit, panel } from './_input.js';

const DOW = ['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su'];
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const TODAY = 13;
// Script: [time, action]. Days are in October 2026.
const SCRIPT = [[0.6, 7], [0.9, -1], [1.3, 'start'], [1.7, 1], [2.0, 1], [2.3, 1], [2.6, 1], [3.0, 'end'], [4.6, 'next'], [5.5, 'prev']];

function month(y, m) {
  const first = (new Date(Date.UTC(y, m, 1)).getUTCDay() + 6) % 7;
  const days = new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
  return { first, days };
}
const DAY3 = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const dayName = (d) => DAY3[(month(2026, 9).first + d - 1) % 7];

export default {
  id: 'input-date-picker',
  title: 'Date Range Picker',
  category: 'Dialogs & Prompts',
  description: 'A calendar range picker for a change freeze: arrows walk the month grid, Enter sets the start, the range previews as the cursor moves, Enter sets the end.',
  tags: ['date picker', 'calendar', 'range', 'schedule', 'form'],
  kind: 'tui',
  size: { w: 52, h: 11 },
  minSize: { w: 27, h: 11 },
  loop: 7,
  color: '256',
  order: 40,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 7);
      let cur = TODAY, start = 0, end = 0, mon = 9;
      for (const [at, a] of SCRIPT) {
        if (p < at) break;
        if (typeof a === 'number') cur += a;
        else if (a === 'start') start = cur;
        else if (a === 'end') end = cur;
        else if (a === 'next') mon = 10;
        else if (a === 'prev') mon = 9;
      }
      const wide = W >= 46;
      const cw = wide ? 25 : W;
      const inner = panel(ctx, b, 0, 0, cw, Math.min(H, 11), { title: 'Change freeze', color: th.accent });
      // Month header with prev/next arrows.
      const head = `${MONTHS[mon]} 2026`;
      const hx = Math.floor((inner.width - head.length) / 2);
      inner.text(0, 0, u ? '‹' : '<', th.muted);
      inner.text(inner.width - 1, 0, u ? '›' : '>', th.muted);
      inner.text(hx, 0, head, th.ink, undefined, ATTR.BOLD);
      const gx = Math.max(0, Math.floor((inner.width - 20) / 2));
      DOW.forEach((d, i) => inner.text(gx + i * 3, 1, d, i >= 5 ? th.dim : th.muted));
      const { first, days } = month(2026, mon);
      const lo = start && (end || (mon === 9 ? cur : start)), a = Math.min(start, lo), z = Math.max(start, lo);
      for (let d = 1; d <= days; d++) {
        const k = first + d - 1;
        const x = gx + (k % 7) * 3 - 1, y = 2 + Math.floor(k / 7);
        if (y >= inner.height - 1) continue;
        const inOct = mon === 9;
        const inRange = inOct && start && d >= a && d <= z;
        const isEnd = inOct && (d === start || d === end);
        const isCur = inOct && d === cur && !end;
        let fg = k % 7 >= 5 ? th.dim : th.ink, bg, attr = 0;
        if (inRange) { bg = tint(ctx, th.accent, end ? 0.3 : 0.18); fg = th.ink; }
        if (isEnd) { bg = th.accent; fg = th.bg; attr = ATTR.BOLD; }
        if (isCur) attr |= ATTR.INVERSE | ATTR.BOLD;
        const cell = String(d).padStart(2);
        // Range cells are joined by tinting the gap column too.
        if (inRange && d < z) inner.set(x + 3, y, ' ', undefined, bg);
        inner.text(x + 1, y, cell, fg, bg, attr);
        if (inOct && d === TODAY && !isEnd && !isCur) inner.text(x + 1, y, cell, th.warn, bg, ATTR.UNDERLINE | ATTR.BOLD);
      }
      // Summary: to the right when wide, else on the last interior row.
      const fmt = (d) => (d ? `${dayName(d)} ${d} Oct` : `${g.ellipsis}`);
      const sum = start && end ? `${g.check} ${start}${u ? '–' : '-'}${end} Oct ${g.mid} ${end - start + 1} days` : start ? `From ${fmt(start)} ${g.right} ${g.ellipsis}` : 'Pick the first day';
      if (wide) {
        const sx = cw + 2, sw = W - sx;
        let y = 1;
        b.text(sx, y++, 'From', th.muted);
        b.text(sx, y++, fit(start ? `${fmt(start)} 2026` : `${g.mid}`, sw, undefined, ctx), start ? th.ink : th.dim, undefined, ATTR.BOLD);
        y++;
        b.text(sx, y++, 'To', th.muted);
        const toD = end || (start && mon === 9 && cur > start ? cur : 0);
        b.text(sx, y++, fit(toD ? `${fmt(toD)} 2026` : `${g.mid}`, sw, undefined, ctx), end ? th.ink : th.dim, undefined, end ? ATTR.BOLD : ATTR.ITALIC);
        y++;
        if (start && toD) b.text(sx, y++, fit(`${z - a + 1} days ${g.mid} no deploys`, sw, undefined, ctx), end ? th.pos : th.dim);
        b.text(sx, Math.min(H, 11) - 1, fit(`${g.left}${g.up}${g.down}${g.right} move ${g.mid} enter pick`, sw, undefined, ctx), th.dim);
        if (mon !== 9) b.text(sx, Math.min(H, 11) - 2, fit('pgup back to October', sw, undefined, ctx), th.dim, undefined, ATTR.ITALIC);
      } else {
        inner.text(0, inner.height - 1, fit(sum, inner.width, undefined, ctx), start && end ? th.pos : th.muted);
      }
    };
  },
};

