// A masked password field with a strength meter and a reveal toggle.
import { ATTR, glyphs, uni, phase, typed, blink, tint, hbar } from './_input.js';

const PW = 'c0rrect-h0rse-battery!';
const RULES = [
  ['12+ characters', (s) => s.length >= 12],
  ['a digit', (s) => /\d/.test(s)],
  ['a symbol', (s) => /[^\w]/.test(s)],
  ['not in breach lists', (s) => s.length >= 16],
];

export default {
  id: 'input-password',
  title: 'Password Field',
  category: 'Text Fields',
  description: 'A masked password input whose strength meter climbs from weak to strong as rules tick off, with a brief reveal toggle at the end.',
  tags: ['password', 'masked', 'strength', 'security', 'input'],
  kind: 'tui',
  size: { w: 52, h: 9 },
  minSize: { w: 34, h: 5 },
  loop: 6,
  color: '256',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 6);
      const v = typed(PW, p, 0.3, 7);
      const reveal = p > 4.4 && p < 5.4;
      const passed = RULES.filter(([, f]) => f(v)).length;
      const fw = Math.min(W - 2, 40);
      b.text(0, 0, 'Password', th.ink, undefined, ATTR.BOLD);
      const bg = tint(ctx, th.accent, 0.08);
      b.fill(0, 1, fw, 1, ' ', undefined, bg);
      const shown = reveal ? v : (u ? '•' : '*').repeat(v.length);
      b.text(1, 1, shown.slice(-(fw - 6)), th.ink, bg);
      if (!reveal && blink(t, 0.9)) b.set(1 + Math.min(v.length, fw - 6), 1, u ? '▏' : '_', th.ink, bg);
      b.text(fw - 4, 1, reveal ? (u ? '◉' : 'o') : (u ? '◎' : '-'), th.muted, bg);
      const levels = [['weak', th.neg], ['fair', th.warn], ['good', th.info], ['strong', th.pos]];
      const [label, c] = levels[Math.max(0, passed - 1)] || levels[0];
      hbar(ctx, b, 0, 2, fw, passed / RULES.length, v ? c : th.line);
      b.text(fw + 1 > W - 6 ? 0 : fw + 1, fw + 1 > W - 6 ? 3 : 2, v ? label : '', c, undefined, ATTR.BOLD);
      const ry = fw + 1 > W - 6 ? 4 : 3;
      RULES.forEach(([text, f], i) => {
        const y = ry + i;
        if (y >= H) return;
        const ok = f(v);
        b.text(0, y, ok ? g.check : g.mid, ok ? th.pos : th.dim);
        b.text(2, y, text, ok ? th.ink : th.muted);
      });
    };
  },
};

sources.prism-term/src/facets/input/progress-dia:
// A modal progress dialog for an approved fix: steps tick off, a bar and ETA
// advance, Cancel becomes Close, and the result is verified before it closes.
import { ATTR, glyphs, uni, phase, span, ease, fit, spin, hbar, button, backdrop, modal } from './_input.js';

// [label, start, end] in seconds into the loop.
const STEPS = [
  ['Snapshot current config', 0.3, 1.0],
  ['Write config (pool=40)', 1.0, 1.7],
  ['Rolling restart', 1.7, 4.5],
  ['Verify p99 < 500ms', 4.5, 5.7],
];
const CLOSE = 8.2;

export default {
  id: 'input-progress-dialog',
  title: 'Progress Dialog',
  category: 'Dialogs & Prompts',
  description: 'A modal that applies a human-approved fix: steps tick off with timings, the bar and ETA advance, Cancel turns into Close, and the result is verified.',
  tags: ['progress', 'dialog', 'modal', 'steps', 'remediation'],
  kind: 'tui',
  size: { w: 60, h: 15 },
  minSize: { w: 42, h: 11 },
  loop: 9,
  color: '256',
  order: 30,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 9);
      backdrop(ctx, b, t);
      b.fill(0, H - 1, W, 1, ' ', undefined, th.panel2);
      if (p >= CLOSE) {
        b.text(1, H - 1, fit(`${g.check} Fix #142 applied ${g.mid} checkout-api p99 180ms`, W - 2, undefined, ctx), th.pos, th.panel2, ATTR.BOLD);
        return;
      }
      const end = STEPS[STEPS.length - 1][2];
      const finished = p >= end;
      b.text(1, H - 1, fit(`PROTEUS ${g.mid} fixes ${g.mid} ${finished ? 'verifying' : '1 running'}`, W - 2, undefined, ctx), th.muted, th.panel2);
      const mw = Math.min(W - 4, 52), mh = Math.min(H - 2, 12);
      const mx = Math.floor((W - mw) / 2), my = Math.max(0, Math.floor((H - 1 - mh) / 2));
      const inner = modal(ctx, b, mx, my, mw, mh, {
        enter: ease(p, 0, 0.3), color: finished ? th.pos : th.accent,
        title: finished ? `${g.check} Fix #142 applied` : 'Applying fix #142', titleColor: finished ? th.pos : th.ink,
      });
      const iw = inner.width, ih = inner.height, bg = th.panel;
      // Compact layouts drop the spacer rows.
      const by = ih >= 10 ? ih - 3 : ih - 2;
      let y = 0;
      inner.text(1, y++, fit(`Raise checkout DB pool 20 ${g.right} 40`, iw - 2, undefined, ctx), th.ink, bg, ATTR.BOLD);
      if (ih >= 10) inner.text(1, y++, fit(`Approved by you ${g.mid} 12:05 ${g.mid} rollback ready`, iw - 2, undefined, ctx), th.dim, bg);
      if (ih >= 10) y++;
      for (const [label, a, z] of STEPS) {
        if (y >= by) break;
        const state = p >= z ? 'done' : p >= a ? 'run' : 'todo';
        const mark = state === 'done' ? g.check : state === 'run' ? spin(ctx, t) : g.ring;
        inner.text(1, y, mark, state === 'done' ? th.pos : state === 'run' ? th.warn : th.dim, bg, ATTR.BOLD);
        let text = label;
        if (label === 'Rolling restart' && state !== 'todo') text += ` ${Math.min(3, Math.floor(span(p, a, z) * 3 + (state === 'done' ? 0 : 1)))}/3 pods`;
        const secs = state === 'done' ? `${(z - a).toFixed(1)}s` : state === 'run' ? `${(p - a).toFixed(1)}s` : '';
        inner.text(3, y, fit(text, iw - 11, undefined, ctx), state === 'todo' ? th.muted : th.ink, bg);
        if (secs) inner.text(iw - 1 - secs.length, y, secs, th.dim, bg);
        y++;
      }
      // Overall bar + ETA.
      const frac = span(p, STEPS[0][1], end);
      const pct = `${Math.round(frac * 100)}%`.padStart(4);
      const eta = finished ? 'done' : `ETA 0:${String(Math.ceil((end - p) * 3)).padStart(2, '0')}`;
      const bw = Math.max(4, iw - 2 - pct.length - eta.length - 2);
      hbar(ctx, inner, 1, by, bw, frac, finished ? th.pos : th.accent);
      inner.text(2 + bw, by, pct, th.ink, bg, ATTR.BOLD);
      inner.text(iw - 1 - eta.length, by, eta, th.dim, bg);
      // Buttons.
      const label = finished ? 'Close' : 'Cancel';
      const bwid = u ? label.length + 2 : label.length + 4;
      button(ctx, inner, iw - bwid - 1, ih - 1, label, { focused: true, color: finished ? th.pos : th.muted, pressed: p > CLOSE - 0.2 });
      if (finished && iw > 30) inner.text(1, ih - 1, fit(`${g.check} p99 2.4s ${g.right} 180ms`, iw - bwid - 4, undefined, ctx), th.pos, bg);
    };
  },
};

// A clack-style prompt flow: text, select, confirm and multiselect prompts
// chained down one gutter, each collapsing to its answer, then a spinner.
import { ATTR, glyphs, uni, phase, typed, blink, spin, clip, stringWidth } from './_input.js';

const T = { tag: 0.3, tagDone: 1.5, envDown: 2.1, envDone: 2.7, migNo: 3.4, migDone: 3.9, n1: 4.5, n2: 4.9, nDone: 5.5, deployed: 7.6 };
const ENVS = ['staging', 'production', 'canary'];
const NOTIFY = ['#checkout-oncall', '#releases', 'release-notes email'];

export default {
  id: 'input-prompt-flow',
  title: 'Prompt Flow',
  category: 'Dialogs & Prompts',
  description: 'A clack-style CLI wizard: text, select, yes/no and multiselect prompts chain down one gutter, each collapsing to its answer before a deploy spinner.',
  tags: ['prompts', 'clack', 'cli wizard', 'confirm', 'yes no'],
  kind: 'tui',
  size: { w: 56, h: 16 },
  minSize: { w: 36, h: 8 },
  loop: 10,
  color: '16',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 10);
      const G = u
        ? { top: '┌', bar: '│', end: '└', done: '◇', act: '◆', on: '●', off: '○', mOn: '◼', mOff: '◻' }
        : { top: '+', bar: '|', end: '+', done: 'o', act: '*', on: '(*)', off: '( )', mOn: '[x]', mOff: '[ ]' };
      const lines = [];
      const L = (...segs) => lines.push(segs);
      const gut = (c = th.dim) => [`${G.bar}  `, c];
      const done = (q, a) => { L([`${G.done}  `, th.pos], [q, th.ink]); L(gut(), [a, th.dim]); L(gut()); };
      const active = (q) => L([`${G.act}  `, th.accent, ATTR.BOLD], [q, th.ink, ATTR.BOLD]);

      L([`${G.top}  `, th.dim], [' deploy ', th.bg, ATTR.BOLD, th.accent], ['  checkout-api', th.muted]);
      L(gut());
      // 1. Release tag (text).
      if (p < T.tagDone) {
        active('Release tag');
        const v = typed('v2.14.1', p, T.tag, 8);
        const caret = blink(t, 0.9) ? (u ? '▏' : '_') : ' ';
        L(gut(th.accent), v ? [v, th.ink] : ['v1.2.3', th.dim, ATTR.ITALIC], [caret, th.ink]);
        L([G.end, th.accent]);
      } else done('Release tag', 'v2.14.1');
      // 2. Environment (select).
      if (p >= T.tagDone && p < T.envDone) {
        active('Environment');
        const cur = p >= T.envDown ? 1 : 0;
        ENVS.forEach((e, i) => L(gut(th.accent), [i === cur ? G.on : G.off, i === cur ? th.pos : th.dim], [` ${e}`, i === cur ? th.ink : th.muted], i === 1 ? ['  (12 hosts)', th.dim] : ['']));
        L([G.end, th.accent]);
      } else if (p >= T.envDone) done('Environment', 'production');
      // 3. Migrations (confirm).
      if (p >= T.envDone && p < T.migDone) {
        active('Run database migrations?');
        const yes = p < T.migNo;
        L(gut(th.accent), [yes ? G.on : G.off, yes ? th.pos : th.dim], [' Yes', yes ? th.ink : th.muted], [' / ', th.dim], [yes ? G.off : G.on, yes ? th.dim : th.pos], [' No', yes ? th.muted : th.ink]);
        L([G.end, th.accent]);
      } else if (p >= T.migDone) done('Run database migrations?', 'No');
      // 4. Notify (multiselect).
      if (p >= T.migDone && p < T.nDone) {
        active('Notify');
        const sel = [p >= T.n1, false, p >= T.n2];
        const cur = p >= T.n2 - 0.12 ? 2 : p >= T.n1 + 0.15 ? 1 : 0;
        NOTIFY.forEach((n, i) => L(gut(th.accent), [i === cur ? g.pointer : ' ', th.accent], [' '], [sel[i] ? G.mOn : G.mOff, sel[i] ? th.pos : th.dim], [` ${n}`, i === cur ? th.ink : th.muted]));
        L([G.end, th.accent], [`  space select ${g.mid} enter confirm`, th.dim]);
      } else if (p >= T.nDone) done('Notify', '#checkout-oncall, release-notes email');
      // 5. Deploy.
      if (p >= T.nDone && p < T.deployed) {
        const k = Math.min(12, Math.floor((p - T.nDone) / (T.deployed - T.nDone) * 12));
        L([`${spin(ctx, t)}  `, th.warn], [`Deploying v2.14.1 to production ${g.mid} ${k}/12 hosts`, th.ink]);
      } else if (p >= T.deployed) {
        L([`${G.done}  `, th.pos], ['Deployed v2.14.1 to 12 hosts in 41s', th.ink]);
        L(gut());
        L([`${G.end}  `, th.dim], ['Done. ', th.ink, ATTR.BOLD], ['https://deploy.example/r/8841', th.info, ATTR.UNDERLINE]);
      }

      // The flow scrolls like a real terminal: show the newest lines.
      const first = Math.max(0, lines.length - H);
      for (let r = 0; r < Math.min(H, lines.length); r++) {
        let x = 0;
        for (const [text, fg, attr, bg] of lines[first + r]) {
          if (!text) continue;
          const room = Math.max(0, W - x);
          x = b.text(x, r, stringWidth(text) <= room ? text : clip(ctx, text, room), fg, bg, attr);
        }
      }
    };
  },
};

// Radio groups: one choice per group, selection hopping between options.
import { ATTR, glyphs, phase, stepAt, tint } from './_input.js';

const GROUPS = [
  ['Environment', ['dev', 'staging', 'production']],
  ['Strategy', ['rolling', 'blue/green', 'canary']],
  ['Notify', ['nobody', 'team', 'on-call']],
];
const SCRIPT = [[0.4, 0, 1], [1.0, 0, 2], [1.7, 1, 2], [2.5, 2, 1], [3.3, 1, 1]];

export default {
  id: 'input-radio-group',
  title: 'Radio Groups',
  category: 'Toggles & Checkboxes',
  description: 'Three labeled radio groups — environment, rollout strategy and notification — with the selected dot hopping as choices change.',
  tags: ['radio', 'options', 'choice', 'form', 'select'],
  kind: 'tui',
  size: { w: 60, h: 9 },
  minSize: { w: 40, h: 6 },
  loop: 5,
  color: '16',
  order: 30,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, H = ctx.height, g = glyphs(ctx);
      const p = phase(t, 5);
      const sel = [0, 0, 1];
      const k = stepAt(p, SCRIPT.map((s) => s[0]));
      let focusG = 0;
      for (let i = 0; i <= k; i++) { sel[SCRIPT[i][1]] = SCRIPT[i][2]; focusG = SCRIPT[i][1]; }
      const step = H >= GROUPS.length * 3 ? 3 : 2;
      GROUPS.forEach(([name, opts], gi) => {
        const y = gi * step;
        if (y + 1 >= H) return;
        const focused = gi === focusG;
        b.text(0, y, name, focused ? th.accent : th.muted, undefined, ATTR.BOLD);
        let x = 2;
        opts.forEach((o, oi) => {
          const on = sel[gi] === oi;
          if (focused && on) b.fill(x - 1, y + 1, o.length + g.radioOn.length + 3, 1, ' ', undefined, tint(ctx, th.accent, 0.14));
          x = b.text(x, y + 1, on ? g.radioOn : g.radioOff, on ? th.accent : th.dim, undefined, ATTR.BOLD);
          x = b.text(x + 1, y + 1, o, on ? th.ink : th.muted, undefined, on ? ATTR.BOLD : 0) + 3;
        });
      });
    };
  },
};

// A long list in a short window: the cursor runs down, the view scrolls, the
// scrollbar thumb tracks it.
import { ATTR, glyphs, phase, panel, scrollbar, tint, fit } from './_input.js';

const PODS = Array.from({ length: 26 }, (_, i) => {
  const svc = ['checkout', 'payments', 'catalog', 'search', 'cart', 'auth', 'orders', 'notify'][i % 8];
  return [`${svc}-7d9f${(i * 7919 % 9000 + 1000).toString(36)}`, ['Running', 'Running', 'Running', 'Pending', 'Running'][i % 5], `${(i * 13) % 59 + 1}m`];
});

export default {
  id: 'input-scroll-list',
  title: 'Scrolling List',
  category: 'Selects & Lists',
  description: 'A long pod list in a short framed window: the cursor runs down and back, the view scrolls with it and the scrollbar thumb tracks position.',
  tags: ['list', 'scroll', 'scrollbar', 'pods', 'cursor'],
  kind: 'tui',
  size: { w: 52, h: 12 },
  minSize: { w: 34, h: 6 },
  loop: 10,
  color: '16',
  order: 30,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx);
      const p = phase(t, 10);
      const pos = p < 5 ? p / 5 : 1 - (p - 5) / 5;
      const cur = Math.round(pos * (PODS.length - 1));
      const inner = panel(ctx, b, 0, 0, W, H, { title: 'pods', footer: `${cur + 1}/${PODS.length}`, color: th.line });
      const vis = inner.height;
      const first = Math.max(0, Math.min(PODS.length - vis, cur - Math.floor(vis / 2)));
      for (let r = 0; r < vis; r++) {
        const i = first + r;
        if (i >= PODS.length) break;
        const [name, status, age] = PODS[i];
        const on = i === cur;
        if (on) inner.fill(0, r, inner.width - 1, 1, ' ', undefined, tint(ctx, th.accent, 0.16));
        inner.text(0, r, on ? g.pointer : ' ', th.accent, undefined, ATTR.BOLD);
        inner.text(2, r, fit(name, Math.max(4, inner.width - 18), undefined, ctx), on ? th.ink : th.muted, undefined, on ? ATTR.BOLD : 0);
        inner.text(inner.width - 15, r, status.padEnd(8), status === 'Running' ? th.pos : th.warn);
        inner.text(inner.width - 5, r, age.padStart(3), th.dim);
      }
      scrollbar(ctx, inner, inner.width - 1, 0, vis, PODS.length, first, vis);
    };
  },
};

