// A multi-line editor: a commit message gets typed with soft line numbers,
// a 50/72 ruler and a character count.
import { ATTR, uni, phase, typed, blink, panel, mix } from './_input.js';

const MSG = 'Raise checkout DB pool to 40\n\nv2.14.1 raised worker concurrency to 32 but left\nthe pool at 20, so requests queued for a connection.\nSize the pool to the workers and alert on pool\nwait time.';

export default {
  id: 'input-textarea',
  title: 'Commit Message Editor',
  category: 'Text Fields',
  description: 'A multi-line textarea where a commit message is typed: line numbers, a 50/72 column guide, subject-length warning and a live character count.',
  tags: ['textarea', 'editor', 'multiline', 'commit', 'git'],
  kind: 'tui',
  size: { w: 64, h: 12 },
  minSize: { w: 40, h: 7 },
  loop: 12,
  color: '256',
  order: 40,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx);
      const p = phase(t, 12);
      const text = typed(MSG, p, 0.2, 26);
      const lines = text.split('\n');
      const inner = panel(ctx, b, 0, 0, W, H, { title: 'COMMIT_EDITMSG', footer: `${text.replace(/\n/g, '').length} chars`, color: th.line });
      const iw = inner.width, ih = inner.height;
      const guide = (col, c) => { if (5 + col < iw) for (let y = 0; y < ih; y++) inner.set(5 + col, y, u ? '┊' : ':', c); };
      guide(50, mix(th.bg, th.warn, 0.35));
      guide(72, mix(th.bg, th.neg, 0.35));
      const first = Math.max(0, lines.length - ih);
      for (let r = 0; r < ih; r++) {
        const i = first + r;
        inner.text(0, r, String(i + 1).padStart(3), i < lines.length ? th.dim : mix(th.bg, th.dim, 0.4));
        if (i >= lines.length) { inner.text(4, r, '~', mix(th.bg, th.accent, 0.5)); continue; }
        const line = lines[i];
        [...line].forEach((ch, x) => { if (5 + x < iw) inner.text(5 + x, r, ch, i === 0 && x >= 50 ? th.warn : i === 0 ? th.ink : th.muted, undefined, i === 0 ? ATTR.BOLD : 0); });
        if (i === lines.length - 1 && blink(t, 0.8)) inner.set(5 + Math.min(line.length, iw - 6), r, u ? '▏' : '_', th.accent);
      }
    };
  },
};

sources.prism-term/src/facets/input/toggles.js:
// A settings pane of switches that flip with a sliding knob.
import { ATTR, uni, glyphs, phase, ease, panel, tint, mix, fit } from './_input.js';

const SETTINGS = [
  ['Auto-approve diagnostics', true, 1.0, 'Read-only checks run unasked; fixes still ask.'],
  ['Stream reasoning summaries', false, 1.8, 'Show a short summary while the model works.'],
  ['Page on-call for sev1', true, 0, 'Locked by your org policy.'],
  ['Compact log view', false, 2.6, 'One line per event; expand with enter.'],
  ['Telemetry to OTLP', true, 3.4, 'Export spans to 127.0.0.1:4318.'],
];

export default {
  id: 'input-toggles',
  title: 'Toggle Switches',
  category: 'Toggles & Checkboxes',
  description: 'A settings pane of on/off switches whose knobs slide across with color easing as a scripted user flips them, labels dimming when off.',
  tags: ['toggle', 'switch', 'settings', 'preferences', 'on off'],
  kind: 'tui',
  size: { w: 52, h: 13 },
  minSize: { w: 34, h: 6 },
  loop: 6,
  color: '256',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx), g = glyphs(ctx);
      const p = phase(t, 6);
      const inner = panel(ctx, b, 0, 0, W, H, { title: 'Settings', footer: `space toggle ${g.mid} ${g.up}/${g.down} move`, color: th.line });
      const rows = Math.min(SETTINGS.length, Math.floor(inner.height / (inner.height >= SETTINGS.length * 2 ? 2 : 1)));
      const step = inner.height >= SETTINGS.length * 2 ? 2 : 1;
      let focus = 0;
      SETTINGS.forEach(([, , at], i) => { if (at && p >= at - 0.3) focus = i; });
      for (let i = 0; i < rows; i++) {
        const [label, init, at] = SETTINGS[i];
        const k = at ? ease(p, at, at + 0.25) * (1 - ease(p, 5.4, 5.7)) : 0;
        const val = init ? 1 - k : k; // 0 off → 1 on
        const y = i * step;
        const on = i === focus;
        const sw = u ? 6 : 5;
        const sx = inner.width - sw - 1;
        if (on) inner.fill(0, y, inner.width, 1, ' ', undefined, tint(ctx, th.accent, 0.1));
        inner.text(1, y, fit(label, Math.max(0, sx - 2), undefined, ctx), val > 0.5 ? th.ink : th.muted, undefined, on ? ATTR.BOLD : 0);
        const track = mix(th.line, th.pos, val);
        if (u) {
          for (let x = 0; x < sw; x++) inner.set(sx + x, y, '━', track);
          inner.set(sx + Math.round(val * (sw - 1)), y, '●', val > 0.5 ? th.ink : th.muted, undefined, ATTR.BOLD);
        } else inner.text(sx, y, val > 0.5 ? '[ON ]' : '[OFF]', val > 0.5 ? th.pos : th.dim, undefined, ATTR.BOLD);
        if (!at && label.length + 3 < sx - 7) inner.text(sx - 7, y, 'locked', th.dim, undefined, ATTR.ITALIC);
      }
      // Help for the focused row, when there's room under the list.
      if (inner.height - 1 > (rows - 1) * step + 1) inner.text(1, inner.height - 1, fit(SETTINGS[focus][3], inner.width - 2, undefined, ctx), th.dim, undefined, ATTR.ITALIC);
    };
  },
};

sources.prism-term/src/facets/input/wizard.js:
// A multi-step wizard: a stepper header fills in as the user moves through
// Source → Target → Schedule → Review, content sliding in on each step.
import { ATTR, glyphs, uni, phase, typed, blink, ease, tint, mix, fit, button, panel, spin } from './_input.js';

const STEPS = ['Source', 'Target', 'Schedule', 'Review'];
const STARTS = [0, 2.2, 4.4, 6.4];
const SNAPS = [['snap-0413-0000', 'today 00:00', '48 GB'], ['snap-0413-0600', 'today 06:00', '48 GB'], ['snap-0412-1800', 'yesterday 18:00', '47 GB']];
const T = { snapDown: 1.0, next1: 1.8, type: 2.6, next2: 4.0, winDown: 5.2, next3: 6.0, restore: 8.2 };

export default {
  id: 'input-wizard',
  title: 'Setup Wizard',
  category: 'Dialogs & Prompts',
  description: 'A four-step restore wizard: the stepper header fills as the user picks a snapshot, names the target, schedules it and reviews before pressing Restore.',
  tags: ['wizard', 'stepper', 'multi-step', 'form', 'onboarding'],
  kind: 'tui',
  size: { w: 64, h: 12 },
  minSize: { w: 44, h: 11 },
  loop: 10,
  color: '256',
  order: 50,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 10);
      let step = 0;
      STARTS.forEach((s, i) => { if (p >= s) step = i; });
      const inner = panel(ctx, b, 0, 0, W, H, { title: 'Restore database', color: th.line });
      const iw = inner.width, ih = inner.height;

      // Stepper: nodes joined by a track that fills as steps complete.
      const seg = Math.floor((iw - 8) / (STEPS.length - 1));
      const nx = (i) => 4 + i * seg;
      for (let i = 0; i < STEPS.length - 1; i++) {
        const fill = ease(p, STARTS[i + 1] - 0.3, STARTS[i + 1]);
        for (let x = nx(i) + 1; x < nx(i + 1); x++) {
          const on = (x - nx(i)) / seg <= fill;
          inner.set(x, 0, u ? (on ? '━' : '─') : (on ? '=' : '-'), on ? th.pos : th.line);
        }
      }
      STEPS.forEach((name, i) => {
        const done = i < step, cur = i === step;
        const mark = done ? g.check : cur ? (u ? '●' : '@') : g.ring;
        inner.set(nx(i), 0, mark, done ? th.pos : cur ? th.accent : th.dim, undefined, ATTR.BOLD);
        const lx = Math.max(0, Math.min(iw - name.length, nx(i) - Math.floor(name.length / 2)));
        inner.text(lx, 1, name, done ? th.pos : cur ? th.ink : th.dim, undefined, cur ? ATTR.BOLD : 0);
      });

      // Step content slides in from the right.
      const slide = Math.round((1 - ease(p, STARTS[step], STARTS[step] + 0.3)) * 6);
      const cx = 2 + slide, cy = 3;
      const body = inner.view(0, cy, iw, Math.max(0, ih - cy - 2));
      const bh = body.height;
      const row = (r, ...segs) => { if (r >= bh) return; let x = cx; for (const [s, c, a, bg] of segs) x = body.text(x, r, s, c, bg, a); };
      if (step === 0) {
        row(0, ['Which snapshot?', th.ink, ATTR.BOLD]);
        const sel = p >= T.snapDown ? 1 : 0;
        SNAPS.forEach(([id, when, size], i) => {
          if (1 + i >= bh) return;
          const on = i === sel;
          if (on) body.fill(cx - 1, 1 + i, Math.max(0, iw - cx), 1, ' ', undefined, tint(ctx, th.accent, 0.12));
          row(1 + i, [on ? g.radioOn : g.radioOff, on ? th.accent : th.dim, ATTR.BOLD], [` ${id}`, on ? th.ink : th.muted, on ? ATTR.BOLD : 0], iw > 52 ? [`  ${when.padEnd(16)}${size}`, th.dim] : [`  ${size}`, th.dim]);
        });
      } else if (step === 1) {
        row(0, ['Restore into a new instance named', th.ink, ATTR.BOLD]);
        const v = typed('checkout-db-restore', p, T.type, 14);
        const fw = Math.min(iw - cx - 2, 32), fbg = mix(th.bg, th.panel2, 0.8);
        body.fill(cx, 1, fw, 1, ' ', undefined, fbg);
        const end = body.text(cx + 1, 1, v, th.ink, fbg);
        if (blink(t, 0.9) && p < T.next2) body.set(end, 1, undefined, undefined, undefined, ATTR.INVERSE);
        if (bh > 2) row(2, [v.length >= 19 ? `${g.check} name is available` : 'lowercase, digits and hyphens', v.length >= 19 ? th.pos : th.dim]);
      } else if (step === 2) {
        row(0, ['When should it run?', th.ink, ATTR.BOLD]);
        const win = p >= T.winDown;
        row(1, [win ? g.radioOff : g.radioOn, win ? th.dim : th.accent, ATTR.BOLD], [' Now', win ? th.muted : th.ink]);
        row(2, [win ? g.radioOn : g.radioOff, win ? th.accent : th.dim, ATTR.BOLD], [' Next maintenance window', win ? th.ink : th.muted, win ? ATTR.BOLD : 0]);
        if (bh > 3) row(3, [`   Sat 17 Oct 02:00${iw > 52 ? ' (in 3 days)' : ''}`, th.dim]);
      } else {
        const kv = [['Snapshot', 'snap-0413-0600'], ['Target', 'checkout-db-restore'], ['When', 'Sat 17 Oct 02:00'], ['Est. time', '~18 min']];
        kv.forEach(([k, v], i) => row(i, [g.check, th.pos], [` ${k.padEnd(10)}`, th.muted], [v, th.ink, ATTR.BOLD]));
      }

      // Footer buttons.
      const by = ih - 1;
      const last = step === STEPS.length - 1;
      if (p >= T.restore + 0.2) {
        inner.text(2, by, fit(`${p < T.restore + 1.2 ? spin(ctx, t) : g.check} Restore queued ${g.mid} job #5521`, iw - 4, undefined, ctx), p < T.restore + 1.2 ? th.warn : th.pos, undefined, ATTR.BOLD);
        return;
      }
      inner.text(2, by, `Step ${step + 1} of ${STEPS.length}`, th.dim);
      const nextLabel = last ? 'Restore' : 'Next';
      const nw = u ? nextLabel.length + 2 : nextLabel.length + 4;
      const bw = u ? 6 : 8;
      const nextX = iw - nw - 1;
      const pressAt = [T.next1, T.next2, T.next3, T.restore][step];
      button(ctx, inner, nextX - bw - 2, by, 'Back', { focused: false });
      button(ctx, inner, nextX, by, nextLabel, { focused: true, color: last ? th.pos : th.accent, pressed: p > pressAt - 0.18 && p < pressAt + 0.2 });
    };
  },
};

