// Dissolves, four ways: a straight cross-fade, an ordered (Bayer 8×8) dither
// dissolve, a random-pixel dissolve, and a noise "burn" whose leading edge
// glows like smouldering paper.
import { transitionSetup } from './_lab.js';
import { mix } from '../../color.js';

const BAYER = [0, 32, 8, 40, 2, 34, 10, 42, 48, 16, 56, 24, 50, 18, 58, 26, 12, 44, 4, 36, 14, 46, 6, 38, 60, 28, 52, 20, 62, 30, 54, 22,
  3, 35, 11, 43, 1, 33, 9, 41, 51, 19, 59, 27, 49, 17, 57, 25, 15, 47, 7, 39, 13, 45, 5, 37, 63, 31, 55, 23, 61, 29, 53, 21].map((v) => (v + 0.5) / 64);
// Integer hash (well mixed, so the random dissolve has no streaks).
const hash = (x, y) => {
  let h = Math.imul(x, 374761393) + Math.imul(y, 668265263);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
};

export default {
  id: 'lab-dissolve',
  title: 'Dissolves',
  gallery: 'lab',
  category: 'Transitions',
  kind: 'scene',
  tags: ['transition', 'dissolve', 'cross-fade', 'dither', 'bayer', 'burn'],
  order: 20,
  description: 'Four dissolves between two scenes: cross-fade, ordered Bayer dither, random pixels and a glowing noise burn.',
  size: { w: 60, h: 20 },
  minSize: { w: 20, h: 7 },
  loop: 16,
  canvas: 'field',
  palette: 'theme',
  params: {},
  setup(ctx) {
    const noise = ctx.noise;
    const VARIANTS = [
      { name: 'dissolve · cross-fade', mask: (x, y, p) => p },
      { name: 'dissolve · ordered dither (Bayer 8×8)', mask: (x, y, p) => (p > BAYER[((y | 0) & 7) * 8 + ((x | 0) & 7)] ? 1 : 0) },
      { name: 'dissolve · random pixels', mask: (x, y, p) => (p > hash(x | 0, y | 0) ? 1 : 0) },
      {
        name: 'dissolve · noise burn',
        draw(px, A, B, W, H, asp, p) {
          for (let y = 0, k = 0; y < H; y++) for (let x = 0; x < W; x++, k++) {
            if (p <= 0) { px[k] = A[k]; continue; }
            if (p >= 1) { px[k] = B[k]; continue; }
            const n = 0.5 + 0.5 * noise.fbm(x * 0.07, y * 0.07 * asp, 0.3, 4);
            const d = p * 1.3 - 0.15 - n;
            if (d > 0.04) px[k] = B[k];
            else if (d > -0.04) px[k] = mix(0xff5a1f, 0xffe08a, 1 - Math.abs(d) / 0.04); // the burning edge
            else if (d > -0.09) px[k] = mix(A[k], 0x2a1206, ((d + 0.09) / 0.05) * 0.8); // scorch
            else px[k] = A[k];
          }
        },
      },
    ];
    return transitionSetup(ctx, VARIANTS);
  },
};

sources.prism-term/src/facets/lab/easing-gallery:
// The easing-curve wall chart, animated: a grid of the standard easings, each
// plotted in braille against dotted 0 and 1 guides (with room for back and
// elastic overshoot), a dot running the curve in lock-step across every panel,
// and a value bar on the right of each that shows what the eased value does.
import { easing } from '../../easing.js';
import { mix } from '../../color.js';
import { grid, put, pxRect } from './_lab.js';

const CURVES = ['linear', 'inQuad', 'outQuad', 'inOutCubic', 'inOutSine', 'inExpo', 'outExpo', 'outCirc', 'outBack', 'inOutBack', 'outElastic', 'outBounce'];
const RUN = 1.6, HOLD = 0.7, VMIN = -0.35, VMAX = 1.35;

export default {
  id: 'lab-easing-gallery',
  title: 'Easing Curves',
  gallery: 'lab',
  category: 'Easing & Timing',
  kind: 'chart',
  tags: ['easing', 'curves', 'tween', 'timing', 'ease in out', 'overshoot', 'braille'],
  order: 10,
  description: 'Twelve standard easings plotted in braille, each with a dot running its curve and a bar showing the eased value.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: RUN + HOLD,
  canvas: 'line',
  palette: 'theme',
  params: {},
  setup(ctx) {
    const cv = ctx.canvas('line');
    const th = ctx.theme;
    const cols = Math.max(1, Math.min(4, Math.floor(ctx.width / 18))), rows = Math.max(1, Math.min(3, Math.floor(ctx.height / 7)));
    const panels = grid(ctx.width, ctx.height, cols, rows, 2, 1).slice(0, CURVES.length);
    const guide = mix(th.bg, th.muted, 0.45), curveC = mix(th.muted, th.ink, 0.25);
    return (t) => {
      cv.clear();
      const ph = ((t % (RUN + HOLD)) + RUN + HOLD) % (RUN + HOLD);
      const u = Math.min(1, ph / RUN);
      const labels = [];
      panels.forEach((r, k) => {
        const name = CURVES[k], fn = easing[name];
        const P = pxRect(cv, { x: r.x, y: r.y + 1, w: r.w - 2, h: r.h - 1 });
        const X = (s) => P.x + s * (P.w - 1), Y = (v) => P.y + (1 - (v - VMIN) / (VMAX - VMIN)) * (P.h - 1);
        // Dotted guides at 0 and 1.
        for (let x = 0; x < P.w; x += 2) { cv.set(P.x + x, Y(0), guide); cv.set(P.x + x, Y(1), guide); }
        // The curve, then the part already traveled in the accent.
        const n = Math.max(8, P.w * 2);
        let px = X(0), py = Y(fn(0));
        for (let i = 1; i <= n; i++) {
          const s = i / n, nx = X(s), ny = Y(fn(s));
          cv.line(px, py, nx, ny, s <= u ? th.accent : curveC);
          px = nx; py = ny;
        }
        const v = fn(u);
        cv.circle(X(u), Y(v), Math.max(1, cv.sx * 0.75), th.ink, true);
        // Value bar: a vertical track to the right of the plot.
        const bx = (r.x + r.w - 1) * cv.sx + Math.floor(cv.sx / 2);
        for (let y = Y(1); y <= Y(0); y++) cv.set(bx, y, guide);
        for (let y = Math.min(Y(0), Y(v)); y <= Math.max(Y(0), Y(v)); y++) cv.set(bx, y, th.info);
        labels.push([r, name]);
      });
      cv.paint(ctx.buffer);
      for (const [r, name] of labels) put(ctx.buffer, r.x, r.y, name, th.ink, undefined, undefined, r.w);
    };
  },
};

sources.prism-term/src/facets/lab/easing-race.js:
// An easing race with an animator's spacing chart. Every lane covers the same
// distance in the same time, but with a different easing; the tick marks are
// where the ball is at equal time steps, so you can read ease-in (ticks
// bunched at the start), ease-out (bunched at the end) and overshoot at a glance.
import { easing } from '../../easing.js';
import { mix } from '../../color.js';
import { put } from './_lab.js';

const LANES = ['linear', 'inQuad', 'outQuad', 'inOutCubic', 'outBack', 'outBounce', 'outElastic', 'inOutExpo'];
const RUN = 1.8, HOLD = 0.8, TICKS = 12;

export default {
  id: 'lab-easing-race',
  title: 'Easing Race',
  gallery: 'lab',
  category: 'Easing & Timing',
  kind: 'chart',
  tags: ['easing', 'spacing chart', 'timing', 'race', 'ease in', 'ease out', 'animation principles'],
  order: 20,
  description: 'Balls racing the same distance in the same time with different easings, over an animator-style spacing chart.',
  size: { w: 64, h: 18 },
  minSize: { w: 24, h: 6 },
  loop: (RUN + HOLD) * 2,
  canvas: 'hires',
  palette: 'prism',
  params: {},
  setup(ctx) {
    const lanes = LANES.slice(0, Math.max(1, Math.floor(ctx.height / 2)));
    const labelW = Math.min(11, Math.max(0, ctx.width - 14));
    const cv = ctx.canvas('hires', { cols: ctx.width - labelW });
    const th = ctx.theme, pal = ctx.palette();
    const W = cv.width, laneH = (ctx.height / lanes.length) * cv.sy;
    const x0 = cv.sx * 1, x1 = W - cv.sx * 1.5;
    const track = mix(th.bg, th.line, 0.9), tick = mix(th.bg, th.muted, 0.8);
    return (t) => {
      cv.clear();
      const period = RUN + HOLD, n = Math.floor(t / period), ph = t - n * period;
      const forward = n % 2 === 0, u = Math.min(1, ph / RUN);
      lanes.forEach((name, k) => {
        const fn = easing[name], cy = laneH * (k + 0.5), col = pal(k / lanes.length);
        for (let x = x0; x <= x1; x += 2) cv.set(x, cy + laneH * 0.3, track);
        // Spacing chart: positions at equal time steps.
        for (let i = 0; i <= TICKS; i++) {
          const v = fn(i / TICKS), x = x0 + (forward ? v : 1 - v) * (x1 - x0);
          for (let d = 0; d < Math.max(1, laneH * 0.2); d++) cv.set(x, cy + laneH * 0.3 - d, tick);
        }
        const v = fn(u), x = x0 + (forward ? v : 1 - v) * (x1 - x0);
        cv.circle(x, cy, Math.max(1, laneH * 0.22 * cv.aspect), col, true);
      });
      cv.paint(ctx.buffer, labelW, 0);
      if (labelW) lanes.forEach((name, k) => put(ctx.buffer, 0, Math.floor((ctx.height / lanes.length) * (k + 0.5)), name, th.muted, undefined, undefined, labelW - 1));
    };
  },
};

sources.prism-term/src/facets/lab/iris.js:
// Irises: the old cinema in-camera trick. A circle opening on the scene
// beneath, a diamond, a five-pointed star, and a circle that opens on — and
// then closes back to — a point of interest instead of the center.
import { transitionSetup } from './_lab.js';

const clamp = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
// Signed distance to a five-pointed star of radius r (iq), y up.
function star(x, y, r) {
  const k1x = 0.809016994375, k1y = -0.587785252292, k2x = -k1x, k2y = k1y;
  x = Math.abs(x);
  let d = 2 * Math.max(k1x * x + k1y * y, 0); x -= d * k1x; y -= d * k1y;
  d = 2 * Math.max(k2x * x + k2y * y, 0); x -= d * k2x; y -= d * k2y;
  x = Math.abs(x); y -= r;
  const bax = 0.5 * -k1y, bay = 0.5 * k1x - 1;
  const h = Math.min(Math.max((x * bax + y * bay) / (bax * bax + bay * bay), 0), r);
  return Math.hypot(x - bax * h, y - bay * h) * Math.sign(y * bax - x * bay);
}
const VARIANTS = [
  { name: 'iris · circle', mask: (x, y, p, W, H, asp) => { const R = Math.hypot(W / 2, (H / 2) * asp) * 1.05 * p; return clamp((R - Math.hypot(x - W / 2, (y - H / 2) * asp)) / 1.5 + 0.5); } },
  { name: 'iris · diamond', mask: (x, y, p, W, H, asp) => { const R = (W / 2 + (H / 2) * asp) * 1.02 * p; return clamp((R - Math.abs(x - W / 2) - Math.abs((y - H / 2) * asp)) / 1.5 + 0.5); } },
  { name: 'iris · star', mask: (x, y, p, W, H, asp) => { const R = Math.hypot(W, H * asp) * 1.6 * p; return clamp(-star(x - W / 2, -(y - H / 2) * asp, R) / 1.5 + 0.5); } },
  { name: 'iris · on a point of interest', mask: (x, y, p, W, H, asp) => { const cx = W * 0.22, cy = H * 0.26, R = Math.hypot(W, H * asp) * p; return clamp((R - Math.hypot(x - cx, (y - cy) * asp)) / 1.5 + 0.5); } },
];

export default {
  id: 'lab-iris',
  title: 'Irises',
  gallery: 'lab',
  category: 'Transitions',
  kind: 'scene',
  tags: ['transition', 'iris', 'iris in', 'iris out', 'cinema', 'mask'],
  order: 30,
  description: 'Cinema irises between two scenes: circle, diamond, five-pointed star, and one that opens on a point of interest.',
  size: { w: 60, h: 20 },
  minSize: { w: 20, h: 7 },
  loop: VARIANTS.length * 4,
  canvas: 'field',
  palette: 'theme',
  params: {},
  setup: (ctx) => transitionSetup(ctx, VARIANTS),
};

sources.prism-term/src/facets/lab/keyframes.js:
// A keyframe timeline, After-Effects style. Up top a stage where a sprite
// moves, grows and changes color; below it one track per property with its
// keyframes (◆ eased, ◇ linear), the value curve between them, and a playhead
// sweeping across with a running timecode. Every property is interpolated
// from its own keys, so you can watch the timeline drive the picture.
import { easing } from '../../easing.js';
import { mix } from '../../color.js';
import { put } from './_lab.js';

const LEN = 4; // seconds
// [time, value, easing-into-this-key]
const TRACKS = [
  { name: 'x', keys: [[0, 0.08, 'linear'], [1.2, 0.5, 'inOutCubic'], [2.4, 0.92, 'outBack'], [3.4, 0.5, 'inOutCubic'], [4, 0.08, 'inOutCubic']] },
  { name: 'y', keys: [[0, 0.75, 'linear'], [0.8, 0.2, 'outQuad'], [1.6, 0.75, 'outBounce'], [2.8, 0.35, 'inOutSine'], [4, 0.75, 'inOutSine']] },
  { name: 'scale', keys: [[0, 0.5, 'linear'], [1.2, 1, 'outElastic'], [2.6, 0.6, 'inOutCubic'], [4, 0.5, 'linear']] },
  { name: 'hue', keys: [[0, 0, 'linear'], [2, 0.5, 'linear'], [4, 1, 'linear']] },
];
function valueAt(keys, t) {
  if (t <= keys[0][0]) return keys[0][1];
  for (let i = 1; i < keys.length; i++) {
    const [t1, v1, e] = keys[i], [t0, v0] = keys[i - 1];
    if (t <= t1) return v0 + (v1 - v0) * easing[e]((t - t0) / (t1 - t0));
  }
  return keys[keys.length - 1][1];
}

export default {
  id: 'lab-keyframes',
  title: 'Keyframe Timeline',
  gallery: 'lab',
  category: 'Easing & Timing',
  kind: 'tui',
  tags: ['keyframes', 'timeline', 'playhead', 'interpolation', 'tracks', 'motion design'],
  order: 40,
  description: 'A keyframe timeline driving a sprite: per-property tracks with eased keys, value curves, a playhead and timecode.',
  size: { w: 72, h: 22 },
  minSize: { w: 30, h: 10 },
  loop: LEN,
  canvas: 'line',
  palette: 'prism',
  params: {},
  setup(ctx) {
    const th = ctx.theme, pal = ctx.palette();
    const W = ctx.width, H = ctx.height;
    const trackH = Math.max(1, Math.min(3, Math.floor((H * 0.5) / TRACKS.length)));
    const tlTop = H - TRACKS.length * trackH - 1, stageH = tlTop - 1;
    const gutter = 7;
    const stage = ctx.canvas('line', { cols: W, rows: Math.max(1, stageH) });
    const curves = ctx.canvas('line', { cols: W - gutter, rows: TRACKS.length * trackH });
    const guide = mix(th.bg, th.line, 0.9), curveC = mix(th.bg, th.muted, 0.7);
    const T = (s) => gutter + Math.round((s / LEN) * (W - gutter - 1));
    return (t) => {
      const tl = ((t % LEN) + LEN) % LEN;
      const [x, y, sc, hue] = TRACKS.map((tr) => valueAt(tr.keys, tl));
      // Stage: floor line, the sprite, and a faint onion-skin of its last positions.
      stage.clear();
      for (let i = 0; i < stage.width; i += 3) stage.set(i, stage.height - 1, guide);
      for (let g = 4; g >= 1; g--) {
        const tg = (((tl - g * 0.08) % LEN) + LEN) % LEN, [gx, gy] = TRACKS.map((tr) => valueAt(tr.keys, tg));
        stage.circle(gx * stage.width, gy * (stage.height - 1), 1, mix(th.bg, th.muted, 0.5 - g * 0.08), true);
      }
      const r = Math.max(1.5, Math.min(stage.width, stage.height * stage.aspect) * 0.24 * sc);
      stage.circle(x * stage.width, y * (stage.height - 1 - r / stage.aspect) + r / stage.aspect, r, pal(hue), true);
      stage.paint(ctx.buffer, 0, 0);
      // Timeline: per-track value curve, then keys and the playhead as text.
      curves.clear();
      TRACKS.forEach((tr, k) => {
        const top = k * trackH * curves.sy, h = trackH * curves.sy - 1;
        let px = 0, py = top + h * (1 - tr.keys[0][1]);
        for (let i = 1; i <= curves.width; i++) {
          const v = valueAt(tr.keys, (i / curves.width) * LEN), ny = top + h * (1 - Math.max(0, Math.min(1.2, v)) / 1.2);
          curves.line(px, py, i, ny, curveC); px = i; py = ny;
        }
      });
      curves.paint(ctx.buffer, gutter, tlTop + 1);
      const b = ctx.buffer;
      // Ruler with seconds.
      for (let x2 = gutter; x2 < W; x2++) b.set(x2, tlTop, '─', guide);
      for (let s = 0; s <= LEN; s++) { const cx = Math.min(W - 2, T(s)); b.set(cx, tlTop, '┬', th.muted); put(b, cx + 1, tlTop, `${s}s`, th.muted); }
      TRACKS.forEach((tr, k) => {
        const row = tlTop + 1 + k * trackH + Math.floor(trackH / 2);
        put(b, 0, row, tr.name, th.ink, undefined, undefined, gutter - 1);
        for (const [kt, , e] of tr.keys) b.set(Math.min(W - 1, T(kt)), row, e === 'linear' ? '◇' : '◆', Math.abs(kt - tl) < 0.12 ? th.accent : th.info);
      });
      const ph = T(tl);
      for (let row = tlTop; row < H; row++) {
        const ch = b.get(ph, row)?.ch;
        b.set(ph, row, ch === '◆' || ch === '◇' ? ch : '│', th.accent); // keys under the playhead stay visible
      }
      put(b, 0, tlTop, `${tl.toFixed(2)}s`, th.accent, undefined, undefined, gutter - 1);
    };
  },
};

sources.prism-term/src/facets/lab/lfo-scope.js:
// A four-channel LFO oscilloscope: sine, triangle, saw and square at musical
// LFO rates, drawn by a sweeping beam over a dotted graticule. Ahead of the
// beam the previous sweep lingers dimmer, like phosphor persistence; each
// channel is labeled with its shape and rate.
import { mix } from '../../color.js';
import { put } from './_lab.js';

const SWEEP = 2;
const CHANNELS = [
  ['SIN', 0.5, (p) => Math.sin(p * Math.PI * 2)],
  ['TRI', 1, (p) => 1 - 4 * Math.abs((((p + 0.25) % 1) + 1) % 1 - 0.5)],
  ['SAW', 1.5, (p) => 2 * ((((p % 1) + 1) % 1)) - 1],
  ['SQR', 2, (p) => ((((p % 1) + 1) % 1) < 0.5 ? 1 : -1)],
];

export default {
  id: 'lab-lfo-scope',
  title: 'LFO Scope',
  gallery: 'lab',
  category: 'Loops & Cycles',
  kind: 'chart',
  tags: ['lfo', 'oscilloscope', 'sine', 'saw', 'square', 'triangle', 'waveform', 'phosphor'],
  order: 10,
  description: 'A four-channel oscilloscope sweeping sine, triangle, saw and square LFOs over a graticule with phosphor persistence.',
  size: { w: 64, h: 20 },
  minSize: { w: 24, h: 8 },
  loop: SWEEP * 2,
  canvas: 'line',
  palette: 'prism',
  params: {},
  setup(ctx) {
    const cv = ctx.canvas('line');
    const W = cv.width, H = cv.height, th = ctx.theme, pal = ctx.palette();
    const chans = CHANNELS.slice(0, Math.max(1, Math.floor(ctx.height / 4)));
    const band = H / chans.length;
    const grat = mix(th.bg, th.line, 0.85);
    const cols = chans.map((_, k) => mix(pal(0.3 + k * 0.17), th.ink, 0.1));
    return (t) => {
      cv.clear();
      // Graticule: dotted divisions every eighth, and each channel's zero line.
      for (let d = 1; d < 8; d++) { const x = Math.round((W * d) / 8); for (let y = 0; y < H; y += 3) cv.set(x, y, grat); }
      const sweepStart = Math.floor(t / SWEEP) * SWEEP, beam = ((t - sweepStart) / SWEEP) * W;
      chans.forEach(([, hz, fn], k) => {
        const cy = band * (k + 0.5), amp = band * 0.38;
        for (let x = 0; x < W; x += 4) cv.set(x, cy, grat);
        let px = null, py = null;
        for (let x = 0; x < W; x++) {
          const live = x <= beam, tt = (live ? sweepStart : sweepStart - SWEEP) + (x / W) * SWEEP;
          const y = cy - fn(tt * hz) * amp;
          const c = live ? cols[k] : mix(th.bg, cols[k], 0.3);
          if (px !== null && Math.abs(x - beam) > 1) cv.line(px, py, x, y, c);
          px = x; py = y;
        }
        const hy = cy - fn(t * hz) * amp;
        cv.circle(beam, hy, 1.4, th.ink, true);
      });
      cv.paint(ctx.buffer);
      chans.forEach(([name, hz], k) => put(ctx.buffer, 1, Math.floor((ctx.height / chans.length) * k), `${name} ${hz.toFixed(2)} Hz`, cols[k], undefined, undefined, ctx.width - 2));
    };
  },
};

sources.prism-term/src/facets/lab/lissajous.js:
// A Lissajous table: columns are the x frequency, rows the y frequency, and
// each cell traces x = sin(a·s + δ), y = sin(b·s) in braille. The phase δ
// drifts slowly, so every figure turns in 3D-looking rotation, and a bright
// dot runs each curve at its own pace.
import { mix } from '../../color.js';
import { grid, put, pxRect } from './_lab.js';

export default {
  id: 'lab-lissajous',
  title: 'Lissajous Table',
  gallery: 'lab',
  category: 'Loops & Cycles',
  kind: 'chart',
  tags: ['lissajous', 'harmonics', 'phase', 'frequency ratio', 'parametric', 'braille'],
  order: 30,
  description: 'A Lissajous table — x frequency across, y frequency down — with drifting phase and a dot running every figure.',
  size: { w: 64, h: 22 },
  minSize: { w: 20, h: 7 },
  loop: 20,
  canvas: 'line',
  palette: 'prism',
  params: {},
  setup(ctx) {
    const cv = ctx.canvas('line');
    const th = ctx.theme, pal = ctx.palette();
    const head = ctx.height >= 10 ? 1 : 0, side = head ? 4 : 0;
    const cols = Math.max(1, Math.min(5, Math.floor((ctx.width - side) / 11))), rows = Math.max(1, Math.min(3, Math.floor((ctx.height - head) / 6)));
    const cells = grid(ctx.width - side, ctx.height - head, cols, rows, 1, 0, side, head);
    return (t) => {
      cv.clear();
      const delta = (t / 20) * Math.PI * 2;
      cells.forEach((r, k) => {
        const a = (k % cols) + 1, b = Math.floor(k / cols) + 1;
        const P = pxRect(cv, r), cx = P.x + P.w / 2, cy = P.y + P.h / 2;
        const rx = P.w / 2 - 1, ry = Math.min(P.h / 2 - 1, rx / cv.aspect);
        const col = pal((k / cells.length) * 0.9), n = 90 * Math.max(a, b);
        let px = null, py = null;
        for (let i = 0; i <= n; i++) {
          const s = (i / n) * Math.PI * 2, x = cx + Math.sin(a * s + delta) * rx, y = cy - Math.sin(b * s) * ry;
          if (px !== null) cv.line(px, py, x, y, mix(th.bg, col, 0.75));
          px = x; py = y;
        }
        const s = t * 1.3;
        cv.circle(cx + Math.sin(a * s + delta) * rx, cy - Math.sin(b * s) * ry, 1.2, th.ink, true);
      });
      cv.paint(ctx.buffer);
      if (head) {
        for (let c = 0; c < cols; c++) put(ctx.buffer, cells[c].x + Math.floor(cells[c].w / 2) - 1, 0, `a${c + 1}`, th.muted);
        for (let r = 0; r < rows; r++) put(ctx.buffer, 0, cells[r * cols].y + Math.floor(cells[r * cols].h / 2), `b${r + 1}`, th.muted);
      }
    };
  },
};

sources.prism-term/src/facets/lab/loading-choreo:
// Loading choreography for a terminal card: skeleton bars with a shimmer
// sweep, then a spinner while a progress bar eases to full, then the real
// content staggering in line by line, then a success mark that pops — and a
// soft fade back to the skeleton. Each stage hands off to the next on cue.
import { easing } from '../../easing.js';
import { mix } from '../../color.js';
import { box } from '../../widgets/index.js';
import { put } from './_lab.js';

const LOOP = 8;
const SPIN = '⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏';
const LINES = [
  ['api-gateway-03.example', 'ink'],
  ['region  lab-west-2   pool  10.20.4.0/24', 'muted'],
  ['p95 latency  182 ms      errors  0.02%', 'muted'],
  ['last deploy  14 min ago  build  4f1c2e7', 'muted'],
];

export default {
  id: 'lab-loading-choreo',
  title: 'Loading Choreography',
  gallery: 'lab',
  category: 'Loops & Cycles',
  kind: 'tui',
  tags: ['loading', 'skeleton', 'shimmer', 'spinner', 'progress', 'stagger', 'choreography'],
  order: 20,
  description: 'A card loading in stages: shimmering skeleton, spinner and eased progress, staggered content, then a popping success mark.',
  size: { w: 56, h: 14 },
  minSize: { w: 30, h: 9 },
  loop: LOOP,
  canvas: 'none',
  palette: 'theme',
  params: {},
  setup(ctx) {
    const th = ctx.theme, b = ctx.buffer;
    return (t) => {
      const tl = ((t % LOOP) + LOOP) % LOOP;
      const W = Math.min(ctx.width, 56), H = Math.min(ctx.height, 14);
      const x0 = Math.floor((ctx.width - W) / 2), y0 = Math.floor((ctx.height - H) / 2);
      box(b, x0, y0, W, H, { theme: th, fill: true, color: th.line });
      const ix = x0 + 2, iw = W - 4, rows = Math.min(LINES.length, H - 5);
      const fadeOut = tl > 7.3 ? (tl - 7.3) / 0.7 : 0;
      const rowY = (r) => y0 + 1 + (r ? r + 1 : 0); // title, a gap, then detail lines
      // Stage 1 (0–1.8 s) and the tail of the loop: skeleton bars with a shimmer.
      if (tl < 3.2 || fadeOut > 0) {
        const sweep = ((tl % 1.4) / 1.4) * (iw + 16) - 8;
        for (let r = 0; r < rows; r++) {
          const len = Math.max(4, Math.round(iw * [0.55, 0.9, 0.8, 0.7][r]));
          for (let x = 0; x < len; x++) {
            const sh = Math.exp(-(((x - sweep + r * 2) / 4) ** 2)) * 0.35;
            b.set(ix + x, rowY(r), ' ', undefined, mix(th.panel2, th.ink, sh * (1 - fadeOut * 0.5)));
          }
        }
      }
      // Stage 2 (1.8–3.2 s): spinner, status line and an eased progress bar.
      if (tl >= 1.8 && tl < 3.4) {
        const p = easing.inOutCubic(Math.min(1, (tl - 1.8) / 1.3));
        const sp = SPIN[Math.floor(tl * 12) % SPIN.length];
        put(b, ix, y0 + H - 3, `${sp} fetching service health…`, th.info, undefined, undefined, iw);
        const bw = iw - 5, fill = p * bw;
        for (let x = 0; x < bw; x++) {
          const part = Math.max(0, Math.min(1, fill - x));
          b.set(ix + x, y0 + H - 2, part >= 1 ? '█' : part > 0 ? '▌' : '─', part > 0 ? th.accent : th.line);
        }
        put(b, ix + bw + 1, y0 + H - 2, `${Math.round(p * 100)}%`.padStart(4), th.muted);
      }
      // Stage 3 (3.2–4.6 s): the real content staggers in, sliding two cells.
      if (tl >= 3.2 && fadeOut < 1) {
        for (let r = 0; r < rows; r++) {
          const q = Math.min(1, Math.max(0, (tl - 3.2 - r * 0.22) / 0.4));
          if (q <= 0) continue;
          const e = easing.outCubic(q), off = Math.round((1 - e) * 2);
          const [text, tone] = LINES[r];
          const fg = mix(th.panel, th[tone], e * (1 - fadeOut));
          put(b, ix + off, rowY(r), text, fg, undefined, r === 0 ? 1 : 0, iw - off);
        }
      }
      // Stage 4 (4.6–5.6 s): the success mark pops (·, •, ✓ with an overshoot in color).
      if (tl >= 4.6 && fadeOut < 1) {
        const q = Math.min(1, (tl - 4.6) / 0.5), mark = q < 0.33 ? '·' : q < 0.66 ? '•' : '✓';
        const glow = q < 1 ? mix(th.pos, 0xffffff, 0.4 * Math.sin(q * Math.PI)) : th.pos;
        put(b, ix, y0 + H - 2, `${mark} healthy`, mix(th.panel, glow, 1 - fadeOut), undefined, 1, iw);
        put(b, ix + 11, y0 + H - 2, 'all checks passed', mix(th.panel, th.muted, Math.min(1, (tl - 4.9) / 0.4) * (1 - fadeOut)), undefined, undefined, iw - 11);
      }
      const stage = tl < 1.8 ? 'skeleton' : tl < 3.2 ? 'fetch' : tl < 4.6 ? 'reveal' : tl < 7.3 ? 'done' : 'reset';
      put(b, x0 + W - stage.length - 3, y0, ` ${stage} `, th.muted);
    };
  },
};

sources.prism-term/src/facets/lab/motion-blur.js:
// Frame rate versus motion blur, side by side. The same scene — a three-blade
// propeller and a ball swinging past — sampled four ways: 60 fps sharp, 12 fps
// sharp (it strobes), 12 fps with a 180° shutter (smooth again, at the same
// frame rate) and 6 fps with a 360° shutter. Blur is real temporal
// supersampling: each panel averages sub-frame samples across its shutter.
import { mix } from '../../color.js';
import { grid, put } from './_lab.js';

const PANELS = [['60 fps', 60, 0], ['12 fps', 12, 0], ['12 fps · 180° shutter', 12, 0.5], ['6 fps · 360° shutter', 6, 1]];
const SUBS = 10, SPIN = 1.15; // revolutions per second

export default {
  id: 'lab-motion-blur',
  title: 'Frame Rate vs Motion Blur',
  gallery: 'lab',
  category: 'Easing & Timing',
  kind: 'scene',
  tags: ['motion blur', 'frame rate', 'shutter angle', 'strobing', 'temporal aliasing', 'fps'],
  order: 60,
  description: 'One scene sampled four ways — 60 fps, 12 fps, 12 fps with a 180° shutter and 6 fps blurred — to compare strobe and blur.',
  size: { w: 72, h: 22 },
  minSize: { w: 30, h: 10 },
  loop: 4,
  canvas: 'field',
  palette: 'prism',
  params: {},
  setup(ctx) {
    const th = ctx.theme, pal = ctx.palette();
    const two = ctx.width >= 28;
    const rects = grid(ctx.width, ctx.height, two ? 2 : 1, two ? 2 : 4, 2, 1).slice(0, PANELS.length);
    const cv = ctx.canvas('field');
    const asp = cv.aspect, blade = pal(0.08), ballC = pal(0.55);
    const covers = (cx, cy, R, x, y, tt) => {
      // Propeller: three tapered blades plus a hub; ball: a disc on a pendulum swing.
      const dx = x - cx, dy = (y - cy) * asp, r = Math.hypot(dx, dy);
      let hit = 0;
      if (r < R * 0.9) {
        const a = Math.atan2(dy, dx) - tt * SPIN * Math.PI * 2;
        for (let k = 0; k < 3; k++) {
          let d = (a + (k * Math.PI * 2) / 3) % (Math.PI * 2); if (d < -Math.PI) d += Math.PI * 2; if (d > Math.PI) d -= Math.PI * 2;
          if (Math.abs(d) < 0.32 * (1 - (r / R) * 0.6) || r < R * 0.14) { hit = 1; break; }
        }
      }
      const bx = cx + Math.sin(tt * Math.PI * 1.5) * R * 1.9, by = cy + R * 1.05;
      if (Math.hypot(x - bx, (y - by) * asp) < R * 0.28) hit = 2;
      return hit;
    };
    return (t) => {
      cv.clear();
      PANELS.forEach(([, fps, shutter], k) => {
        const r = rects[k];
        if (!r || r.h < 3) return;
        const x0 = r.x * cv.sx, y0 = r.y * cv.sy, w = r.w * cv.sx, h = (r.h - 1) * cv.sy;
        const R = Math.min(w / 4.4, (h * asp) / 2.9), cx = x0 + w / 2, cy = y0 + h * 0.4;
        const tf = Math.floor(t * fps) / fps, n = shutter ? SUBS : 1;
        for (let y = y0; y < y0 + h; y++) for (let x = x0; x < x0 + w; x++) {
          let a = 0, b = 0;
          for (let s = 0; s < n; s++) {
            const hit = covers(cx, cy, R, x + 0.5, y + 0.5, tf + (shutter * (s + 0.5)) / (n * fps));
            if (hit === 1) a++; else if (hit === 2) b++;
          }
          if (!a && !b) continue;
          let c = mix(th.bg, blade, a / n);
          c = mix(c, ballC, b / n);
          cv.set(x, y, c);
        }
      });
      cv.paint(ctx.buffer);
      PANELS.forEach(([name], k) => { const r = rects[k]; if (r && r.h >= 3) put(ctx.buffer, r.x, r.y + r.h - 1, name, th.muted, undefined, undefined, r.w); });
    };
  },
};

// A pendulum wave seen from above: fifteen pendulums whose lengths are tuned
// so pendulum k swings 20 + k times every 30 seconds. They start in a line,
// drift into traveling snakes, split into two and three interleaved rows,
// dissolve into apparent chaos — and all line up again at the end of the loop.
import { mix } from '../../color.js';
import { put } from './_lab.js';

const N = 15, T = 30, BASE = 20;

export default {
  id: 'lab-pendulum-wave',
  title: 'Pendulum Wave',
  gallery: 'lab',
  category: 'Loops & Cycles',
  kind: 'scene',
  tags: ['pendulum wave', 'harmonics', 'phase', 'beats', 'realignment', 'loop'],
  order: 40,
  description: 'Fifteen pendulums tuned to 20–34 swings per 30 s: snakes, interleaved rows, chaos, then perfect realignment.',
  size: { w: 60, h: 20 },
  minSize: { w: 20, h: 7 },
  loop: T,
  canvas: 'field',
  palette: 'prism',
  params: {},
  setup(ctx) {
    const label = ctx.height >= 8;
    const cv = ctx.canvas('field', { rows: label ? ctx.height - 1 : ctx.height });
    const W = cv.width, H = cv.height, asp = cv.aspect, th = ctx.theme, pal = ctx.palette();
    const gap = W / N, R = Math.max(1, Math.min(gap * 0.38, H * asp * 0.08)), amp = H * 0.5 - R / asp - 1;
    const rail = mix(th.bg, th.line, 0.8), snake = mix(th.bg, th.muted, 0.5);
    return (t) => {
      cv.clear();
      const tl = ((t % T) + T) % T, cy = H / 2;
      for (let x = 0; x < W; x += 2) cv.set(x, cy, rail);
      const pos = Array.from({ length: N }, (_, k) => [gap * (k + 0.5), cy + Math.cos((Math.PI * 2 * (BASE + k) * tl) / T) * amp]);
      for (let k = 1; k < N; k++) cv.line(pos[k - 1][0], pos[k - 1][1], pos[k][0], pos[k][1], snake);
      pos.forEach(([x, y], k) => {
        const col = pal(k / N);
        for (let yy = Math.floor(y - R / asp) - 1; yy <= y + R / asp + 1; yy++) for (let xx = Math.floor(x - R) - 1; xx <= x + R + 1; xx++) {
          const nx = (xx + 0.5 - x) / R, ny = ((yy + 0.5 - y) * asp) / R, q = nx * nx + ny * ny;
          if (q <= 1) cv.set(xx, yy, mix(mix(0x000000, col, 0.4 + 0.6 * Math.max(0, 0.6 - nx * 0.4 - ny * 0.5 + 0.3 * Math.sqrt(1 - q))), 0xffffff, Math.max(0, -nx - ny - 1.1) * 0.6));
        }
      });
      cv.paint(ctx.buffer);
      if (label) put(ctx.buffer, 1, ctx.height - 1, `pendulum k swings ${BASE}+k times per ${T} s · t = ${tl.toFixed(1).padStart(4)} s`, th.muted, undefined, undefined, ctx.width - 2);
    };
  },
};

sources.prism-term/src/facets/lab/slide.js:
// Slides: the moves every UI uses. Push (the new scene shoves the old one
// out), cover (it slides over the top), reveal (the old one slides away), and
// a vertical push — each eased out so it lands softly.
import { transitionSetup } from './_lab.js';
import { easing } from '../../easing.js';

const VARIANTS = [
  {
    name: 'slide · push left',
    draw(px, A, B, W, H, asp, p) {
      const o = Math.round(p * W);
      for (let y = 0, k = 0; y < H; y++) for (let x = 0; x < W; x++, k++) px[k] = x + o < W ? A[y * W + x + o] : B[y * W + x + o - W];
    },
  },
  {
    name: 'slide · cover from the right',
    draw(px, A, B, W, H, asp, p) {
      const e = Math.round((1 - p) * W);
      for (let y = 0, k = 0; y < H; y++) for (let x = 0; x < W; x++, k++) px[k] = x >= e ? B[y * W + x - e] : A[k];
    },
  },
  {
    name: 'slide · reveal (old scene slides away)',
    draw(px, A, B, W, H, asp, p) {
      const o = Math.round(p * W);
      for (let y = 0, k = 0; y < H; y++) for (let x = 0; x < W; x++, k++) px[k] = x + o < W ? A[y * W + x + o] : B[k];
    },
  },
  {
    name: 'slide · push up',
    draw(px, A, B, W, H, asp, p) {
      const o = Math.round(p * H);
      for (let y = 0, k = 0; y < H; y++) for (let x = 0; x < W; x++, k++) px[k] = y + o < H ? A[(y + o) * W + x] : B[(y + o - H) * W + x];
    },
  },
];

export default {
  id: 'lab-slide',
  title: 'Slides & Pushes',
  gallery: 'lab',
  category: 'Transitions',
  kind: 'scene',
  tags: ['transition', 'slide', 'push', 'cover', 'reveal', 'ui motion'],
  order: 40,
  description: 'Slide transitions between two scenes: push, cover, reveal and a vertical push, each eased out to land softly.',
  size: { w: 60, h: 20 },
  minSize: { w: 20, h: 7 },
  loop: VARIANTS.length * 4,
  canvas: 'field',
  palette: 'theme',
  params: {},
  setup: (ctx) => transitionSetup(ctx, VARIANTS, { ease: easing.outCubic }),
};

sources.prism-term/src/facets/lab/spring.js:
// Spring and damper tuning: four masses on identical springs, differing only
// in damping ratio ζ — underdamped (rings), lightly damped, critically damped
// (fastest with no overshoot) and overdamped (sluggish). The target steps back
// and forth; each lane draws the coil and mass, and plots x(t) against the target.
import { mix } from '../../color.js';
import { put } from './_lab.js';

const LANES = [[0.15, 'ringing'], [0.4, 'light'], [1, 'critical'], [2, 'overdamped']];
const STEP = 2.5, HZ = 240, W0 = Math.PI * 2 * 1.1, HIST = 180; // history samples (60 Hz → 3 s)

export default {
  id: 'lab-spring',
  title: 'Spring & Damper',
  gallery: 'lab',
  category: 'Springs & Physics',
  kind: 'chart',
  tags: ['spring', 'damping', 'damping ratio', 'critical damping', 'overshoot', 'physics animation'],
  order: 10,
  description: 'Four springs differing only in damping ratio chase a stepping target, each plotting its response against it.',
  size: { w: 72, h: 20 },
  minSize: { w: 30, h: 8 },
  loop: STEP * 2,
  canvas: 'line',
  palette: 'prism',
  params: {},
  setup(ctx) {
    const cv = ctx.canvas('line');
    const th = ctx.theme, pal = ctx.palette();
    const lanes = LANES.slice(0, Math.max(1, Math.floor(ctx.height / 4)));
    const labelW = 11, split = labelW + Math.floor((ctx.width - labelW) * 0.48);
    const laneH = (ctx.height / lanes.length) * cv.sy;
    const sx0 = labelW * cv.sx, sx1 = split * cv.sx - cv.sx, px0 = (split + 1) * cv.sx, px1 = cv.width - cv.sx;
    const S = lanes.map(() => ({ x: 0.2, v: 0, hist: [] }));
    const guide = mix(th.bg, th.muted, 0.45);
    let acc = 0, rec = 0, simT = 0;
    const target = (tt) => (Math.floor(tt / STEP) % 2 === 0 ? 0.8 : 0.2);
    return (t, dt) => {
      acc += Math.min(0.25, Math.max(0, dt)) * HZ;
      for (; acc >= 1; acc--) {
        simT += 1 / HZ;
        const g = target(simT);
        lanes.forEach(([z], k) => { const s = S[k]; s.v += (-W0 * W0 * (s.x - g) - 2 * z * W0 * s.v) / HZ; s.x += s.v / HZ; });
        if (++rec % 4 === 0) S.forEach((s) => { s.hist.push([s.x, g]); if (s.hist.length > HIST) s.hist.shift(); });
      }
      cv.clear();
      lanes.forEach(([z], k) => {
        const s = S[k], col = pal(k / lanes.length), top = k * laneH, cy = top + laneH * 0.5;
        const X = (v) => sx0 + cv.sx + v * (sx1 - sx0 - cv.sx * 3);
        // Wall, coil, mass.
        for (let y = top + laneH * 0.2; y < top + laneH * 0.8; y++) cv.set(sx0, y, th.muted);
        const mx = X(s.x), coils = 9, amp = laneH * 0.18;
        let lx = sx0, ly = cy;
        for (let i = 1; i <= coils * 2; i++) {
          const nx = sx0 + ((mx - sx0) * i) / (coils * 2), ny = cy + (i === coils * 2 ? 0 : (i % 2 ? -amp : amp));
          cv.line(lx, ly, nx, ny, mix(th.muted, th.ink, 0.3)); lx = nx; ly = ny;
        }
        cv.circle(mx + cv.sx, cy, Math.max(1.5, laneH * 0.22), col, true);
        const gx = X(target(simT));
        for (let y = top + laneH * 0.15; y < top + laneH * 0.85; y += 2) cv.set(gx + cv.sx, y, guide);
        // Response plot: target (dotted) and x(t), newest on the right.
        const h = s.hist, ph = laneH * 0.7, py = (v) => top + laneH * 0.15 + (1 - (v + 0.1) / 1.2) * ph;
        for (let i = 1; i < h.length; i++) {
          const xa = px1 - ((h.length - i) / HIST) * (px1 - px0), xb = px1 - ((h.length - i - 1) / HIST) * (px1 - px0);
          if (i % 2) cv.set(xb, py(h[i][1]), guide);
          cv.line(xa, py(h[i - 1][0]), xb, py(h[i][0]), col);
        }
      });
      cv.paint(ctx.buffer);
      lanes.forEach(([z, word], k) => {
        const row = Math.floor((ctx.height / lanes.length) * k + (ctx.height / lanes.length) / 2) - (ctx.height >= 12 ? 1 : 0);
        put(ctx.buffer, 0, row, `ζ ${z.toFixed(2)}`, th.ink, undefined, undefined, labelW - 1);
        if (ctx.height >= 12) put(ctx.buffer, 0, row + 1, word, th.muted, undefined, undefined, labelW - 1);
      });
    };
  },
};

sources.prism-term/src/facets/lab/stagger.js:
// Stagger studies: a grid of tiles entering one after another, each popping in
// with an overshoot (outBack) and leaving on the same order reversed. Four
// orderings cycle — from the left, from the center out, a diagonal wave and a
// seeded shuffle — to show how much the order alone changes the feel.
import { easing } from '../../easing.js';
import { mix } from '../../color.js';
import { cycle, put } from './_lab.js';

const MODE = 3.4, SPREAD = 1.1, POP = 0.45;

export default {
  id: 'lab-stagger',
  title: 'Stagger',
  gallery: 'lab',
  category: 'Easing & Timing',
  kind: 'scene',
  tags: ['stagger', 'cascade', 'delay', 'outback', 'choreography', 'ui motion'],
  order: 50,
  description: 'A grid of tiles staggering in and out four ways — from the left, from the center, as a wave, and shuffled.',
  size: { w: 60, h: 20 },
  minSize: { w: 20, h: 7 },
  loop: MODE * 4,
  canvas: 'field',
  palette: 'prism',
  params: {},
  setup(ctx) {
    const label = ctx.height >= 8;
    const cv = ctx.canvas('field', { rows: label ? ctx.height - 1 : ctx.height });
    const W = cv.width, H = cv.height, th = ctx.theme, pal = ctx.palette(), rand = ctx.rng;
    const tw = Math.max(3, Math.round(W / 12)), thH = Math.max(3, Math.round(tw / cv.aspect * 0.9));
    const cols = Math.max(1, Math.floor((W + 1) / (tw + 1))), rows = Math.max(1, Math.floor((H + 1) / (thH + 1)));
    const ox = Math.floor((W - (cols * (tw + 1) - 1)) / 2), oy = Math.floor((H - (rows * (thH + 1) - 1)) / 2);
    const tiles = [];
    for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) tiles.push({ c, r, rnd: rand() });
    const maxD = Math.hypot((cols - 1) / 2, (rows - 1) / 2) || 1;
    const MODES = [
      ['from the left', (p) => p.c / Math.max(1, cols - 1)],
      ['from the centre', (p) => Math.hypot(p.c - (cols - 1) / 2, p.r - (rows - 1) / 2) / maxD],
      ['diagonal wave', (p) => (p.c + p.r) / Math.max(1, cols + rows - 2)],
      ['shuffled', (p) => p.rnd],
    ];
    return (t) => {
      const { i, f } = cycle(t, MODES.length, MODE);
      const [name, order] = MODES[i], lt = f * MODE;
      cv.clear();
      for (const p of tiles) {
        const d = order(p) * SPREAD;
        const qIn = Math.min(1, Math.max(0, (lt - d) / POP));
        const qOut = Math.min(1, Math.max(0, (lt - 2.1 - d * 0.6) / (POP * 0.7)));
        const k = qOut > 0 ? 1 - easing.inQuad(qOut) : easing.outBack(qIn);
        if (k <= 0.01) continue;
        const cx = ox + p.c * (tw + 1) + tw / 2, cy = oy + p.r * (thH + 1) + thH / 2;
        const hw = (tw / 2) * k, hh = (thH / 2) * k, col = mix(th.bg, pal(order(p) * 0.85), Math.min(1, qIn * 1.5) * (1 - qOut * 0.5));
        for (let y = Math.round(cy - hh); y < Math.round(cy + hh); y++) for (let x = Math.round(cx - hw); x < Math.round(cx + hw); x++) cv.set(x, y, col);
      }
      cv.paint(ctx.buffer);
      if (label) put(ctx.buffer, 1, ctx.height - 1, `stagger · ${name} · ${Math.round((SPREAD / Math.max(1, tiles.length)) * 1000)} ms apart · outBack in, inQuad out`, th.muted, undefined, undefined, ctx.width - 2);
    };
  },
};

sources.prism-term/src/facets/lab/wipe.js:
// Wipes, four ways, between a daybreak and a night skyline: a soft-edged
// linear wipe, a diagonal, a clock (radial sweep) and barn doors. Each runs
// day → night and back on an eased hold-move-hold beat.
import { transitionSetup } from './_lab.js';

const clamp = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
const VARIANTS = [
  { name: 'wipe · linear, soft edge', mask: (x, y, p, W) => { const soft = W * 0.08, e = p * (W + soft * 2) - soft; return clamp((e - x) / soft + 0.5); } },
  { name: 'wipe · diagonal', mask: (x, y, p, W, H, asp) => { const u = x + y * asp, span = W + H * asp, soft = span * 0.05, e = p * (span + soft * 2) - soft; return clamp((e - u) / soft + 0.5); } },
  { name: 'wipe · clock', mask: (x, y, p, W, H, asp) => { const a = (Math.atan2(x - W / 2, -(y - H / 2) * asp) / (Math.PI * 2) + 1) % 1; return clamp((p * 1.04 - a) / 0.04); } },
  { name: 'wipe · barn doors', mask: (x, y, p, W) => { const u = Math.abs(x - W / 2) / (W / 2), soft = 0.06; return clamp((p * (1 + soft * 2) - soft - u) / soft + 0.5); } },
];

export default {
  id: 'lab-wipe',
  title: 'Wipes',
  gallery: 'lab',
  category: 'Transitions',
  kind: 'scene',
  tags: ['transition', 'wipe', 'clock wipe', 'barn doors', 'soft edge', 'scene change'],
  order: 10,
  description: 'Four wipes between a daybreak and a night skyline: soft linear, diagonal, clock sweep and barn doors.',
  size: { w: 60, h: 20 },
  minSize: { w: 20, h: 7 },
  loop: VARIANTS.length * 4,
  canvas: 'field',
  palette: 'theme',
  params: {},
  setup: (ctx) => transitionSetup(ctx, VARIANTS),
};

sources.prism-term/src/facets/loaders/_kit.js:
// Shared presentation for spinner facets.
//
// A spinner tile shows the spinner the way you meet it — inline, in front of a
// task label with an elapsed timer — and then the whole cycle as a filmstrip
// (current frame lit) with its frame count and interval, so you can judge the
// rhythm at a glance. Tiles degrade by dropping rows: at two rows you get the
// live line and the strip, at one row just the live line.
//
// Without Unicode (TERM=linux, LANG=C) a non-ASCII spinner falls back to the
// classic `-\|/` and every label uses plain ASCII.

import { getSpinner } from '../../spinners.js';
import { palette as makePalette, PALETTES } from '../../palettes.js';
import { stringWidth, truncate } from '../../width.js';
import { mix } from '../../color.js';

export const ASCII_LINE = { frames: ['-', '\\', '|', '/'], interval: 130 };
const isAscii = (s) => /^[\x20-\x7e]*$/.test(s);
export const asciiSpinner = (spin) => spin.frames.every(isAscii);

const BITS = [[0x01, 0x08], [0x02, 0x10], [0x04, 0x20], [0x40, 0x80]];
/** Dots ([[x,y], …] with x in 0..2*cells-1, y in 0..3) → a braille string `cells` wide. */
export function braille(cells, dots) {
  const m = new Array(cells).fill(0);
  for (const [x, y] of dots) {
    const xi = Math.round(x), yi = Math.round(y);
    if (xi < 0 || yi < 0 || yi > 3 || xi >= cells * 2) continue;
    m[xi >> 1] |= BITS[yi][xi & 1];
  }
  return m.map((v) => String.fromCharCode(0x2800 + v)).join('');
}
export const range = (n, f) => Array.from({ length: n }, (_, i) => f(i));

/** Index of the frame showing at time t. */
export const frameAt = (spin, t) => Math.floor((Math.max(0, t) * 1000) / spin.interval) % spin.frames.length;

/**
 * Draw one spinner frame. Color precedence: spin.colorAt(t, i, k, theme) per
 * character, then a sweeping spin.palette, then `color`.
 */
export function drawFrame(surface, x, y, spin, k, t, theme, color, cache) {
  const chars = [...spin.frames[k]];
  let cx = x;
  let g = null;
  if (spin.palette && !spin.colorAt) {
    g = cache.get(spin.palette);
    if (!g) { g = makePalette(spin.palette, theme); cache.set(spin.palette, g); }
  }
  chars.forEach((ch, i) => {
    let c = color;
    if (spin.colorAt) c = spin.colorAt(t, i, k, theme);
    else if (g) {
      const u = ((t * 0.45 + (i / Math.max(1, chars.length)) * 0.5) % 1 + 1) % 1;
      c = PALETTES[spin.palette]?.cyclic ? g(u) : g(0.45 + 0.55 * (u < 0.5 ? u * 2 : 2 - u * 2));
    }
    cx = surface.text(cx, y, ch, c);
  });
  return cx;
}

const fmtElapsed = (s) => (s < 60 ? `${s.toFixed(1)}s` : `${Math.floor(s / 60)}m${String(Math.floor(s % 60)).padStart(2, '0')}s`);

/**
 * Build a spinner facet.
 * @param {object} o
 *   id, title, category, description, tags     catalog metadata
 *   spin      a name from src/spinners.js, or { frames, interval, palette?, colorAt? }
 *   labels    task messages the live line cycles through (Unicode allowed; ASCII twins via asciiLabels)
 *   name      label for the meta line (defaults to the spinner name)
 *   color     theme token for monochrome spinners (default 'accent')
 */
export function spinnerFacet(o) {
  const spin0 = typeof o.spin === 'string' ? getSpinner(o.spin) : o.spin;
  const ascii = asciiSpinner(spin0);
  const width = Math.max(...spin0.frames.map(stringWidth));
  const labels = o.labels || ['Working…'];
  const asciiLabels = o.asciiLabels || labels.map((l) => l.replace(/…/g, '...').replace(/[^\x20-\x7e]/g, ''));
  return {
    id: o.id,
    title: o.title,
    category: o.category,
    description: o.description,
    tags: ['spinner', 'loader', ...(o.tags || [])],
    kind: 'spinner',
    size: { w: 44, h: 5 },
    minSize: { w: 24, h: 2 },
    loop: o.loop || 8,
    glyphs: ascii ? 'ascii' : o.glyphs || (spin0.frames.some((f) => /[⠀-⣿]/.test(f)) ? 'braille' : 'unicode'),
    color: spin0.palette || spin0.colorAt ? '256' : '16',
    order: o.order ?? 50,
    params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
    setup(ctx) {
      const th = ctx.theme;
      const unicode = ctx.caps.unicode !== false;
      const spin = unicode || ascii ? spin0 : ASCII_LINE;
      const lines = unicode ? labels : asciiLabels;
      const base = th[o.color || 'accent'] ?? th.accent;
      const cache = new Map();
      const speed = ctx.param('speed', 1);
      const W = ctx.width, H = ctx.height;
      const fw = unicode || ascii ? width : 1;
      return (t) => {
        const b = ctx.buffer;
        const tt = t * speed;
        const k = frameAt(spin, tt);
        // Live line: spinner, task label, elapsed (right).
        const row = 0;
        let x = drawFrame(b, 1, row, spin, k, tt, th, base, cache);
        const label = lines[Math.floor(t / 2.6) % lines.length];
        const elapsed = fmtElapsed(t);
        const room = W - x - 2 - (W >= 32 ? elapsed.length + 1 : 0);
        b.text(x + 1, row, truncate(label, Math.max(0, room), unicode ? '…' : '.'), th.ink);
        if (W >= 32) b.text(W - 1 - elapsed.length, row, elapsed, th.dim);
        if (H < 2) return;

        // Filmstrip of the whole cycle, windowed around the current frame.
        // Rows: live line · strip · meta, spread over what the tile has.
        const stripY = H >= 4 ? 2 : 1;
        const metaY = H >= 5 ? 4 : H >= 4 ? 3 : 2;
        const cellW = fw + 1;
        const fit = Math.max(1, Math.floor((W - 2) / cellW));
        const n = spin.frames.length;
        const start = n <= fit ? 0 : Math.min(n - fit, Math.max(0, k - Math.floor(fit / 2)));
        for (let i = start, sx = 1; i < Math.min(n, start + fit); i++, sx += cellW) {
          if (i === k) {
            b.fill(sx, stripY, fw, 1, undefined, undefined, mix(th.bg, base, 0.18));
            drawFrame(b, sx, stripY, spin, i, tt, th, base, cache);
          } else b.text(sx, stripY, spin.frames[i], th.dim);
        }
        if (n > fit && W > 12) b.text(W - 3, stripY, unicode ? ' …' : '..', th.dim);
        if (H < 3) return;

        // Meta line.
        const fallback = unicode || ascii ? '' : ' (ASCII fallback)';
        const meta = `${o.name || (typeof o.spin === 'string' ? o.spin : o.id.replace(/^loaders-/, ''))}${fallback} ${unicode ? '·' : '-'} ${n} frames ${unicode ? '·' : '-'} ${spin.interval} ms`;
        b.text(1, metaY, truncate(meta, W - 2, unicode ? '…' : '.'), th.muted);
      };
    },
  };
}

// Prism originals — spinners with a bit of personality, generated from small
// formulas so every frame is exactly the same width.
import { spinnerFacet, braille, range } from './_kit.js';
import { mix, hsl } from '../../color.js';

const lerp = (a, b, k) => a + (b - a) * k;

// A ball under gravity bouncing across eight cells, with a two-dot motion trail.
const bounceFrames = (() => {
  const N = 40, out = [], pos = [];
  for (let k = 0; k < N; k++) {
    const u = k / N;                            // one lap: right then back
    const x = u < 0.5 ? u * 2 * 15 : (1 - u) * 2 * 15;
    const hop = (u * 6) % 1;                    // six hops per lap
    const y = 3 - 3 * 4 * hop * (1 - hop);      // parabola, floor at y=3
    pos.push([x, y]);
  }
  for (let k = 0; k < N; k++) out.push(braille(8, [pos[k], pos[(k - 1 + N) % N], pos[(k - 2 + N) % N]]));
  return out;
})();

// Five dots riding a traveling sine wave.
const dotWave = range(16, (k) => braille(5, range(5, (i) => [i * 2 + 0.5, 1.5 - 1.5 * Math.sin((k / 16) * Math.PI * 2 - i * 0.8)])));

// A nucleus with two electrons on tilted orbits.
const electrons = range(24, (k) => {
  const a = (k / 24) * Math.PI * 2;
  const dots = [[3, 1], [4, 1], [3, 2], [4, 2]];
  for (let j = 0; j < 3; j++) {
    const b = a - j * 0.35;
    dots.push([3.5 + 3.5 * Math.cos(b), 1.5 + 1.4 * Math.sin(b) * 0.9]);
    dots.push([3.5 + 2.6 * Math.cos(-b * 1.5 + 1.3), 1.5 + 1.5 * Math.sin(-b * 1.5 + 1.3)]);
  }
  return braille(4, dots);
});

// Concentric rings expanding from the center and fading.
const ripple = range(14, (k) => {
  const dots = [];
  for (const off of [0, 7]) {
    const r = ((k + off) % 14) / 14 * 3.2;
    if (r < 0.3) { dots.push([2.5, 1.5]); continue; }
    for (let s = 0; s < 24; s++) {
      const a = (s / 24) * Math.PI * 2;
      dots.push([2.5 + r * Math.cos(a), 1.5 + r * 0.55 * Math.sin(a)]);
    }
  }
  return braille(3, dots);
});

// A clock hand sweeping a two-cell dial, with a fixed hub.
const clockHand = range(12, (k) => {
  const a = (k / 12) * Math.PI * 2 - Math.PI / 2;
  const dots = [[1.5, 1.5]];
  for (let s = 0.6; s <= 2; s += 0.45) dots.push([1.5 + s * Math.cos(a) * 1.15, 1.5 + s * Math.sin(a)]);
  return braille(2, dots);
});

// Morse "PRISM" on a scrolling tape, with a signal lamp.
const morse = (() => {
  const code = { P: '.--.', R: '.-.', I: '..', S: '...', M: '--' };
  const units = [];
  for (const ch of 'PRISM') {
    for (const [j, s] of [...code[ch]].entries()) {
      units.push(...Array(s === '.' ? 1 : 3).fill(1));
      if (j < code[ch].length - 1) units.push(0);
    }
    units.push(0, 0, 0);
  }
  units.push(0, 0, 0, 0);
  const T = 12;
  return range(units.length, (k) => {
    const lamp = units[k] ? '●' : '○';
    const tape = range(T, (i) => (units[(k + i) % units.length] ? '━' : ' ')).join('');
    return `${lamp} ${tape}`;
  });
})();

// White light entering a prism and fanning out as a spectrum.
const prismSweep = range(12, (k) => {
  const beam = range(3, (i) => (i === k % 3 ? '━' : '─')).join('');
  const fan = range(6, (j) => {
    const spread = (j + 1) * 0.28;
    return braille(1, [0, 1].flatMap((dx) => [1.5 - spread, 1.5 - spread / 3, 1.5 + spread / 3, 1.5 + spread].map((y) => [dx, y])));
  }).join('');
  return `${beam}◆${fan}`;
});

// An ECG trace scrolling left: baseline, P wave, QRS spike, T wave.
const ecg = (() => {
  const beat = [2, 2, 2, 1.6, 2, 2, 3, 0, 3, 2, 2, 1.4, 1.2, 1.6, 2, 2, 2, 2, 2, 2];
  return range(beat.length, (k) => {
    const dots = [];
    let prev = null;
    for (let x = 0; x < 16; x++) {
      const y = beat[(k + x) % beat.length];
      if (prev !== null) for (let s = 0; s <= 1; s += 0.5) dots.push([x - 1 + s, lerp(prev, y, s)]);
      dots.push([x, y]);
      prev = y;
    }
    return braille(8, dots);
  });
})();

// Two paddles rallying a ball across an eight-cell court.
const pong = range(32, (k) => {
  const u = k / 32;
  const bx = 1 + (u < 0.5 ? u * 2 : 2 - u * 2) * 13;
  const by = 1.5 + 1.5 * Math.sin(u * Math.PI * 4);
  const pl = Math.max(0, Math.min(2, by - 0.5)), pr = Math.max(0, Math.min(2, 1.5 + 1.5 * Math.sin((u + 0.04) * Math.PI * 4) - 0.5));
  return braille(8, [[0, pl], [0, pl + 1], [15, pr], [15, pr + 1], [bx, by]]);
});

// A snake on a serpentine path through a 8×4 dot field, eating and growing.
const snakeGame = (() => {
  const path = [];
  for (let y = 0; y < 4; y++) for (let i = 0; i < 8; i++) path.push([y % 2 ? 7 - i : i, y]);
  const N = path.length;
  return range(N, (k) => {
    const len = 2 + Math.floor((k / N) * 5);
    const body = range(len, (j) => path[(k - j + N) % N]);
    const food = path[(k + 6) % N];
    return braille(4, [...body, food]);
  });
})();

// A rotating two-arm spiral.
const spiral = range(16, (k) => {
  const dots = [];
  for (let arm = 0; arm < 2; arm++) for (let s = 0; s < 6; s++) {
    const r = 0.3 + s * 0.3, a = (k / 16) * Math.PI * 2 + s * 0.7 + arm * Math.PI;
    dots.push([1.5 + r * Math.cos(a) * 1.2, 1.5 + r * Math.sin(a)]);
  }
  return braille(2, dots);
});

// A chomping mouth working through a row of pellets.
const pacman = range(8, (k) => {
  const open = [0.9, 0.6, 0.25, 0.05, 0.25, 0.6, 0.9, 1][k];
  const head = [];
  for (let y = 0; y < 4; y++) for (let x = 0; x < 4; x++) {
    const dx = x - 1.5, dy = y - 1.5;
    if (dx * dx + dy * dy > 4.2) continue;
    const ang = Math.abs(Math.atan2(dy, dx));
    if (dx > 0 && ang < open) continue;
    head.push([x, y]);
  }
  // Pellets every other dot, sliding one dot left per frame into the mouth.
  const pellets = range(5, (p) => [1 + p * 2 - (k % 2), 1.5]);
  return braille(2, head) + braille(5, pellets);
});

// Three dots breathing in sequence.
const dotsSizes = ['∙', '•', '●', '•'];
const gradientDots = range(12, (k) => range(3, (i) => dotsSizes[Math.floor((k / 3 + 4 - i) % 4)]).join(' '));

// A real 8-bit counter (binary increments), not random noise.
const bits = range(64, (k) => ((k + 176) & 255).toString(2).padStart(8, '0'));

// Embers rising out of three cells of flame.
const ember = (() => {
  let s = 1234567;
  const rnd = () => ((s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
  return range(20, () => {
    const dots = [];
    for (let x = 0; x < 6; x++) {
      const hgt = 1 + Math.floor(rnd() * 3.2);
      for (let y = 3; y > 3 - hgt; y--) dots.push([x, y]);
      if (rnd() < 0.35) dots.push([x, Math.floor(rnd() * 2)]);
    }
    return braille(3, dots);
  });
})();

const O = 'Orbits & Shapes', B = 'Braille Spinners', P = 'Bars & Pulses', T = 'Truecolor Spinners', CL = 'Classic Spinners';

export default [
  spinnerFacet({ id: 'loaders-gravity-bounce', name: 'gravity-bounce', title: 'Gravity Bounce', category: O, order: 70,
    spin: { frames: bounceFrames, interval: 45, colorAt: (t, i, k, th) => mix(th.info, th.ink, 0.35) },
    description: 'A braille ball hopping across eight cells under real parabolic gravity, trailing two dots of motion blur.',
    tags: ['physics', 'ball', 'gravity', 'original'], labels: ['Rebalancing load…', 'Bouncing requests…'] }),
  spinnerFacet({ id: 'loaders-dot-wave', name: 'dot-wave', title: 'Dot Wave', category: B, order: 80,
    spin: { frames: dotWave, interval: 60 },
    description: 'Five braille dots riding a traveling sine wave — a calm, readable loader for long tasks.',
    tags: ['braille', 'wave', 'original'], labels: ['Syncing…', 'Applying migrations…'] }),
  spinnerFacet({ id: 'loaders-electrons', name: 'electrons', title: 'Electron Orbits', category: O, order: 80,
    spin: { frames: electrons, interval: 55, colorAt: (t, i, k, th) => (i === 1 || i === 2 ? mix(th.warn, th.ink, 0.2) : th.info) },
    description: 'Two electrons circling a warm nucleus on tilted orbits, drawn in four braille cells.',
    tags: ['braille', 'atom', 'orbit', 'original'], labels: ['Splitting workloads…', 'Charging capacitors…'] }),
  spinnerFacet({ id: 'loaders-ripple', name: 'ripple', title: 'Ripple', category: P, order: 140,
    spin: { frames: ripple, interval: 70, colorAt: (t, i, k, th) => mix(th.accent, th.info, 0.5 + 0.5 * Math.sin(t * 3 + i)) },
    description: 'Concentric braille rings expanding from a point and fading out — a sonar ping with depth.',
    tags: ['braille', 'ripple', 'sonar', 'original'], labels: ['Discovering services…', 'Waiting for gossip…'] }),
  spinnerFacet({ id: 'loaders-clock-hand', name: 'clock-hand', title: 'Clock Hand', category: O, order: 90,
    spin: { frames: clockHand, interval: 110 },
    description: 'A braille clock hand sweeping a two-cell dial round a fixed hub — Unicode-only, no emoji needed.',
    tags: ['braille', 'clock', 'time', 'original'], labels: ['Waiting for maintenance window…', 'Sleeping 30s…'] }),
  spinnerFacet({ id: 'loaders-morse', name: 'morse', title: 'Morse Lamp', category: P, order: 150,
    spin: { frames: morse, interval: 90, colorAt: (t, i, k, th) => (i === 0 ? (morse[k][0] === '●' ? th.warn : th.dim) : th.accent) },
    description: 'A signal lamp flashing PRISM in real Morse timing while the code scrolls past on a tape.',
    tags: ['morse', 'signal', 'lamp', 'original'], labels: ['Transmitting…', 'Signalling peers…'] }),
  spinnerFacet({ id: 'loaders-prism-sweep', name: 'prism-sweep', title: 'Prism Refraction', category: T, order: 100,
