// The atom symbol, built for real: a nucleus of lit, z-buffered protons and
// neutrons, three tilted orbits drawn as anti-aliased (bilinear-splatted) rings
// that pass behind and in front of it, and electrons with glowing heads and
// fading trails. Everything loops exactly every twelve seconds.
import { zbuffer, sphere, perspective, rotX, rotY, rotZ, mul, apply, norm, blend } from './_raster.js';
import { NONE, luminance } from '../../color.js';

const LOOP = 12;

export default {
  title: 'Atom',
  gallery: 'objects',
  category: 'Icons & Logos',
  kind: 'art',
  tags: ['atom', 'science', 'orbit', 'electron', 'nucleus', 'physics'],
  order: 20,
  description: 'A lit nucleus of protons and neutrons inside three tilted orbits, with glowing electrons trailing light.',
  size: { w: 56, h: 22 },
  minSize: { w: 18, h: 7 },
  loop: LOOP,
  canvas: 'field',
  palette: 'prism',
  params: { electrons: { default: 3, min: 1, max: 6, label: 'Electrons' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const z = zbuffer(cv);
    const W = cv.width, H = cv.height, asp = cv.aspect, th = ctx.theme;
    const pal = ctx.palette();
    const nE = Math.round(ctx.param('electrons', 3));
    const dist = 5;
    const project = perspective(cv, { distance: dist, fill: 0.43 });
    const scale = Math.min(W, H * asp) * 0.43; // pixels per world unit at the origin
    const light = norm([-0.5, -0.65, -0.6]);
    const half = norm([light[0], light[1], light[2] - 1]); // Blinn half-vector (viewer at -z)
    const dark = luminance(th.bg) < 0.5;
    const proton = blend(0xe8505b, th.neg, 0.35), neutron = blend(0x9fb3c8, th.muted, 0.3);
    // Nucleons packed on two shells; protons and neutrons alternate (seeded).
    const nucleons = [];
    const shell = (n, rad) => {
      for (let i = 0; i < n; i++) {
        const y = 1 - (2 * (i + 0.5)) / n, r = Math.sqrt(1 - y * y), a = i * 2.39996;
        nucleons.push({ p: [Math.cos(a) * r * rad, y * rad, Math.sin(a) * r * rad], c: ctx.rng() < 0.5 ? proton : neutron });
      }
    };
    shell(10, 0.2); shell(3, 0.07);
    const nr = Math.max(0.12, 0.9 / scale); // nucleon radius (world), never below ~1px
    const orbitCol = [0.02, 0.36, 0.68].map((f) => blend(pal(f), th.info, 0.2));
    const tilt = [0, 1, 2].map((k) => mul(rotZ((k * Math.PI) / 3 + 0.1), rotX(1.08)));
    const spd = [4, -3, 5, 6, -4, 7];

    const acc = new Float32Array(W * H * 4); // r, g, b, alpha (premultiplied)
    const splat1 = (i, d, col, a) => {
      if (z[i] < d - 0.02) return; // hidden behind the nucleus
      const o = i * 4;
      acc[o] += ((col >> 16) & 255) * a; acc[o + 1] += ((col >> 8) & 255) * a; acc[o + 2] += (col & 255) * a; acc[o + 3] += a;
    };
    const splat = (x, y, d, col, a) => {
      x -= 0.5; y -= 0.5;
      const x0 = Math.floor(x), y0 = Math.floor(y), fx = x - x0, fy = y - y0;
      for (let j = 0; j < 4; j++) {
        const xx = x0 + (j & 1), yy = y0 + (j >> 1);
        if (xx < 0 || yy < 0 || xx >= W || yy >= H) continue;
        splat1(yy * W + xx, d, col, a * ((j & 1) ? fx : 1 - fx) * ((j >> 1) ? fy : 1 - fy));
      }
    };
    const glow = (x, y, d, col, a, sigma) => {
      const R = Math.ceil(sigma * 2.5), Ry = Math.ceil(R / asp);
      for (let yy = Math.floor(y) - Ry; yy <= Math.floor(y) + Ry; yy++) for (let xx = Math.floor(x) - R; xx <= Math.floor(x) + R; xx++) {
        if (xx < 0 || yy < 0 || xx >= W || yy >= H) continue;
        const dx = xx + 0.5 - x, dy = (yy + 0.5 - y) * asp;
        const w = Math.exp(-(dx * dx + dy * dy) / (2 * sigma * sigma));
        if (w > 0.02) splat1(yy * W + xx, d, col, a * w);
      }
    };

    // Splat orbit M from angle a0 to a1 in n steps, each weighted by the screen
    // distance it covers, so the line is evenly bright even where it is seen edge-on.
    const arc = (M, a0, a1, n, col, k) => {
      let prev = null;
      for (let s = 0; s <= n; s++) {
        const f = s / n, a = a0 + (a1 - a0) * f;
        const q = apply(M, [Math.cos(a), Math.sin(a), 0]);
        const p = project(q);
        if (prev) splat((p[0] + prev[0]) / 2, (p[1] + prev[1]) / 2, p[2], col, Math.hypot(p[0] - prev[0], p[1] - prev[1]) * k(f, q));
        prev = p;
      }
    };

    return (t) => {
      cv.clear();
      z.fill(Infinity);
      acc.fill(0);
      const ph = (t / LOOP) * Math.PI * 2;
      const G = mul(rotY(Math.sin(ph) * 0.45), mul(rotX(0.18 + Math.cos(ph) * 0.14), rotZ(Math.sin(ph * 2) * 0.08)));
      // Nucleus: slowly tumbling, lit spheres, z-buffered against each other.
      const N = mul(G, mul(rotY(ph), rotX(ph * 2)));
      for (const n of nucleons) {
        const q = apply(N, n.p), [sx, sy, sd] = project(q);
        const rp = (nr * scale * dist) / sd;
        sphere(cv, z, sx, sy, rp, sd, (nx, ny, nz) => {
          const dif = Math.max(0, nx * light[0] + ny * light[1] + nz * light[2]);
          const spec = Math.pow(Math.max(0, nx * half[0] + ny * half[1] + nz * half[2]), 28);
          return blend(blend(0x000000, n.c, 0.22 + 0.78 * dif), 0xffffff, spec * 0.8);
        }, nr);
      }
      // Orbits, brighter on the near side.
      const orbits = tilt.map((T) => mul(G, T));
      const steps = Math.ceil(Math.PI * 2 * scale * 4);
      orbits.forEach((M, k) => arc(M, 0, Math.PI * 2, steps, orbitCol[k], (f, q) => 0.42 - q[2] * 0.22));
      // Electrons: a glowing head and a trail fading back along the orbit.
      for (let e = 0; e < nE; e++) {
        const k = e % 3, M = orbits[k], w = (spd[e] * Math.PI * 2) / LOOP;
        const a0 = w * t + e * 2.1;
        const col = blend(orbitCol[k], 0xffffff, 0.55);
        arc(M, a0 - Math.sign(w) * 1.3, a0, Math.ceil(scale * 2.5), col, (f) => 0.6 * Math.pow(f, 2.2));
        const q = apply(M, [Math.cos(a0), Math.sin(a0), 0]);
        const [x, y, d] = project(q);
        glow(x, y, d, col, 1.1, Math.max(0.7, scale * 0.06));
      }
      // Composite the light: additive on dark themes, ink-like on light ones.
      const px = cv.px;
      for (let i = 0; i < W * H; i++) {
        const o = i * 4, a = acc[o + 3];
        if (a < 0.01) continue;
        const base = px[i] === NONE ? th.bg : px[i];
        if (dark) {
          const r = Math.min(255, ((base >> 16) & 255) + acc[o]), g = Math.min(255, ((base >> 8) & 255) + acc[o + 1]), b = Math.min(255, (base & 255) + acc[o + 2]);
          px[i] = (r << 16) | (g << 8) | (b | 0);
        } else {
          const col = ((acc[o] / a) << 16) | ((acc[o + 1] / a) << 8) | ((acc[o + 2] / a) | 0);
          px[i] = blend(base, blend(col, th.ink, 0.35), Math.min(1, a * 1.8));
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/objects/dna.js:
// A DNA double helix spinning about its axis while the whole molecule slowly
// yaws and rolls in perspective. Backbones, base-pair rungs (A–T / G–C colored
// halves) and nucleotide beads are depth-sorted and shaded front-to-back, so
// the near strand reads in front of the far one even at braille resolution.
import { rotate, projector } from '../../math3d.js';
import { mix, NONE } from '../../color.js';

export default {
  title: 'DNA Helix',
  gallery: 'objects',
  category: '3D Solids',
  kind: 'scene',
  tags: ['dna', 'helix', 'biology', '3d'],
  order: 40,
  description: 'Rotating double helix in perspective — depth-sorted, shaded backbones, A–T/G–C base-pair rungs and drifting motes.',
  canvas: 'line',
  palette: 'prism',
  setup(ctx) {
    const cv = ctx.canvas();
    const { width: W, height: H, aspect } = cv;
    const th = ctx.theme;
    const rand = ctx.rng;
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const fill = 0.42;
    const unit = Math.min(W, H * aspect) * fill;
    const L = Math.max(1, (W / 2 / unit) * 0.92);
    const R = Math.min(0.55, (H * aspect) / unit / 2 * 0.62);
    const turns = Math.max(1.5, (L * 2) / 1.35);
    const kx = (turns * Math.PI * 2) / (2 * L);
    const proj = projector(cv, { distance: 3.4, fill });
    const BASES = [[th.pos, th.neg], [th.neg, th.pos], [th.warn, th.info], [th.info, th.warn]];
    const NR = Math.round(turns * 10);
    const pairs = Array.from({ length: NR }, () => BASES[Math.floor(rand() * 4)]);
    const NS = Math.max(60, Math.round(W * 0.9));
    const bg = ctx.bg === NONE ? 0 : ctx.bg;
    const motes = Array.from({ length: Math.round(W * H * 0.0006) + 8 }, () => ({ x: rand() * W, y: rand() * H, v: 0.5 + rand(), p: rand() * 6.28 }));

    const shade = (c, k) => mix(bg, c, k);
    return (t, dt) => {
      const spin = t * 0.9 * speed;
      const ay = 0.3 * Math.sin(t * 0.21), az = 0.16 * Math.sin(t * 0.13 + 1), ax = 0.25 * Math.sin(t * 0.17);
      const P = (x, phase) => {
        const a = x * kx + spin + phase;
        const p = rotate([x, R * Math.cos(a), R * Math.sin(a)], ax, ay, az);
        return proj(p);
      };
      const segs = [];
      for (let s = 0; s < 2; s++) {
        let prev = P(-L, s * Math.PI);
        for (let i = 1; i <= NS; i++) {
          const x = -L + (2 * L * i) / NS;
          const cur = P(x, s * Math.PI);
          const u = i / NS;
          segs.push({ a: prev, b: cur, d: (prev[2] + cur[2]) / 2, c: pal(u * 0.45 + s * 0.5 + t * 0.02), w: 1 });
          prev = cur;
        }
      }
      for (let i = 0; i < NR; i++) {
        const x = -L + (2 * L * (i + 0.5)) / NR;
        const a = P(x, 0), b = P(x, Math.PI);
        const m = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2];
        segs.push({ a, b: m, d: (a[2] + m[2]) / 2, c: pairs[i][0], w: 0 });
        segs.push({ a: m, b, d: (m[2] + b[2]) / 2, c: pairs[i][1], w: 0 });
        segs.push({ bead: a, d: a[2] - 0.01, c: pal(((i + 0.5) / NR) * 0.45 + t * 0.02) });
        segs.push({ bead: b, d: b[2] - 0.01, c: pal(((i + 0.5) / NR) * 0.45 + 0.5 + t * 0.02) });
      }
      let dmin = Infinity, dmax = -Infinity;
      for (const s of segs) { if (s.d < dmin) dmin = s.d; if (s.d > dmax) dmax = s.d; }
      const span = dmax - dmin || 1;
      segs.sort((p, q) => q.d - p.d);

      cv.clear();
      for (const m of motes) {
        m.y -= m.v * dt * H * 0.03;
        if (m.y < 0) { m.y += H; m.x = rand() * W; }
        cv.set(m.x + Math.sin(t * 0.5 + m.p) * 3, m.y, shade(th.muted, 0.35 + 0.25 * Math.sin(t + m.p)));
      }
      for (const s of segs) {
        const near = 1 - (s.d - dmin) / span;
        const k = 0.28 + 0.72 * near * near;
        if (s.bead) {
          const r = (1 + near * 1.6) * (cv.sx / 2);
          cv.ellipse(s.bead[0], s.bead[1], r, r / aspect, shade(s.c, Math.min(1, k + 0.15)), true);
        } else {
          cv.line(s.a[0], s.a[1], s.b[0], s.b[1], shade(s.c, Math.min(1, s.w ? k : k * 1.1)));
          // Thicken the near half of the backbones.
          if (s.w && near > 0.55) cv.line(s.a[0], s.a[1] + 1, s.b[0], s.b[1] + 1, shade(s.c, k * 0.8));
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/objects/donut.js:
// donut.c, done properly: a torus splatted into a z-buffer at a density matched
// to the canvas resolution (surface points, normals and materials precomputed
// once; one 3×3 matrix per frame), Lambert + Blinn-Phong lit, hole-filled, and
// dressed in glossy frosting with a wavy drip edge and sprinkles. It spins on
// its axis, wobbles, and flips over every few seconds. `--set style=solid`
// renders a theme-lit ring instead.
export default {
  title: 'Donut',
  gallery: 'objects',
  category: '3D Solids',
  kind: 'scene',
  tags: ['donut', 'torus', 'donut.c', '3d', 'lighting'],
  order: 10,
  description: 'The donut.c torus, z-buffered and properly lit — frosted with sprinkles, or --set style=solid.',
  canvas: 'hires',
  palette: 'candy',
  setup(ctx) {
    const cv = ctx.canvas(undefined, { dither: true });
    const solid = ctx.param('style', ctx.params.palette ? 'solid' : 'frosted') === 'solid';
    const sprinkleColors = ctx.palette('candy');
    const ramp = ctx.params.palette
      ? ctx.palette()
      : ctx.palette([0x05060a, ctx.theme.accent, ctx.theme.info, 0xffffff]);
    const frost = ctx.param('frosting', '#ff6fae');
    const frostC = typeof frost === 'string' ? parseInt(frost.replace('#', ''), 16) : frost;
    const flipEvery = ctx.param('flip', 9);
    const { width: W, height: H, px, aspect } = cv;
    const zbuf = new Float32Array(W * H);
    const R = 1, r = 0.46, dist = 5;
    const scale = Math.min(W, H * aspect) * 0.29 * dist;
    const kmax = scale / (dist - (R + r));
    const nP = Math.ceil(2 * Math.PI * (R + r) * kmax * 1.05);
    const nT = Math.ceil(2 * Math.PI * r * kmax * 1.1);
    const N = nP * nT;

    // Surface samples: position, normal, material (0 dough, 1 frosting, 2+ sprinkle).
    const P = new Float32Array(N * 3), Nn = new Float32Array(N * 3), mat = new Uint8Array(N), tone = new Float32Array(N);
    const sprink = [];
    const rand = ctx.rng;
    for (let k = 0; k < 14; k++) sprink.push(sprinkleColors(k / 14));
    const cellsP = 46, cellsT = 12, seeds = [];
    for (let a = 0; a < cellsT * cellsP; a++) seeds.push(rand() < 0.62 ? { u: rand(), v: rand(), ang: rand() * Math.PI, c: 2 + Math.floor(rand() * 14) } : null);
    for (let i = 0, n = 0; i < nT; i++) {
      const th = (i / nT) * Math.PI * 2, ct = Math.cos(th), st = Math.sin(th);
      for (let j = 0; j < nP; j++, n++) {
        const ph = (j / nP) * Math.PI * 2, cp = Math.cos(ph), sp = Math.sin(ph);
        const ring = R + r * ct;
        P[n * 3] = ring * cp; P[n * 3 + 1] = r * st; P[n * 3 + 2] = ring * sp;
        Nn[n * 3] = ct * cp; Nn[n * 3 + 1] = st; Nn[n * 3 + 2] = ct * sp;
        tone[n] = 0.5 + 0.5 * st;
        if (solid) continue;
        const edge = 0.18 + 0.13 * Math.sin(ph * 9 + Math.sin(ph * 4) * 2) + 0.06 * Math.sin(ph * 23);
        if (st > edge) continue; // dough (underside)
        let m = 1;
        // Sprinkles: one jittered sugar strand per parameter-space cell.
        const fu = (ph / (Math.PI * 2)) * cellsP, fv = (th / (Math.PI * 2)) * cellsT;
        const cu = Math.floor(fu), cvv = Math.floor(fv);
        const s = seeds[cvv * cellsP + cu];
        if (s && st < edge - 0.12) {
          const du = (fu - cu - (0.25 + s.u * 0.5)) * 1.6, dv = (fv - cvv - (0.25 + s.v * 0.5)) * 3.2;
          const along = du * Math.cos(s.ang) + dv * Math.sin(s.ang), across = -du * Math.sin(s.ang) + dv * Math.cos(s.ang);
          if (Math.abs(along) < 0.36 && Math.abs(across) < 0.09) m = s.c;
        }
        mat[n] = m;
      }
    }

    // Light from upper-left-front (screen y grows downward, camera looks along +z).
    const L = [-0.45, -0.7, -0.55], ll = Math.hypot(...L);
    const lx = L[0] / ll, ly = L[1] / ll, lz = L[2] / ll;
    const hl = Math.hypot(lx, ly, lz - 1);
    const hx = lx / hl, hy = ly / hl, hz = (lz - 1) / hl;
    const back = new Int32Array(W * H);
    const plainBg = cv.mode === 'ascii' || cv.mode === 'braille';
    const glow = ctx.theme.panel, base = ctx.bg === -1 ? 0 : ctx.bg;
    for (let y = 0, i = 0; y < H; y++)
      for (let x = 0; x < W; x++, i++) {
        const dx = (x - W / 2) / W, dy = ((y - H / 2) * aspect) / W;
        const k = Math.max(0, 1 - Math.sqrt(dx * dx + dy * dy) * 1.6);
        back[i] = plainBg ? -1 : mixc(base, glow, k * k);
      }
    const smooth = (u) => u * u * (3 - 2 * u);

    return (t) => {
      // Spin about its own axis, present the frosted top tilted toward us, roll gently,
      // and every `flipEvery` seconds do a full somersault.
      const spin = t * 0.8;
      const fp = flipEvery > 0 ? (t % flipEvery) / flipEvery : 0;
      const flip = fp > 0.8 ? smooth((fp - 0.8) / 0.2) * Math.PI * 2 : 0;
      const tilt = 1.0 + Math.sin(t * 0.6) * 0.35 + flip, roll = Math.sin(t * 0.37) * 0.45;
      const cs = Math.cos(spin), ss = Math.sin(spin), ca = Math.cos(tilt), sa = Math.sin(tilt), cr = Math.cos(roll), sr = Math.sin(roll);
      // M = Rz(roll) · Rx(tilt) · Ry(spin)
      const b10 = sa * ss, b11 = ca, b12 = -sa * cs;   // row 1 of Rx·Ry (row 0 is [cs, 0, ss])
      const b20 = -ca * ss, b21 = sa, b22 = ca * cs;   // row 2
      const M00 = cr * cs - sr * b10, M01 = -sr * b11, M02 = cr * ss - sr * b12;
      const M10 = sr * cs + cr * b10, M11 = cr * b11, M12 = sr * ss + cr * b12;
      const M20 = b20, M21 = b21, M22 = b22;

      px.set(back);
      zbuf.fill(0);
      const ox = W / 2, oy = H / 2;
      for (let n = 0, q = 0; n < N; n++, q += 3) {
        const nx0 = Nn[q], ny0 = Nn[q + 1], nz0 = Nn[q + 2];
        const nx = M00 * nx0 + M01 * ny0 + M02 * nz0;
        const ny = M10 * nx0 + M11 * ny0 + M12 * nz0;
        const nz = M20 * nx0 + M21 * ny0 + M22 * nz0;
        if (nz > 0.42) continue; // back-facing even at the widest view angle — skip before transforming the point
        const x0 = P[q], y0 = P[q + 1], z0 = P[q + 2];
        const x = M00 * x0 + M01 * y0 + M02 * z0;
        const y = M10 * x0 + M11 * y0 + M12 * z0;
        const d = M20 * x0 + M21 * y0 + M22 * z0 + dist;
        if (nx * x + ny * y + nz * d >= 0) continue;
        const iz = 1 / d, k = scale * iz;
        const sx = (ox + x * k) | 0, sy = (oy + (y * k) / aspect) | 0;
        if (sx < 0 || sy < 0 || sx >= W || sy >= H) continue;
        const p = sy * W + sx;
        if (iz <= zbuf[p]) continue;
        zbuf[p] = iz;
        const diff = Math.max(0, nx * lx + ny * ly + nz * lz);
        const sd = Math.max(0, nx * hx + ny * hy + nz * hz);
        if (solid) {
          const s2 = sd * sd, s4 = s2 * s2, s8 = s4 * s4, s32 = s8 * s8 * s8 * s8;
          px[p] = ramp(Math.min(1, 0.12 + diff * 0.72 + s32 * 0.5));
          continue;
        }
        const m = mat[n];
        let rr, gg, bb, gloss;
        if (m === 0) {
          const tn = tone[n];
          rr = 196 + 40 * tn; gg = 120 + 52 * tn; bb = 58 + 40 * tn;
          const s2 = sd * sd, s4 = s2 * s2;
          gloss = s4 * s4 * s4 * 0.12;
        } else {
          const c = m === 1 ? frostC : sprink[m - 2];
          rr = (c >> 16) & 255; gg = (c >> 8) & 255; bb = c & 255;
          const s2 = sd * sd, s4 = s2 * s2, s8 = s4 * s4, s16 = s8 * s8;
          gloss = s16 * s16 * s16 * 0.85;
        }
        const lit = 0.24 + diff * 0.86, g255 = gloss * 255;
        rr = rr * lit + g255; gg = gg * lit + g255; bb = bb * lit + g255;
        px[p] = ((rr > 255 ? 255 : rr) << 16) | ((gg > 255 ? 255 : gg) << 8) | (bb > 255 ? 255 : bb | 0);
      }
      // Fill single-pixel splat gaps: an empty pixel flanked by surface on both sides.
      for (let y = 1; y < H - 1; y++)
        for (let x = 1, p = y * W + 1; x < W - 1; x++, p++) {
          if (zbuf[p] !== 0) continue;
          if (zbuf[p - 1] && zbuf[p + 1]) { px[p] = zbuf[p - 1] > zbuf[p + 1] ? px[p - 1] : px[p + 1]; zbuf[p] = zbuf[p - 1]; }
          else if (zbuf[p - W] && zbuf[p + W]) { px[p] = px[p - W]; zbuf[p] = zbuf[p - W]; }
        }
      cv.paint(ctx.buffer);
    };
  },
};

function mixc(a, b, t) {
  const r = ((a >> 16) & 255) + ((((b >> 16) & 255) - ((a >> 16) & 255)) * t);
  const g = ((a >> 8) & 255) + ((((b >> 8) & 255) - ((a >> 8) & 255)) * t);
  const bl = (a & 255) + (((b & 255) - (a & 255)) * t);
  return (r << 16) | (g << 8) | (bl | 0);
}

sources.prism-term/src/facets/objects/gears.js:
// A gear train: three spur gears of 16, 10 and 8 teeth meshing at their pitch
// circles, each turning at the ratio it should (and in alternating directions).
// Rendered per pixel from the analytic tooth profile, so every edge is
// anti-aliased: spun-metal highlights that stay put while the gear turns,
// bevelled rims, recessed webs with lightening holes, raised hubs, steel axles
// and a soft drop shadow seen through the holes.
import { blend } from './_raster.js';
import { NONE } from '../../color.js';

const N = [16, 10, 8];
const HOLES = [6, 5, 0];
const METALS = [0xc9a43a, 0xa9b8c8, 0xc8804c];
const LIGHT = Math.atan2(-1, -1); // from the upper left (screen y grows down)

export default {
  title: 'Gear Train',
  gallery: 'objects',
  category: 'Mechanical',
  kind: 'scene',
  tags: ['gears', 'mechanical', 'machine', 'ratio', 'clockwork'],
  order: 10,
  description: 'Three spur gears (16, 10 and 8 teeth) meshing at true ratios, anti-aliased, with spun-metal shading and drop shadows.',
  size: { w: 64, h: 22 },
  minSize: { w: 20, h: 7 },
  loop: 6,
  canvas: 'field',
  palette: 'gold',
  params: { speed: { default: 1, min: 0.1, max: 5, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const speed = ctx.param('speed', 1);
    const W = cv.width, H = cv.height, asp = cv.aspect, th = ctx.theme;
    // Layout in "unit" space (gear 0 pitch radius = 1), then fit and center.
    const r = N.map((n) => n / N[0]);
    const add = 1 / (N[0] / 2); // addendum = one module (2r/N)
    const a01 = -0.42, a12 = 1.2;
    const u0 = [0, 0];
    const u1 = [u0[0] + Math.cos(a01) * (r[0] + r[1]), u0[1] + Math.sin(a01) * (r[0] + r[1])];
    const u2 = [u1[0] + Math.cos(a12) * (r[1] + r[2]), u1[1] + Math.sin(a12) * (r[1] + r[2])];
    const U = [u0, u1, u2];
    let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
    U.forEach(([x, y], g) => { const R = r[g] + add; x0 = Math.min(x0, x - R); x1 = Math.max(x1, x + R); y0 = Math.min(y0, y - R); y1 = Math.max(y1, y + R); });
    const unit = Math.min((W - 3) / (x1 - x0), (H * asp - 3) / (y1 - y0));
    const C = U.map(([x, y]) => [W / 2 + (x - (x0 + x1) / 2) * unit, H / 2 + ((y - (y0 + y1) / 2) * unit) / asp]);
    const R = r.map((v) => v * unit);
    const tip = add * unit, root = add * 1.25 * unit;
    const sh = [Math.max(1, unit * 0.05), Math.max(1, (unit * 0.05) / asp)]; // shadow offset (px)

    // Tooth profile radius at angle a (gear-local): root land, flank, tip land.
    const prof = (g, a) => {
      const u = (a * N[g]) / (Math.PI * 2);
      const f = Math.abs(u - Math.round(u));
      if (f < 0.17) return R[g] + tip;
      if (f < 0.31) return R[g] + tip - ((f - 0.17) / 0.14) * (tip + root);
      return R[g] - root;
    };
    // Coverage of gear g at a point (dx, dy in horizontal-pixel units from its center).
    const cover = (g, dx, dy, ang) => {
      const d = Math.hypot(dx, dy);
      if (d > R[g] + tip + 1) return 0;
      const a = Math.atan2(dy, dx) - ang[g];
      let c = Math.min(1, Math.max(0, prof(g, a) - d + 0.5));
      if (c > 0 && HOLES[g]) {
        const step = (Math.PI * 2) / HOLES[g];
        const s = a - Math.round(a / step) * step;
        const hx = d * Math.cos(s) - R[g] * 0.58, hy = d * Math.sin(s);
        c *= Math.min(1, Math.max(0, Math.hypot(hx, hy) - R[g] * 0.15 + 0.5));
      }
      return c;
    };
    const shade = (g, dx, dy, ang) => {
      const d = Math.hypot(dx, dy) + 1e-6, Rg = R[g], a = Math.atan2(dy, dx);
      const facing = Math.cos(a - LIGHT); // +1 on the edge nearest the light
      // Spun finish: a bright bow-tie streak aimed at the light, fixed on screen.
      let k = 0.5 + 0.34 * Math.pow(Math.abs(facing), 10) + 0.08 * facing;
      const local = a - ang[g];
      const edge = prof(g, local) - d;
      if (edge < 1.4) k += 0.32 * facing; // bevelled outline (teeth and rim)
      const web0 = Rg * 0.32, web1 = Rg - root - Rg * 0.12;
      if (HOLES[g] && d > web0 && d < web1) {
        k -= 0.14; // recessed web
        if (d - web0 < 1.1) k -= 0.2 * facing; // inner wall of the recess
        if (web1 - d < 1.1) k += 0.2 * facing; // outer wall
        const step = (Math.PI * 2) / HOLES[g];
        const s = local - Math.round(local / step) * step;
        const hx = d * Math.cos(s) - Rg * 0.58, hy = d * Math.sin(s);
        if (Math.hypot(hx, hy) - Rg * 0.15 < 1.2) k += 0.22 * Math.cos(Math.atan2(hy, hx) + a - s + Math.PI - LIGHT); // hole wall
      }
      if (d < Rg * 0.26) {
        k += 0.1; // raised hub
        if (Rg * 0.26 - d < 1.1) k += 0.3 * facing;
      }
      if (d < Rg * 0.1) return blend(0x2a2e33, 0xe8eef4, Math.max(0, 0.35 + 0.5 * facing * (d / (Rg * 0.1)))); // steel axle
      if (d < Rg * 0.14) return blend(0x000000, METALS[g], 0.22); // bore
      return k <= 1 ? blend(0x000000, METALS[g], Math.max(0.08, k)) : blend(METALS[g], 0xffffff, Math.min(0.85, k - 1));
    };

    return (t) => {
      cv.clear();
      // Gear 0 turns half a revolution per loop; the others follow by rolling
      // contact: θb = -(Na/Nb)(θa - α) + α + π - π/Nb (a tooth of a along α sits in a gap of b).
      const follow = (ta, na, nb, alpha) => -(na / nb) * (ta - alpha) + alpha + Math.PI - Math.PI / nb;
      const ang = [(t * speed * Math.PI) / 6];
      ang[1] = follow(ang[0], N[0], N[1], a01);
      ang[2] = follow(ang[1], N[1], N[2], a12);
      for (let py = 0; py < H; py++) for (let px = 0; px < W; px++) {
        let col = NONE, best = 0;
        let shadowC = 0;
        for (let g = 0; g < 3; g++) {
          const dx = px + 0.5 - C[g][0], dy = (py + 0.5 - C[g][1]) * asp;
          const c = cover(g, dx, dy, ang);
          if (c > best) { best = c; col = shade(g, dx, dy, ang); }
          shadowC = Math.max(shadowC, cover(g, dx - sh[0], dy - sh[1] * asp, ang));
        }
        if (best <= 0 && shadowC <= 0) continue;
        const under = shadowC > 0 ? blend(th.bg, 0x000000, 0.45 * shadowC) : th.bg;
        cv.set(px, py, best >= 1 ? col : best > 0 ? blend(under, col, best) : under);
      }
      cv.paint(ctx.buffer);
    };
  },
};

