    const neu = ['api-7d9c6b5f8d-2xk4p', 'api-7d9c6b5f8d-9qwlz', 'api-7d9c6b5f8d-hv6s1'];
    const events = [[0, 'worker-5f4b9c7d6f-q8l2c', '1/1', 'Running', 0, '6d2h'], [0, 'redis-0', '1/1', 'Running', 0, '19d'], ...old.map((n) => [0, n, '1/1', 'Running', 0, '3d4h'])];
