        ...visible.map(([, n, r, s, rs, age]) => [[pad(n, 28), c.fg], [pad(r, 8), c.fg], [pad(s, 20), STC(c, s)], [pad(rs, 11), c.fg], [age, c.fg]])];
      const room = ctx.height - 1;
