            if (s.finished && local >= t1 + 7.15) { add(''); add(`${stamp(t1 + 7.15)} (${rate(s.avg).replace('MB/s', ' MB/s')}) - ${q[0]}${name}${q[1]} saved [${total}/${total}]`, th.pos); }
          }
        } else if (local >= t1) {
          const s = head.at(Math.min(local - t1, failAt));
