      // pv sizes: three significant figures and an IEC unit ("1.21GiB", " 512MiB").
      const sz = (n) => {
        const u = ['B', 'KiB', 'MiB', 'GiB'];
        let i = 0;
        while (n >= 1000 && i < 3) { n /= 1024; i++; }
