        at += 0.06;
        if (e[1] !== undefined) {
          const secs = Math.max(0.12, e[1] / rate);
          xfr += 1;
          script.push({ at, kind: 'file', size: e[1], secs, xfr, chk: nEntries - 1 - i, sim: transfer(ctx.rng, { total: e[1], seconds: secs, burst: 0.4, stalls: 0 }) });
          at += secs + 0.05;
