      });
      const end = at;
      const sent = totalSize + 12300, received = 465, elapsed = end - 0.3;
      const rateTxt = (r) => (r >= MiB ? `${(r / MiB).toFixed(2)}MB/s` : `${(r / 1024).toFixed(2)}kB/s`);
      const time = (s) => `${String(Math.floor(s / 3600)).padStart(4)}:${p2((s % 3600) / 60)}:${p2(s % 60)}`;
      return (t) => {
