// A moonlit lake painted the way ANSI artists did it: a procedural scene
// encoded cell by cell into VGA colors and ░▒▓ shading. Moonlit ridges,
// pine silhouettes, twinkling stars, a shivering reflection, the odd meteor.
import { bbsPalette, lerpc, hash2 } from './_kit.js';
import { ansify } from './_bbs.js';

export default {
  title: 'ANSI Moonlit Lake',
  gallery: 'retro',
  category: 'BBS & ANSI Art',
  kind: 'art',
  tags: ['ansi', 'landscape', 'moon', 'lake', 'bbs', 'shading', 'night'],
  order: 40,
  description: 'A moonlit lake in true ANSI shading — VGA colors and ░▒▓ dithers — with twinkling stars and a rippling reflection.',
  size: { w: 80, h: 22 },
  minSize: { w: 30, h: 8 },
  loop: 10,
  color: '16',
  params: { colors: { default: 'vga', options: ['vga', 'theme'], label: 'Colors' } },
  setup(ctx) {
    const P = bbsPalette(ctx);
    const W = ctx.width, H = ctx.height, PH = H * 2;
    const { fbm } = ctx.noise;
    const rng = ctx.rng;
    const img = new Int32Array(W * PH);
    const isSky = new Uint8Array(W * PH);
    const shore = Math.floor(PH * 0.6);
    const moon = { x: W * 0.74, y: PH * 0.16, r: Math.max(2.2, Math.min(W * 0.055, PH * 0.11)) };

    // Far range: one continuous ridge of a few octaves; near hills low and soft.
    const ph = [rng() * 6.28, rng() * 6.28, rng() * 6.28];
    const peak = (v) => Math.pow(1 - Math.abs(Math.sin(v)), 1.6);   // ridged: sharp tops, round valleys
    const ridge = (u) => 0.62 * peak(u * 4.4 + ph[0]) + 0.26 * peak(u * 9.7 + ph[1]) + 0.1 * peak(u * 21 + ph[2]) + 0.03 * fbm(u * 12, 2, 0, 2);
    const far = new Float32Array(W), near = new Float32Array(W), lit = new Uint8Array(W);
    for (let x = 0; x < W; x++) {
      const u = x / W;
      far[x] = shore - PH * (0.07 + 0.4 * Math.max(0, ridge(u)));
      near[x] = shore - PH * (0.035 + 0.05 * (0.5 + 0.5 * Math.sin(u * 7.3 + 1.1)) + 0.015 * fbm(u * 6, 5, 0, 2));
      // Slopes descending toward the moon (on the right) catch the light.
      lit[x] = ridge(u + 1.5 / W) < ridge(u - 1.5 / W) ? 1 : 0;
    }
    const snowLine = shore - PH * 0.36;
    // Pines along the near hills: narrow triangles of varying height.
    const pine = new Float32Array(W);
    for (let x = 0; x < W; x++) {
      if (hash2(x, 7) > 0.18) continue;
      const h = PH * (0.05 + hash2(x, 9) * 0.06);
      for (let dx = -2; dx <= 2; dx++) {
        const xx = x + dx;
        if (xx >= 0 && xx < W) pine[xx] = Math.max(pine[xx], h * (1 - Math.abs(dx) / 2.6));
      }
    }
    const stars = Array.from({ length: Math.max(6, Math.round(W * H * 0.035)) }, (_, i) => [Math.floor(hash2(i, 1) * W), Math.floor(hash2(i, 2) * (shore * 0.75)), hash2(i, 3)]);
    const mid = P[1], horizon = lerpc(P[5], P[13], 0.25);
    const ridgeBody = lerpc(P[1], P[0], 0.7), ridgeRim = lerpc(P[8], P[7], 0.3);

    function sky(x, y) {
      const v = y / shore;
      let c = v < 0.7 ? lerpc(P[0], mid, Math.pow(v / 0.7, 1.8)) : lerpc(mid, horizon, Math.pow((v - 0.7) / 0.3, 1.2));
      const dx = x + 0.5 - moon.x, dy = y + 0.5 - moon.y, d = Math.sqrt(dx * dx + dy * dy);
      if (d < moon.r) {
        c = d < moon.r * 0.82 ? P[15] : P[7];
        if (hash2(Math.floor(dx * 1.5 + 9), Math.floor(dy * 1.5 + 9), 3) > 0.82 && d < moon.r * 0.7) c = P[7];   // craters
      } else if (d < moon.r * 2) c = lerpc(c, P[9], (1 - (d - moon.r) / moon.r) * 0.45);
      return c;
    }
    function land(x, y) {
      if (y >= near[x] - pine[x]) return P[0];
      if (y >= far[x]) {
        const depth = y - far[x];
        if (depth < 1.5 && far[x] < snowLine) return P[7];
        return lit[x] && depth < 1.2 ? ridgeRim : ridgeBody;
      }
      return -1;
    }

    return (t) => {
      isSky.fill(0);
      for (let y = 0; y < PH; y++) for (let x = 0; x < W; x++) {
        const i = y * W + x;
        let c;
        if (y < shore) {
          c = land(x, y);
          if (c < 0) { c = sky(x, y); isSky[i] = 1; }
        } else {
          // Water: the mirrored scene, displaced by ripples and darkened with depth.
          const my = 2 * shore - y - 1;
          const k = (y - shore) / Math.max(1, PH - shore);
          const ripple = Math.round((Math.sin(y * 1.9 + t * Math.PI) * 0.6 + Math.sin(y * 0.7 - t * Math.PI * 0.6) * 0.5) * k * 2.2);
          const mx = Math.min(W - 1, Math.max(0, x + ripple));
          let m = my >= 0 ? land(mx, my) : P[0];
          if (m < 0) m = sky(mx, Math.max(0, my));
          c = lerpc(m, P[1], 0.45);
        }
        img[i] = c;
      }
      ansify(ctx.buffer, img, W, H, 0, 0, P);
      const b = ctx.buffer;
      for (const [x, y, k] of stars) {
        if (!isSky[y * W + x] || !isSky[(y ^ 1) * W + x]) continue;
        const tw = Math.sin((t * Math.PI * (2 + Math.floor(k * 5))) / 5 + k * 40);
        if (tw > 0.1) b.set(x, y >> 1, tw > 0.85 ? '*' : k > 0.55 ? '+' : '.', tw > 0.85 ? P[15] : k > 0.3 ? P[7] : P[8]);
      }
      // Glitter on the water under the moon.
      const gx = Math.round(moon.x);
      for (let row = Math.ceil(shore / 2); row < H; row++) {
        const spread = 1 + (row - shore / 2) * 0.6;
        for (let j = 0; j < 3; j++) {
          const x = Math.round(gx + (hash2(row, j + Math.floor(t * 4) * 3, 5) - 0.5) * 2 * spread);
          if (x >= 0 && x < W && hash2(row, j, Math.floor(t * 6)) > 0.45) b.set(x, row, hash2(x, row) > 0.5 ? '~' : '-', j ? P[11] : P[15]);
        }
      }
      // A meteor every five seconds.
      const mt = t % 5;
      if (mt < 0.8) {
        const k = Math.floor(t / 5);
        const sx = hash2(k, 11) * W * 0.5 + W * 0.05, sy = hash2(k, 12) * shore * 0.3;
        for (let i = 0; i < 7; i++) {
          const px = Math.round(sx + mt * W * 0.45 - i * 1.6), py = Math.round((sy + mt * shore * 0.5 - i * 0.7) / 2);
          if (py >= 0 && py < H && px >= 0 && px < W && isSky[py * 2 * W + px]) b.set(px, py, i === 0 ? '*' : i < 3 ? '-' : '·', i < 2 ? P[15] : i < 4 ? P[11] : P[3]);
        }
      }
    };
  },
};

sources.prism-term/src/facets/retro/ansi-logo.js:
// An ANSI group logo in the 1994 style: bevelled block letters encoded as real
// ANSI art (VGA colors, ░▒▓ shading, half blocks), a light sweep gliding
// across them, sparkles, and the obligatory scene tagline and credits.
import { textMask, maskAt, bbsPalette, lerpc, hash2 } from './_kit.js';
import { ansify } from './_bbs.js';

export default {
  title: 'ANSI Group Logo',
  gallery: 'retro',
  category: 'BBS & ANSI Art',
  kind: 'art',
  tags: ['ansi', 'logo', 'bbs', 'acid', 'ice', 'scene', 'shading'],
  order: 30,
  description: 'A 1994-style ANSI group logo: bevelled block letters in ░▒▓ shading with a light sweep and sparkles.',
  size: { w: 78, h: 16 },
  minSize: { w: 36, h: 8 },
  loop: 8,
  color: '16',
  params: {
    text: { default: 'PRISM', label: 'Logo' },
    colors: { default: 'vga', options: ['vga', 'theme'], label: 'Colors' },
  },
  setup(ctx) {
    const P = bbsPalette(ctx);
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const mask = textMask(String(ctx.param('text', 'PRISM')).toUpperCase(), { font: 'bold' });
    const rows = Math.max(4, H - 5);
    // One font pixel = L cells wide × L half-rows tall, i.e. visually square.
    const L = Math.max(1, Math.min(Math.floor((W - 2) / mask.w), Math.floor((rows * 2) / mask.h)));
    const sx = L, sy = L;
    const lw = Math.min(W, mask.w * sx), lh = Math.ceil((mask.h * sy) / 2);
    const lx = Math.floor((W - lw) / 2), ly = Math.max(0, Math.floor((H - lh - 3) / 2));
    const img = new Int32Array(lw * lh * 2);
    const inside = (x, y) => maskAt(mask, x, y, sx, sy);
    const base = [P[1], P[9], P[11], P[15]];
    return (t) => {
      b.fill(0, 0, W, H, ' ', P[7], P[0]);
      const sweep = ((t * 0.28) % 1.5) - 0.25;
      for (let y = 0; y < lh * 2; y++) for (let x = 0; x < lw; x++) {
        let c = P[0];
        if (inside(x, y)) {
          const v = y / (lh * 2);
          c = lerpc(base[Math.min(3, Math.floor((1 - v) * 3.99))], base[Math.min(3, Math.floor((1 - v) * 3.99) + 1)] ?? base[3], ((1 - v) * 3.99) % 1);
          if (!inside(x - 1, y - 1)) c = lerpc(c, P[15], 0.55);           // bevel highlight
          if (!inside(x + 1, y + 1)) c = lerpc(c, P[0], 0.5);            // bevel shadow
          const d = Math.abs(x / lw - sweep - (y / (lh * 2)) * 0.2);
          if (d < 0.07) c = lerpc(c, P[15], (1 - d / 0.07) * 0.8);
        } else if (inside(x - Math.max(1, sx >> 1), y - Math.max(1, sy >> 1))) c = P[8];   // drop shadow
        img[y * lw + x] = c;
      }
      ansify(b, img, lw, lh, lx, ly, P);
      // Sparkles that bloom and fade around the letters.
      for (let i = 0; i < 8; i++) {
        const k = Math.floor(t * 1.3) + i * 7;
        const x = lx + Math.floor(hash2(k, 1) * lw), y = ly + Math.floor(hash2(k, 2) * lh);
        const life = (t * 1.3) % 1;
        b.set(x, y, life < 0.3 ? '·' : life < 0.6 ? '+' : '*', life < 0.6 ? P[15] : P[11]);
      }
      const tag = '-[ PRiSM ANSi & ASCii DiViSiON ]-';
      const credits = 'ans by ckr/prism · 10/94 · 80x25 · iCE-free';
      if (ly + lh + 1 < H) b.text(Math.max(0, Math.floor((W - tag.length) / 2)), ly + lh + 1, tag.slice(0, W), P[13]);
      if (ly + lh + 2 < H) b.text(Math.max(0, Math.floor((W - credits.length) / 2)), ly + lh + 2, credits.slice(0, W), P[8]);
    };
  },
};

sources.prism-term/src/facets/retro/bbs-login.js:
// A BBS login screen, 1993: block-letter board logo, caller stats in a double
// frame, and a login that types itself — handle, password, credential check,
// welcome — then hangs up and does it again. VGA colors (or --set colors=theme).
import { textMask, bbsPalette } from './_kit.js';
import { blockLogo, frame } from './_bbs.js';

const HANDLE = 'LIGHTMAN';
const SPIN = '|/-\\';

export default {
  title: 'BBS Login',
  gallery: 'retro',
  category: 'BBS & ANSI Art',
  kind: 'art',
  tags: ['bbs', 'ansi', 'login', 'dial-up', '1993', 'sysop'],
  order: 10,
  description: 'A 1993 BBS login: block-letter board logo, caller stats in a double frame and a login that types itself.',
  size: { w: 80, h: 24 },
  minSize: { w: 40, h: 12 },
  loop: 12,
  color: '16',
  params: { colors: { default: 'vga', options: ['vga', 'theme'], label: 'Colors' } },
  setup(ctx) {
    const P = bbsPalette(ctx);
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const logo = textMask('PRISM', { font: 'bold' });
    const sx = logo.w * 2 + 2 <= W ? 2 : 1;
    const showLogo = H >= 18 && logo.w * sx + 2 <= W;
    const ramp = (v) => (v < 0.2 ? P[15] : v < 0.45 ? P[11] : v < 0.75 ? P[3] : P[9]);
    return (t) => {
      const lt = t % 12;
      b.fill(0, 0, W, H, ' ', P[7], P[0]);
      // Status bar.
      const mins = 41 + Math.floor(t / 60);
      const clock = `${String((23 + Math.floor(mins / 60)) % 24).padStart(2, '0')}:${String(mins % 60).padStart(2, '0')}`;
      b.fill(0, 0, W, 1, ' ', P[15], P[1]);
      b.text(1, 0, (W >= 56 ? ' PRISM BBS · Node 3 of 8 · 2400 bps · ANSI ' : ' PRISM BBS · Node 3 · 2400 bps ').slice(0, W - 2), P[15], P[1]);
      if (W > 56) b.text(W - 7, 0, clock, P[14], P[1]);
      let y = 2;
      if (showLogo) {
        const lx = Math.floor((W - logo.w * sx) / 2);
        blockLogo(b, lx, y, logo, { sx, ramp, shadow: P[8] });
        y += 5;
        const tag = 'THE TERMINAL ART UNDERGROUND · EST. 1991';
        if (tag.length < W) b.text(Math.floor((W - tag.length) / 2), y, tag, P[6]);
        y += 2;
      } else {
        b.text(2, y, 'P R I S M   B B S', P[11]);
        y += 2;
      }
      // Caller stats.
      const fw = Math.min(W - 4, 46), fx = Math.floor((W - fw) / 2);
      const stats = [['Last caller', 'CRASH OVERRIDE'], ['Calls today', '42'], ['Your node', '3 of 8'], ['Software', 'PRISM/BBS 0.42']];
      const rows = H - y >= 13 ? stats : stats.slice(0, Math.max(0, H - y - 8));
      if (rows.length) {
        frame(b, fx, y, fw, rows.length + 2, P[1], 'SYSTEM', P[14]);
        rows.forEach(([k, v], i) => {
          const dots = '.'.repeat(Math.max(2, 16 - k.length));
          b.text(fx + 2, y + 1 + i, `${k} ${dots} `, P[7]);
          b.text(fx + 2 + k.length + dots.length + 2, y + 1 + i, v.slice(0, fw - k.length - dots.length - 6), P[15]);
        });
        y += rows.length + 3;
      }
      // The login, scripted on a 12-second loop.
      const px = Math.max(1, fx);
      const blink = Math.floor(t * 2.5) % 2 === 0;
      const typed = (from, text, cps) => text.slice(0, Math.max(0, Math.min(text.length, Math.floor((lt - from) * cps))));
      const line = (text, color, cursor) => {
        if (y >= H - 1) return;
        const end = b.text(px, y, text, color);
        if (cursor && blink) b.set(end, y, '█', P[7]);
        y++;
      };
      const handle = lt >= 1.4 ? typed(1.4, HANDLE, 6) : '';
      const ask = W - px >= 46 ? 'Enter your handle (NEW to apply): ' : 'Handle: ';
      line(ask, P[11], false);
      if (y - 1 < H - 1) {
        const end = b.text(px + ask.length, y - 1, handle, P[15]);
        if (lt < 3.3 && blink) b.set(end, y - 1, '█', P[7]);
      }
      if (lt >= 3.3) {
        const stars = '*'.repeat(typed(3.8, 'xxxxxxxx', 7).length);
        line(`Password: ${stars}`, P[11], lt < 5.2);
      }
      if (lt >= 5.2 && lt < 6.8) line(`Checking credentials... ${SPIN[Math.floor(t * 8) % 4]}`, P[7], false);
      if (lt >= 6.8) {
        line(`Welcome back, ${HANDLE}!`, P[10], false);
        if (lt >= 7.4) line(W - px > 62 ? 'You have 3 new messages and 12 new files since your last call.' : '3 new messages, 12 new files.', P[7], lt > 10.8);
      }
      // Footer.
      if (H > 12) {
        const foot = '[ESC] hang up   [?] help   SysOp is AVAILABLE';
        b.text(Math.max(0, Math.floor((W - foot.length) / 2)), H - 1, foot.slice(0, W), P[8]);
      }
    };
  },
};

sources.prism-term/src/facets/retro/bbs-menu.js:
// BBS main menu: a shaded header, two columns of hotkey commands with a
// lightbar walking through them, a who's-online panel and the classic
// time-left status line.
import { bbsPalette } from './_kit.js';
import { frame } from './_bbs.js';

const ITEMS = [
  ['M', 'Message Bases'], ['F', 'File Areas'], ['D', 'Door Games'], ['C', 'Chat with SysOp'],
  ['B', 'Bulletins'], ['W', "Who's Online"], ['N', 'New Files Scan'], ['U', 'User Settings'],
  ['L', 'Last Callers'], ['G', 'Goodbye (Log Off)'],
];
const ONLINE = [['1', 'ZERO COOL', 'Playing L.O.R.D.'], ['2', 'ACID BURN', 'Reading msgs'], ['3', 'LIGHTMAN', 'Main menu'], ['4', 'THE PHREAK', 'Downloading']];

export default {
  title: 'BBS Main Menu',
  gallery: 'retro',
  category: 'BBS & ANSI Art',
  kind: 'art',
  tags: ['bbs', 'ansi', 'menu', 'lightbar', 'hotkeys', 'sysop'],
  order: 20,
  description: 'A BBS main menu: shaded header, hotkey commands with a walking lightbar, who-is-online and time left.',
  size: { w: 80, h: 22 },
  minSize: { w: 40, h: 12 },
  loop: 10,
  color: '16',
  params: { colors: { default: 'vga', options: ['vga', 'theme'], label: 'Colors' } },
  setup(ctx) {
    const P = bbsPalette(ctx);
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const twoCols = W >= 60;
    const panel = W >= 72 && H >= 16;
    return (t) => {
      b.fill(0, 0, W, H, ' ', P[7], P[0]);
      // Header: ░▒▓█ MAIN MENU █▓▒░ across the top.
      const title = ' MAIN MENU ';
      const side = Math.max(0, Math.floor((W - title.length) / 2));
      const grad = '░▒▓█';
      for (let x = 0; x < W; x++) {
        const d = x < side ? side - x : x - side - title.length;
        if (x >= side && x < side + title.length) continue;
        b.set(x, 0, grad[Math.max(0, 3 - Math.min(3, Math.floor(d / Math.max(1, side / 4))))], x % 2 ? P[1] : P[9]);
      }
      b.text(side, 0, title, P[15], P[1]);
      b.text(Math.max(0, Math.floor((W - 37) / 2)), 1, 'PRISM BBS · terminal art since 1991'.slice(0, W), P[8]);
      // Menu.
      const menuW = panel ? Math.min(52, W - 28) : W - 2;
      const colW = twoCols ? Math.floor((menuW - 4) / 2) : menuW - 4;
      const perCol = twoCols ? Math.ceil(ITEMS.length / 2) : ITEMS.length;
      const visible = Math.min(perCol, Math.max(1, H - 7));
      frame(b, 1, 3, menuW, visible + 2, P[1], 'COMMANDS', P[14]);
      const sel = Math.floor(t / 0.8) % ITEMS.length;
      ITEMS.forEach(([key, label], i) => {
        const col = twoCols ? Math.floor(i / perCol) : 0, row = twoCols ? i % perCol : i;
        if (row >= visible) return;
        const x = 3 + col * (colW + 1), y = 4 + row;
        const on = i === sel;
        if (on) b.fill(x - 1, y, colW, 1, ' ', P[0], P[3]);
        b.text(x, y, '[', on ? P[0] : P[1], on ? P[3] : undefined);
        b.text(x + 1, y, key, on ? P[0] : P[14], on ? P[3] : undefined);
        b.text(x + 2, y, ']', on ? P[0] : P[1], on ? P[3] : undefined);
        b.text(x + 4, y, label.slice(0, colW - 6), on ? P[0] : P[7], on ? P[3] : undefined);
      });
      // Who's online.
      if (panel) {
        const px = menuW + 3, pw = W - px - 1;
        frame(b, px, 3, pw, ONLINE.length * 2 + 2, P[5], 'ONLINE', P[13]);
        ONLINE.forEach(([n, who, what], i) => {
          const y = 4 + i * 2;
          const live = Math.floor(t * 1.5 + i) % 5 !== 0;
          b.text(px + 2, y, `${n}`, P[8]);
          b.text(px + 4, y, who.slice(0, pw - 6), i === 2 ? P[11] : P[15]);
          b.text(px + 4, y + 1, what.slice(0, pw - 6), live ? P[7] : P[8]);
        });
      }
      // Prompt + status line.
      const py = Math.min(H - 3, 4 + visible + 2);
      const blink = Math.floor(t * 2.5) % 2 === 0;
      const end = b.text(2, py, 'Command ', P[11]);
      const end2 = b.text(end, py, '» ', P[14]);
      b.text(end2, py, ITEMS[sel][0], P[15]);
      if (blink) b.set(end2 + 1, py, '█', P[7]);
      const left = 58 - Math.floor(t / 60);
      b.fill(0, H - 1, W, 1, ' ', P[0], P[7]);
      b.text(1, H - 1, `Time left: ${left} min  ·  Node 3  ·  3 new msgs  ·  ↑↓ select  Enter`.slice(0, W - 2), P[0], P[7]);
    };
  },
};

sources.prism-term/src/facets/retro/boing-ball.j:
// Homage to the 1984 Amiga Boing demo: a red-and-white checkered sphere spins
// and bounces across a purple grid room, casting a soft shadow on the wall.
import { lerpc } from './_kit.js';

export default {
  title: 'Boing Ball',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['boing', 'amiga', 'ball', 'checker', '1984'],
  order: 30,
  description: 'The 1984 Amiga Boing Ball: a spinning checkered sphere bouncing across a grid room with its shadow.',
  size: { w: 64, h: 24 },
  minSize: { w: 20, h: 8 },
  loop: 6,
  canvas: 'hires',
  palette: 'prism',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px, aspect } = cv;
    const th = ctx.theme;
    const wall = lerpc(th.bg, 0xb0b0b0, 0.12), line = lerpc(th.bg, th.crit, 0.75);
    const red = 0xe0262b, white = 0xf2f2f2;
    const VH = H * aspect;                       // height in horizontal-pixel units
    const R = Math.min(W * 0.17, VH * 0.24);
    const floor = VH * 0.9;
    const gridX = Math.max(4, Math.round(W / 14)), gridY = Math.max(3, Math.round(H / 9));
    return (t) => {
      const tt = t * speed;
      // Room: wall grid + floor grid in perspective.
      const floorRow = Math.floor(floor / aspect);
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
        let c = wall;
        if (y < floorRow) { if (x % gridX === 0 || y % gridY === 0) c = line; }
        else {
          const k = (y - floorRow + 1) / (H - floorRow + 1);
          const fx = (x - W / 2) / (0.6 + k * 1.4) + W / 2;
          if (Math.abs(fx % gridX) < 0.6 || (y - floorRow) % Math.max(1, Math.round(gridY * 0.5 * k + 1)) === 0) c = line;
        }
        px[y * W + x] = c;
      }
      // Bounce: horizontal ping-pong, vertical |sin|.
      const span = W - 2 * R - 2;
      const ph = (tt * 0.22) % 2;
      const bx = R + 1 + (ph < 1 ? ph : 2 - ph) * span;
      const by = floor - R - Math.abs(Math.sin(tt * 2.4)) * (floor - 2 * R - 2);
      const dir = ph < 1 ? 1 : -1;
      // Shadow on the wall (offset right) — drawn first.
      const sx0 = bx + R * 0.45, sy0 = by + R * 0.18;
      for (let y = Math.floor((sy0 - R) / aspect); y <= Math.ceil((sy0 + R) / aspect); y++) {
        for (let x = Math.floor(sx0 - R); x <= Math.ceil(sx0 + R); x++) {
          const dx = x + 0.5 - sx0, dy = (y + 0.5) * aspect - sy0;
          if (dx * dx + dy * dy < R * R && x >= 0 && x < W && y >= 0 && y < H) px[y * W + x] = lerpc(px[y * W + x], 0x000000, 0.45);
        }
      }
      // The ball: checker in (longitude, latitude), tilted, spinning.
      const spin = tt * 3 * dir, tilt = 0.35;
      for (let y = Math.floor((by - R) / aspect); y <= Math.ceil((by + R) / aspect); y++) {
        for (let x = Math.floor(bx - R); x <= Math.ceil(bx + R); x++) {
          if (x < 0 || x >= W || y < 0 || y >= H) continue;
          const nx = (x + 0.5 - bx) / R, ny = ((y + 0.5) * aspect - by) / R;
          const r2 = nx * nx + ny * ny;
          if (r2 > 1) continue;
          const nz = Math.sqrt(1 - r2);
          // Tilt around z then read longitude/latitude.
          const tx = nx * Math.cos(tilt) - ny * Math.sin(tilt), ty = nx * Math.sin(tilt) + ny * Math.cos(tilt);
          const lon = Math.atan2(tx, nz) + spin, lat = Math.asin(Math.max(-1, Math.min(1, ty)));
          const check = ((Math.floor(lon / (Math.PI / 8)) + Math.floor(lat / (Math.PI / 8))) & 1) === 0;
          const light = 0.45 + 0.55 * Math.max(0, nz * 0.8 - nx * 0.25 - ny * 0.35);
          px[y * W + x] = lerpc(0x000000, check ? red : white, Math.min(1, light + 0.15));
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/checker-floo:
// The infinite checkerboard floor: a perspective-mapped checker plane racing
// toward the horizon and slowly banking, under a raster-gradient sunset sky.
// Distance fog keeps the far squares from shimmering.
import { lerpc } from './_kit.js';

export default {
  title: 'Checker Floor',
  gallery: 'retro',
  category: 'Raster & Copper',
  kind: 'scene',
  tags: ['checkerboard', 'floor', 'perspective', 'amiga', 'mode 7'],
  order: 40,
  description: 'A perspective checkerboard plane racing to the horizon and banking, under a raster-gradient sky.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 8 },
  loop: 12,
  canvas: 'field',
  palette: 'sunset',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px, aspect } = cv;
    const hz = Math.floor(H * 0.45);
    const a = ctx.theme.accent, b = lerpc(ctx.theme.bg, ctx.theme.ink, 0.9);
    return (t) => {
      const tt = t * speed;
      const bank = Math.sin(tt * 0.35) * 0.18;
      const cs = Math.cos(bank), sn = Math.sin(bank);
      const mid = lerpc(a, b, 0.5), haze = pal(0.66);
      for (let y = 0; y < H; y++) {
        if (y < hz) {
          px.fill(pal(0.08 + (y / hz) * 0.62), y * W, (y + 1) * W);
          continue;
        }
        const dy = (y - hz + 0.5) * aspect;
        const z = (H * aspect * 0.55) / dy;      // depth of this row
        // Far squares shrink below a pixel: fade their contrast first, then haze to the horizon.
        const contrast = 1 - Math.min(1, Math.pow(z / 7, 1.3));
        const hazeK = Math.min(1, Math.pow(z / 14, 1.2));
        for (let x = 0; x < W; x++) {
          const sx = (x - W / 2) / (W / 2);
          let wx = sx * z * 1.8, wz = z * 1.2 + tt * 4;
          [wx, wz] = [wx * cs - wz * sn, wx * sn + wz * cs];
          const check = ((Math.floor(wx) + Math.floor(wz)) & 1) === 0;
          px[y * W + x] = lerpc(lerpc(mid, check ? a : b, contrast), haze, hazeK);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

// Amiga copper bars: glossy horizontal bars swing past each other in depth,
// each a vertical gradient with a white-hot center line — the copper chip's
// party trick, now in a terminal.
import { lerpc } from './_kit.js';

export default {
  title: 'Copper Bars',
  gallery: 'retro',
  category: 'Raster & Copper',
  kind: 'scene',
  tags: ['copper', 'raster bars', 'amiga', 'demoscene', 'gradient'],
  order: 10,
  description: 'Glossy raster bars swinging through each other in depth, each a gradient with a white-hot core.',
  size: { w: 80, h: 20 },
  minSize: { w: 20, h: 6 },
  loop: 10,
  canvas: 'field',
  palette: 'prism',
  params: {
    bars: { default: 7, min: 2, max: 14, label: 'Bars' },
    speed: { default: 1, min: 0.25, max: 4, label: 'Speed' },
  },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const n = Math.round(ctx.param('bars', 7));
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px } = cv;
    const r = Math.max(2, H / 14);
    const bars = Array.from({ length: n }, (_, i) => ({ phase: (i / n) * Math.PI * 2, color: pal(i / n) }));
    const bg = ctx.theme.bg;
    return (t) => {
      const tt = t * speed;
      for (let y = 0; y < H; y++) px.fill(lerpc(bg, 0x000000, 0.35 * Math.abs(y / H - 0.5) * 2), y * W, (y + 1) * W);
      const live = bars.map((b) => {
        const a = tt * 1.4 + b.phase;
        return { y: H / 2 + Math.sin(a) * (H / 2 - r - 1) * 0.92, z: Math.cos(a), color: b.color };
      }).sort((a, b) => a.z - b.z);
      for (const b of live) {
        const rr = r * (0.75 + 0.35 * (b.z + 1) / 2);
        const depth = 0.55 + 0.45 * (b.z + 1) / 2;
        for (let y = Math.max(0, Math.floor(b.y - rr)); y <= Math.min(H - 1, Math.ceil(b.y + rr)); y++) {
          const d = Math.abs(y + 0.5 - b.y) / rr;
          if (d > 1) continue;
          const k = 1 - d;
          let c = lerpc(0x000000, b.color, Math.min(1, k * 1.6) * depth);
          if (k > 0.72) c = lerpc(c, 0xffffff, (k - 0.72) / 0.28 * 0.85 * depth);
          px.fill(c, y * W, (y + 1) * W);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/cracktro.js:
// A complete cracktro screen: chrome group logo with a shine sweep, raster bars
// pumping in the middle, a greetings sine scroller along the bottom, and a
// parallax starfield behind it all. Everything a 1989 floppy needed.
import { textMask, maskAt, fontPx, makeStars, lerpc, dim } from './_kit.js';

const GREETS = 'CRACKED AND TRAINED BY THE PRISM CREW   *   GREETINGS TO ALL TERMINAL SCENERS   *   CALL OUR BOARD AT 300-2400 BAUD   *   ';

export default {
  title: 'Cracktro',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['cracktro', 'intro', 'logo', 'scroller', 'raster bars', 'demoscene'],
  order: 5,
  description: 'Full cracktro: chrome logo with shine sweep, pumping raster bars, greetings scroller and starfield.',
  size: { w: 80, h: 24 },
  minSize: { w: 36, h: 12 },
  loop: 14,
  canvas: 'field',
  palette: 'prism',
  params: {
    logo: { default: 'PRISM', label: 'Logo' },
    text: { default: GREETS, label: 'Scroller' },
    speed: { default: 1, min: 0.25, max: 4, label: 'Speed' },
  },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px, aspect } = cv;
    const logo = textMask(String(ctx.param('logo', 'PRISM')).toUpperCase(), { font: 'bold' });
    const greets = textMask(String(ctx.param('text', GREETS)).toUpperCase(), { font: 'standard' });
    // Logo: as large as fits in the top ~40%.
    let L = fontPx(cv, Math.max(3, ctx.height * 0.3), 7);
    if (logo.w * L.sx > W * 0.92) {
      const sx = Math.max(1, Math.floor((W * 0.92) / logo.w));
      L = { sx, sy: Math.max(1, Math.round((L.sy * sx) / L.sx)) };
    }
    const lw = logo.w * L.sx, lh = logo.h * L.sy;
    const lx = Math.round((W - lw) / 2), ly = Math.max(1, Math.round(H * 0.06));
    const G = fontPx(cv, Math.max(1.5, ctx.height * 0.1), 7);
    const gh = greets.h * G.sy, gw = greets.w * G.sx;
    const stars = makeStars(ctx.rng, W, H, Math.round(W * H * 0.015));
    const bg = ctx.theme.bg;
    const chrome = [0x2a3446, 0x8fa3c4, 0xf4f7ff, 0x6c7f9f, 0x1b2230, 0x9fb4d6, 0xe8eef9];
    const metal = (v) => {
      const i = Math.min(chrome.length - 2, Math.floor(v * (chrome.length - 1)));
      return lerpc(chrome[i], chrome[i + 1], v * (chrome.length - 1) - i);
    };
    const barsTop = ly + lh + Math.round(H * 0.05), barsBot = H - gh - Math.round(H * 0.12);
    return (t) => {
      const tt = t * speed;
      px.fill(bg);
      for (const s of stars) {
        const x = ((s[0] - tt * (4 + 30 * s[2] * s[2])) % W + W) % W;
        cv.set(x, s[1], lerpc(bg, 0xffffff, 0.2 + 0.7 * s[2]));
      }
      // Raster bars between logo and scroller.
      if (barsBot > barsTop + 2) {
        const mid = (barsTop + barsBot) / 2, span = (barsBot - barsTop) / 2;
        for (let i = 0; i < 4; i++) {
          const y0 = mid + Math.sin(tt * 2.2 + i * 0.9) * span * 0.75;
          const r = Math.max(1.5, span * 0.28);
          const c = pal(i / 4 + tt * 0.05);
          for (let y = Math.floor(y0 - r); y <= Math.ceil(y0 + r); y++) {
            if (y < barsTop || y >= barsBot) continue;
            const k = 1 - Math.abs(y + 0.5 - y0) / r;
            if (k <= 0) continue;
            const col = k > 0.75 ? lerpc(c, 0xffffff, (k - 0.75) * 3) : lerpc(0x000000, c, k * 1.4);
            px.fill(col, y * W, (y + 1) * W);
          }
        }
      }
      // Logo with a diagonal shine sweep.
      const sweep = ((tt * 0.35) % 1.6) - 0.3;
      for (let y = 0; y < lh; y++) for (let x = 0; x < lw; x++) {
        if (!maskAt(logo, x, y, L.sx, L.sy)) continue;
        const v = y / lh;
        let c = metal(v);
        const d = Math.abs((x / lw) - v * 0.25 * aspect - sweep);
        if (d < 0.06) c = lerpc(c, 0xffffff, 1 - d / 0.06);
        cv.set(lx + x + 1, ly + y + 1, dim(bg, 0.3));
        cv.set(lx + x, ly + y, c);
      }
      // Greetings sine scroller.
      const period = gw + W;
      const scroll = tt * 30 * G.sx;
      const gy = H - gh - Math.max(1, Math.round(H * 0.06));
      for (let x = 0; x < W; x++) {
        const u = ((x - W + scroll) % period + period) % period;
        if (u >= gw) continue;
        const yOff = Math.round(gy + Math.sin(u * 0.09 / G.sx + tt * 3) * Math.max(1, H * 0.035));
        for (let k = 0; k < gh; k++) {
          if (!maskAt(greets, u, k, G.sx, G.sy)) continue;
          cv.set(x, yOff + k, pal((x / W) * 0.6 + tt * 0.2));
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/dot-tunnel.j:
// Dot tunnel: rings of dots flying at the camera along a snaking path, each
// ring twisted a little further than the last. Near dots are big and bright,
// far ones fade into the dark — braille makes the dots razor sharp.
import { lerpc } from './_kit.js';

export default {
  title: 'Dot Tunnel',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['tunnel', 'dots', 'demoscene', '3d', 'braille'],
  order: 50,
  description: 'Rings of dots racing at the camera along a snaking path, twisting ring by ring, fading with depth.',
  size: { w: 70, h: 24 },
  minSize: { w: 20, h: 8 },
  loop: 10,
  canvas: 'line',
  palette: 'prism',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, aspect } = cv;
    const VH = H * aspect;
    const RINGS = 30, DOTS = 28, DEPTH = 18;
    const f = Math.min(W, VH) * 0.62;
    const bg = ctx.theme.bg;
    const path = (z, t) => [Math.sin(z * 0.23 + t * 0.9) * 1.1, Math.cos(z * 0.17 + t * 0.7) * 0.8];
    return (t) => {
      const tt = t * speed;
      cv.clear();
      const travel = tt * 5;
      const [camX, camY] = path(travel, tt);
      for (let r = RINGS - 1; r >= 0; r--) {
        const zWorld = Math.floor(travel) + r + 1;
        const z = zWorld - travel;                 // distance from camera
        if (z <= 0.15) continue;
        const [ox, oy] = path(zWorld, tt);
        const fade = Math.pow(1 - Math.min(1, z / DEPTH), 0.55);
        const c = lerpc(bg, lerpc(pal((zWorld * 0.045) % 1), 0xffffff, 0.15 * fade), 0.2 + 0.8 * fade);
        const twist = zWorld * 0.35 + tt * 0.8;
        for (let d = 0; d < DOTS; d++) {
          const a = (d / DOTS) * Math.PI * 2 + twist;
          const x = W / 2 + ((ox - camX + Math.cos(a) * 1.6) * f) / z;
          const y = (VH / 2 + ((oy - camY + Math.sin(a) * 1.6) * f) / z) / aspect;
          cv.set(x, y, c);
          if (z < 2.2) { cv.set(x + 1, y, c); cv.set(x, y + 1, c); cv.set(x + 1, y + 1, c); }
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/dycp-scrolle:
// DYCP — "Different Y Character Position", the C64 scroller where every
// letter bobs on its own sine phase. This one bounces off a mirrored water line
// that ripples its reflection.
import { textMask, maskAt, fontPx, lerpc, dim } from './_kit.js';

const MESSAGE = 'DIFFERENT Y CHARACTER POSITION   ';

export default {
  title: 'DYCP Scroller',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['dycp', 'scroller', 'c64', 'reflection', 'demoscene'],
  order: 20,
  description: 'C64-style DYCP scroller: every letter bobs on its own sine, mirrored in a rippling water line.',
  size: { w: 80, h: 20 },
  minSize: { w: 30, h: 8 },
  loop: 10,
  canvas: 'field',
  palette: 'candy',
  params: {
    text: { default: MESSAGE, label: 'Message' },
    speed: { default: 1, min: 0.25, max: 4, label: 'Speed' },
  },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const text = String(ctx.param('text', MESSAGE)).toUpperCase();
    const { width: W, height: H, px } = cv;
    const water = Math.round(H * 0.68);
    const S = fontPx(cv, Math.max(2, ctx.height * 0.22), 7);
    const chars = [...text].map((ch) => textMask(ch === ' ' ? ' ' : ch, { font: 'bold' }));
    const adv = chars.map((m) => (m.w + 1) * S.sx);
    const total = adv.reduce((a, b) => a + b, 0);
    const ch = 7 * S.sy;
    const amp = Math.max(1, (water - ch) * 0.42);
    const bg = ctx.theme.bg;
    const sky0 = lerpc(bg, 0x000000, 0.25), sky1 = lerpc(bg, pal(0.3), 0.18);
    return (t) => {
      const tt = t * speed;
      for (let y = 0; y < H; y++) {
        const c = y < water ? lerpc(sky0, sky1, y / water) : lerpc(dim(pal(0.55), 0.22), bg, (y - water) / (H - water));
        px.fill(c, y * W, (y + 1) * W);
      }
      let x0 = W - ((tt * 24 * S.sx) % (total + W));
      for (let i = 0; i < chars.length * 2; i++) {
        const k = i % chars.length;
        const m = chars[k];
        const gx = Math.round(x0);
        x0 += adv[k];
        if (gx > W || gx + adv[k] < 0 || text[k] === ' ') continue;
        const gy = Math.round(water - ch - 1 - Math.abs(Math.sin(tt * 2.6 + i * 0.55)) * amp);
        const color = pal((k / chars.length + tt * 0.1) % 1);
        for (let y = 0; y < ch; y++) for (let x = 0; x < m.w * S.sx; x++) {
          if (!maskAt(m, x, y, S.sx, S.sy)) continue;
          const c = y < S.sy ? lerpc(color, 0xffffff, 0.5) : color;
          cv.set(gx + x, gy + y, c);
          // Reflection below the water line, rippled and darker.
          const ry = water + (water - (gy + y)) - 1;
          if (ry < H) cv.set(gx + x + Math.round(Math.sin(ry * 0.9 + tt * 4) * 1.2), ry, lerpc(c, bg, 0.6));
        }
      }
      for (let x = 0; x < W; x++) px[water * W + x] = lerpc(pal(0.6), 0xffffff, 0.3 + 0.2 * Math.sin(x * 0.4 + tt * 3));
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/kefrens-bars:
// Kefrens bars (a.k.a. Alcatraz bars): one short shaded bar is redrawn on every
// scanline at a wandering x, and each line keeps what the line above drew —
// so the bars stack into a twisting staircase of cylinders. Pure 1990 magic.
import { lerpc } from './_kit.js';

export default {
  title: 'Kefrens Bars',
  gallery: 'retro',
  category: 'Raster & Copper',
  kind: 'scene',
  tags: ['kefrens', 'alcatraz', 'raster', 'amiga', 'demoscene'],
  order: 20,
  description: 'One shaded bar per scanline that never gets erased, stacking into a twisting staircase of cylinders.',
  size: { w: 80, h: 22 },
  minSize: { w: 24, h: 8 },
  loop: 12,
  canvas: 'field',
  palette: 'prism',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px } = cv;
    const bw = Math.max(3, Math.round(W / 14));
    const row = new Int32Array(W);
    const bg = ctx.theme.bg;
    return (t) => {
      const tt = t * speed;
      row.fill(bg);
      for (let y = 0; y < H; y++) {
        const x0 = Math.round(W / 2 - bw / 2
          + Math.sin(y * 0.11 + tt * 1.9) * W * 0.22
          + Math.sin(y * 0.047 - tt * 1.3) * W * 0.16);
        const c = pal((y / H) * 0.85 + tt * 0.07);
        for (let k = 0; k < bw; k++) {
          const x = x0 + k;
          if (x < 0 || x >= W) continue;
          const u = (k + 0.5) / bw * 2 - 1;          // -1..1 across the bar
          const shade = Math.sqrt(1 - u * u);       // cylinder
          let col = lerpc(0x000000, c, 0.25 + 0.75 * shade);
          if (shade > 0.9) col = lerpc(col, 0xffffff, (shade - 0.9) * 6);
          row[x] = col;
        }
        px.set(row, y * W);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/modem-connec:
// Dialing in, 1992: the modem init string, the dial, RINGING, CONNECT 2400,
// then the board's welcome screen painting itself cell by cell at line speed —
// cursor racing ahead of the paint — until NO CARRIER sends you back to start.
import { CellBuffer } from '../../buffer.js';
import { textMask, bbsPalette } from './_kit.js';
import { blockLogo, frame } from './_bbs.js';

const SCRIPT = [
  [0.0, 'ATZ'], [0.6, 'OK'], [1.0, 'ATDT 555-0142'], [2.4, 'RINGING'], [3.4, 'RINGING'], [4.2, 'CONNECT 2400/ARQ/V42BIS'],
];
const PAINT_AT = 5.0, PAINT = 3.4, HOLD = 2.6;

function welcome(W, H, P) {
  const s = new CellBuffer(W, H);
  s.clear(P[0]);
  const logo = textMask('PRISM', { font: 'bold' });
  const sx = logo.w * 2 + 2 <= W ? 2 : 1;
  let y = 1;
  if (H >= 14 && logo.w * sx <= W) {
    blockLogo(s, Math.floor((W - logo.w * sx) / 2), y, logo, { sx, ramp: (v) => (v < 0.25 ? P[15] : v < 0.5 ? P[14] : v < 0.8 ? P[6] : P[4]), shadow: P[8] });
    y += 5;
  }
  const lines = [['P R I S M   B B S', P[11]], ['300 · 1200 · 2400 bps · 24 hours · 2 nodes', P[7]], ['', 0], ['Home of the terminal art underground', P[6]]];
  for (const [text, c] of lines) { if (y < H - 4 && text) s.text(Math.max(0, Math.floor((W - text.length) / 2)), y, text, c); y++; }
  const fw = Math.min(W - 2, 44), fx = Math.floor((W - fw) / 2);
  if (y + 4 <= H) {
    frame(s, fx, y, fw, 4, P[2], 'NEWS', P[10]);
    s.text(fx + 2, y + 1, 'New door game: TradeWars 2002 on node 2'.slice(0, fw - 4), P[7]);
    s.text(fx + 2, y + 2, 'Upload ratio waived this weekend'.slice(0, fw - 4), P[7]);
  }
  return s;
}

export default {
  title: 'Modem Connect',
  gallery: 'retro',
  category: 'BBS & ANSI Art',
  kind: 'art',
  tags: ['modem', 'dial-up', 'bbs', 'ansi', 'connect', 'hayes', '2400 baud'],
  order: 50,
  description: 'Dialing a BBS: ATZ, ATDT, RINGING, CONNECT 2400 — then the welcome screen paints in at line speed.',
  size: { w: 80, h: 22 },
  minSize: { w: 40, h: 10 },
  loop: 12,
  color: '16',
  params: { colors: { default: 'vga', options: ['vga', 'theme'], label: 'Colors' } },
  setup(ctx) {
    const P = bbsPalette(ctx);
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const screen = welcome(W, H - 1, P);
    const total = W * (H - 1);
    const paintDur = PAINT, CPS = total / PAINT;
    const loop = PAINT_AT + PAINT + HOLD + 1;
    const statusBar = (lt, online) => {
      const secs = online ? Math.floor(lt - 4.2) : 0;
      const clock = `${String(Math.floor(secs / 60)).padStart(2, '0')}:${String(secs % 60).padStart(2, '0')}`;
      b.fill(0, H - 1, W, 1, ' ', P[0], P[3]);
      const parts = ['PRiSMTERM 3.51', 'Alt-Z Help', 'ANSI-BBS', '2400 N81', 'FDX', online ? `Online ${clock}` : 'Offline'];
      let x = 1;
      for (const [i, p] of parts.entries()) {
        if (x + p.length >= W) break;
        x = b.text(x, H - 1, p, i === parts.length - 1 && online ? P[15] : P[0], P[3]);
        if (i < parts.length - 1 && x + 3 < W) x = b.text(x, H - 1, ' │ ', P[1], P[3]);
      }
    };
    const dialBox = (lt) => {
      const bw = Math.min(W - 4, 36), bh = 6;
      if (H < bh + 4) return;
      const bx = Math.floor((W - bw) / 2), by = Math.max(SCRIPT.length + 1, Math.floor((H - bh) / 2));
      b.fill(bx, by, bw, bh, ' ', P[15], P[1]);
      frame(b, bx, by, bw, bh, P[11], 'Dialing', P[15]);
      const rows = [['System', 'PRISM BBS'], ['Number', '555-0142'], ['Elapsed', `${Math.floor((lt - 1) * 3)}s`], ['Status', lt < 2.4 ? 'Dialing' : lt < 4.2 ? 'Ringing' : 'CONNECT']];
      rows.forEach(([k, v], i) => {
        b.text(bx + 2, by + 1 + i, `${k}:`.padEnd(9), P[7], P[1]);
        b.text(bx + 11, by + 1 + i, v.slice(0, bw - 13), i === 3 && lt >= 4.2 ? P[10] : P[14], P[1]);
      });
    };
    return (t) => {
      const lt = t % loop;
      b.fill(0, 0, W, H, ' ', P[7], P[0]);
      const blink = Math.floor(t * 3) % 2 === 0;
      if (lt < PAINT_AT) {
        let y = 0;
        for (const [at, text] of SCRIPT) {
          if (lt < at || y >= H - 1) break;
          const isCmd = text.startsWith('AT');
          const shown = isCmd ? text.slice(0, Math.floor((lt - at) * 14)) : text;
          const end = b.text(0, y, shown, isCmd ? P[15] : text.startsWith('CONNECT') ? P[10] : P[7]);
          if (isCmd && shown.length < text.length && blink) b.set(end, y, '█', P[7]);
          y++;
        }
        if (lt >= 1 && lt < PAINT_AT - 0.3) dialBox(lt);
        statusBar(lt, lt >= 4.2);
        return;
      }
      // Paint the welcome screen in transmission order, cursor at the head.
      const n = Math.min(total, Math.floor((lt - PAINT_AT) * CPS));
      for (let i = 0; i < n; i++) {
        const x = i % W, y = (i / W) | 0;
        const c = screen.get(x, y);
        b.set(x, y, c.ch, c.fg, c.bg, c.attr);
      }
      if (n < total) b.set(n % W, (n / W) | 0, '█', P[7]);
      if (lt > PAINT_AT + paintDur + HOLD) {
        b.fill(0, H - 2, W, 1, ' ', P[7], P[0]);
        b.text(0, H - 2, 'NO CARRIER', P[12]);
      }
      statusBar(lt, lt <= PAINT_AT + paintDur + HOLD);
    };
  },
};

sources.prism-term/src/facets/retro/neon-skyline:
// A neon city at night drifting past in three parallax layers: hazy far
// towers, mid-rise blocks full of lit windows, near buildings trimmed in neon
// with flickering signs — searchlights sweeping the clouds, traffic streaming
// along the waterfront, and the whole thing mirrored in a rippling harbour.
import { lerpc, hash2 } from './_kit.js';

const LOOP = 40;
const add = (a, b, k) => {
  const r = Math.min(255, ((a >> 16) & 255) + ((b >> 16) & 255) * k);
  const g = Math.min(255, ((a >> 8) & 255) + ((b >> 8) & 255) * k);
  const bl = Math.min(255, (a & 255) + (b & 255) * k);
  return (r << 16) | (g << 8) | bl;
};

export default {
  title: 'Neon Skyline',
  gallery: 'retro',
  category: 'Outrun',
  kind: 'scene',
  tags: ['city', 'skyline', 'neon', 'night', 'parallax', 'reflection', 'synthwave', 'cyberpunk'],
  order: 20,
  description: 'A neon city drifting past in parallax: lit windows, neon trim, searchlights, waterfront traffic and a rippling harbour.',
  size: { w: 80, h: 22 },
  minSize: { w: 24, h: 8 },
  loop: LOOP,
  canvas: 'field',
  palette: 'synthwave',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { width: PW, height: PH, px, aspect } = cv;
    const waterY = Math.floor(PH * 0.72);
    const road = waterY - Math.max(2, Math.round(PH * 0.03));
    const pitch = Math.max(2, Math.round(PH / 24));                 // window grid in pixels
    const neon = [0xff3fd0, 0x3ff0ff, 0xffe45a, pal(0.62), 0x7a5cff];
    const scale = Math.max(1, PW / 80);
    // Each layer is a strip of buildings exactly one loop's travel long, so the drift repeats seamlessly.
    const LAYERS = [
      { speed: PW / 20, hMin: 0.22, hMax: 0.6, wMin: 4, wMax: 10, body: lerpc(pal(0.1), pal(0.24), 0.5), lit: 0.16, haze: 0.45 },
      { speed: PW / 10, hMin: 0.16, hMax: 0.48, wMin: 5, wMax: 12, body: lerpc(pal(0.07), pal(0.16), 0.5), lit: 0.42, haze: 0.18 },
      { speed: PW / 5, hMin: 0.08, hMax: 0.36, wMin: 8, wMax: 17, body: lerpc(pal(0.02), 0x000000, 0.5), lit: 0.3, haze: 0, near: true },
    ].map((L, li) => {
      const len = Math.round(L.speed * LOOP);
      const owner = new Int32Array(len), local = new Int32Array(len), bs = [];
      let x = 0, j = 0;
      while (x < len) {
        let w = Math.round((L.wMin + hash2(j, li, 1) * (L.wMax - L.wMin)) * scale);
        if (len - x - w < L.wMin * scale) w = len - x;
        const top = waterY - Math.round(PH * (L.hMin + Math.pow(hash2(j, li, 2), 1.3) * (L.hMax - L.hMin)));
        bs.push({ w, top, trim: L.near && hash2(j, li, 3) < 0.5, sign: L.near && hash2(j, li, 7) < 0.4, c: neon[Math.floor(hash2(j, li, 4) * neon.length)], mast: hash2(j, li, 5) < 0.3, tone: hash2(j, li, 6) });
        for (let i = 0; i < w && x + i < len; i++) { owner[x + i] = j; local[x + i] = i; }
        x += w; j++;
      }
      return { ...L, len, owner, local, bs };
    });
    const skyTop = pal(0.01), skyMid = pal(0.14), skyLow = pal(0.42);
    const stars = Array.from({ length: Math.round(PW * PH * 0.005) }, (_, i) => [Math.floor(hash2(i, 9) * PW), Math.floor(hash2(i, 8) * waterY * 0.45), hash2(i, 7)]);
    const above = new Int32Array(PW * waterY);
    const warm = 0xffd38a, cool = 0xa8ecff;
    const beams = [{ x: 0.28, ph: 0, sp: 0.31 }, { x: 0.71, ph: 2.1, sp: 0.23 }];

    return (t) => {
      const lt = t % LOOP;
      for (let y = 0; y < waterY; y++) {
        const v = y / waterY;
        above.fill(v < 0.5 ? lerpc(skyTop, skyMid, v / 0.5) : lerpc(skyMid, skyLow, Math.pow((v - 0.5) / 0.5, 1.3)), y * PW, (y + 1) * PW);
      }
      for (const [x, y, k] of stars) if (Math.sin((t * Math.PI * (1 + Math.floor(k * 3))) / 10 + k * 30) > -0.2) above[y * PW + x] = lerpc(skyMid, 0xffffff, 0.45 + k * 0.4);
      // Searchlights: soft additive cones swinging slowly across the sky.
      for (const bm of beams) {
        const ang = Math.sin((lt * Math.PI * 2 * 2) / LOOP + bm.ph) * 0.55;    // two sweeps per loop
        const ox = bm.x * PW, oy = waterY, dx = Math.sin(ang), dy = -Math.cos(ang);
        for (let y = 0; y < waterY; y++) for (let x = 0; x < PW; x++) {
          const vx = x + 0.5 - ox, vy = (y + 0.5 - oy) * aspect;
          const along = vx * dx + vy * dy;
          if (along <= 0) continue;
          const across = Math.abs(vx * dy - vy * dx), width = 0.6 + along * 0.09;
          if (across < width) above[y * PW + x] = add(above[y * PW + x], pal(0.7), 0.32 * (1 - across / width) * Math.max(0, 1 - along / (PW * 0.9)));
        }
      }
      for (const L of LAYERS) {
        const scroll = lt * L.speed;
        for (let x = 0; x < PW; x++) {
          const wx = Math.floor(x + scroll) % L.len, j = L.owner[wx], lx = L.local[wx], bd = L.bs[j];
          for (let y = Math.max(0, bd.top); y < waterY; y++) {
            let c = L.haze ? lerpc(L.body, skyLow, L.haze * (0.4 + 0.6 * ((y - bd.top) / (waterY - bd.top)))) : L.body;
            const wy = y - bd.top - 1, edge = lx === 0 || lx === bd.w - 1;
            if (!edge && wy > 0 && lx % pitch === 1 && wy % pitch === 1) {
              const cxI = (lx / pitch) | 0, cyI = (wy / pitch) | 0;
              const on = hash2(j * 31 + cxI, cyI, Math.floor(lt / 8 + hash2(j, cxI, cyI) * 5)) < L.lit;
              if (on) c = lerpc(bd.tone < 0.65 ? warm : cool, c, L.haze * 0.9);
            }
            if (bd.sign && lx >= 2 && lx < 2 + pitch && wy > pitch && wy < pitch * 7) {
              const flick = hash2(j, Math.floor(t * 12), 5) < 0.05 ? 0.2 : 1;
              c = lerpc(L.body, wy % (pitch * 2) < pitch ? bd.c : lerpc(bd.c, 0xffffff, 0.4), flick);
            }
            above[y * PW + x] = c;
          }
          // Neon trim along the roofline and down the edges of some near buildings.
          if (bd.trim && bd.top >= 0) {
            above[bd.top * PW + x] = bd.c;
            if (lx === 0 || lx === bd.w - 1) for (let y = bd.top; y < Math.min(road, bd.top + pitch * 4); y++) above[y * PW + x] = lerpc(bd.c, L.body, (y - bd.top) / (pitch * 4));
          }
          if (bd.mast && lx === bd.w >> 1) {
            const mh = Math.max(2, pitch * 2);
            for (let y = Math.max(0, bd.top - mh); y < bd.top; y++) above[y * PW + x] = L.body;
            if ((lt + j * 0.37) % 2 < 0.5 && bd.top - mh - 1 >= 0) above[(bd.top - mh - 1) * PW + x] = lerpc(L.body, 0xff3040, L.haze ? 0.55 : 1);
          }
        }
      }
      // Waterfront road: a dark deck with headlights streaming right and tail-lights left.
      for (let y = road; y < waterY; y++) above.fill(0x0a0612, y * PW, (y + 1) * PW);
      for (let i = 0; i < Math.ceil(PW / 14); i++) {
        const xr = Math.floor((hash2(i, 1) * PW + lt * PW * 0.25) % PW), xl = Math.floor((((hash2(i, 2) * PW - lt * PW * 0.2) % PW) + PW) % PW);
        above[road * PW + xr] = 0xfff4d0;
        if (road + 1 < waterY) above[(road + 1) * PW + xl] = 0xff3a3a;
      }
      for (let x = (PW >> 3) % 7; x < PW; x += 7) above[(road - 1) * PW + x] = lerpc(warm, above[(road - 1) * PW + x], 0.3);
      px.set(above);
      // Harbour: the city upside down, rippled sideways, lights stretching into streaks.
      const water = lerpc(skyTop, 0x000000, 0.3);
      for (let y = waterY; y < PH; y++) {
        const d = y - waterY, k = d / Math.max(1, PH - waterY);
        const my = waterY - 1 - Math.floor(d * 0.8);
        const off = Math.round(Math.sin(d * 1.3 + (t * Math.PI * 2 * 8) / LOOP) * (0.5 + k * 2) + Math.sin(d * 0.5 - (t * Math.PI * 2 * 5) / LOOP) * k * 1.4);
        for (let x = 0; x < PW; x++) {
          const sx = Math.min(PW - 1, Math.max(0, x + off));
          const src = my >= 0 ? above[my * PW + sx] : skyTop;
          px[y * PW + x] = lerpc(src, water, 0.38 + k * 0.3);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/oscilloscope:
// A phosphor oscilloscope on the chiptune: graticule, a trace triggered on the
// bass so it stands still, and persistence — the last few sweeps fading out
// behind the beam. `--set mode=xy` plots bass against lead as Lissajous figures.
import { lerpc } from './_kit.js';
import { songAt } from './_music.js';

const PHOSPHOR = { green: 0x40ff80, amber: 0xffb020, blue: 0x60c8ff };

export default {
  title: 'Oscilloscope',
  gallery: 'retro',
  category: 'Chiptune Visuals',
  kind: 'scene',
  tags: ['oscilloscope', 'scope', 'waveform', 'phosphor', 'lissajous', 'audio', 'chiptune'],
  order: 30,
  description: 'A phosphor oscilloscope on the chiptune: graticule, a bass-triggered trace with persistence, and an XY Lissajous mode.',
  size: { w: 64, h: 18 },
  minSize: { w: 20, h: 6 },
  loop: 7.68,
  canvas: 'line',
  params: {
    mode: { default: 'yt', options: ['yt', 'xy'], label: 'Mode' },
    phosphor: { default: 'green', options: ['green', 'amber', 'blue', 'theme'], label: 'Phosphor' },
  },
  setup(ctx) {
    const { theme } = ctx;
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const cv = ctx.canvas('line');
    const PW = cv.width, PHt = cv.height;
    const xy = ctx.param('mode', 'yt') === 'xy';
    const ph = ctx.param('phosphor', 'green');
    const beam = ph === 'theme' ? theme.accent : PHOSPHOR[ph] ?? PHOSPHOR.green;
    const grid = lerpc(theme.bg, beam, 0.2), axis = lerpc(theme.bg, beam, 0.32);
    const trails = [1, 0.5, 0.26, 0.12].map((k) => lerpc(theme.bg, beam, k));
    const readout = H >= 10 && W >= 36;
    const cx = PW / 2, cy = PHt / 2;
    const amp = PHt * 0.42;
    function graticule() {
      const dx = PW / 10, dy = PHt / 8;
      for (let i = 0; i <= 10; i++) {
        const x = Math.min(PW - 1, Math.round(i * dx));
        for (let y = 0; y < PHt; y += 3) cv.set(x, y, i === 5 ? axis : grid);
      }
      for (let j = 0; j <= 8; j++) {
        const y = Math.min(PHt - 1, Math.round(j * dy));
        for (let x = 0; x < PW; x += 3) cv.set(x, y, j === 4 ? axis : grid);
      }
      // Minor ticks along the center axes.
      for (let i = 0; i <= 50; i++) { const x = Math.round((i * PW) / 50); cv.set(x, Math.round(cy) - 1, axis); cv.set(x, Math.round(cy) + 1, axis); }
      for (let j = 0; j <= 40; j++) { const y = Math.round((j * PHt) / 40); cv.set(Math.round(cx) - 1, y, axis); cv.set(Math.round(cx) + 1, y, axis); }
    }
    // The scope looks at the tonal voices through a gentle low-pass: rounded
    // squares and pulses plus the kick's thump; the noise channels stay out.
    const soft = (ph, duty) => Math.tanh(4 * (Math.sin(2 * Math.PI * ph) + (duty - 0.5) * 2)) * 0.95;
    function sweepYT(t, color) {
      // Trigger on the bass so the picture holds still: two bass periods per screen.
      const s = songAt(t), fb = s.bassFreq;
      const start = Math.floor(t * fb) / fb, span = 2 / fb;
      let px = 0, py = cy;
      for (let x = 0; x < PW; x++) {
        const tau = start + (x / PW) * span, a = s.kickAge + (tau - start);
        const v = 0.42 * s.bass * soft(tau * fb, 0.5) + 0.28 * s.lead * soft(tau * s.leadFreq, 0.3) + 0.45 * s.kick * Math.sin(2 * Math.PI * 52 * a);
        const y = cy - v * amp;
        if (x) cv.line(px, py, x, y, color);
        px = x; py = y;
      }
    }
    // XY: the bass/lead interval picks a small-integer frequency ratio, so the
    // figure changes shape with the harmony and closes on itself.
    const RATIO = [[1, 1], [9, 8], [9, 8], [6, 5], [5, 4], [4, 3], [7, 5], [3, 2], [8, 5], [5, 3], [7, 4], [2, 1]];
    function sweepXY(t, color) {
      const s = songAt(t);
      const [p, q] = RATIO[(((s.leadNote - s.bassNote) % 12) + 12) % 12];
      const ax = (0.55 + 0.35 * s.bass) * (1 + s.kick * 0.18), ay = (0.5 + 0.4 * s.lead) * (1 + s.kick * 0.18);
      const phase = t * 0.9, N = Math.max(200, PW * 4);
      let px = 0, py = 0;
      for (let i = 0; i <= N; i++) {
        const u = (i / N) * 2 * Math.PI;
        const x = cx + Math.sin(q * u + phase) * ax * cx * 0.92;
        const y = cy - Math.sin(p * u) * ay * amp * 1.05;
        if (i) cv.line(px, py, x, y, color);
        px = x; py = y;
      }
    }
    return (t) => {
      b.fill(0, 0, W, H, ' ', theme.ink, theme.bg);
      cv.clear();
      graticule();
      // Persistence: older sweeps first, dimmer, so the newest sits on top.
      for (let k = trails.length - 1; k >= 0; k--) (xy ? sweepXY : sweepYT)(t - k / 30, trails[k]);
      cv.paint(b);
      if (readout) {
        const s = songAt(t);
        const dim = lerpc(theme.bg, beam, 0.6);
        b.text(1, 0, xy ? 'X: BASS  Y: LEAD' : 'CH1 0.5V/div', dim);
        b.text(W - 12, 0, xy ? '    XY MODE' : 'TRIG ↑ BASS', dim);
        b.text(1, H - 1, xy ? `${RATIO[(((s.leadNote - s.bassNote) % 12) + 12) % 12].join(':')}  ${s.bassFreq.toFixed(1)} Hz` : `${s.bassFreq.toFixed(1)} Hz`, dim);
        if (!xy) b.text(W - 11, H - 1, `${((2 / s.bassFreq) * 100).toFixed(2)}ms/div`.padStart(10), dim);
      }
    };
  },
};

// Arcade-racer pseudo-3D: a road built row by row from the horizon down, with
// curvature integrated per scanline so it sweeps left and right, alternating
// rumble strips and lane dashes, palm silhouettes scaling past, the sunset
// sliding against the curves, a red convertible leaning in — and the HUD.
import { lerpc, hash2 } from './_kit.js';

const CAR = [
  '......rrrrrrrrrrrrrrrr......',
  '.....rkkkkkkkkkkkkkkkkr.....',
  '....rkkhkkkkkkkkkkkkkkkr....',
  '..rrrrrrrrrrrrrrrrrrrrrrrr..',
  '.RRRRRRRRRRRRRRRRRRRRRRRRRR.',
  'RRLLLLRRRRRRRRRRRRRRRRLLLLRR',
  'RRLLLLRRggggggggggggRRLLLLRR',
  'RRRRRRRRggggggggggggRRRRRRRR',
  'ddssssddddddddddddddddssssdd',
  'kkkkkk................kkkkkk',
];
const SEG = 7, LOOP = 12, SPEED = 60;            // world units; one loop covers 720 units
const TAU = Math.PI * 2, LEN = SPEED * LOOP;
const curve = (z) => Math.sin((TAU * z) / LEN) * 0.9 + Math.sin((TAU * 3 * z) / LEN + 1) * 0.45;
const curveInt = (z) => (-Math.cos((TAU * z) / LEN) * 0.9 * LEN) / TAU - (Math.cos((TAU * 3 * z) / LEN + 1) * 0.45 * LEN) / (3 * TAU);

export default {
  title: 'Outrun Road',
  gallery: 'retro',
  category: 'Outrun',
  kind: 'scene',
  tags: ['outrun', 'racer', 'pseudo-3d', 'road', 'palms', 'sunset', 'arcade', '1986'],
  order: 10,
  description: 'Arcade pseudo-3D racing: a curving road with rumble strips, palm silhouettes, a sunset and a red convertible.',
  size: { w: 80, h: 24 },
  minSize: { w: 24, h: 8 },
  loop: LOOP,
  canvas: 'field',
  palette: 'sunset',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { theme } = ctx;
    const b = ctx.buffer;
    const { width: PW, height: PH, px, aspect } = cv;
    const hy = Math.floor(PH * 0.46);
    const rows = PH - hy;
    const zNear = 3, zFar = 260;
    const halfW = (p) => p * PW * 0.4;
    const fogC = pal(0.62);
    const roadA = 0x5c5866, roadB = 0x56525f, grassA = 0x1f7a3c, grassB = 0x1a6a34;
    const sil = lerpc(pal(0.05), 0x000000, 0.3);
    const sunR = Math.min(PW * 0.16, hy * aspect * 0.8);
    // Mountains: a ridge wider than the screen so it can slide with the curves.
    const MW = PW * 3, ridge = new Float32Array(MW);
    for (let x = 0; x < MW; x++) {
      const u = x / MW;
      ridge[x] = hy - PH * (0.04 + 0.09 * Math.pow(Math.abs(Math.sin(u * TAU * 3 + 1.3)), 0.7) * (0.6 + 0.4 * Math.sin(u * TAU * 7)));
    }
    const wx = new Float32Array(rows);            // road centre per row, in road half-widths
    const hud = PW >= 40 && ctx.height >= 12;
    const carW0 = CAR[0].length, carH0 = CAR.length;
    const carScale = Math.max(PW * 0.3, 8) / carW0;
    const carColors = { r: 0xd81e2c, R: 0xf0283a, k: 0x1a1020, h: 0x6a6aa8, L: 0xffb040, g: 0x2a1418, d: 0x301018, s: 0x8a8a96 };

    return (t) => {
      const lt = t % LOOP, camZ = lt * SPEED;
      const shift = (curveInt(camZ) * 0.04 * PW) / 10;
      // Sky and sun.
      for (let y = 0; y < hy; y++) {
        const c = pal(0.04 + (y / hy) * 0.62);
        px.fill(c, y * PW, (y + 1) * PW);
      }
      const sunX = PW / 2 - shift * 0.6, sunY = hy - sunR * 0.35 / aspect;
      for (let y = Math.max(0, Math.floor(sunY - sunR / aspect)); y < hy; y++) for (let x = Math.max(0, Math.floor(sunX - sunR)); x < Math.min(PW, sunX + sunR); x++) {
        const dx = x + 0.5 - sunX, dy = (y + 0.5 - sunY) * aspect;
        if (dx * dx + dy * dy < sunR * sunR) px[y * PW + x] = lerpc(pal(0.98), pal(0.78), (y - (sunY - sunR / aspect)) / (2 * sunR / aspect));
      }
      for (let x = 0; x < PW; x++) {
        const rx = Math.floor((((x + shift) % MW) + MW) % MW);
        for (let y = Math.max(0, Math.floor(ridge[rx])); y < hy; y++) px[y * PW + x] = lerpc(sil, fogC, 0.35);
      }
      // Road: walk from the bottom (near) up to the horizon, integrating curvature.
      let x = 0, dx = 0, zPrev = zNear;
      for (let r = rows - 1; r >= 0; r--) {
        const p = (r + 1) / rows, z = zNear / p;
        if (z > zFar) { wx[r] = x; continue; }
        const dz = z - zPrev; zPrev = z;
        dx += curve(camZ + z) * 0.0011 * dz;
        x += dx * dz;
        wx[r] = x;
      }
      for (let r = 0; r < rows; r++) {
        const y = hy + r, p = (r + 1) / rows, z = zNear / p;
        const hw = halfW(p), cx = PW / 2 + wx[r] * hw;
        const seg = Math.floor((camZ + z) / SEG) & 1;
        const fog = Math.min(1, Math.pow(z / zFar, 0.7));
        const grass = lerpc(seg ? grassA : grassB, fogC, fog), road = lerpc(seg ? roadA : roadB, fogC, fog);
        const rumble = lerpc(seg ? 0xf0f0f0 : 0xd02030, fogC, fog), lane = lerpc(0xf0f0f0, road, fog);
        const rw = hw * 0.12, lw = hw * 0.035;
        for (let xx = 0; xx < PW; xx++) {
          const d = Math.abs(xx + 0.5 - cx);
          let c = grass;
          if (d < hw) c = road;
          else if (d < hw + rw) c = rumble;
          if (seg && d < hw && Math.abs(d - hw / 3) < lw) c = lane;
          px[y * PW + xx] = c;
        }
      }
      // Palms, far to near: trunk and drooping fronds, silhouetted against the sunset.
      const GAP = 10, first = Math.ceil((camZ + zNear + 1) / GAP), last = Math.floor((camZ + zFar) / GAP);
      for (let k = last; k >= first; k--) {
        const z = k * GAP - camZ, p = zNear / z;
        const r = Math.min(rows - 1, Math.max(0, Math.round(p * rows) - 1));
        const side = k & 1 ? 1 : -1, hw = halfW(p);
        const bx = PW / 2 + (wx[r] + side * (1.4 + hash2(k, 3) * 0.35)) * hw, by = hy + r;
        const fog = Math.min(1, Math.pow(z / zFar, 0.7)), c = lerpc(sil, fogC, fog * 0.9);
        const hgt = (hw * 2.1) / aspect, lean = side * hw * 0.22;
        const th = Math.max(1, hw * 0.06);
        for (let i = 0; i <= 40; i++) {
          const f = i / 40, tx = bx + lean * f * f, ty = by - hgt * f;
          for (let w = 0; w < th; w++) cv.set(tx + w - th / 2, ty, c);
        }
        const topX = bx + lean, topY = by - hgt;
        for (let a = 0; a < 8; a++) {
          // Fronds arc up and out, then droop; each a little different.
          const ang = -Math.PI + (a / 7) * Math.PI, len = hw * (0.7 + 0.2 * hash2(k, a));
          for (let i = 0; i <= 30; i++) {
            const f = i / 30, fx = topX + Math.cos(ang) * len * f, fy = topY + (Math.sin(ang) * len * f * 0.55 + len * f * f * 0.7) / aspect;
            cv.set(fx, fy, c);
            if (f < 0.7) cv.set(fx, fy + 1, c);
          }
        }
      }
      // The car: bobbing slightly, leaning into the curve.
      const lean = curve(camZ + 20) * PW * 0.03;
      const cw = carW0 * carScale, ch = (carH0 * carScale) / aspect;
      const cx0 = PW / 2 - cw / 2 + lean, cy0 = PH - ch - Math.max(1, PH * 0.03) - (Math.floor(lt * 8) % 2 ? 0 : 0.6);
      for (let y = 0; y < ch; y++) for (let xx = 0; xx < cw; xx++) {
        const k = CAR[Math.min(carH0 - 1, Math.floor((y / ch) * carH0))][Math.min(carW0 - 1, Math.floor((xx / cw) * carW0))];
        if (k !== '.') cv.set(cx0 + xx, cy0 + y, k === 'L' && Math.floor(lt * 2) % 4 === 0 ? 0xff5a3a : carColors[k]);
      }
      cv.paint(b);
      if (hud) {
        const time = 60 - Math.floor(lt * 2.5);
        const score = String(1250000 + Math.floor(camZ * 37) * 10).padStart(8, '0');
        const kmh = 286 + Math.round(Math.sin(lt * 1.3) * 6);
        b.text(1, 0, 'TIME', theme.warn);
        b.text(6, 0, String(time), 0xffffff);
        b.text(Math.floor(ctx.width / 2) - 7, 0, `SCORE ${score}`, 0x7cf0ff);
        const sp = `${kmh} km/h`;
        b.text(ctx.width - sp.length - 1, ctx.height - 1, sp, 0xffe14a);
      }
    };
  },
};

sources.prism-term/src/facets/retro/rotozoomer.j:
// Rotozoomer: one small tile — a checker with a prism emblem — rotated and
// zoomed across the whole screen every frame. The texture-mapping trick that
// showed what a 7 MHz CPU could do.
import { lerpc } from './_kit.js';

const T = 32;
function makeTile(pal, theme) {
  const tile = new Int32Array(T * T);
  for (let y = 0; y < T; y++) for (let x = 0; x < T; x++) {
    const check = ((x >> 3) + (y >> 3)) & 1;
    let c = check ? lerpc(theme.bg, theme.accent, 0.42) : lerpc(theme.bg, 0x000000, 0.25);
    // Prism emblem: a triangle with a bright edge, centered in the tile.
    const u = (x - T / 2 + 0.5) / (T / 2), v = (y - T / 2 + 0.5) / (T / 2);
    const inTri = v > -0.62 && v < 0.55 && Math.abs(u) < (v + 0.62) * 0.62;
    const edge = inTri && (v > 0.43 || Math.abs(u) > (v + 0.62) * 0.62 - 0.16);
    if (inTri) c = edge ? 0xffffff : pal(((u + 1) * 0.5 + 0.1) % 1);
    tile[y * T + x] = c;
  }
  return tile;
}

export default {
  title: 'Rotozoomer',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['rotozoom', 'texture mapping', 'demoscene', 'rotation', 'zoom'],
  order: 60,
  description: 'One small emblem tile rotated and zoomed across the whole screen every frame — classic texture mapping.',
  size: { w: 70, h: 22 },
  minSize: { w: 16, h: 6 },
  loop: 12,
  canvas: 'field',
  palette: 'prism',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px, aspect } = cv;
    const tile = makeTile(pal, ctx.theme);
    return (t) => {
      const tt = t * speed;
      const a = tt * 0.6, zoom = 1.1 + Math.sin(tt * 0.45) * 0.75;
      const ca = Math.cos(a) * zoom * (T / Math.min(W, H * aspect)) * 1.6, sa = Math.sin(a) * zoom * (T / Math.min(W, H * aspect)) * 1.6;
      const ox = tt * 9, oy = tt * 5;
      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y - H / 2) * aspect;
        for (let x = 0; x < W; x++, i++) {
          const vx = x - W / 2;
          const u = Math.floor(vx * ca - vy * sa + ox), v = Math.floor(vx * sa + vy * ca + oy);
          px[i] = tile[(v & (T - 1)) * T + (u & (T - 1))];
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

