// A 1998 media-player spectrum analyser: log-spaced bars in eighth-block
// resolution, green-to-red by height, falling bars and peak caps that drop
// with gravity — dancing to the shared chiptune. A dim floor reflection when tall.
import { lerpc } from './_kit.js';
import { bands } from './_music.js';

const EIGHTHS = ' ▁▂▃▄▅▆▇█';
const K = 26, STEP = 1 / 30;

export default {
  title: 'Spectrum Analyzer',
  gallery: 'retro',
  category: 'Chiptune Visuals',
  kind: 'scene',
  tags: ['spectrum', 'analyzer', 'fft', 'eq', 'audio', 'bars', 'chiptune', 'winamp'],
  order: 20,
  description: 'A media-player spectrum analyser: log-spaced bars in eighth-blocks, falling peak caps and a floor reflection.',
  size: { w: 64, h: 16 },
  minSize: { w: 20, h: 6 },
  loop: 7.68,
  params: { style: { default: 'classic', options: ['classic', 'palette'], label: 'Colors' } },
  setup(ctx) {
    const { theme } = ctx;
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const pal = ctx.palette('prism');
    const classic = ctx.param('style', 'classic') !== 'palette';
    const barW = W >= 48 ? 2 : 1, pitch = barW + 1;
    const n = Math.max(4, Math.floor((W - 1) / pitch));
    const x0 = Math.floor((W - (n * pitch - 1)) / 2);
    const labels = H >= 10;
    const reflect = H >= 12 ? Math.max(2, Math.round(H * 0.18)) : 0;
    const rows = H - (labels ? 1 : 0) - reflect;
    const hist = Array.from({ length: K }, () => new Float32Array(n));
    const color = (f) => (!classic ? pal(f) : f < 0.55 ? theme.pos : f < 0.8 ? lerpc(theme.pos, theme.warn, (f - 0.55) / 0.25) : lerpc(theme.warn, theme.neg, (f - 0.8) / 0.2));
    const rowColor = Array.from({ length: rows }, (_, r) => color((r + 0.5) / rows));
    const freqs = [[60, '60'], [250, '250'], [1000, '1k'], [4000, '4k'], [10000, '10k']];
    return (t) => {
      b.fill(0, 0, W, H, ' ', theme.ink, theme.bg);
      for (let k = 0; k < K; k++) bands(t - k * STEP, n, hist[k]);
      for (let i = 0; i < n; i++) {
        // Bars fall at a fixed rate; caps hold briefly then fall with gravity.
        let bar = 0, peak = 0;
        for (let k = 0; k < K; k++) {
          const v = hist[k][i], age = k * STEP;
          bar = Math.max(bar, v - age * 2.2);
          peak = Math.max(peak, v - Math.max(0, age - 0.2) ** 2 * 3.2);
        }
        const h = Math.max(0, bar) * rows, ph = Math.max(h / rows, peak) * rows;
        const x = x0 + i * pitch;
        for (let r = 0; r < rows; r++) {
          const y = rows - 1 - r, fill = Math.min(1, Math.max(0, h - r));
          if (fill <= 0) break;
          const ch = EIGHTHS[Math.max(1, Math.round(fill * 8))];
          for (let dx = 0; dx < barW; dx++) b.set(x + dx, y, ch, rowColor[r]);
        }
        // The cap sits on the cell above the bar's top when there's room.
        const pr = Math.min(rows - 1, Math.floor(ph));
        if (ph > 0.05 && pr >= Math.ceil(h)) for (let dx = 0; dx < barW; dx++) b.set(x + dx, rows - 1 - pr, '▔', lerpc(rowColor[pr], theme.ink, 0.5));
        // Floor reflection: dim, upside down, fading away.
        for (let r = 0; r < reflect; r++) {
          const fill = Math.min(1, Math.max(0, h - r));
          if (fill <= 0) break;
          const fade = 0.28 * (1 - r / reflect);
          for (let dx = 0; dx < barW; dx++) b.set(x + dx, rows + r, fill > 0.5 ? '█' : '▀', lerpc(theme.bg, rowColor[r], fade));
        }
      }
      if (labels) {
        const y = H - 1;
        const lo = Math.log2(40), hi = Math.log2(12000);
        for (const [f, s] of freqs) {
          const x = Math.round(x0 + ((Math.log2(f) - lo) / (hi - lo)) * (n * pitch - 1) - s.length / 2);
          if (x >= 0 && x + s.length <= W) b.text(x, y, s, theme.muted);
        }
      }
    };
  },
};

sources.prism-term/src/facets/retro/starfield.js:
// Warp-speed starfield: stars fly at the camera in 3D, drawn as braille
// streaks whose length tracks the current speed. Every ten seconds the ship
// surges to warp; color temperature runs from ember (far) to blue-white (near).
export default {
  title: 'Starfield',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['starfield', 'warp', 'space', 'demoscene'],
  order: 10,
  description: 'Warp-speed 3D starfield — braille motion streaks, periodic warp surges, depth-based color temperature.',
  canvas: 'line',
  setup(ctx) {
    const cv = ctx.canvas();
    const { width: W, height: H, aspect } = cv;
    const rand = ctx.rng;
    const temp = ctx.palette(['#ff5a2e', '#ffab5e', '#fff0d8', '#d6e4ff', '#8db4ff']);
    const speedK = ctx.param('speed', 1);
    const Hv = H * aspect;
    const k = 0.5 * Math.max(W, Hv);
    const ax = (W / 2 / k) * 1.2, ay = (Hv / 2 / k) * 1.2;
    const N = Math.max(60, Math.min(1800, Math.round(ctx.width * ctx.height * 0.16)));
    const X = new Float32Array(N), Y = new Float32Array(N), Z = new Float32Array(N), T = new Float32Array(N);
    const spawn = (i, z) => {
      X[i] = (rand() * 2 - 1) * ax;
      Y[i] = (rand() * 2 - 1) * ay;
      Z[i] = z;
      T[i] = rand();
    };
    for (let i = 0; i < N; i++) spawn(i, 0.04 + rand() * 0.96);
    const cx = W / 2, cy = H / 2;

    // Brightness-ramped line: dim at the tail, full at the head.
    const streak = (x0, y0, x1, y1, c) => {
      const n = Math.min(240, Math.max(1, Math.ceil(Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0)))));
      const r = (c >> 16) & 255, g = (c >> 8) & 255, b = c & 255;
      for (let s = 0; s <= n; s++) {
        const u = s / n, k2 = 0.18 + 0.82 * u * u;
        cv.set(x0 + (x1 - x0) * u, y0 + (y1 - y0) * u, ((r * k2) << 16) | ((g * k2) << 8) | ((b * k2) | 0));
      }
    };

    return (t, dt) => {
      // Surge envelope: cruise, then a 5 s warp bump every 10 s.
      const u = (t % 10) / 10;
      const bump = u < 0.5 ? Math.pow(Math.sin(Math.PI * u * 2), 2) : 0;
      const speed = (0.22 + 1.9 * bump) * speedK;
      const tail = 0.06 + 0.1 * bump;
      const roll = 0.35 * Math.sin(t * 0.11) + 0.25 * bump * Math.sin(t * 0.7);
      const cr = Math.cos(roll), sr = Math.sin(roll);
      cv.clear();
      for (let i = 0; i < N; i++) {
        Z[i] -= speed * dt;
        if (Z[i] <= 0.03) { spawn(i, 1); continue; }
        const x = X[i] * cr - Y[i] * sr, y = X[i] * sr + Y[i] * cr;
        const z = Z[i], zt = Math.min(1.05, z + speed * tail + 0.004);
        const hx = cx + (x / z) * k, hy = cy + ((y / z) * k) / aspect;
        if (hx < -2 || hy < -2 || hx > W + 2 || hy > H + 2) { spawn(i, 1); continue; }
        const tx = cx + (x / zt) * k, ty = cy + ((y / zt) * k) / aspect;
        const near = 1 - z;
        const c = temp(Math.min(1, near * 0.85 + T[i] * 0.3));
        const bright = Math.min(1, 0.42 + 0.8 * near * near + 0.25 * bump);
        const r = ((c >> 16) & 255) * bright, g = ((c >> 8) & 255) * bright, b = (c & 255) * bright;
        const col = (r << 16) | (g << 8) | (b | 0);
        streak(tx, ty, hx, hy, col);
        // Close stars get a fat 2×2 head so they read as bodies, not just lines.
        if (z < 0.3) { cv.set(hx + 1, hy, col); cv.set(hx, hy + 1, col); cv.set(hx + 1, hy + 1, col); }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/synthwave.js:
// Outrun flyover: a striped, gradient sun sinking behind a neon-rimmed
// mountain ridge, starry dusk sky, and a perspective grid racing toward the
// camera. Grid lines are anti-aliased analytically (world-space distance
// converted to pixels per row), so they stay crisp without moiré at the horizon.
export default {
  title: 'Synthwave',
  gallery: 'retro',
  category: 'Outrun',
  kind: 'scene',
  tags: ['synthwave', 'outrun', 'retrowave', 'grid', 'sun'],
  order: 40,
  description: 'Outrun flyover — striped gradient sun, neon-rimmed mountains and an anti-aliased perspective grid.',
  canvas: 'field',
  palette: 'synthwave',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const rand = ctx.rng;
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const hz = Math.floor(H * 0.6);           // horizon row
    const S = Math.min(W, H * aspect);
    const sunR = S * 0.3, sunX = W / 2, sunY = hz * aspect - sunR * 0.62; // sun center in visual units
    const camH = 1, focal = W * 0.55;
    const gridC = pal(0.62), gridC2 = pal(0.5), rimC = pal(0.7);
    const sky = new Int32Array(W * hz);
    const skyTop = pal(0.02), skyLow = pal(0.45);
    for (let y = 0; y < hz; y++) {
      const k = Math.pow(y / hz, 1.6);
      sky.fill(lerpc(skyTop, skyLow, k * 0.85), y * W, (y + 1) * W);
    }
    const stars = Array.from({ length: Math.floor(W * hz * 0.01) }, () => [Math.floor(rand() * W), Math.floor(rand() * hz * 0.7), rand()]);
    const ridge = new Float32Array(W), ridge2 = new Float32Array(W);
    // Ridged noise for sharp peaks; the near range is low in the middle so the sun shows.
    for (let x = 0; x < W; x++) {
      const u = x / W, side = 0.25 + 0.75 * Math.min(1, Math.abs(u - 0.5) * 2.4);
      const p = Math.max(0, 1 - Math.abs(fbm(u * 3.4, 1.7, 0, 3)) * 1.7);
      const q = Math.max(0, 1 - Math.abs(fbm(u * 7.5, 8.2, 0, 3)) * 1.7);
      ridge[x] = hz - H * (0.012 + 0.2 * side * p * p);
      ridge2[x] = hz - H * (0.02 + 0.13 * q * q * (0.35 + 0.65 * side));
    }

    return (t) => {
      const zoff = t * 2.2 * speed;
      const xoff = Math.sin(t * 0.25) * 1.2;
      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y + 0.5) * aspect;
        for (let x = 0; x < W; x++, i++) {
          if (y < hz) {
            let c = sky[i];
            // Sun: vertical gradient, with horizontal gaps that widen toward its base and scroll down.
            const dx = x + 0.5 - sunX, dy = vy - sunY;
            const d = Math.sqrt(dx * dx + dy * dy);
            if (d < sunR) {
              const v = (dy / sunR + 1) / 2;       // 0 top → 1 bottom
              const band = v > 0.42 ? ((v * 6.5 - t * 0.35) % 1 + 1) % 1 : 1;
              const gap = (v - 0.42) * 1.35;
              if (band > gap) c = pal(0.98 - v * 0.42);
            } else if (d < sunR * 1.5) {
              c = lerpc(c, pal(0.75), Math.pow(1 - (d - sunR) / (sunR * 0.5), 2) * 0.35);
            }
            if (y >= ridge2[x]) c = lerpc(0x1a0630, rimC, y - ridge2[x] < 1 ? 0.55 : 0.04);
            if (y >= ridge[x]) c = lerpc(0x0c0218, rimC, y - ridge[x] < 1 ? 0.95 : 0.02);
            px[i] = c;
          } else {
            const dyp = y - hz + 0.5;
            const z = (camH * focal) / dyp;           // world depth of this row
            const wx = ((x + 0.5 - W / 2) * z) / focal + xoff;
            const fx = wx - Math.round(wx), fz = (z + zoff) - Math.round(z + zoff);
            const pxPerX = focal / z, pxPerZ = (camH * focal) / (z * z);
            // Coverage of a ~0.9px line, faded out as lines converge below ~3px spacing (no moiré).
            const lx = Math.max(0, 1 - Math.abs(fx) * pxPerX / 0.9) * Math.min(1, Math.max(0, (pxPerX - 2.5) / 6));
            const lz = Math.max(0, 1 - Math.abs(fz) * pxPerZ / 0.9) * Math.min(1, Math.max(0, (pxPerZ - 1.5) / 4));
            const fog = Math.exp(-z / 18);
            const near = Math.min(1, dyp / (H - hz));
            const base = lerpc(0x0a0016, 0x1d0638, near);
            let c = lerpc(base, gridC2, Math.min(1, lz * fog * 1.15));
            c = lerpc(c, gridC, Math.min(1, lx * fog * 1.2));
            // Horizon haze glow.
            const sx = (x + 0.5 - sunX) / (sunR * 1.3);
            c = lerpc(c, pal(0.74), Math.pow(Math.max(0, 1 - dyp / (H * 0.12)), 1.5) * (0.3 + 0.45 * Math.exp(-sx * sx)));
            px[i] = c;
          }
        }
      }
      for (const [sx, sy, p] of stars) {
        const tw = 0.4 + 0.6 * Math.abs(Math.sin(t * (0.8 + p * 2) + p * 10));
        const dx = sx + 0.5 - sunX, dy = (sy + 0.5) * aspect - sunY;
        if (sy < ridge2[sx] && dx * dx + dy * dy > sunR * sunR * 1.6) px[sy * W + sx] = lerpc(px[sy * W + sx], 0xffffff, tw * 0.8);
      }
      cv.paint(ctx.buffer);
    };
  },
};

function lerpc(a, b, t) {
  const r = ((a >> 16) & 255) + ((((b >> 16) & 255) - ((a >> 16) & 255)) * t);
  const g = ((a >> 8) & 255) + ((((b >> 8) & 255) - ((a >> 8) & 255)) * t);
  const bl = (a & 255) + (((b & 255) - (a & 255)) * t);
  return (r << 16) | (g << 8) | (bl | 0);
}

sources.prism-term/src/facets/retro/tracker-patt:
// A 4-channel tracker playing the shared chiptune: hex row numbers, note /
// instrument / effect columns, the play row locked in the middle while the
// pattern scrolls under it, per-channel VU strips and an instrument list.
import { lerpc } from './_kit.js';
import { PATTERN, ROWS, ROW, BPM, SONG, INSTRUMENTS, songAt, levels, noteName } from './_music.js';

const CHANNELS = ['DRUMS', 'BASS', 'LEAD', 'HATS'];
const BAR = ' ▏▎▍▌▋▊▉█';
const hex = (n) => n.toString(16).toUpperCase().padStart(2, '0');

export default {
  title: 'Tracker Pattern',
  gallery: 'retro',
  category: 'Chiptune Visuals',
  kind: 'scene',
  tags: ['tracker', 'mod', 'protracker', 'pattern', 'chiptune', 'music', 'amiga'],
  order: 40,
  description: 'A 4-channel tracker playing a chiptune: hex rows, note/instrument/effect columns and a locked play row with VUs.',
  size: { w: 76, h: 22 },
  minSize: { w: 40, h: 10 },
  loop: ROW * ROWS,
  setup(ctx) {
    const { theme } = ctx;
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const side = W >= 70 ? 22 : 0;
    const avail = W - side - 3;
    const full = avail >= 4 * 11;
    const cw = full ? 11 : Math.max(9, Math.floor(avail / 4));
    const body = Math.max(3, H - 4);
    const bar = lerpc(theme.bg, theme.accent, 0.38);
    const beatRow = lerpc(theme.bg, theme.panel, 0.7);
    const cell = (ev) => {
      if (!ev) return full ? ['---', ' --', ' ---'] : ['---', '--', '---'];
      const inst = String(ev.inst).padStart(2, '0');
      return full ? [noteName(ev.note), ` ${inst}`, ` ${ev.eff}`] : [noteName(ev.note), inst, ev.eff];
    };
    return (t) => {
      b.fill(0, 0, W, H, ' ', theme.ink, theme.bg);
      const s = songAt(t), lv = levels(s);
      // Title bar.
      b.fill(0, 0, W, 1, ' ', theme.bg, theme.panel);
      const secs = s.t;
      const clock = `${String(Math.floor(secs / 60)).padStart(2, '0')}:${secs.toFixed(2).padStart(5, '0')}`;
      const left = ` ▶ PRiSMTRACKER · ${SONG}`;
      const right = W >= 60 ? `POS 00 PAT 00  BPM ${BPM} SPD 06  ${clock} ` : `${clock} `;
      b.text(0, 0, left.slice(0, W - right.length - 1), theme.ink, theme.panel);
      b.text(W - right.length, 0, right, theme.muted, theme.panel);
      // Channel headers with VU strips.
      for (let c = 0; c < 4; c++) {
        const x = 3 + c * cw;
        const name = `${c + 1} ${CHANNELS[c]}`.slice(0, cw - 2);
        b.text(x + 1, 1, name, theme.muted);
        const n = (cw - 2) * lv[c];
        for (let i = 0; i < cw - 2; i++) {
          const f = Math.min(1, Math.max(0, n - i));
          b.set(x + 1 + i, 2, f > 0 ? BAR[Math.round(f * 8)] : ' ', i / (cw - 2) < 0.7 ? theme.pos : theme.warn);
        }
      }
      // Pattern body: play row fixed in the middle.
      const mid = 3 + Math.floor(body / 2);
      for (let y = 3; y < 3 + body; y++) {
        const r = s.row + (y - mid);
        if (r < 0 || r >= ROWS) continue;
        const play = y === mid;
        const bg = play ? bar : r % 16 === 0 ? beatRow : undefined;
        if (bg !== undefined) b.fill(0, y, 3 + 4 * cw, 1, ' ', theme.ink, bg);
        b.text(0, y, hex(r), play ? theme.ink : r % 4 === 0 ? theme.warn : theme.muted, bg);
        for (let c = 0; c < 4; c++) {
          const x = 3 + c * cw;
          b.set(x - 1, y, '│', lerpc(theme.bg, theme.line, 0.9), bg);
          const ev = PATTERN[r][c];
          const [nt, ins, ef] = cell(ev);
          const fresh = play && ev && s.frac < 0.5;
          let cx = b.text(x, y, nt, ev ? (fresh ? 0xffffff : theme.ink) : theme.dim, bg);
          cx = b.text(cx, y, ins, ev ? theme.info : theme.dim, bg);
          b.text(cx, y, ef, ev ? theme.accent2 ?? theme.warn : theme.dim, bg);
        }
      }
      b.text(3 + 4 * cw - 1, mid, '◀', theme.accent, bar);
      // Instrument list, with the ones just struck lit up.
      if (side) {
        const sx = W - side + 1;
        b.text(sx, 1, 'INSTRUMENTS', theme.muted);
        const hot = new Set(PATTERN[s.row].filter(Boolean).map((e) => e.inst));
        for (let i = 1; i < INSTRUMENTS.length && 2 + i < H - 1; i++) {
          const on = hot.has(i) && s.frac < 0.6;
          b.text(sx, 2 + i, hex(i), on ? theme.bg : theme.info, on ? theme.accent : undefined);
          b.text(sx + 3, 2 + i, INSTRUMENTS[i].slice(0, side - 5), on ? theme.ink : theme.muted);
        }
        const y0 = 4 + INSTRUMENTS.length;
        if (y0 + 3 < H) {
          b.text(sx, y0, 'BAR', theme.muted);
          b.text(sx + 4, y0, `${s.bar + 1}/4  beat ${(s.beat % 4) + 1}`, theme.ink);
          const chord = ['Am', 'F', 'C', 'G'][s.bar];
          b.text(sx, y0 + 1, 'KEY', theme.muted);
          b.text(sx + 4, y0 + 1, `A minor · ${chord}`, theme.ink);
        }
      }
      // Footer hint.
      b.text(0, H - 1, (W >= 60 ? ' F1 help  F5 play  F8 stop  ←→ channel  ↑↓ row  Space edit' : ' F5 play  F8 stop  Space edit').slice(0, W), theme.dim);
    };
  },
};

sources.prism-term/src/facets/retro/twister.js:
// The Amiga twister: a square column whose rotation angle varies with height,
// drawn scanline by scanline as the visible faces of a spinning prism. Each
// face keeps its own color; brightness follows its apparent width.
import { lerpc, makeStars } from './_kit.js';

export default {
  title: 'Twister',
  gallery: 'retro',
  category: 'Raster & Copper',
  kind: 'scene',
  tags: ['twister', 'amiga', 'raster', 'demoscene', 'column'],
  order: 30,
  description: 'A square column twisting along its height, drawn per scanline from its visible faces — Amiga classic.',
  size: { w: 60, h: 24 },
  minSize: { w: 16, h: 8 },
  loop: 10,
  canvas: 'field',
  palette: 'prism',
  params: {
    twist: { default: 1, min: 0, max: 3, label: 'Twist' },
    speed: { default: 1, min: 0.25, max: 4, label: 'Speed' },
  },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const twist = ctx.param('twist', 1);
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px } = cv;
    const R = Math.min(W * 0.22, H * cv.aspect * 0.5);
    const faces = [pal(0.02), pal(0.27), pal(0.52), pal(0.77)];
    const stars = makeStars(ctx.rng, W, H, Math.round(W * H * 0.01));
    const bg = ctx.theme.bg;
    return (t) => {
      const tt = t * speed;
      px.fill(bg);
      for (const s of stars) cv.set(s[0], (s[1] + tt * (2 + 6 * s[2])) % H, lerpc(bg, ctx.theme.muted, 0.3 + s[2] * 0.6));
      for (let y = 0; y < H; y++) {
        const cx = W / 2 + Math.sin(y * 0.03 + tt * 0.9) * W * 0.12;
        const a = tt * 1.6 + Math.sin(y / H * 3.1 + tt * 0.8) * 2.2 * twist;
        for (let f = 0; f < 4; f++) {
          const x1 = cx + Math.sin(a + (f * Math.PI) / 2) * R;
          const x2 = cx + Math.sin(a + ((f + 1) * Math.PI) / 2) * R;
          if (x2 <= x1) continue;
          const light = 0.35 + 0.65 * ((x2 - x1) / (R * Math.SQRT2));
          for (let x = Math.max(0, Math.floor(x1)); x < Math.min(W, Math.ceil(x2)); x++) {
            const u = (x - x1) / (x2 - x1);
            const edge = u < 0.08 || u > 0.92 ? 0.7 : 1;
            px[y * W + x] = lerpc(0x000000, faces[f], Math.min(1, light) * edge);
          }
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/vector-balls:
// Vector balls: 64 shaded spheres arranged in 3D, morphing cube → sphere →
// torus → helix while the formation tumbles. Painter's-sorted, Phong-lit,
// sized by perspective — the Amiga demo effect that made people buy Amigas.
import { lerpc } from './_kit.js';
import { rotate } from '../../math3d.js';
import { easing } from '../../easing.js';

const N = 64;
function shapes() {
  const cube = [], sphere = [], torus = [], helix = [];
  for (let i = 0; i < N; i++) {
    cube.push([(i % 4) / 1.5 - 1, (Math.floor(i / 4) % 4) / 1.5 - 1, Math.floor(i / 16) / 1.5 - 1]);
    const y = 1 - (i + 0.5) / N * 2, r = Math.sqrt(1 - y * y), th = i * 2.399963;
    sphere.push([Math.cos(th) * r * 1.15, y * 1.15, Math.sin(th) * r * 1.15]);
    const a = (i % 16) / 16 * Math.PI * 2, b = Math.floor(i / 16) / 4 * Math.PI * 2;
    torus.push([(1 + 0.42 * Math.cos(b)) * Math.cos(a), 0.42 * Math.sin(b), (1 + 0.42 * Math.cos(b)) * Math.sin(a)]);
    const k = i / N, s = i % 2 ? Math.PI : 0;
    helix.push([Math.cos(k * Math.PI * 6 + s) * 0.7, k * 2.4 - 1.2, Math.sin(k * Math.PI * 6 + s) * 0.7]);
  }
  return [cube, sphere, torus, helix];
}

export default {
  title: 'Vector Balls',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['vector balls', 'amiga', '3d', 'morph', 'demoscene', 'spheres'],
  order: 40,
  description: '64 Phong-lit spheres morphing cube → sphere → torus → helix while the formation tumbles in 3D.',
  size: { w: 70, h: 24 },
  minSize: { w: 24, h: 8 },
  loop: 16,
  canvas: 'field',
  palette: 'prism',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px, aspect } = cv;
    const forms = shapes();
    const VH = H * aspect, S = Math.min(W, VH) * 0.36, D = 4;
    const ballR = Math.max(1.2, Math.min(W, VH) * 0.045);
    const L = [-0.45, -0.6, 0.66];
    const bg0 = ctx.theme.bg, bg1 = lerpc(ctx.theme.bg, pal(0.7), 0.15);
    const colors = Array.from({ length: N }, (_, i) => pal(i / N));
    return (t) => {
      const tt = t * speed;
      for (let y = 0; y < H; y++) px.fill(lerpc(bg0, bg1, y / H), y * W, (y + 1) * W);
      const seg = (tt / 4) % forms.length, i0 = Math.floor(seg), k = easing.inOutCubic(Math.min(1, (seg - i0) * 1.6));
      const A = forms[i0], B = forms[(i0 + 1) % forms.length];
      const pts = [];
      for (let i = 0; i < N; i++) {
        const p = [A[i][0] + (B[i][0] - A[i][0]) * k, A[i][1] + (B[i][1] - A[i][1]) * k, A[i][2] + (B[i][2] - A[i][2]) * k];
        const [x, y, z] = rotate(p, tt * 0.7, tt * 0.9, tt * 0.31);
        const zz = z + D;
        pts.push({ x: W / 2 + (x * S * D) / zz, y: (VH / 2 + (y * S * D) / zz) / aspect, r: (ballR * D) / zz, z: zz, c: colors[i] });
      }
      pts.sort((a, b) => b.z - a.z);
      for (const b of pts) {
        const ry = b.r / aspect;
        for (let y = Math.floor(b.y - ry); y <= Math.ceil(b.y + ry); y++) {
          if (y < 0 || y >= H) continue;
          for (let x = Math.floor(b.x - b.r); x <= Math.ceil(b.x + b.r); x++) {
            if (x < 0 || x >= W) continue;
            const nx = (x + 0.5 - b.x) / b.r, ny = ((y + 0.5) - b.y) * aspect / b.r;
            const r2 = nx * nx + ny * ny;
            if (r2 > 1) continue;
            const nz = Math.sqrt(1 - r2);
            const diff = Math.max(0, nx * L[0] + ny * L[1] + nz * L[2]);
            const spec = Math.pow(Math.max(0, 2 * diff * nz - L[2]), 18);
            const fog = Math.min(1, (b.z - D + 1.3) / 2.6);
            let c = lerpc(0x000000, b.c, 0.18 + 0.82 * diff);
            c = lerpc(c, 0xffffff, spec * 0.9);
            px[y * W + x] = lerpc(c, bg0, fog * 0.45);
          }
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/vu-meters.js:
// Twin analog VU meters on a backlit amber face, needles riding a little
// chiptune with real VU ballistics (300 ms integration), a red zone past 0 dB,
// peak lamps, and fast LED ladders with peak-hold underneath.
import { lerpc } from './_kit.js';
import { songAt } from './_music.js';

const SCALE = [[-20, 0], [-10, 0.28], [-7, 0.4], [-5, 0.5], [-3, 0.62], [-2, 0.69], [-1, 0.76], [0, 0.83], [1, 0.89], [2, 0.95], [3, 1]];
const pos = (db) => {
  if (db <= SCALE[0][0]) return 0;
  for (let i = 1; i < SCALE.length; i++) if (db <= SCALE[i][0]) {
    const [d0, p0] = SCALE[i - 1], [d1, p1] = SCALE[i];
    return p0 + ((db - d0) / (d1 - d0)) * (p1 - p0);
  }
  return 1;
};
const toDb = (v) => 20 * Math.log10(Math.max(1e-3, v)) + 3;
const lum = (c) => ((c >> 16) & 255) * 0.3 + ((c >> 8) & 255) * 0.59 + (c & 255) * 0.11;
const clamp = (v) => Math.min(1, Math.max(0, v));

function stereo(t) {
  const s = songAt(t), d = Math.max(s.kick, s.snare);
  return [clamp(0.5 * d + 0.34 * s.bass + 0.22 * s.lead + 0.06 * s.hat), clamp(0.5 * d + 0.22 * s.bass + 0.34 * s.lead + 0.18 * s.hat)];
}

export default {
  title: 'VU Meters',
  gallery: 'retro',
  category: 'Chiptune Visuals',
  kind: 'scene',
  tags: ['vu', 'meter', 'audio', 'needle', 'led', 'chiptune', 'hifi'],
  order: 10,
  description: 'Twin analog VU meters on a backlit face — needles with real ballistics, a red zone, peak lamps and LED ladders.',
  size: { w: 64, h: 18 },
  minSize: { w: 24, h: 8 },
  loop: 7.68,
  canvas: 'line',
  setup(ctx) {
    const { theme } = ctx;
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const cv = ctx.canvas('line');
    const ladders = H >= 10 ? 2 : 0;
    const dark = lum(theme.bg) < lum(theme.ink) ? theme.bg : theme.ink;
    const face = lerpc(theme.panel, theme.warn, 0.62), faceHi = lerpc(face, 0xffffff, 0.35);
    const red = lerpc(theme.neg, dark, 0.15);
    const mw = Math.floor(W / 2), mh = H - ladders;
    // Geometry in cell units; a cell is about twice as tall as it is wide.
    // Pivot hides at the bottom of the face; the arc's radius is set by the face
    // height and the sweep narrows to fit the width.
    const top = mh >= 12 ? 2.6 : 1.6;
    const R = Math.max(3, (mh - 0.6 - top) * 2);
    const SPAN = Math.min((50 * Math.PI) / 180, Math.asin(Math.min(1, (mw - 4) / (2 * R * 1.05))));
    const labels = mw >= 26 ? [-20, -10, -5, -3, 0, 3] : mw >= 16 ? [-20, -5, 0, 3] : [-20, 0];
    const meters = [0, 1].map((i) => ({ x0: i * mw, cx: i * mw + mw / 2, cy: mh - 0.6, name: i ? 'R' : 'L' }));
    const at = (m, p, r) => {
      const a = -SPAN + p * 2 * SPAN;
      return [(m.cx + r * Math.sin(a)) * cv.sx, (m.cy - (r * Math.cos(a)) / 2) * cv.sy];
    };
    // VU: 300 ms integration. PPM ladders: instant attack, ~1.2 s fall. Both pure in t.
    const vu = (t) => {
      let l = 0, r = 0, w = 0;
      for (let k = 0; k < 12; k++) {
        const [a, c] = stereo(t - k * 0.025), wk = Math.exp(-k / 4);
        l += a * wk; r += c * wk; w += wk;
      }
      return [l / w, r / w];
    };
    const ppm = (t) => {
      const out = [0, 0], hold = [0, 0];
      for (let k = 0; k < 40; k++) {
        const v = stereo(t - k * 0.03), f = Math.exp(-(k * 0.03) / 0.4);
        for (let c = 0; c < 2; c++) { out[c] = Math.max(out[c], v[c] * f); hold[c] = Math.max(hold[c], v[c]); }
      }
      return [out, hold];
    };
    return (t) => {
      b.fill(0, 0, W, H, ' ', theme.ink, theme.bg);
      cv.clear();
      const lv = vu(t);
      meters.forEach((m, i) => {
        // Backlit face: brighter toward the middle.
        for (let y = 0; y < mh; y++) for (let x = m.x0; x < m.x0 + mw - (i ? 0 : 1); x++) {
          const dx = (x + 0.5 - m.cx) / (mw / 2), dy = (y + 0.5 - mh * 0.55) / (mh / 2);
          b.set(x, y, ' ', dark, lerpc(face, faceHi, clamp(1 - Math.sqrt(dx * dx + dy * dy * 0.6))));
        }
        // Scale arc, red zone and ticks.
        for (let s = 0; s <= 200; s++) {
          const p = s / 200;
          for (const k of p > 0.83 ? [0.84, 0.87, 0.9] : [0.86, 0.875]) {
            const [x, y] = at(m, p, R * k);
            cv.set(x, y, p > 0.83 ? red : dark);
          }
        }
        for (const [db, p] of SCALE) {
          const major = labels.includes(db);
          const [x0, y0] = at(m, p, R * (major ? 0.78 : 0.82)), [x1, y1] = at(m, p, R * 0.94);
          cv.line(x0, y0, x1, y1, db > 0 ? red : dark);
        }
        // Needle.
        const p = pos(toDb(lv[i]));
        const [nx0, ny0] = at(m, p, R * 0.06), [nx1, ny1] = at(m, p, R * 1.0);
        cv.line(nx0, ny0, nx1, ny1, dark);
        cv.line(nx0 + 1, ny0, nx1 + 1, ny1, dark);
        // The pivot cover the needle disappears under.
        cv.ellipse(m.cx * cv.sx, m.cy * cv.sy, R * 0.14 * cv.sx, R * 0.07 * cv.sy, dark, true);
      });
      cv.paint(b);
      meters.forEach((m, i) => {
        // Labels sit just outside the arc; the bg is whatever the face set.
        for (const db of labels) {
          const s = db > 0 ? `+${db}` : String(db);
          const [x, y] = at(m, pos(db), R * 1.13);
          const cx = Math.min(m.x0 + mw - 1 - s.length, Math.max(m.x0, Math.round(x / cv.sx - s.length / 2))), cy = Math.floor(y / cv.sy);
          if (cy >= 0) b.text(cx, cy, s, db > 0 ? red : dark);
        }
        const vy = Math.round(m.cy - R * 0.2);
        if (vy > 0 && vy < mh - 1) b.text(Math.round(m.cx - 1), vy, 'VU', dark);
        b.text(m.x0 + 1, mh - 1, m.name, dark);
        const peak = toDb(stereo(t)[i]) > 1.5;
        if (mw >= 12) b.text(m.x0 + mw - (i ? 3 : 4), 0, 'PK', peak ? 0xffffff : lerpc(face, dark, 0.3), peak ? theme.neg : undefined);
      });
      if (!ladders) return;
      const [level, hold] = ppm(t);
      const segs = Math.max(4, W - 8);
      for (let c = 0; c < 2; c++) {
        const y = mh + c;
        b.text(0, y, c ? 'R' : 'L', theme.muted);
        const lit = Math.round(pos(toDb(level[c])) * segs), hi = Math.round(pos(toDb(hold[c])) * segs) - 1;
        for (let s = 0; s < segs; s++) {
          const f = s / segs;
          const col = f < 0.62 ? theme.pos : f < 0.83 ? theme.warn : theme.neg;
          const on = s < lit || s === hi;
          b.set(2 + s, y, '▌', on ? col : lerpc(theme.bg, col, 0.2));
        }
        const db = Math.round(toDb(level[c]));
        b.text(W - 5, y, `${db > 0 ? '+' : ''}${Math.max(-20, db)}`.padStart(4), theme.muted);
      }
    };
  },
};

sources.prism-term/src/facets/sim/boids.js:
// Boids: Reynolds flocking — separation, alignment, cohesion — plus soft
// walls and a wandering predator that hunts the flock's center while every
// boid within sight scatters. Boids are little oriented arrowheads colored by
// heading, dragging short fading wakes; the predator is larger and red.
import { mix, NONE } from '../../color.js';

export default {
  title: 'Boids',
  gallery: 'sim',
  category: 'Life & Flocking',
  kind: 'scene',
  tags: ['boids', 'flocking', 'birds', 'predator'],
  order: 30,
  description: 'Reynolds flocking (separation, alignment, cohesion) with a hunting predator — oriented arrowheads with fading wakes.',
  canvas: 'line',
  palette: 'candy',
  setup(ctx) {
    const trail = ctx.canvas();
    const view = ctx.canvas();
    const { width: W, height: H, aspect } = view;
    const rand = ctx.rng;
    const pal = ctx.palette();
    const th = ctx.theme;
    const speedK = ctx.param('speed', 1);
    const Hv = H * aspect;
    const S = Math.min(W, Hv);
    const N = Math.max(24, Math.min(240, Math.round((ctx.width * ctx.height) / 14)));
    const maxV = S * 0.34 * speedK, minV = maxV * 0.45;
    const rN = S * 0.11, rS = rN * 0.55, rP = S * 0.24, margin = S * 0.08;
    const X = new Float32Array(N), Y = new Float32Array(N), VX = new Float32Array(N), VY = new Float32Array(N);
    for (let i = 0; i < N; i++) {
      X[i] = W * (0.2 + rand() * 0.6); Y[i] = Hv * (0.2 + rand() * 0.6);
      const a = rand() * Math.PI * 2;
      VX[i] = Math.cos(a) * maxV * 0.7; VY[i] = Math.sin(a) * maxV * 0.7;
    }
    const pred = { x: W * 0.1, y: Hv * 0.5, vx: maxV * 0.6, vy: 0 };
    const size = view.mode === 'braille' ? 3.4 : view.mode === 'ascii' || view.mode === 'half' ? 1.6 : 2.6;
    const bg = ctx.bg === NONE ? 0 : ctx.bg;
    const bgR = (bg >> 16) & 255, bgG = (bg >> 8) & 255, bgB = bg & 255;
    const tp = trail.px;
    const fadeTrail = (k) => {
      for (let i = 0; i < tp.length; i++) {
        const c = tp[i];
        if (c === NONE) continue;
        const r = bgR + (((c >> 16) & 255) - bgR) * k, g = bgG + (((c >> 8) & 255) - bgG) * k, b = bgB + ((c & 255) - bgB) * k;
        tp[i] = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB) < 14 ? NONE : (r << 16) | (g << 8) | (b | 0);
      }
    };
    const arrow = (x, y, vx, vy, len, c) => {
      const v = Math.hypot(vx, vy) || 1, dx = vx / v, dy = vy / v;
      const nose = [x + dx * len, (y + dy * len) / aspect];
      const l = [x - dx * len * 0.6 - dy * len * 0.55, (y - dy * len * 0.6 + dx * len * 0.55) / aspect];
      const r = [x - dx * len * 0.6 + dy * len * 0.55, (y - dy * len * 0.6 - dx * len * 0.55) / aspect];
      const tail = [x - dx * len * 0.25, (y - dy * len * 0.25) / aspect];
      view.polygon([nose, l, tail, r], c);
      view.line(nose[0], nose[1], tail[0], tail[1], c);
    };
    const steer = (vx, vy, tx, ty, w) => [vx + tx * w, vy + ty * w];

    return (t, dt) => {
      fadeTrail(Math.exp(-dt * 3.2));
      // Predator: drift toward the flock's centroid with a noisy wander.
      let mx = 0, my = 0;
      for (let i = 0; i < N; i++) { mx += X[i]; my += Y[i]; }
      mx /= N; my /= N;
      const wa = ctx.noise.noise2(t * 0.25, 3.7) * Math.PI * 2;
      let pax = (mx - pred.x) * 0.9 + Math.cos(wa) * S * 0.6, pay = (my - pred.y) * 0.9 + Math.sin(wa) * S * 0.6;
      pred.vx += pax * dt; pred.vy += pay * dt;
      const pv = Math.hypot(pred.vx, pred.vy), pmax = maxV * 0.82;
      if (pv > pmax) { pred.vx *= pmax / pv; pred.vy *= pmax / pv; }
      const pox = pred.x, poy = pred.y;
      pred.x += pred.vx * dt; pred.y += pred.vy * dt;
      pred.x = Math.min(W - 1, Math.max(0, pred.x)); pred.y = Math.min(Hv - 1, Math.max(0, pred.y));
      if (pred.x <= 0 || pred.x >= W - 1) pred.vx *= -1;
      if (pred.y <= 0 || pred.y >= Hv - 1) pred.vy *= -1;

      for (let i = 0; i < N; i++) {
        let sx = 0, sy = 0, ax = 0, ay = 0, cx = 0, cy = 0, n = 0;
        const xi = X[i], yi = Y[i];
        for (let j = 0; j < N; j++) {
          if (j === i) continue;
          const dx = X[j] - xi, dy = Y[j] - yi;
          const d2 = dx * dx + dy * dy;
          if (d2 > rN * rN) continue;
          n++;
          ax += VX[j]; ay += VY[j]; cx += X[j]; cy += Y[j];
          if (d2 < rS * rS) { const d = Math.sqrt(d2) || 0.01; sx -= dx / d * (rS - d); sy -= dy / d * (rS - d); }
        }
        let vx = VX[i], vy = VY[i];
        if (n) {
          [vx, vy] = steer(vx, vy, ax / n - vx, ay / n - vy, 1.1 * dt);
          [vx, vy] = steer(vx, vy, cx / n - xi, cy / n - yi, 0.55 * dt);
        }
        [vx, vy] = steer(vx, vy, sx, sy, 7 * dt);
        const pdx = xi - pred.x, pdy = yi - pred.y, pd = Math.hypot(pdx, pdy);
        if (pd < rP) [vx, vy] = steer(vx, vy, (pdx / (pd || 1)) * maxV, (pdy / (pd || 1)) * maxV, 4 * (1 - pd / rP) * dt);
        // Soft walls.
        if (xi < margin) vx += maxV * 2.5 * dt; else if (xi > W - margin) vx -= maxV * 2.5 * dt;
        if (yi < margin) vy += maxV * 2.5 * dt; else if (yi > Hv - margin) vy -= maxV * 2.5 * dt;
        const v = Math.hypot(vx, vy) || 1;
        const cl = v > maxV ? maxV / v : v < minV ? minV / v : 1;
        VX[i] = vx * cl; VY[i] = vy * cl;
      }

      view.clear();
      for (let i = 0; i < N; i++) {
        const ox = X[i], oy = Y[i];
        X[i] = Math.min(W - 0.5, Math.max(0, X[i] + VX[i] * dt));
        Y[i] = Math.min(Hv - 0.5, Math.max(0, Y[i] + VY[i] * dt));
        const hue = Math.atan2(VY[i], VX[i]) / (Math.PI * 2) + 0.5;
        trail.line(ox, oy / aspect, X[i], Y[i] / aspect, mix(bg, pal(hue), 0.45));
      }
      trail.line(pox, poy / aspect, pred.x, pred.y / aspect, mix(bg, th.neg, 0.6));
      view.px.set(tp);
      for (let i = 0; i < N; i++) arrow(X[i], Y[i], VX[i], VY[i], size, pal(Math.atan2(VY[i], VX[i]) / (Math.PI * 2) + 0.5));
      arrow(pred.x, pred.y, pred.vx, pred.vy, size * 2.1, th.neg);
      view.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/bouncing-balls:
// Billiard-ball physics under gravity: balls of different sizes (mass goes
// with area) collide elastically with each other and the walls, integrated at
// a fixed 240 Hz so it never tunnels or explodes. Every few seconds the floor
// "pops" and throws whatever is resting on it back into the air. Lit spheres,
// soft floor shadows that tighten as a ball lands, and a flash on hard hits.
import { sphere, blend } from '../objects/_raster.js';
import { NONE } from '../../color.js';

const HZ = 240, KICK = 4.5;

export default {
  title: 'Bouncing Balls',
  gallery: 'sim',
  category: 'Physics',
  kind: 'scene',
  tags: ['physics', 'collision', 'elastic', 'balls', 'gravity', 'billiards'],
  order: 10,
  description: 'Balls of different masses colliding elastically under gravity at a fixed 240 Hz step, with shadows and impact flashes.',
  size: { w: 60, h: 22 },
  minSize: { w: 20, h: 7 },
  loop: KICK * 4,
  canvas: 'field',
  palette: 'prism',
  params: { balls: { default: 9, min: 2, max: 24, label: 'Balls' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const W = cv.width, H = cv.height, asp = cv.aspect, th = ctx.theme, rand = ctx.rng;
    const HP = H * asp; // world height in horizontal-pixel units
    const pal = ctx.palette();
    const n = Math.round(ctx.param('balls', 9));
    const unit = Math.min(W, HP);
    const G = HP * 2.2, FLOOR = HP - 1;
    const balls = [];
    for (let i = 0; i < n; i++) {
      const r = unit * (0.05 + rand() * 0.05);
      let x, y, tries = 0;
      do { x = r + rand() * (W - 2 * r); y = r + rand() * (FLOOR * 0.6 - r); tries++; } while (tries < 40 && balls.some((b) => Math.hypot(b.x - x, b.y - y) < b.r + r + 0.5));
      balls.push({ x, y, vx: (rand() - 0.5) * W * 0.9, vy: (rand() - 0.5) * HP * 0.4, r, m: r * r, c: pal(i / n), flash: 0 });
    }
    let acc = 0, kicks = 0;

    const step = (h) => {
      for (const b of balls) {
        b.vy += G * h;
        b.x += b.vx * h; b.y += b.vy * h;
        if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx) * 0.95; }
        if (b.x > W - b.r) { b.x = W - b.r; b.vx = -Math.abs(b.vx) * 0.95; }
        if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy) * 0.95; }
        if (b.y > FLOOR - b.r) {
          if (b.vy > HP * 0.9) b.flash = Math.max(b.flash, Math.min(1, b.vy / (HP * 3)));
          b.y = FLOOR - b.r; b.vy = -Math.abs(b.vy) * 0.86; b.vx *= 0.995;
        }
      }
      for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
        const a = balls[i], b = balls[j];
        const dx = b.x - a.x, dy = b.y - a.y, d = Math.hypot(dx, dy), min = a.r + b.r;
        if (d >= min || d === 0) continue;
        const nx = dx / d, ny = dy / d;
        // Push apart in proportion to inverse mass, then exchange impulse along the normal.
        const over = min - d, ia = 1 / a.m, ib = 1 / b.m, sum = ia + ib;
        a.x -= nx * over * (ia / sum); a.y -= ny * over * (ia / sum);
        b.x += nx * over * (ib / sum); b.y += ny * over * (ib / sum);
        const vn = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;
        if (vn >= 0) continue;
        const jimp = (-(1 + 0.97) * vn) / sum;
        a.vx -= jimp * ia * nx; a.vy -= jimp * ia * ny;
        b.vx += jimp * ib * nx; b.vy += jimp * ib * ny;
        const hit = Math.min(1, -vn / (unit * 2.5));
        if (hit > 0.25) { a.flash = Math.max(a.flash, hit); b.flash = Math.max(b.flash, hit); }
      }
    };

    return (t, dt) => {
      // The floor pops every KICK seconds, flinging resting balls back up.
      while (t >= (kicks + 1) * KICK) {
        kicks++;
        for (const b of balls) if (b.y > FLOOR - b.r - unit * 0.2) { b.vy = -HP * (1.6 + rand() * 0.9); b.vx += (rand() - 0.5) * W * 0.6; }
      }
      acc += Math.min(0.25, Math.max(0, dt)) * HZ;
      for (; acc >= 1; acc--) step(1 / HZ);
      for (const b of balls) b.flash *= Math.pow(0.02, Math.min(0.25, dt));

      cv.clear();
      const floorRow = Math.floor(FLOOR / asp);
      for (let x = 0; x < W; x++) cv.set(x, floorRow, blend(th.bg, th.line, 0.9));
      // Shadows: wider and fainter the higher the ball.
      for (const b of balls) {
        const hgt = Math.max(0, FLOOR - b.r - b.y) / HP;
        const sw = b.r * (1 + hgt * 1.5), k = 0.45 * (1 - Math.min(0.85, hgt * 1.3));
        for (let x = Math.floor(b.x - sw); x <= Math.ceil(b.x + sw); x++) {
          const f = 1 - Math.abs(x + 0.5 - b.x) / sw;
          if (f <= 0) continue;
          const y = floorRow - 1, old = cv.get(x, y);
          cv.set(x, y, blend(old === NONE ? th.bg : old, 0x000000, k * f));
        }
      }
      // Balls, far-to-near isn't needed in 2D; small ones last so they stay visible.
      const order = balls.slice().sort((a, b) => b.r - a.r);
      for (const b of order) {
        sphere(cv, null, b.x, b.y / asp, b.r, 0, (nx, ny, nz) => {
          const dif = Math.max(0, -nx * 0.45 - ny * 0.62 - nz * 0.64);
          const spec = Math.pow(Math.max(0, -nx * 0.3 - ny * 0.5 - nz * 0.81), 30);
          let c = blend(blend(0x000000, b.c, 0.3 + 0.7 * dif), 0xffffff, spec * 0.85);
          if (b.flash > 0.02) c = blend(c, 0xffffff, b.flash * 0.6 * (1 + nz));
          return c;
        });
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/brians-brain.j:
// Brian's Brain: a three-state automaton (ready → firing → refractory → ready)
// where a ready cell fires when exactly two neighbors are firing. Almost any
// seed boils into a sea of colliding "spaceships". Firing cells burn white-hot,
// refractory cells glow in the accent, and a short afterglow traces where the
// ships have been. Re-seeds itself if activity ever dies down.
import { NONE, mix } from '../../color.js';

export default {
  title: "Brian's Brain",
  gallery: 'sim',
  category: 'Cellular Automata',
  kind: 'scene',
  tags: ['brians brain', 'cellular automata', 'three-state', 'spaceships', 'chaos'],
  order: 40,
  description: "Brian's Brain: a three-state automaton where nearly any seed boils into colliding spaceships with glowing wakes.",
  size: { w: 60, h: 22 },
  minSize: { w: 20, h: 7 },
  loop: 10,
  canvas: 'field',
  palette: 'theme',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const W = cv.width, H = cv.height, px = cv.px, th = ctx.theme, rand = ctx.rng;
    const gps = 12 * ctx.param('speed', 1);
    const N = W * H;
    let cur = new Uint8Array(N), nxt = new Uint8Array(N); // 0 ready, 1 firing, 2 refractory
    const glow = new Float32Array(N);
    const xm = new Int32Array(W), xp = new Int32Array(W);
    for (let x = 0; x < W; x++) { xm[x] = (x - 1 + W) % W; xp[x] = (x + 1) % W; }
    const seed = () => {
      // A few dense blobs rather than uniform noise: they burst outward as ship swarms.
      for (let k = 0; k < 3 + Math.floor(rand() * 3); k++) {
        const cx = rand() * W, cy = rand() * H, r = Math.max(3, Math.min(W, H) * (0.12 + rand() * 0.1));
        for (let y = Math.floor(cy - r); y <= cy + r; y++) for (let x = Math.floor(cx - r); x <= cx + r; x++) {
          if (Math.hypot(x - cx, y - cy) > r || rand() > 0.35) continue;
          cur[(((y % H) + H) % H) * W + (((x % W) + W) % W)] = 1;
        }
      }
    };
    seed();
    const fire = mix(0xffffff, th.info, 0.15), refr = mix(th.bg, th.accent, 0.75), trail = th.info;
    let acc = 0;
    const step = () => {
      let live = 0;
      for (let y = 0; y < H; y++) {
        const r0 = ((y - 1 + H) % H) * W, r1 = y * W, r2 = ((y + 1) % H) * W;
        for (let x = 0; x < W; x++) {
          const i = r1 + x, s = cur[i];
          if (s === 1) { nxt[i] = 2; continue; }
          if (s === 2) { nxt[i] = 0; continue; }
          const a = xm[x], b = xp[x];
          const n = (cur[r0 + a] === 1) + (cur[r0 + x] === 1) + (cur[r0 + b] === 1) + (cur[r1 + a] === 1) + (cur[r1 + b] === 1) + (cur[r2 + a] === 1) + (cur[r2 + x] === 1) + (cur[r2 + b] === 1);
          if (n === 2) { nxt[i] = 1; live++; } else nxt[i] = 0;
        }
      }
      [cur, nxt] = [nxt, cur];
      for (let i = 0; i < N; i++) glow[i] = cur[i] === 1 ? 1 : glow[i] * 0.72;
      if (live < N * 0.004) seed();
    };

    return (t, dt) => {
      acc += Math.min(0.25, Math.max(0, dt)) * gps;
      for (let k = 0; acc >= 1 && k < 6; k++, acc--) step();
      if (acc > 6) acc = 0;
      for (let i = 0; i < N; i++) {
        const s = cur[i];
        if (s === 1) px[i] = fire;
        else if (s === 2) px[i] = refr;
        else px[i] = glow[i] > 0.06 ? mix(th.bg, trail, glow[i] * 0.45) : NONE;
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/double-pendulu:
// Sensitive dependence, made visible: three double pendulums released from
// starting angles a thousandth of a radian apart, integrated with RK4 at
// 480 Hz. For a few seconds they move as one; then the trails split and they
// go their own chaotic ways. Each run restarts from the same three starts.
import { mix } from '../../color.js';

const RUN = 20, HZ = 480, G = 9.81;
const TRAIL = 260; // trail samples kept per pendulum (recorded at 60 Hz)

function deriv(s) {
  const [t1, w1, t2, w2] = s;
  const d = t1 - t2, den = 3 - Math.cos(2 * d); // m1 = m2 = 1, L1 = L2 = 1
  const a1 = (-G * 3 * Math.sin(t1) - G * Math.sin(t1 - 2 * t2) - 2 * Math.sin(d) * (w2 * w2 + w1 * w1 * Math.cos(d))) / den;
  const a2 = (2 * Math.sin(d) * (w1 * w1 * 2 + G * 2 * Math.cos(t1) + w2 * w2 * Math.cos(d))) / den;
  return [w1, a1, w2, a2];
}
function rk4(s, h) {
  const k1 = deriv(s);
  const k2 = deriv(s.map((v, i) => v + (h / 2) * k1[i]));
  const k3 = deriv(s.map((v, i) => v + (h / 2) * k2[i]));
  const k4 = deriv(s.map((v, i) => v + h * k3[i]));
  return s.map((v, i) => v + (h / 6) * (k1[i] + 2 * k2[i] + 2 * k3[i] + k4[i]));
}

export default {
  title: 'Double Pendulum',
  gallery: 'sim',
  category: 'Physics',
  kind: 'scene',
  tags: ['pendulum', 'chaos', 'rk4', 'butterfly effect', 'trails', 'braille'],
  order: 20,
  description: 'Three double pendulums started a thousandth of a radian apart — together at first, then chaos splits their trails.',
  size: { w: 48, h: 24 },
  minSize: { w: 16, h: 8 },
  loop: RUN,
  canvas: 'line',
  palette: 'prism',
  params: { pendulums: { default: 3, min: 1, max: 6, label: 'Pendulums' } },
  setup(ctx) {
    const cv = ctx.canvas('line');
    const W = cv.width, H = cv.height, asp = cv.aspect, th = ctx.theme;
    const pal = ctx.palette();
    const count = Math.round(ctx.param('pendulums', 3));
    const L = Math.min(W / 2, (H * asp) / 2) * 0.47; // arm length in pixels
    const ox = W / 2, oy = (H * asp) / 2;
    const cols = Array.from({ length: count }, (_, i) => mix(pal(i / count), th.ink, 0.15));
    const fresh = () => Array.from({ length: count }, (_, i) => ({ s: [2.3 + i * 0.001, 0, 2.6, 0], trail: [] }));
    let ps = fresh(), run = 0, acc = 0, rec = 0;
    const tip = (s) => {
      const x1 = ox + Math.sin(s[0]) * L, y1 = oy + Math.cos(s[0]) * L;
      return [x1, y1, x1 + Math.sin(s[2]) * L, y1 + Math.cos(s[2]) * L];
    };

    return (t, dt) => {
      const r = Math.floor(t / RUN);
      if (r !== run) { run = r; ps = fresh(); acc = 0; }
      acc += Math.min(0.25, Math.max(0, dt)) * HZ;
      for (; acc >= 1; acc--) {
        for (const p of ps) p.s = rk4(p.s, 1 / HZ);
        if (++rec % (HZ / 60) === 0) for (const p of ps) { p.trail.push(tip(p.s).slice(2)); if (p.trail.length > TRAIL) p.trail.shift(); }
      }
      cv.clear();
      // Trails, oldest (faintest) first; later pendulums drawn over earlier ones.
      ps.forEach((p, k) => {
        const tr = p.trail;
        for (let i = 1; i < tr.length; i++) {
          const f = i / tr.length;
          cv.line(tr[i - 1][0], tr[i - 1][1] / asp, tr[i][0], tr[i][1] / asp, mix(th.bg, cols[k], 0.2 + 0.8 * Math.pow(f, 1.4)));
        }
      });
      // Arms and bobs.
      ps.forEach((p, k) => {
        const [x1, y1, x2, y2] = tip(p.s);
        cv.line(ox, oy / asp, x1, y1 / asp, th.muted);
        cv.line(x1, y1 / asp, x2, y2 / asp, th.muted);
        cv.circle(x1, y1 / asp, Math.max(1, L * 0.06), th.ink, true);
        cv.circle(x2, y2 / asp, Math.max(1, L * 0.08), cols[k], true);
      });
      cv.circle(ox, oy / asp, Math.max(1, L * 0.04), th.ink, true);
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/falling-sand.j:
// A falling-sand automaton like the old sand-art toys: three spouts sweep back
// and forth pouring grains whose hue drifts slowly, so the pile builds up in
// colored strata over sloped ledges. Grains fall, then slide diagonally when
// blocked (never squeezing between two diagonal walls). Every cycle a trapdoor
// opens, the whole pile drains out through the floor, and pouring starts again.
import { NONE, mix } from '../../color.js';

const CYCLE = 24, DRAIN = 6;

export default {
  title: 'Falling Sand',
  gallery: 'sim',
  category: 'Particles',
  kind: 'scene',
  tags: ['sand', 'falling sand', 'automaton', 'granular', 'pile', 'sand art'],
  order: 20,
  description: 'Sweeping spouts pour color-drifting grains that pile into strata over ledges, then drain through a trapdoor.',
  size: { w: 60, h: 22 },
  minSize: { w: 20, h: 8 },
  loop: CYCLE,
  canvas: 'field',
  palette: 'prism',
  params: { rate: { default: 1, min: 0.2, max: 3, label: 'Pour rate' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const W = cv.width, H = cv.height, px = cv.px, th = ctx.theme;
    const rand = ctx.rng, pal = ctx.palette();
    const rate = ctx.param('rate', 1);
    const EMPTY = 0, SAND = 1, WALL = 2;
    const grid = new Uint8Array(W * H), col = new Int32Array(W * H);
    const wallC = th.muted, wallTop = th.ink;
    // Ledges: sloped shelves alternating sides, each stopping short of the far wall.
    const ledge = (x0, y0, x1, y1) => {
      const n = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0));
      for (let s = 0; s <= n; s++) {
        const x = Math.round(x0 + ((x1 - x0) * s) / n), y = Math.round(y0 + ((y1 - y0) * s) / n);
        if (x >= 0 && x < W && y >= 0 && y < H) grid[y * W + x] = WALL;
      }
    };
    const build = () => {
      grid.fill(EMPTY);
      const rows = H >= 24 ? 3 : H >= 14 ? 2 : 1;
      for (let k = 0; k < rows; k++) {
        const y = Math.round(H * (rows === 1 ? 0.5 : 0.3 + (0.42 * k) / (rows - 1)));
        const left = k % 2 === 0, len = Math.round(W * (0.38 + rand() * 0.08)), drop = Math.max(1, Math.round(len * 0.22));
        if (left) ledge(Math.round(W * 0.06), y - drop, Math.round(W * 0.06) + len, y);
        else ledge(W - 1 - Math.round(W * 0.06), y - drop, W - 1 - Math.round(W * 0.06) - len, y);
      }
    };
    build();
    const spouts = [0.2, 0.5, 0.8].map((f, i) => ({ f, ph: rand() * 6.28, sp: 0.25 + rand() * 0.2, hue: i / 3 }));
    let acc = 0, steps = 0, lastCycle = 0;

    const step = (t, draining) => {
      // Bottom-up so a grain moves at most once per step; alternate the scan
      // direction per row and per step so piles don't lean one way.
      const gate0 = Math.floor(W * 0.4), gate1 = Math.ceil(W * 0.6);
      if (draining) for (let x = gate0; x < gate1; x++) { const i = (H - 1) * W + x; if (grid[i] === SAND) grid[i] = EMPTY; }
      for (let y = H - 2; y >= 0; y--) {
        const rtl = (y + steps) & 1;
        for (let k = 0; k < W; k++) {
          const x = rtl ? W - 1 - k : k, i = y * W + x;
          if (grid[i] !== SAND) continue;
          const d = i + W;
          if (grid[d] === EMPTY) { grid[d] = SAND; col[d] = col[i]; grid[i] = EMPTY; continue; }
          const first = rand() < 0.5 ? -1 : 1;
          for (const s of [first, -first]) {
            const nx = x + s;
            if (nx < 0 || nx >= W) continue;
            if (grid[d + s] === EMPTY && grid[i + s] === EMPTY) { grid[d + s] = SAND; col[d + s] = col[i]; grid[i] = EMPTY; break; }
          }
        }
      }
      if (!draining) {
        for (const s of spouts) {
          const x = Math.round((s.f + Math.sin(t * s.sp + s.ph) * 0.12) * (W - 1));
          if (rand() > 0.55 * rate || x < 0 || x >= W || grid[x] !== EMPTY) continue;
          grid[x] = SAND;
          const hue = (s.hue + t * 0.021) % 1;
          col[x] = mix(pal(hue + (rand() - 0.5) * 0.03), 0xd9b77a, 0.3 + rand() * 0.12);
        }
      }
      steps++;
    };

    return (t, dt) => {
      const c = Math.floor(t / CYCLE);
      if (c !== lastCycle) { lastCycle = c; build(); }
      const local = t - c * CYCLE, draining = local > CYCLE - DRAIN;
      acc += dt * 60;
      for (let k = 0; acc >= 1 && k < 10; k++, acc--) step(t, draining);
      if (acc > 10) acc = 0;
      for (let i = 0; i < W * H; i++) {
        const g = grid[i];
        if (g === EMPTY) px[i] = NONE;
        else if (g === WALL) px[i] = i >= W && grid[i - W] !== WALL ? wallTop : wallC;
        else {
          // Surface grains catch the light; buried ones sit a touch darker.
          const top = i < W || grid[i - W] === EMPTY;
          const c0 = col[i];
          const k = top ? 1.12 : 0.92;
          px[i] = (Math.min(255, ((c0 >> 16) & 255) * k) << 16) | (Math.min(255, ((c0 >> 8) & 255) * k) << 8) | Math.min(255, (c0 & 255) * k);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/fireworks.js:
// Fireworks: rockets climb on sparkling trails and burst into one of four shell
// types — peony (sphere), ring, willow, crackle — whose sparks fly under
// gravity and drag, cool from white-hot to ember, and leave glowing trails
// (additive plotting on a persistent, fading canvas). The lower band of the
// sky is mirrored into a rippling lake.
import { mix, NONE } from '../../color.js';

const WHITE = 0xffffff, EMBER = 0x6a1606, GOLD = 0xffc35a;

export default {
  title: 'Fireworks',
  gallery: 'sim',
  category: 'Particles',
  kind: 'scene',
  tags: ['fireworks', 'particles', 'celebration', 'glow'],
  order: 30,
  description: 'Rockets and four shell types (peony, ring, willow, crackle) with gravity, drag, additive glow trails and a lake reflection.',
  canvas: 'line',
  palette: 'prism',
  setup(ctx) {
    const cv = ctx.canvas();
    const { width: W, height: H, aspect, px } = cv;
    const rand = ctx.rng;
    const pal = ctx.palette();
    const reflect = ctx.param('reflect', true) && H >= 16;
    const Hv = H * aspect; // vertical extent in horizontal-pixel units (keeps bursts round)
    const S = Math.min(W, Hv);
    const g = S * 0.42;
    const groundRow = reflect ? Math.floor(H * 0.84) : H;
    const ground = groundRow * aspect;
    const maxSparks = Math.max(400, Math.min(6000, Math.round(W * H * 0.08)));
    const rockets = [], sparks = [];
    let next = 0.2;

    const addLine = (x0, y0, x1, y1, c) => {
      const n = Math.min(64, Math.max(1, Math.ceil(Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0)))));
      for (let s = 1; s <= n; s++) cv.add(x0 + ((x1 - x0) * s) / n, y0 + ((y1 - y0) * s) / n, c);
    };
    const dim = (c, k) => ((((c >> 16) & 255) * k) << 16) | ((((c >> 8) & 255) * k) << 8) | (((c & 255) * k) | 0);
    const spark = (o) => { if (sparks.length < maxSparks) sparks.push(o); };

    const launch = () => {
      const x = W * (0.12 + 0.76 * rand());
      const apex = Hv * (0.1 + 0.32 * rand());
      rockets.push({
        x, y: ground, vx: (rand() - 0.5) * S * 0.12,
        vy: -Math.sqrt(2 * g * (ground - apex)),
        color: pal(rand()), type: rand(),
      });
    };

    const explode = (r) => {
      const c2 = rand() < 0.3 ? pal(rand()) : r.color;
      const base = { x: r.x, y: r.y, crackle: false, gf: 1 };
      if (r.type < 0.38) { // peony: sphere projected to the screen
        const n = 110 + Math.floor(rand() * 70), s = S * (0.7 + rand() * 0.3);
        for (let i = 0; i < n; i++) {
          const z = rand() * 2 - 1, a = rand() * Math.PI * 2, q = Math.sqrt(1 - z * z);
          const k = s * (0.92 + rand() * 0.16);
          const life = 1.2 + rand() * 0.6;
          spark({ ...base, vx: Math.cos(a) * q * k, vy: Math.sin(a) * q * k, life, max: life, drag: 1.7, color: i % 2 ? r.color : c2 });
        }
      } else if (r.type < 0.6) { // ring, tilted and rotated
        const n = 48 + Math.floor(rand() * 18), s = S * (0.72 + rand() * 0.2);
        const tilt = 0.3 + rand() * 0.7, rot = rand() * Math.PI;
        for (let i = 0; i < n; i++) {
          const a = (i / n) * Math.PI * 2, ex = Math.cos(a), ey = Math.sin(a) * tilt;
          const vx = (ex * Math.cos(rot) - ey * Math.sin(rot)) * s, vy = (ex * Math.sin(rot) + ey * Math.cos(rot)) * s;
          spark({ ...base, vx, vy, life: 1.4, max: 1.4, drag: 1.5, color: r.color });
        }
        for (let i = 0; i < 18; i++) { // a small core
          const a = rand() * Math.PI * 2, k = s * 0.25 * rand();
          spark({ ...base, vx: Math.cos(a) * k, vy: Math.sin(a) * k, life: 0.9, max: 0.9, drag: 2, color: c2 });
        }
      } else if (r.type < 0.8) { // willow: slow, heavy drag, long golden fall
        const n = 110 + Math.floor(rand() * 40), s = S * (0.55 + rand() * 0.15);
        for (let i = 0; i < n; i++) {
          const a = rand() * Math.PI * 2, k = s * Math.sqrt(rand());
          const life = 2.6 + rand() * 1.2;
          spark({ ...base, vx: Math.cos(a) * k, vy: Math.sin(a) * k - s * 0.1, life, max: life, drag: 2.6, gf: 0.55, color: GOLD, trail: [] });
        }
      } else { // crackle: a sphere whose sparks split into flickering white glitter
        const n = 80 + Math.floor(rand() * 30), s = S * (0.65 + rand() * 0.2);
        for (let i = 0; i < n; i++) {
          const z = rand() * 2 - 1, a = rand() * Math.PI * 2, q = Math.sqrt(1 - z * z);
          const life = 0.8 + rand() * 0.4;
          spark({ ...base, vx: Math.cos(a) * q * s, vy: Math.sin(a) * q * s, life, max: life, drag: 1.8, color: r.color, crackle: true });
        }
      }
    };

    return (t, dt) => {
      cv.fade(Math.exp(-dt * 11));
      // Clear the lake band; it is rebuilt from the sky every frame.
      if (reflect) px.fill(NONE, groundRow * W);

      if (t >= next) {
        launch();
        if (rand() < 0.18) { launch(); launch(); }
        next = t + 0.35 + rand() * 1.1;
      }

      for (let i = rockets.length - 1; i >= 0; i--) {
        const r = rockets[i];
        const ox = r.x, oy = r.y;
        r.vy += g * dt; r.x += r.vx * dt; r.y += r.vy * dt;
        addLine(ox, oy / aspect, r.x, r.y / aspect, 0xffd9a0);
        if (rand() < 0.6) spark({ x: r.x, y: r.y, vx: (rand() - 0.5) * S * 0.05, vy: S * 0.05 * rand(), life: 0.35, max: 0.35, drag: 3, gf: 0.3, color: 0xffa94d, crackle: false });
        if (r.vy > -S * 0.04) { explode(r); rockets.splice(i, 1); }
      }

      for (let i = sparks.length - 1; i >= 0; i--) {
        const p = sparks[i];
        const ox = p.x, oy = p.y;
        const d = Math.exp(-p.drag * dt);
        p.vx *= d; p.vy = p.vy * d + g * p.gf * dt;
        p.x += p.vx * dt; p.y += p.vy * dt;
        p.life -= dt;
        if (p.life <= 0 || p.y > ground || p.x < -4 || p.x > W + 4) {
          if (p.crackle && p.life <= 0) {
            for (let k = 0; k < 4; k++) {
              const a = rand() * Math.PI * 2, s = S * 0.08 * rand();
              spark({ x: p.x, y: p.y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, life: 0.3, max: 0.3, drag: 4, gf: 0.2, color: WHITE, crackle: false, flicker: true });
            }
          }
          sparks.splice(i, 1);
          continue;
        }
        if (p.flicker && rand() < 0.45) continue;
        const age = 1 - p.life / p.max;
        let c = age < 0.12 ? mix(WHITE, p.color, age / 0.12) : age > 0.65 ? mix(p.color, EMBER, (age - 0.65) / 0.35) : p.color;
        c = dim(c, Math.pow(p.life / p.max, 0.6) * 0.85 + 0.15);
        addLine(ox, oy / aspect, p.x, p.y / aspect, c);
        if (p.trail) {
          // Willow sparks drag a long fading tail of their own recent positions.
          p.trail.push(p.x, p.y);
          if (p.trail.length > 28) p.trail.splice(0, 2);
          const n = p.trail.length / 2;
          for (let k = 1; k < n; k++) {
            const tk = dim(c, (k / n) * 0.55);
            addLine(p.trail[2 * k - 2], p.trail[2 * k - 1] / aspect, p.trail[2 * k], p.trail[2 * k + 1] / aspect, tk);
          }
        }
      }

      if (reflect) {
        // Mirror the whole sky into the lake band, squashed vertically and rippled.
        // Each lake row samples a slab of sky rows and keeps the brightest pixel
        // so single sparks survive the squash.
        const rows = H - groundRow, step = groundRow / rows;
        for (let y = groundRow; y < H; y++) {
          const d = (y - groundRow + 0.5) / rows;
          const s0 = Math.max(0, Math.floor(groundRow - (d + 0.5 / rows) * groundRow));
          const s1 = Math.min(groundRow - 1, Math.ceil(s0 + step));
          const k = 0.42 * (1 - d * 0.55);
          const shift = Math.round(Math.sin(y * 1.9 + t * 2.6) * (1 + d * 2.5));
          for (let x = 0; x < W; x++) {
            const sx = (x + shift + W) % W;
            let best = NONE, bl = -1;
            for (let sy = s0; sy <= s1; sy++) {
              const c = px[sy * W + sx];
              if (c === NONE) continue;
              const l = ((c >> 16) & 255) + ((c >> 8) & 255) + (c & 255);
              if (l > bl) { bl = l; best = c; }
            }
            px[y * W + x] = best === NONE ? NONE : dim(best, k);
          }
        }
        // A faint dashed shoreline.
        const shore = mix(ctx.theme.line, ctx.theme.muted, 0.5);
        for (let x = 0; x < W; x += 3) if (px[groundRow * W + x] === NONE) px[groundRow * W + x] = shore;
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/flowfield.js:
// Flow field: particles drift through a slowly evolving curl-noise field (the
// curl of a Perlin potential is divergence-free, so streams swirl without
// collapsing into sinks), painting silky braille trails on a persistent canvas
// that fades toward the background. Hue follows heading, brightness speed.
import { NONE } from '../../color.js';
export default {
  title: 'Flow Field',
  gallery: 'sim',
  category: 'Particles',
  kind: 'scene',
  tags: ['flow field', 'particles', 'noise', 'trails'],
  order: 50,
  description: 'Particles advected through an evolving curl-noise flow field, leaving fading silk trails colored by heading.',
  canvas: 'line',
  palette: 'prism',
  setup(ctx) {
    const cv = ctx.canvas();
    const { width: W, height: H, aspect } = cv;
    const rand = ctx.rng;
    const pal = ctx.palette();
    const { noise3 } = ctx.noise;
    const speedK = ctx.param('speed', 1);
    const Hv = H * aspect;
    const sc = 2.6 / Math.max(W, Hv);
    const spd = Math.min(W, Hv) * 0.16 * speedK;
    const N = Math.max(150, Math.min(2600, Math.round(W * H * 0.012)));
    const X = new Float32Array(N), Y = new Float32Array(N), A = new Float32Array(N), L = new Float32Array(N);
    const spawn = (i) => { X[i] = rand() * W; Y[i] = rand() * Hv; A[i] = 0; L[i] = 2 + rand() * 5; };
    for (let i = 0; i < N; i++) { spawn(i); A[i] = rand() * L[i]; }

    const bg = ctx.bg === NONE ? 0 : ctx.bg;
    const bgR = (bg >> 16) & 255, bgG = (bg >> 8) & 255, bgB = bg & 255;
    const px = cv.px;
    // Fade toward the background color (not black) so old trails never read as
    // dark smudges; pixels that reach the background become transparent again.
    const fade = (k) => {
      for (let i = 0; i < px.length; i++) {
        const c = px[i];
        if (c === NONE) continue;
        const r = bgR + (((c >> 16) & 255) - bgR) * k, g = bgG + (((c >> 8) & 255) - bgG) * k, b = bgB + ((c & 255) - bgB) * k;
        px[i] = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB) < 12 ? NONE : (r << 16) | (g << 8) | (b | 0);
      }
    };
    const e = 0.75; // finite-difference step, in noise space units ÷ sc
    return (t, dt) => {
      fade(Math.exp(-dt * 1.5));
      const z = t * 0.07;
      for (let i = 0; i < N; i++) {
        const x0 = X[i], y0 = Y[i];
        const nx = x0 * sc, ny = y0 * sc;
        // Curl of the potential ψ: v = (∂ψ/∂y, −∂ψ/∂x).
        const dpy = noise3(nx, ny + e * sc, z) - noise3(nx, ny - e * sc, z);
        const dpx = noise3(nx + e * sc, ny, z) - noise3(nx - e * sc, ny, z);
        let vx = dpy / (2 * e * sc), vy = -dpx / (2 * e * sc);
        const m = Math.hypot(vx, vy) || 1e-6;
        const sp = Math.min(1.6, 0.35 + m * 0.6);
        vx = (vx / m) * sp; vy = (vy / m) * sp;
        X[i] += vx * spd * dt;
        Y[i] += vy * spd * dt;
        A[i] += dt;
        // Fade in on spawn and out at end of life so respawns never pop.
        const life = Math.min(1, A[i] / 0.6, (L[i] - A[i]) / 0.6);
        if (life <= 0 || X[i] < 0 || X[i] >= W || Y[i] < 0 || Y[i] >= Hv) { spawn(i); continue; }
        const hue = Math.atan2(vy, vx) / (Math.PI * 2) + 0.5;
        const c = pal(hue + t * 0.02);
        const k = Math.min(1, 0.45 + 0.4 * sp) * life;
        const r = bgR + (((c >> 16) & 255) - bgR) * k, g = bgG + (((c >> 8) & 255) - bgG) * k, bl = bgB + ((c & 255) - bgB) * k;
        cv.line(x0, y0 / aspect, X[i], Y[i] / aspect, (r << 16) | (g << 8) | (bl | 0));
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/galaxy.js:
// A rotating barred-free spiral galaxy built on the density-wave trick: each
// star orbits on an ellipse whose tilt grows with radius, and inner orbits run
// faster (differential rotation). Where neighboring ellipses crowd together
// two spiral arms emerge — and, unlike real winding, they never wrap up.
// The glow is a pre-baked texture of that same star density plus a hot core,
// sampled per pixel through the view transform; stars are added on top.
import { mix, NONE } from '../../color.js';

const EXT = 1.15; // texture half-extent in galaxy units

export default {
  title: 'Spiral Galaxy',
  gallery: 'sim',
  category: 'Particles',
  kind: 'scene',
  tags: ['galaxy', 'spiral', 'stars', 'space'],
  order: 40,
  description: 'Density-wave spiral galaxy — thousands of stars on tilted elliptical orbits with differential rotation, glowing core and dust.',
  canvas: 'field',
  setup(ctx) {
    const cv = ctx.canvas();
    const { width: W, height: H, aspect, px } = cv;
    const rand = ctx.rng;
    const speed = ctx.param('speed', 1);
    const starCol = ctx.palette(['#ffcf9a', '#fff1dd', '#dfe7ff', '#9fb9ff', '#7f9cff']);
    const Hv = H * aspect;
    const incl = 0.62, tilt = -0.3, twist = 4.2;
    const Rg = Math.min(W * 0.47, (Hv * 0.47) / (incl + 0.25 * Math.abs(Math.sin(tilt))));
    const cx = W / 2, cy = H / 2;

    const ecc = (r) => 1 - 0.55 * Math.sqrt(Math.sin(Math.PI * Math.min(1, r)));
    const orbit = (r, th) => {
      const a = r, b = r * ecc(r), ph = r * twist;
      const c = Math.cos(th), s = Math.sin(th), cp = Math.cos(ph), sp = Math.sin(ph);
      return [a * c * cp - b * s * sp, a * c * sp + b * s * cp];
    };
    // 75% disk (uniform by area, so the arms carry the mass) + 25% exponential bulge.
    const sampleR = () => (rand() < 0.75 ? Math.sqrt(rand()) : Math.min(1, -Math.log(1 - rand() * 0.98) * 0.12));

    // ── bake the glow texture from the orbit density ──
    const G = 160;
    const dens = new Float32Array(G * G);
    for (let n = 0; n < 70000; n++) {
      const [x, y] = orbit(sampleR(), rand() * Math.PI * 2);
      const ix = Math.floor(((x / EXT) * 0.5 + 0.5) * G), iy = Math.floor(((y / EXT) * 0.5 + 0.5) * G);
      if (ix >= 0 && iy >= 0 && ix < G && iy < G) dens[iy * G + ix]++;
    }
    const tmp = new Float32Array(G * G);
    for (let pass = 0; pass < 3; pass++) {
      for (let y = 0; y < G; y++) for (let x = 0; x < G; x++) {
        let s = 0;
        for (let k = -2; k <= 2; k++) s += dens[y * G + Math.min(G - 1, Math.max(0, x + k))];
        tmp[y * G + x] = s / 5;
      }
      for (let y = 0; y < G; y++) for (let x = 0; x < G; x++) {
        let s = 0;
        for (let k = -2; k <= 2; k++) s += tmp[Math.min(G - 1, Math.max(0, y + k)) * G + x];
        dens[y * G + x] = s / 5;
      }
    }
    // Normalize against the disk (not the core spike) so the arms keep contrast.
    let ref = 0;
    for (let y = 0; y < G; y++) for (let x = 0; x < G; x++) {
      const gx = ((x + 0.5) / G * 2 - 1) * EXT, gy = ((y + 0.5) / G * 2 - 1) * EXT;
      if (Math.hypot(gx, gy) > 0.3) ref = Math.max(ref, dens[y * G + x]);
    }
    const tex = new Int32Array(G * G);
    const core = 0xffe6b8, disk = 0x8aa6ff, arm = 0xc9a7ff, bg = ctx.bg < 0 ? 0 : ctx.bg;
    for (let y = 0; y < G; y++) for (let x = 0; x < G; x++) {
      const gx = ((x + 0.5) / G * 2 - 1) * EXT, gy = ((y + 0.5) / G * 2 - 1) * EXT, r = Math.hypot(gx, gy);
      const d = Math.min(1, dens[y * G + x] / (ref || 1));
      const dust = 0.7 + 0.3 * ctx.noise.fbm(gx * 5, gy * 5, 0.5, 3);
      const kc = Math.exp(-((r / 0.06) ** 2)) * 1.0 + Math.exp(-r / 0.1) * 0.35;
      const kd = Math.pow(d, 1.6) * 0.42 * dust * Math.min(1, r / 0.12);
      const R = ((bg >> 16) & 255) + ((core >> 16) & 255) * kc + ((mix(disk, arm, d) >> 16) & 255) * kd;
      const Gc = ((bg >> 8) & 255) + ((core >> 8) & 255) * kc + ((mix(disk, arm, d) >> 8) & 255) * kd;
      const B = (bg & 255) + (core & 255) * kc + (mix(disk, arm, d) & 255) * kd;
      tex[y * G + x] = kc + kd < 0.012 ? NONE : (Math.min(255, R) << 16) | (Math.min(255, Gc) << 8) | Math.min(255, B);
    }

    // ── stars ──
    const NS = Math.max(600, Math.min(9000, Math.round(W * H * 0.22)));
    const SR = new Float32Array(NS), ST = new Float32Array(NS), SW = new Float32Array(NS), SC = new Int32Array(NS);
    for (let i = 0; i < NS; i++) {
      const r = sampleR();
      SR[i] = r;
      ST[i] = rand() * Math.PI * 2;
      SW[i] = (0.55 / Math.pow(0.12 + r, 0.8)) * (0.9 + rand() * 0.2);
      // Bulge stars overlap heavily under additive blending, so keep them faint.
      const b = (0.1 + 0.9 * Math.pow(rand(), 3.5)) * (0.3 + 0.7 * Math.min(1, r / 0.35));
      const c = rand() < 0.035 && r > 0.25 ? 0xff7fb0 : starCol(Math.min(1, r * 0.9 + (rand() - 0.5) * 0.35));
      SC[i] = (((c >> 16) & 255) * b << 16) | (((c >> 8) & 255) * b << 8) | (((c & 255) * b) | 0);
    }
    const FIELD = Math.round(W * H * 0.0025);
    const field = Array.from({ length: FIELD }, () => [rand() * W, rand() * H, mix(bg, 0xcfd8ff, 0.12 + rand() * 0.3)]);

    const ct = Math.cos(tilt), st = Math.sin(tilt);
    return (t) => {
      const rot = t * 0.04 * speed, cr = Math.cos(rot), sr = Math.sin(rot);
      // Glow: inverse-map each pixel into galaxy space and sample the texture.
      for (let y = 0, i = 0; y < H; y++) {
        const y3 = ((y + 0.5 - cy) * aspect) / Rg;
        for (let x = 0; x < W; x++, i++) {
          const x3 = (x + 0.5 - cx) / Rg;
          const x1 = x3 * ct + y3 * st, y1 = (-x3 * st + y3 * ct) / incl;
          const gx = x1 * cr + y1 * sr, gy = -x1 * sr + y1 * cr;
          const ix = Math.floor(((gx / EXT) * 0.5 + 0.5) * G), iy = Math.floor(((gy / EXT) * 0.5 + 0.5) * G);
          px[i] = ix >= 0 && iy >= 0 && ix < G && iy < G ? tex[iy * G + ix] : NONE;
        }
      }
      for (const [x, y, c] of field) cv.add(x, y, c);
      // Stars: advance along their ellipse, rotate with the disk, incline, tilt.
      for (let i = 0; i < NS; i++) {
        const [gx, gy] = orbit(SR[i], ST[i] + SW[i] * t * speed);
        const x1 = gx * cr - gy * sr, y1 = (gx * sr + gy * cr) * incl;
        const x3 = x1 * ct - y1 * st, y3 = x1 * st + y1 * ct;
        cv.add(cx + x3 * Rg, cy + (y3 * Rg) / aspect, SC[i]);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/harmonograph.j:
// A rotary harmonograph: two damped pendulums per axis (near-integer frequency
// ratios with a little detune) trace a decaying Lissajous figure. Each cycle a
// pen draws the curve in, the figure breathes as its phases drift, then it
// fades and a fresh set of pendulums takes over. Color flows along the path.
import { mix, NONE } from '../../color.js';
import { rng, easing, smoothstep } from '../../easing.js';

const RATIOS = [[2, 3], [3, 4], [1, 2], [3, 5], [4, 5], [2, 5], [1, 3], [5, 6], [1, 1], [3, 2]];

export default {
  title: 'Harmonograph',
  gallery: 'sim',
  category: 'Physics',
  kind: 'scene',
  tags: ['harmonograph', 'lissajous', 'pendulum', 'curves'],
  order: 20,
  description: 'Damped rotary harmonograph — a pen traces evolving Lissajous figures in braille, re-tuning its pendulums every cycle.',
  canvas: 'line',
  palette: 'prism',
  setup(ctx) {
    const cv = ctx.canvas();
    const { width: W, height: H, aspect } = cv;
    const pal = ctx.palette();
    const C = ctx.param('cycle', 14);
    const Hv = H * aspect;
    const cx = W / 2, cy = H / 2, amp = Math.min(W, Hv) * 0.47, ampX = Math.min(W * 0.47, amp * 1.3);
    const CYCLES = 55, PER = 44; // pendulum swings drawn per figure, samples per swing
    const N = CYCLES * PER;
    const bg = ctx.bg === NONE ? 0 : ctx.bg;

    // Pendulum set for cycle k: x and y run at a near-integer ratio a:b, and
    // each axis sums two slightly detuned pendulums so the figure beats/rotates.
    const tune = (k) => {
      const r = rng((ctx.seed * 7919 + k * 104729) >>> 0);
      const [a, b] = RATIOS[Math.floor(r() * RATIOS.length)];
      const fx = a + (r() - 0.5) * 0.01, fy = b + (r() - 0.5) * 0.01;
      const det = () => (r() < 0.5 ? -1 : 1) * (0.004 + r() * 0.012) * Math.max(a, b);
      const S = (CYCLES * Math.PI * 2) / Math.max(a, b);
      const damp = () => (Math.log(12) / S) * (0.6 + r() * 0.7);
      const A = [0.45 + r() * 0.3, 0, 0.45 + r() * 0.3, 0];
      A[1] = 1 - A[0]; A[3] = 1 - A[2];
      return {
        S,
        f: [fx, fx + det(), fy, fy + det()],
        p: [r() * 6.28, r() * 6.28, r() * 6.28, r() * 6.28],
        d: [damp(), damp(), damp(), damp()],
        A,
        rot: (r() - 0.5) * (1.2 / S),
        hue: r(),
      };
    };
    let cached = -1, P = null;

    return (t) => {
      const k = Math.floor(t / C), u = (t - k * C) / C;
      if (k !== cached) { P = tune(k); cached = k; }
      const progress = easing.inOutSine(Math.min(1, u / 0.55));
      const alpha = 1 - smoothstep(0.86, 1, u);
      const drift = (t - k * C) * 0.08;
      const { S, f, p, d, A, rot, hue } = P;
      cv.clear();
      const n = Math.max(2, Math.floor(N * progress));
      let px0 = 0, py0 = 0;
      for (let i = 0; i <= n; i++) {
        const s = (i / N) * S;
        let x = A[0] * Math.sin(f[0] * s + p[0] + drift) * Math.exp(-d[0] * s) + A[1] * Math.sin(f[1] * s + p[1]) * Math.exp(-d[1] * s);
        let y = A[2] * Math.sin(f[2] * s + p[2] - drift * 0.7) * Math.exp(-d[2] * s) + A[3] * Math.sin(f[3] * s + p[3]) * Math.exp(-d[3] * s);
        const a = rot * s, ca = Math.cos(a), sa = Math.sin(a);
        [x, y] = [x * ca - y * sa, x * sa + y * ca];
        const X = cx + x * ampX, Y = cy + (y * amp) / aspect;
        if (i > 0) {
          const along = i / N;
          const c = pal(hue + along * 0.5 + t * 0.015);
          cv.line(px0, py0, X, Y, mix(bg, c, alpha * (0.45 + 0.55 * (1 - along * 0.6))));
        }
        px0 = X; py0 = Y;
      }
      if (u < 0.55) {
        // The pen: a bright nib at the drawing point.
        const c = mix(pal(hue + (n / N) * 0.5 + t * 0.015), 0xffffff, 0.6);
        cv.ellipse(px0, py0, 1.5 * cv.sx / 2, (1.5 * cv.sx / 2) / aspect, c, true);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/langtons-ant.j:
// Langton's ant at braille resolution: on a white cell turn right, on a black
// cell turn left, flip the cell, step. Two ants share the grid and the cells
// they flip carry their color. The step rate ramps up through each run so
// the famous transition — ten thousand steps of chaos, then the endless
// diagonal "highway" — arrives inside the loop. A step counter ticks below.
import { NONE } from '../../color.js';

const RUN = 30;
const DIRS = [[0, -1], [1, 0], [0, 1], [-1, 0]];

export default {
  title: "Langton's Ant",
  gallery: 'sim',
  category: 'Cellular Automata',
  kind: 'scene',
  tags: ['langton', 'ant', 'turmite', 'cellular automata', 'emergence', 'braille'],
  order: 20,
  description: "Two Langton's ants at braille resolution, accelerating through ten thousand steps of chaos into the highway.",
  size: { w: 60, h: 22 },
  minSize: { w: 20, h: 7 },
  loop: RUN,
  canvas: 'line',
  palette: 'prism',
  params: { ants: { default: 2, min: 1, max: 4, label: 'Ants' } },
  setup(ctx) {
    const label = ctx.height >= 10;
    const cv = ctx.canvas('line', { rows: label ? ctx.height - 1 : ctx.height });
    const W = cv.width, H = cv.height, px = cv.px, th = ctx.theme;
    const pal = ctx.palette();
    const nAnts = Math.round(ctx.param('ants', 2));
    const cell = new Uint8Array(W * H), owner = new Uint8Array(W * H);
    const cols = Array.from({ length: nAnts }, (_, i) => pal(0.55 + i * 0.27));
    let ants = [], steps = 0, run = -1, acc = 0;
    const reset = () => {
      cell.fill(0);
      ants = Array.from({ length: nAnts }, (_, i) => ({
        x: Math.floor(W * (nAnts === 1 ? 0.5 : 0.3 + (0.4 * i) / (nAnts - 1))),
        y: Math.floor(H * (0.5 + (i % 2 ? 0.12 : -0.12) * (nAnts > 1 ? 1 : 0))),
        d: i % 4,
      }));
      steps = 0;
    };
    const step = () => {
      for (let k = 0; k < ants.length; k++) {
        const a = ants[k], i = a.y * W + a.x;
        a.d = (a.d + (cell[i] ? 3 : 1)) & 3; // white (0) → right, black (1) → left
        cell[i] ^= 1; owner[i] = k;
        a.x = (a.x + DIRS[a.d][0] + W) % W; a.y = (a.y + DIRS[a.d][1] + H) % H;
      }
      steps++;
    };

    return (t, dt) => {
      const r = Math.floor(t / RUN);
      if (r !== run) { run = r; reset(); acc = 0; }
      // Steps per second ramp from 150 to ~2400 across the run.
      const local = t - r * RUN, rate = 150 + 2250 * Math.pow(local / RUN, 1.5);
      acc += Math.min(0.25, Math.max(0, dt)) * rate;
      for (; acc >= 1; acc--) step();
      for (let i = 0; i < W * H; i++) px[i] = cell[i] ? cols[owner[i]] : NONE;
      for (const a of ants) px[a.y * W + a.x] = th.ink;
      cv.paint(ctx.buffer);
      if (label) {
        const txt = `step ${steps.toLocaleString('en-US')}`;
        ctx.buffer.text(1, ctx.height - 1, txt.slice(0, ctx.width - 2), th.muted);
      }
    };
  },
};

sources.prism-term/src/facets/sim/life.js:
// Conway's Game of Life on a toroidal grid at canvas-pixel resolution (8 cells
// per terminal cell in braille). Cells are colored by age — newborns white-hot,
// survivors cooling through the theme's accents — and recently dead cells leave
// a ghost glow in block modes. A rolling state hash detects stagnation and
// short cycles, which trigger fresh soup; gliders are fired in periodically.

import { NONE } from '../../color.js';

const GLIDER = [[1, 0], [2, 1], [0, 2], [1, 2], [2, 2]];
const LWSS = [[1, 0], [4, 0], [0, 1], [0, 2], [4, 2], [0, 3], [1, 3], [2, 3], [3, 3]];

export default {
  title: 'Game of Life',
  gallery: 'sim',
  category: 'Cellular Automata',
  kind: 'scene',
  tags: ['game of life', 'conway', 'cellular automata', 'braille'],
  order: 10,
  description: "Conway's Life at braille resolution — age-colored cells, ghost trails, auto-reseeding on stagnation, injected gliders.",
  canvas: 'line',
  setup(ctx) {
    const cv = ctx.canvas();
    const { width: W, height: H, px } = cv;
    const rand = ctx.rng;
    const th = ctx.theme;
    const gps = 14 * ctx.param('speed', 1);
    const ageCol = ctx.palette(['#ffffff', th.accent, th.info, th.pos, th.crit]);
    const AGES = 90;
    const lut = new Int32Array(AGES);
    for (let a = 0; a < AGES; a++) lut[a] = ageCol(Math.pow(a / (AGES - 1), 0.6));
    const ghosts = cv.mode !== 'braille' && cv.mode !== 'ascii';
    const N = W * H;
    let cur = new Uint8Array(N), nxt = new Uint8Array(N);
    const age = new Uint16Array(N);
    const heat = new Float32Array(N);
    const xm = new Int32Array(W), xp = new Int32Array(W);
    for (let x = 0; x < W; x++) { xm[x] = (x - 1 + W) % W; xp[x] = (x + 1) % W; }

    const soup = (x0, y0, w, h, density) => {
      for (let y = y0; y < y0 + h; y++)
        for (let x = x0; x < x0 + w; x++) {
          const i = (((y % H) + H) % H) * W + (((x % W) + W) % W);
          if (rand() < density) { cur[i] = 1; age[i] = 0; }
        }
    };
    const stamp = (shape, ox, oy, fx, fy) => {
      const sw = Math.max(...shape.map((p) => p[0])), sh = Math.max(...shape.map((p) => p[1]));
      for (const [x, y] of shape) {
        const X = ((ox + (fx ? sw - x : x)) % W + W) % W, Y = ((oy + (fy ? sh - y : y)) % H + H) % H;
        cur[Y * W + X] = 1; age[Y * W + X] = 0;
      }
    };
    const reseed = () => {
      const n = 2 + Math.floor(rand() * 3), s = Math.max(6, Math.floor(Math.min(W, H) * 0.35));
      for (let k = 0; k < n; k++) soup(Math.floor(rand() * W), Math.floor(rand() * H), s, s, 0.38);
    };
    soup(0, 0, W, H, 0.27);

    const recent = new Map(); // state hash → generation it was seen
    let gen = 0, stuck = 0, acc = 0, nextShip = 2 + rand() * 3, pop = 0;

    const step = () => {
      let h = 0x811c9dc5, p = 0;
      for (let y = 0; y < H; y++) {
        const r0 = ((y - 1 + H) % H) * W, r1 = y * W, r2 = ((y + 1) % H) * W;
        for (let x = 0; x < W; x++) {
          const a = xm[x], b = xp[x];
          const n = cur[r0 + a] + cur[r0 + x] + cur[r0 + b] + cur[r1 + a] + cur[r1 + b] + cur[r2 + a] + cur[r2 + x] + cur[r2 + b];
          const i = r1 + x, alive = cur[i];
          const v = n === 3 || (alive && n === 2) ? 1 : 0;
          nxt[i] = v;
          if (v) {
            age[i] = alive ? Math.min(65535, age[i] + 1) : 0;
            p++;
            h = Math.imul(h ^ i, 16777619);
          } else if (alive) heat[i] = 1;
          else if (heat[i] > 0) heat[i] = heat[i] < 0.03 ? 0 : heat[i] * 0.78;
        }
      }
      [cur, nxt] = [nxt, cur];
      gen++;
      pop = p;
      h = (h ^ p) >>> 0;
      // Periodic (≤ 60 generations) or near-empty → stir in fresh soup.
      if (recent.has(h) && gen - recent.get(h) <= 60) stuck++;
      else stuck = Math.max(0, stuck - 1);
      recent.set(h, gen);
      if (recent.size > 120) recent.delete(recent.keys().next().value);
      if (stuck > 24 || pop < N * 0.015) { reseed(); stuck = 0; recent.clear(); }
    };

    return (t, dt) => {
      acc += dt * gps;
      for (let k = 0; acc >= 1 && k < 4; k++, acc--) step();
      if (acc > 4) acc = 0;
      if (t >= nextShip) {
        const shape = rand() < 0.7 ? GLIDER : LWSS;
        stamp(shape, Math.floor(rand() * W), Math.floor(rand() * H), rand() < 0.5, rand() < 0.5);
        nextShip = t + 2.5 + rand() * 3.5;
      }
      const ghostCol = th.crit, bg = ctx.bg < 0 ? 0 : ctx.bg;
      for (let i = 0; i < N; i++) {
        if (cur[i]) px[i] = lut[age[i] < AGES ? age[i] : AGES - 1];
        else if (ghosts && heat[i] > 0.04) {
          const k = heat[i] * 0.4;
          const r = ((bg >> 16) & 255) + ((((ghostCol >> 16) & 255) - ((bg >> 16) & 255)) * k);
          const g = ((bg >> 8) & 255) + ((((ghostCol >> 8) & 255) - ((bg >> 8) & 255)) * k);
          const b = (bg & 255) + (((ghostCol & 255) - (bg & 255)) * k);
          px[i] = (r << 16) | (g << 8) | (b | 0);
        } else px[i] = NONE;
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/n-body.js:
// The figure-eight three-body choreography (Chenciner & Montgomery, 2000):
// three equal masses chasing each other round one figure-eight, integrated
// with velocity Verlet. A ring of massless dust starts in orbit around the
// trio and gets slung about chaotically by it — some captured, some flung
// clear — so the stable dance and the chaos sit side by side.
import { mix } from '../../color.js';

const H_STEP = 0.0025, RATE = 1; // integrator step (sim units), sim seconds per second
const RUN = 30, DUST = 14;
const FIG8 = [
  [-0.97000436, 0.24308753, 0.466203685, 0.43236573],
  [0.97000436, -0.24308753, 0.466203685, 0.43236573],
  [0, 0, -0.93240737, -0.86473146],
];

export default {
  title: 'N-Body Orbits',
  gallery: 'sim',
  category: 'Physics',
  kind: 'scene',
  tags: ['n-body', 'gravity', 'orbits', 'three-body', 'figure eight', 'chaos', 'braille'],
  order: 30,
  description: 'The figure-eight three-body choreography, with a ring of dust that the dancing trio flings about chaotically.',
  size: { w: 60, h: 22 },
  minSize: { w: 20, h: 7 },
  loop: RUN,
  canvas: 'line',
  palette: 'prism',
  params: { dust: { default: DUST, min: 0, max: 40, label: 'Dust particles' } },
  setup(ctx) {
    const label = ctx.height >= 12;
    const cv = ctx.canvas('line', { rows: label ? ctx.height - 1 : ctx.height });
    const W = cv.width, Hc = cv.height, asp = cv.aspect, th = ctx.theme, rand = ctx.rng;
    const pal = ctx.palette();
    const nDust = Math.round(ctx.param('dust', DUST));
    const scale = Math.min((W / 2) / 1.6, ((Hc * asp) / 2) / 0.85);
    const cx = W / 2, cy = (Hc * asp) / 2;
    const bodyCol = [pal(0), pal(0.36), pal(0.66)];
    const dustCol = mix(th.muted, th.ink, 0.3);
    let B, D, all, run = -1, acc = 0;
    const trails = [[], [], []];
    const reset = () => {
      B = FIG8.map(([x, y, vx, vy]) => ({ x, y, vx, vy, ax: 0, ay: 0 }));
      D = Array.from({ length: nDust }, (_, i) => {
        const a = (i / Math.max(1, nDust)) * Math.PI * 2 + rand() * 0.2, r = 1.35 + rand() * 0.45, v = Math.sqrt(3 / r) * (0.92 + rand() * 0.1);
        return { x: Math.cos(a) * r, y: Math.sin(a) * r, vx: -Math.sin(a) * v, vy: Math.cos(a) * v, ax: 0, ay: 0, tr: [] };
      });
      all = [...B, ...D];
      for (const tr of trails) tr.length = 0;
      accel();
    };
    const accel = () => {
      for (const p of B) { p.ax = 0; p.ay = 0; }
      for (let i = 0; i < 3; i++) for (let j = i + 1; j < 3; j++) {
        const a = B[i], b = B[j], dx = b.x - a.x, dy = b.y - a.y, r2 = dx * dx + dy * dy + 1e-6, f = 1 / (r2 * Math.sqrt(r2));
        a.ax += dx * f; a.ay += dy * f; b.ax -= dx * f; b.ay -= dy * f;
      }
      for (const p of D) {
        p.ax = 0; p.ay = 0;
        for (const b of B) { const dx = b.x - p.x, dy = b.y - p.y, r2 = dx * dx + dy * dy + 0.004, f = 1 / (r2 * Math.sqrt(r2)); p.ax += dx * f; p.ay += dy * f; }
      }
    };
    const step = (h) => {
      for (const p of all) { p.vx += p.ax * h * 0.5; p.vy += p.ay * h * 0.5; p.x += p.vx * h; p.y += p.vy * h; }
      accel();
      for (const p of all) { p.vx += p.ax * h * 0.5; p.vy += p.ay * h * 0.5; }
    };
    const P = (x, y) => [cx + x * scale, (cy + y * scale) / asp];
    let rec = 0;

    return (t, dt) => {
      const r = Math.floor(t / RUN);
      if (r !== run) { run = r; reset(); acc = 0; }
      acc += Math.min(0.25, Math.max(0, dt)) * RATE / H_STEP;
      for (; acc >= 1; acc--) {
        step(H_STEP);
        if (++rec % 8 === 0) {
          B.forEach((b, i) => { trails[i].push([b.x, b.y]); if (trails[i].length > 120) trails[i].shift(); });
          for (const d of D) { d.tr.push([d.x, d.y]); if (d.tr.length > 40) d.tr.shift(); }
        }
      }
      cv.clear();
      for (const d of D) {
        for (let i = 1; i < d.tr.length; i++) {
          const [x0, y0] = P(...d.tr[i - 1]), [x1, y1] = P(...d.tr[i]);
          if (Math.abs(x1 - x0) < W / 3) cv.line(x0, y0, x1, y1, mix(th.bg, dustCol, 0.15 + 0.5 * (i / d.tr.length)));
        }
        const [x, y] = P(d.x, d.y);
        cv.set(x, y, dustCol);
      }
      trails.forEach((tr, k) => {
        for (let i = 1; i < tr.length; i++) {
          const [x0, y0] = P(...tr[i - 1]), [x1, y1] = P(...tr[i]);
          cv.line(x0, y0, x1, y1, mix(th.bg, bodyCol[k], 0.2 + 0.8 * (i / tr.length)));
        }
      });
      B.forEach((b, k) => { const [x, y] = P(b.x, b.y); cv.circle(x, y, Math.max(1.2, scale * 0.09), bodyCol[k], true); });
      cv.paint(ctx.buffer);
      if (label) ctx.buffer.text(1, ctx.height - 1, 'figure-eight choreography · 3 equal masses'.slice(0, ctx.width - 2), th.muted);
    };
  },
};

sources.prism-term/src/facets/sim/rain.js:
// Night rain over a city: three parallax layers of slanted braille rain (far
// drops slow, short and dim; near drops fast and long), splashes on the street
// and rooftops, lit windows that come and go, and lightning — a branching bolt
// whose double-flicker flash floods the sky and throws the skyline into
// silhouette.
import { mix, NONE } from '../../color.js';

const FLASH = 0xdfe8ff, BOLT = 0xf4f7ff;
const WINDOW = [0xffc46b, 0xffd99a, 0xffb347, 0x9fd3ff, 0xfff0c8];

export default {
  title: 'Night Rain',
  gallery: 'sim',
  category: 'Weather',
  kind: 'scene',
  tags: ['rain', 'city', 'lightning', 'night'],
  order: 60,
  description: 'Parallax rain over a city skyline — street and rooftop splashes, flickering windows, and lightning that silhouettes the city.',
  canvas: 'line',
  setup(ctx) {
    const th = ctx.theme;
    const rand = ctx.rng;
    const sky = ctx.canvas('field');
    const rain = ctx.canvas('line');
    const { width: W, height: H, aspect } = rain;
    const SW = sky.width, SH = sky.height;
    const intensity = ctx.param('intensity', 1);
    const base = ctx.bg === NONE ? 0x0b0f18 : ctx.bg;
    const skyTop = mix(base, 0x000000, 0.35), skyLow = mix(base, th.info, 0.16);

    // ── skyline (in sky-canvas pixels) ──
    const roof = new Int32Array(SW).fill(SH);
    const buildings = [];
    for (let x = -2; x < SW;) {
      const w = Math.max(3, Math.round(SW * (0.03 + rand() * 0.06)));
      const h = Math.round(SH * (0.14 + Math.pow(rand(), 1.6) * 0.42));
      const top = SH - h;
      buildings.push({ x, w, top, spire: rand() < 0.18, tone: 0.45 + rand() * 0.25 });
      for (let k = Math.max(0, x); k < Math.min(SW, x + w); k++) roof[k] = top;
      x += w + (rand() < 0.3 ? 1 : 0);
    }
    for (const b of buildings) if (b.spire) {
      const sx = b.x + (b.w >> 1), sh = Math.max(2, Math.round(SH * 0.06));
      for (let y = b.top - sh; y < b.top; y++) if (sx >= 0 && sx < SW) roof[sx] = Math.min(roof[sx], y);
    }
    const windows = [];
    for (const b of buildings)
      for (let y = b.top + 2; y < SH - 2; y += 2)
        for (let x = b.x + 1; x < b.x + b.w - 1; x += 2)
          if (x >= 0 && x < SW && rand() < 0.42) windows.push({ x, y, c: WINDOW[Math.floor(rand() * WINDOW.length)], phase: rand() * 100, rate: 0.05 + rand() * 0.2 });
    const silhouette = mix(base, 0x000000, 0.55);

    // Rain-canvas roof height at a rain-canvas x.
    const roofAt = (x) => (roof[Math.max(0, Math.min(SW - 1, Math.floor((x / W) * SW)))] / SH) * H;

    // ── rain layers ──
    const area = (ctx.width * ctx.height) / 3000 * (rain.mode === "braille" ? 1 : 0.3);
    const LAYERS = [
      { n: 360, v: 0.85, len: 2, k: 0.3, roof: false },
      { n: 210, v: 1.35, len: 4, k: 0.52, roof: true },
      { n: 90, v: 2.2, len: 7, k: 0.9, roof: false },
    ];
    const drops = [];
    for (let li = 0; li < LAYERS.length; li++) {
      const L = LAYERS[li];
      const n = Math.max(8, Math.round(L.n * area * intensity));
      for (let i = 0; i < n; i++) drops.push({ li, x: rand() * W * 1.3 - W * 0.15, y: rand() * H, s: 0.85 + rand() * 0.3 });
    }
    const splashes = [];
    const rainCol = mix(th.info, 0xc8d6ff, 0.5);

    let nextStrike = 2.5 + rand() * 2, strikeAt = -10, bolt = [];
    const makeBolt = () => {
      const segs = [];
      const grow = (x, y, dir, depth, w) => {
        const target = roofAt(x) - 1;
        while (y < target) {
          const ny = y + 2 + rand() * 4, nx = x + dir * (rand() * 2) + (rand() - 0.5) * 5;
          segs.push([x, y, nx, ny, w]);
          if (depth < 2 && rand() < 0.12) grow(nx, ny, rand() < 0.5 ? -1 : 1, depth + 1, w * 0.5);
          x = nx; y = ny;
          if (depth > 0 && rand() < 0.06) return;
        }
      };
      grow(W * (0.15 + rand() * 0.7), 0, rand() < 0.5 ? -0.5 : 0.5, 0, 1);
      return segs;
    };

    return (t, dt) => {
      // Lightning envelope: a sharp flash and two decaying re-strikes.
      if (t >= nextStrike) { strikeAt = t; bolt = makeBolt(); nextStrike = t + 5 + rand() * 6; }
      const u = t - strikeAt;
      const f = u < 0 || u > 1.2 ? 0 : Math.min(1, Math.exp(-u * 9) + (u > 0.16 ? 0.7 * Math.exp(-(u - 0.16) * 7) : 0) + (u > 0.42 ? 0.35 * Math.exp(-(u - 0.42) * 10) : 0));
      const wind = 0.22 + 0.14 * Math.sin(t * 0.17) + 0.06 * Math.sin(t * 0.71);

      // Sky: a vertical gradient on cell backgrounds, lit by the flash.
      const buf = ctx.buffer;
      for (let y = 0; y < ctx.height; y++) {
        const c = mix(mix(skyTop, skyLow, Math.pow(y / Math.max(1, ctx.height - 1), 1.5)), FLASH, f * 0.8);
        buf.fill(0, y, ctx.width, 1, ' ', undefined, c);
      }

      // Skyline and windows.
      sky.clear();
      for (const b of buildings) {
        const c = mix(silhouette, 0x000000, f * 0.6);
        for (let y = b.top; y < SH; y++) for (let x = Math.max(0, b.x); x < Math.min(SW, b.x + b.w); x++) sky.px[y * SW + x] = c;
      }
      const spire = mix(silhouette, 0x000000, f * 0.6);
      for (let x = 0; x < SW; x++) for (let y = roof[x]; y < SH; y++) if (sky.px[y * SW + x] === NONE) sky.px[y * SW + x] = spire;
      for (const w of windows) {
        const on = Math.sin(w.phase + t * w.rate) > -0.35;
        if (on) sky.px[w.y * SW + w.x] = mix(w.c, 0x000000, 0.15 + 0.25 * (0.5 + 0.5 * Math.sin(w.phase * 3 + t * 0.7)));
      }
      sky.paint(buf);

      // Rain, splashes, bolt.
      rain.clear();
      const lit = 1 + f * 0.9;
      for (const d of drops) {
        const L = LAYERS[d.li];
        const v = L.v * H * d.s;
        d.y += v * dt;
        d.x += v * wind * dt;
        const floor = L.roof ? roofAt(d.x) : H - 1;
        if (d.y >= floor) {
          if (d.li === 2 || (L.roof && d.y < H - 1)) {
            const n = d.li === 2 ? 3 : 1;
            for (let k = 0; k < n; k++) splashes.push({ x: d.x, y: floor - 1, vx: (rand() - 0.5) * H * 0.35, vy: -H * (0.25 + rand() * 0.3), life: 0.22 + rand() * 0.12, k: L.k });
          }
          d.y = -rand() * H * 0.2;
          d.x = rand() * W * 1.3 - W * 0.3;
          continue;
        }
        const len = L.len * Math.max(1, H / 120) * (0.8 + 0.4 * d.s);
        const k = Math.min(1, L.k * lit);
        const c = mix(base, rainCol, k);
        rain.line(d.x - len * wind, (d.y - len) / aspect, d.x, d.y / aspect, c);
      }
      for (let i = splashes.length - 1; i >= 0; i--) {
        const s = splashes[i];
        s.vy += H * 2.4 * dt; s.x += s.vx * dt; s.y += s.vy * dt; s.life -= dt;
        if (s.life <= 0) { splashes.splice(i, 1); continue; }
        rain.set(s.x, s.y / aspect, mix(base, rainCol, Math.min(1, s.k * lit)));
      }
      if (f > 0.2) {
        const c = mix(rainCol, BOLT, Math.min(1, f * 1.2));
        for (const [x0, y0, x1, y1, w] of bolt) if (w >= 0.5 || f > 0.5) rain.line(x0, y0 / aspect, x1, y1 / aspect, c);
      }
      rain.paint(buf);
    };
  },
};

sources.prism-term/src/facets/sim/reaction-diffu:
// Gray-Scott reaction-diffusion: two chemicals, U fed in and V feeding on it
// (U + 2V → 3V), diffusing at different rates. The feed and kill rates drift
// slowly between the "mitosis", "coral" and "maze" regimes, so spots divide,
// then grow into coral, then wind into labyrinths. V is shaded as a lit relief
// so the patterns read like living tissue.
import { NONE, mix } from '../../color.js';

// [feed, kill] presets (Karl Sims' parameterisation: Du = 1, Dv = 0.5, dt = 1),
// with diffusion scaled by DS so features stay a few cells wide at terminal size.
const DS = 0.32;
const REGIMES = [[0.0367, 0.0649], [0.0545, 0.062], [0.029, 0.057]];
const HOLD = 14;

export default {
  title: 'Reaction-Diffusion',
  gallery: 'sim',
  category: 'Life & Flocking',
  kind: 'scene',
  tags: ['gray-scott', 'reaction diffusion', 'turing', 'morphogenesis', 'pattern'],
  order: 20,
  description: 'Gray-Scott reaction-diffusion drifting from dividing spots to coral to mazes, shaded as a lit living relief.',
  size: { w: 60, h: 22 },
  minSize: { w: 20, h: 7 },
  loop: HOLD * REGIMES.length,
  canvas: 'field',
  palette: 'aurora',
  params: { speed: { default: 1, min: 0.25, max: 3, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const W = cv.width, H = cv.height, px = cv.px, th = ctx.theme, rand = ctx.rng;
    const pal = ctx.palette();
    const rate = 260 * ctx.param('speed', 1); // solver steps per second
    const N = W * H;
    let U = new Float32Array(N).fill(1), V = new Float32Array(N);
    let U2 = new Float32Array(N), V2 = new Float32Array(N);
    const xm = new Int32Array(W), xp = new Int32Array(W);
    for (let x = 0; x < W; x++) { xm[x] = (x - 1 + W) % W; xp[x] = (x + 1) % W; }
    const seed = (count) => {
      for (let k = 0; k < count; k++) {
        const cx = Math.floor(rand() * W), cy = Math.floor(rand() * H), r = 1;
        for (let y = cy - r; y <= cy + r; y++) for (let x = cx - r; x <= cx + r; x++) {
          const i = ((y + H) % H) * W + ((x + W) % W);
          U[i] = 0.5; V[i] = 0.25 + rand() * 0.1;
        }
      }
    };
    seed(Math.max(4, Math.round(N / 120)));
    let acc = 0;
    const step = (F, K) => {
      for (let y = 0; y < H; y++) {
        const r0 = ((y - 1 + H) % H) * W, r1 = y * W, r2 = ((y + 1) % H) * W;
        for (let x = 0; x < W; x++) {
          const a = xm[x], b = xp[x], i = r1 + x;
          // 9-point Laplacian (0.2 edges, 0.05 corners, -1 center).
          const lu = 0.2 * (U[r0 + x] + U[r2 + x] + U[r1 + a] + U[r1 + b]) + 0.05 * (U[r0 + a] + U[r0 + b] + U[r2 + a] + U[r2 + b]) - U[i];
          const lv = 0.2 * (V[r0 + x] + V[r2 + x] + V[r1 + a] + V[r1 + b]) + 0.05 * (V[r0 + a] + V[r0 + b] + V[r2 + a] + V[r2 + b]) - V[i];
          const u = U[i], v = V[i], uvv = u * v * v;
          U2[i] = u + (DS * lu - uvv + F * (1 - u));
          V2[i] = v + (0.5 * DS * lv + uvv - (K + F) * v);
        }
      }
      [U, U2] = [U2, U]; [V, V2] = [V2, V];
    };

    return (t, dt) => {
      // Parameters ease from one regime to the next over the last third of each hold.
      const cyc = ((t / HOLD) % REGIMES.length + REGIMES.length) % REGIMES.length;
      const k = Math.floor(cyc), f = cyc - k, m = f < 0.66 ? 0 : (f - 0.66) / 0.34;
      const s = m * m * (3 - 2 * m), A = REGIMES[k], B = REGIMES[(k + 1) % REGIMES.length];
      const F = A[0] + (B[0] - A[0]) * s, K = A[1] + (B[1] - A[1]) * s;
      acc += Math.min(0.25, Math.max(0, dt)) * rate;
      let n = 0;
      for (; acc >= 1 && n < 24; acc--, n++) step(F, K);
      if (acc > 24) acc = 0;
      // Keep it alive: if V has nearly vanished, seed fresh droplets.
      if (n) { let sum = 0; for (let i = 0; i < N; i += 7) sum += V[i]; if (sum < N * 0.0005) seed(6); }
      for (let y = 0; y < H; y++) {
        const r0 = ((y - 1 + H) % H) * W, r2 = ((y + 1) % H) * W;
        for (let x = 0; x < W; x++) {
          const i = y * W + x, v = V[i];
          if (v < 0.04) { px[i] = NONE; continue; }
          // Relief lighting from the V gradient (light from the upper left).
          const gx = V[y * W + xp[x]] - V[y * W + xm[x]], gy = V[r2 + x] - V[r0 + x];
          const light = Math.max(0, Math.min(1.4, 0.8 + (gx + gy) * 3));
          const c = pal(Math.min(1, 0.35 + v * 1.9));
          const lit = mix(mix(0x000000, c, Math.min(1, light)), 0xffffff, Math.max(0, light - 1) * 0.6);
          px[i] = mix(th.bg, lit, Math.min(1, (v - 0.04) / 0.12));
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/slime-mold.js:
// Physarum slime mold: thousands of agents each sense the trail ahead-left,
// ahead and ahead-right, steer toward the strongest scent, step, and deposit.
// The trail diffuses and evaporates. Food sources keep leaking scent, so the
// swarm self-organizes into a transport network linking them — the same trick
// the real organism uses to rebuild a railway map out of oat flakes.
import { NONE, mix } from '../../color.js';

const SA = Math.PI / 4, RA = Math.PI / 4, SO = 9; // sensor angle, rotation angle, sensor offset (px)

export default {
  title: 'Slime Mold',
  gallery: 'sim',
  category: 'Life & Flocking',
  kind: 'scene',
  tags: ['physarum', 'slime mold', 'agents', 'network', 'emergence', 'trails'],
  order: 30,
  description: 'Physarum agents sensing and laying scent trails self-organize into a transport network linking food sources.',
  size: { w: 60, h: 22 },
  minSize: { w: 20, h: 7 },
  loop: 20,
  canvas: 'line',
  palette: 'toxic',
  params: { agents: { default: 1, min: 0.2, max: 3, label: 'Agent density' } },
  setup(ctx) {
    const cv = ctx.canvas('line');
    const W = cv.width, H = cv.height, px = cv.px, th = ctx.theme, rand = ctx.rng;
    const pal = ctx.palette();
    const N = W * H;
    const count = Math.min(9000, Math.round(N * 0.13 * ctx.param('agents', 1)));
    let trail = new Float32Array(N), tmp = new Float32Array(N);
    const occ = new Uint8Array(N); // one agent per pixel (Jones' exclusion rule)
    const ax = new Float32Array(count), ay = new Float32Array(count), ah = new Float32Array(count);
    // Scattered start, random headings: the network condenses out of the noise.
    for (let i = 0; i < count; i++) {
      let x, y, tries = 0;
      do { x = rand() * W; y = rand() * H; tries++; } while (occ[(y | 0) * W + (x | 0)] && tries < 8);
      ax[i] = x; ay[i] = y; ah[i] = rand() * Math.PI * 2; occ[(y | 0) * W + (x | 0)] = 1;
    }
    const food = Array.from({ length: Math.max(3, Math.min(7, Math.round(N / 1500))) }, () => [3 + rand() * (W - 6), 3 + rand() * (H - 6)]);
    const sense = (x, y) => (x < 0 || y < 0 || x >= W || y >= H ? -1 : trail[(y | 0) * W + (x | 0)]);
    let acc = 0, peak = 1;
    const step = () => {
      for (const [fx, fy] of food) for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) trail[((fy | 0) + dy) * W + (fx | 0) + dx] += 6;
      for (let i = 0; i < count; i++) {
        const h = ah[i], x = ax[i], y = ay[i];
        // Sensory stage: steer toward the strongest of three sensors.
        const f = sense(x + Math.cos(h) * SO, y + Math.sin(h) * SO);
        const l = sense(x + Math.cos(h - SA) * SO, y + Math.sin(h - SA) * SO);
        const r = sense(x + Math.cos(h + SA) * SO, y + Math.sin(h + SA) * SO);
        let nh = h;
        if (f >= l && f >= r) { /* straight on */ } else if (f < l && f < r) nh += (rand() < 0.5 ? -1 : 1) * RA; else if (l > r) nh -= RA; else nh += RA;
        // Motor stage: move only into a free pixel inside the dish; otherwise pick a new heading.
        const nx = x + Math.cos(nh), ny = y + Math.sin(nh);
        const j = (ny | 0) * W + (nx | 0), o = (y | 0) * W + (x | 0);
        if (nx < 0 || ny < 0 || nx >= W || ny >= H || (j !== o && occ[j])) { ah[i] = rand() * Math.PI * 2; continue; }
        occ[o] = 0; occ[j] = 1;
        ax[i] = nx; ay[i] = ny; ah[i] = nh > Math.PI * 2 ? nh - Math.PI * 2 : nh < 0 ? nh + Math.PI * 2 : nh;
        trail[j] += 5;
      }
      // Diffuse (3×3 mean, closed edges) and evaporate.
      let mx = 0;
      for (let y = 0; y < H; y++) {
        const y0 = y > 0 ? y - 1 : y, y1 = y < H - 1 ? y + 1 : y;
        for (let x = 0; x < W; x++) {
          const a = x > 0 ? x - 1 : x, b = x < W - 1 ? x + 1 : x;
          const s = trail[y0 * W + a] + trail[y0 * W + x] + trail[y0 * W + b] + trail[y * W + a] + trail[y * W + x] + trail[y * W + b] + trail[y1 * W + a] + trail[y1 * W + x] + trail[y1 * W + b];
          const v = (s / 9) * 0.9;
          tmp[y * W + x] = v;
          if (v > mx) mx = v;
        }
      }
      [trail, tmp] = [tmp, trail];
      peak = peak * 0.9 + mx * 0.1;
    };

    return (t, dt) => {
      acc += Math.min(0.25, Math.max(0, dt)) * 30;
      for (let k = 0; acc >= 1 && k < 6; k++, acc--) step();
      if (acc > 6) acc = 0;
      // Braille is on/off per dot: threshold the scent against its running peak.
      const thr = peak * 0.18;
      for (let i = 0; i < N; i++) {
        const v = trail[i];
        px[i] = v < thr ? NONE : pal(0.45 + 0.55 * Math.min(1, (v - thr) / (peak * 0.6)));
      }
      for (const [fx, fy] of food) {
        cv.circle(fx, fy, 1.5, mix(th.warn, 0xffffff, 0.3 + 0.2 * Math.sin(t * 3 + fx)), true);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/snow.js:
// Snow over a cabin. Three parallax layers of flakes sway down through a gusty
// wind; the near layer actually lands, building drifts on the ground and a
// cap on the roof, and the drifts slump downwind once they get too steep.
// The cabin's window glows (and spills warm light onto the snow), the chimney
// smokes, and dark pines stand behind it all.
import { NONE, mix as blend, luminance } from '../../color.js';

export default {
  title: 'Snow over a Cabin',
  gallery: 'sim',
  category: 'Weather',
  kind: 'scene',
  tags: ['snow', 'winter', 'cabin', 'drifts', 'weather', 'particles', 'night'],
  order: 20,
  description: 'Parallax snowfall in a gusty wind that settles into drifts and a roof cap, around a cabin with a glowing window.',
  size: { w: 64, h: 22 },
  minSize: { w: 24, h: 8 },
  loop: 30,
  canvas: 'field',
  palette: 'ice',
  params: { density: { default: 1, min: 0.2, max: 3, label: 'Snowfall' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const W = cv.width, H = cv.height, asp = cv.aspect, px = cv.px, th = ctx.theme;
    const rand = ctx.rng, noise = ctx.noise;
    const dense = ctx.param('density', 1);
    const night = luminance(th.bg) < 0.5;
    const skyTop = blend(th.bg, night ? 0x10204a : 0x9fb4cc, 0.45);
    const snowC = night ? 0xe8f0ff : 0xffffff, snowShade = night ? 0x7f93b8 : 0xb8c6d8;
    // Terrain: gentle hills, plus a far ridge silhouette.
    const ground = new Float32Array(W), ridge = new Float32Array(W);
    for (let x = 0; x < W; x++) {
      ground[x] = H * 0.8 + Math.sin(x * 0.07 + 1) * H * 0.04 + noise.noise2(x * 0.05, 3.1) * H * 0.03;
      ridge[x] = H * 0.52 + noise.fbm(x * 0.03, 7.7, 0, 3) * H * 0.18;
    }
    const snow = new Float32Array(W).fill(1); // settled depth (pixels)
    const CAP = H * 0.12;
    // Cabin.
    const cw = Math.max(8, Math.round(W * 0.2)), cx0 = Math.round(W * 0.56), cx1 = cx0 + cw;
    const floorY = Math.round(Math.max(...Array.from({ length: cw }, (_, i) => ground[Math.min(W - 1, cx0 + i)])));
    const wallH = Math.max(4, Math.round(H * 0.16)), roofH = Math.max(3, Math.round(cw * 0.32 / asp * 1.2));
    const eave = 2;
    const roofAt = (x) => floorY - wallH - roofH * (1 - Math.abs((x - (cx0 + cx1) / 2) / (cw / 2 + eave)));
    const roofSnow = new Float32Array(W);
    const chimX = cx0 + Math.round(cw * 0.72), chimTop = Math.round(roofAt(chimX)) - Math.max(2, Math.round(roofH * 0.4));
    // Pines.
    const pines = Array.from({ length: Math.max(2, Math.round(W / 22)) }, (_, i) => {
      const x = Math.round(W * (0.08 + i * 0.3 + rand() * 0.08));
      return { x, h: H * (0.32 + rand() * 0.14), w: W * 0.05 + rand() * W * 0.02 };
    }).filter((p) => p.x + p.w < cx0 - 2 || p.x - p.w > cx1 + 2);
    // Flakes in three parallax layers; only the near layer settles.
    const flakes = Array.from({ length: Math.round(((W * H) / 26) * dense) }, () => {
      const z = [0.35, 0.65, 1][Math.floor(rand() * 3)];
      return { x: rand() * W, y: rand() * H, z, ph: rand() * 6.28, sw: 0.5 + rand() * 1.5 };
    });
    const smoke = Array.from({ length: 22 }, (_, i) => ({ age: i / 22, ph: rand() * 6.28 }));
    const surface = (x) => {
      const xi = Math.max(0, Math.min(W - 1, x | 0));
      if (xi >= cx0 - eave && xi <= cx1 + eave) return roofAt(xi) - roofSnow[xi];
      return ground[xi] - snow[xi];
    };

    let last = 0;
    return (t, dt) => {
      dt = Math.min(0.1, Math.max(0, dt));
      const wind = 0.9 * Math.sin(t * 0.13) + 0.6 * noise.noise2(t * 0.3, 0.5);
      // Flakes.
      for (const f of flakes) {
        f.y += dt * (4 + 7 * f.z) * (H / 44);
        f.x += dt * (wind * 6 * f.z + Math.sin(t * f.sw + f.ph) * 1.4);
        if (f.x < 0) f.x += W; else if (f.x >= W) f.x -= W;
        const xi = f.x | 0;
        if (f.z === 1 && f.y >= surface(f.x)) {
          if (xi >= cx0 - eave && xi <= cx1 + eave) { if (roofSnow[xi] < CAP * 0.45) roofSnow[xi] += 0.35; }
          else if (snow[xi] < CAP + (xi % 7) * 0.2) snow[xi] += 0.35;
          f.y = -rand() * 4; f.x = rand() * W;
        } else if (f.y > H) { f.y = -rand() * 4; f.x = rand() * W; }
      }
      // Drifts slump when steep, a little more readily downwind.
      if (t - last > 0.05) {
        last = t;
        for (let x = 1; x < W - 1; x++) {
          for (const s of [-1, 1]) {
            const h0 = ground[x] - snow[x], h1 = ground[x + s] - snow[x + s];
            const lim = s * wind > 0 ? 0.9 : 1.6;
            if (h1 - h0 > lim && snow[x] > 0.3) { snow[x] -= 0.12; snow[x + s] += 0.12; }
          }
        }
        for (let x = 1; x < W - 1; x++) snow[x] += 0.03 * (snow[x - 1] + snow[x + 1] - 2 * snow[x]);
        for (let x = cx0 - eave + 1; x < cx1 + eave; x++) roofSnow[x] = Math.min(roofSnow[x], (roofSnow[x - 1] + roofSnow[x + 1]) / 2 + 0.6);
      }
      // Draw: sky, ridge, pines, ground + snow, cabin, smoke, flakes.
      for (let y = 0; y < H; y++) {
        const sky = blend(skyTop, th.bg, y / (H * 0.8));
        for (let x = 0; x < W; x++) px[y * W + x] = y > ridge[x] ? blend(sky, night ? 0x1a2236 : 0xc9d3de, 0.6) : sky;
      }
      const flick = 0.85 + 0.15 * noise.noise2(t * 3, 9.1);
      const winX0 = cx0 + Math.round(cw * 0.2), winX1 = winX0 + Math.max(2, Math.round(cw * 0.25));
      const winY0 = floorY - wallH + Math.round(wallH * 0.25), winY1 = winY0 + Math.max(1, Math.round(wallH * 0.4));
      for (const p of pines) {
        const base = Math.round(ground[Math.max(0, Math.min(W - 1, p.x))]);
        for (let y = Math.round(base - p.h); y < base; y++) {
          const f = (y - (base - p.h)) / p.h, tier = (f * 3) % 1;
          const half = p.w * (0.25 + 0.75 * f) * (0.55 + 0.45 * tier);
          for (let x = Math.round(p.x - half); x <= Math.round(p.x + half); x++) {
            if (x < 0 || x >= W || y < 0) continue;
            const edge = tier < 0.18 && Math.abs(x - p.x) > half * 0.3;
            px[y * W + x] = edge ? blend(snowShade, snowC, 0.4) : blend(0x0d2a1c, 0x1f5a3a, 0.4 + 0.3 * ((x - p.x) / (half + 1)));
          }
        }
      }
      for (let x = 0; x < W; x++) {
        const g = ground[x], top = g - snow[x];
        const slope = (snow[Math.min(W - 1, x + 1)] - snow[Math.max(0, x - 1)]) * 0.5;
        for (let y = Math.max(0, Math.floor(top)); y < H; y++) {
          const i = y * W + x;
          // Fresh snow on top, older snowpack below it, a little bluer with depth.
          let c = y < g ? blend(snowShade, snowC, Math.min(1, 0.68 + slope * 0.4 + (y - top) * 0.04))
            : blend(snowShade, snowC, Math.max(0.15, 0.55 - (y - g) * 0.05));
          const glowD = Math.hypot((x - (winX0 + winX1) / 2) / (cw * 0.6), (y - floorY) / 3);
          if (glowD < 1) c = blend(c, 0xffc46b, (1 - glowD) * 0.35 * flick);
          // Anti-alias the surface: the top pixel is only partly covered.
          px[i] = y === Math.floor(top) ? blend(px[i], c, 1 - (top - y)) : c;
        }
      }
      // Cabin: walls, window, door, chimney, roof and its snow cap.
      for (let y = floorY - wallH; y < floorY; y++) for (let x = cx0; x < cx1; x++) {
        if (y < 0 || y >= H) continue;
        let c = blend(0x3a2414, 0x6a4326, (y & 1) ? 0.55 : 0.75); // log courses
        if (x >= winX0 && x < winX1 && y >= winY0 && y < winY1) c = blend(0xffb347, 0xffe7a3, flick * 0.7);
        const dx0 = cx1 - Math.round(cw * 0.32);
        if (x >= dx0 && x < dx0 + Math.max(2, Math.round(cw * 0.18)) && y >= floorY - Math.round(wallH * 0.75)) c = 0x2a180c;
        px[y * W + x] = c;
      }
      for (let y = chimTop; y < roofAt(chimX); y++) for (let x = chimX; x < chimX + 2; x++) if (y >= 0 && x < W) px[y * W + x] = 0x5a3a2a;
      for (let x = cx0 - eave; x <= cx1 + eave; x++) {
        if (x < 0 || x >= W) continue;
        const r = roofAt(x);
        for (let y = Math.max(0, Math.floor(r - roofSnow[x])); y < Math.min(H, floorY - wallH + 1); y++) {
          if (y < r) px[y * W + x] = blend(snowShade, snowC, 0.8);
          else if (y < r + 1.5) px[y * W + x] = 0x2b1a12;
        }
      }
      for (const s of smoke) {
        const a = (s.age + t * 0.12) % 1;
        const x = chimX + 1 + a * 9 * (0.6 + wind * 0.5) + Math.sin(a * 6 + s.ph) * 1.2, y = chimTop - a * H * 0.45;
        const k = (1 - a) * 0.5;
        for (const [ox, oy] of [[0, 0], [1, 0], [0, -1]]) {
          const xx = Math.round(x + ox), yy = Math.round(y + oy);
          if (xx < 0 || yy < 0 || xx >= W || yy >= H) continue;
          px[yy * W + xx] = blend(px[yy * W + xx], night ? 0x8a93a6 : 0x8f99a6, k);
        }
      }
      for (const f of flakes) {
        const xx = f.x | 0, yy = f.y | 0;
        if (yy < 0 || yy >= H || f.y > surface(f.x)) continue; // hidden by the ground in front
        const i = yy * W + xx;
        px[i] = blend(px[i] === NONE ? th.bg : px[i], snowC, 0.35 + 0.65 * f.z);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/string-waves.j:
// A six-string harp played in an arpeggio. Each string is a real 1-D wave
// equation (finite differences, fixed ends, light damping and a touch of
// stiffness) plucked into a triangle and left to ring, so you see the kink
// split into two traveling waves, reflect off the bridges and settle into
// the fundamental. Lower strings swing slower and wider; ringing strings glow,
// and a dotted envelope traces each string's recent swing — the blur your eye
// sees on a real vibrating string, which single frames would otherwise miss.
import { mix } from '../../color.js';

const STRINGS = 6, N = 72, HZ = 900;
const PLUCK = 0.5; // seconds between plucks
const PATTERN = [0, 2, 4, 5, 3, 1, 2, 4, 3, 5, 1, 0];

export default {
  title: 'Plucked Strings',
  gallery: 'sim',
  category: 'Physics',
  kind: 'scene',
  tags: ['wave equation', 'strings', 'harp', 'standing waves', 'pluck', 'braille'],
  order: 40,
  description: 'A six-string harp plucked in an arpeggio: real wave-equation strings that split, reflect and ring down.',
  size: { w: 60, h: 20 },
  minSize: { w: 20, h: 7 },
  loop: PATTERN.length * PLUCK,
  canvas: 'line',
  palette: 'prism',
  params: {},
  setup(ctx) {
    const cv = ctx.canvas('line');
    const W = cv.width, H = cv.height, th = ctx.theme;
    const pal = ctx.palette();
    // Wave speed per string (Courant number ≤ 1), lowest string first.
    const c = Array.from({ length: STRINGS }, (_, k) => 0.42 + k * 0.11);
    const y = Array.from({ length: STRINGS }, () => new Float32Array(N));
    const yp = Array.from({ length: STRINGS }, () => new Float32Array(N));
    const yn = new Float32Array(N);
    const energy = new Float32Array(STRINGS);
    const env = Array.from({ length: STRINGS }, () => new Float32Array(N));
    const cols = Array.from({ length: STRINGS }, (_, k) => pal(k / STRINGS));
    const x0 = Math.max(2, W * 0.06), x1 = W - 1 - Math.max(2, W * 0.06);
    const gap = H / STRINGS;
    let acc = 0, plucked = -1;
    const pluck = (k, at, amp) => {
      const p = Math.round(N * at);
      for (let i = 0; i < N; i++) y[k][i] = yp[k][i] = i <= p ? (amp * i) / p : (amp * (N - 1 - i)) / (N - 1 - p);
    };
    const step = () => {
      for (let k = 0; k < STRINGS; k++) {
        const Y = y[k], P = yp[k], c2 = c[k] * c[k];
        let e = 0;
        for (let i = 1; i < N - 1; i++) {
          const lap = Y[i - 1] - 2 * Y[i] + Y[i + 1];
          const stiff = i > 1 && i < N - 2 ? Y[i - 2] - 4 * Y[i - 1] + 6 * Y[i] - 4 * Y[i + 1] + Y[i + 2] : 0;
          yn[i] = (2 * Y[i] - P[i] * 0.9993 + c2 * lap - 0.004 * stiff) / 1.0007;
          e += Math.abs(yn[i]);
        }
        yn[0] = yn[N - 1] = 0;
        P.set(Y); Y.set(yn);
        const E = env[k];
        for (let i = 0; i < N; i++) { const a = yn[i] < 0 ? -yn[i] : yn[i]; E[i] = a > E[i] ? a : E[i] * 0.9988; }
        energy[k] = e / N;
      }
    };

    return (t, dt) => {
      const n = Math.floor(t / PLUCK);
      if (n !== plucked) {
        plucked = n;
        const k = PATTERN[((n % PATTERN.length) + PATTERN.length) % PATTERN.length];
        pluck(k, 0.18 + (n % 3) * 0.07, 1 - k * 0.05);
      }
      acc += Math.min(0.25, Math.max(0, dt)) * HZ;
      for (let s = 0; acc >= 1 && s < 240; s++, acc--) step();
      if (acc > 240) acc = 0;
      cv.clear();
      for (let k = 0; k < STRINGS; k++) {
        const base = gap * (k + 0.5), amp = gap * 0.9;
        const glow = Math.min(1, energy[k] * 4);
        const col = mix(mix(th.bg, th.muted, 0.85), cols[k], glow);
        const haze = mix(th.bg, cols[k], 0.25 + 0.45 * glow);
        const Y = y[k], E = env[k];
        let px = x0, py = base;
        for (let s = 1; s <= Math.ceil(x1 - x0); s++) {
          const f = s / (x1 - x0), u = f * (N - 1), i = Math.min(N - 2, Math.floor(u)), fr = u - i;
          const v = Y[i] * (1 - fr) + Y[i + 1] * fr;
          const nx = x0 + s, ny = base + v * amp;
          // Envelope edges, every other pixel so they read as a blur, not a second string.
          const e = (E[i] * (1 - fr) + E[i + 1] * fr) * amp;
          if (e > 1.2 && (s & 1) === 0) { cv.set(nx, base - e, haze); cv.set(nx, base + e, haze); }
          cv.line(px, py, nx, ny, col);
          px = nx; py = ny;
        }
        // Pegs and bridge pins.
        cv.set(x0 - 1, base, th.ink); cv.set(x0 - 2, base, th.ink);
        cv.set(x1 + 1, base, th.ink);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/wireworld.js:
// Wireworld on a generated circuit board. Clock loops (cut-corner rings, each
// carrying one electron, period = ring length) fire pulses down tapped traces
// that a router lays out PCB-style — straight runs, diagonal corners, fan-out
// branches — keeping every trace clear of every other. Rules: head → tail,
// tail → copper, copper → head when one or two neighbors are heads.
import { NONE, mix } from '../../color.js';

const EMPTY = 0, WIRE = 1, HEAD = 2, TAIL = 3;
const D4 = [[1, 0], [0, 1], [-1, 0], [0, -1]];

export default {
  title: 'Wireworld',
  gallery: 'sim',
  category: 'Cellular Automata',
  kind: 'scene',
  tags: ['wireworld', 'cellular automata', 'circuit', 'electrons', 'pcb', 'clock'],
  order: 30,
  description: 'Wireworld on a generated circuit board: clock loops fire electrons down routed traces that fan out across it.',
  size: { w: 60, h: 22 },
  minSize: { w: 20, h: 7 },
  loop: 12,
  canvas: 'field',
  palette: 'theme',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const W = cv.width, H = cv.height, px = cv.px, th = ctx.theme, rand = ctx.rng;
    const gps = 14 * ctx.param('speed', 1);
    let cur = new Uint8Array(W * H), nxt = new Uint8Array(W * H);
    const taken = new Uint8Array(W * H); // occupied or reserved by a clock
    const inside = (x, y) => x >= 1 && y >= 1 && x < W - 1 && y < H - 1;
    const at = (x, y) => y * W + x;
    // A cell may be laid if all its neighbors are empty except the `allow` cells.
    const clear = (x, y, allow) => {
      if (!inside(x, y) || taken[at(x, y)]) return false;
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        if (!dx && !dy) continue;
        const X = x + dx, Y = y + dy;
        if (X < 0 || Y < 0 || X >= W || Y >= H) continue;
        if (taken[at(X, Y)] && !allow.includes(at(X, Y))) return false;
      }
      return true;
    };
    const lay = (x, y) => { cur[at(x, y)] = WIRE; taken[at(x, y)] = 1; };
    const ends = []; // trace ends, drawn as vias

    // Route a trace from (x, y) heading d; returns cells laid.
    const route = (x, y, d, prev, budget, depth) => {
      const trail = [...prev];
      let run = 2 + Math.floor(rand() * 4), extra = [];
      for (let n = 0; n < budget; n++) {
        let moved = false;
        // Keep going straight for the rest of the run, turning only when forced;
        // after a run, prefer a turn. (A trunk just past a branch must go straight.)
        const side = rand() < 0.5 ? 1 : 3, other = 4 - side;
        const options = run > 0 ? (extra.length ? [0] : [0, side, other]) : [side, 0, other];
        for (const turn of options) {
          let nx, ny, nd = (d + turn) & 3;
          if (turn) { nx = x + D4[d][0] + D4[nd][0]; ny = y + D4[d][1] + D4[nd][1]; } // diagonal corner
          else { nx = x + D4[d][0]; ny = y + D4[d][1]; }
          if (!clear(nx, ny, [...trail.slice(-2), ...extra])) continue;
          lay(nx, ny); trail.push(at(nx, ny)); x = nx; y = ny; d = nd; moved = true; extra = [];
          run = turn ? 2 + Math.floor(rand() * 5) : run - 1;
          break;
        }
        if (!moved) break;
        // Occasionally fan out a branch at right angles.
        if (depth < 3 && n > 2 && rand() < 0.1) {
          const bd = (d + (rand() < 0.5 ? 1 : 3)) & 3, bx = x + D4[bd][0], by = y + D4[bd][1];
          const allow = trail.slice(-3);
          // The branch's first cell sits diagonal to the trunk's next cell, so let the trunk pass it.
          if (clear(bx, by, allow)) { lay(bx, by); extra = [at(bx, by)]; run = Math.max(run, 1); route(bx, by, bd, [...allow, at(bx, by)], Math.floor(budget * 0.5), depth + 1); }
        }
      }
      if (trail.length) ends.push([x, y]);
      return trail;
    };

    // Clocks: cut-corner rings with one electron and a tap from a side.
    const clocks = Math.max(1, Math.min(7, Math.round((W * H) / 700)));
    for (let c = 0; c < clocks; c++) {
      for (let tries = 0; tries < 30; tries++) {
        // Small boards get small clocks and a one-cell margin.
        const m = W < 30 || H < 14 ? 1 : 2;
        const w = (m === 1 ? 4 : 5) + Math.floor(rand() * 5), h = (m === 1 ? 2 : 3) + Math.floor(rand() * 3);
        const x0 = m + Math.floor(rand() * Math.max(1, W - w - 2 * m)), y0 = m + Math.floor(rand() * Math.max(1, H - h - 2 * m));
        let ok = x0 + w < W - m && y0 + h < H - m;
        for (let y = y0 - 1; ok && y <= y0 + h + 1; y++) for (let x = x0 - 1; x <= x0 + w + 1; x++) if (taken[at(x, y)]) { ok = false; break; }
        if (!ok) continue;
        const ring = [];
        for (let x = x0 + 1; x < x0 + w; x++) ring.push([x, y0]);
        for (let y = y0 + 1; y < y0 + h; y++) ring.push([x0 + w, y]);
        for (let x = x0 + w - 1; x > x0; x--) ring.push([x, y0 + h]);
        for (let y = y0 + h - 1; y > y0; y--) ring.push([x0, y]);
        for (const [x, y] of ring) lay(x, y);
        for (let y = y0; y <= y0 + h; y++) for (let x = x0; x <= x0 + w; x++) taken[at(x, y)] = 1; // keep the interior clear
        cur[at(...ring[1])] = HEAD; cur[at(...ring[0])] = TAIL;
        // Tap out of the middle of the right or left side.
        const right = x0 + w < W * 0.6, ym = y0 + (h >> 1);
        const tx = right ? x0 + w + 1 : x0 - 1, d = right ? 0 : 2;
        const allow = [at(right ? x0 + w : x0, ym - 1), at(right ? x0 + w : x0, ym), at(right ? x0 + w : x0, ym + 1)];
        if (clear(tx, ym, allow)) { lay(tx, ym); route(tx, ym, d, [...allow, at(tx, ym)], W + H, 0); }
        break;
      }
    }

    const copper = mix(th.bg, 0xc8873e, 0.45), via = mix(th.bg, 0xe8c27a, 0.8), headC = mix(0x9fe8ff, th.ink, 0.2), tailC = 0xff7a3c;
    let acc = 0;
    const step = () => {
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
        const i = y * W + x, s = cur[i];
        if (s === EMPTY) { nxt[i] = EMPTY; continue; }
        if (s === HEAD) { nxt[i] = TAIL; continue; }
        if (s === TAIL) { nxt[i] = WIRE; continue; }
        let n = 0;
        for (let dy = -1; dy <= 1; dy++) {
          const Y = y + dy;
          if (Y < 0 || Y >= H) continue;
          for (let dx = -1; dx <= 1; dx++) {
            const X = x + dx;
            if (X >= 0 && X < W && cur[Y * W + X] === HEAD) n++;
          }
        }
        nxt[i] = n === 1 || n === 2 ? HEAD : WIRE;
      }
      [cur, nxt] = [nxt, cur];
    };

    return (t, dt) => {
      acc += Math.min(0.25, Math.max(0, dt)) * gps;
      for (let k = 0; acc >= 1 && k < 8; k++, acc--) step();
      if (acc > 8) acc = 0;
      for (let i = 0; i < W * H; i++) {
        const s = cur[i];
        px[i] = s === EMPTY ? NONE : s === WIRE ? copper : s === HEAD ? headC : tailC;
      }
      // Vias where traces end (drawing only — not part of the automaton).
      for (const [x, y] of ends) if (cur[at(x, y)] === WIRE) px[at(x, y)] = via;
      cv.paint(ctx.buffer);
    };
  },
};

